const SNAPSHOT_ENDPOINT = 'https://forestnothing.jcbdev.com/server_fn/snapshot.php';
// Private, developer-only capture on every Legado reset — see _captureLegadoTelemetry. Its own
// endpoint/table (server_fn/legado_snapshot.php, fn_legado_snapshots), deliberately NOT the same
// one "Compartir mi ciudad" uses: that one is player-facing (chosen city name, listable/votable,
// sometimes a real CrazyGames username) — this is the opposite on purpose, write-only and never
// surfaced anywhere in-game, reviewed later through index.php's own admin viewer.
const LEGADO_SNAPSHOT_ENDPOINT = 'https://forestnothing.jcbdev.com/server_fn/legado_snapshot.php';
// Reto (challenge) results — ranking + recent-completions feed on web/retos.html. Own
// endpoint/table (server_fn/reto_snapshot.php, fn_reto_results): every COMPLETED run uploads
// here (see _retoFinish), not just a new personal best, unlike the old localStorage-only record.
// Same open-write trust model as the others.
const RETO_SNAPSHOT_ENDPOINT = 'https://forestnothing.jcbdev.com/server_fn/reto_snapshot.php';
// Historial de compras de la tienda (server_fn/purchase.php, tabla fn_purchases): una fila por pedido, con el usuario, para
// revisarlo en el panel (?view=purchases) y saber a quién dar el rol de Discord o los créditos. Ver _shopLogPurchase.
const PURCHASE_ENDPOINT = 'https://forestnothing.jcbdev.com/server_fn/purchase.php';
// Nombres de quienes apoyan el juego, para Créditos (server_fn/supporters.php, tabla fn_supporters; se llevan a mano desde el panel)
const SUPPORTERS_ENDPOINT = 'https://forestnothing.jcbdev.com/server_fn/supporters.php';
// Los Founder también son aldeanos: los primeros de cada partida, el n.º 1, 2, 3... por orden de la lista (ver _villagerNameForId)
// Desde la última lista guardada ya al cargar, para que los aldeanos salgan con su nombre desde el primer momento (luego se pide al servidor)
let _founderNames = (() => { try { const l = JSON.parse(localStorage.getItem('fn_supporters') || '[]'); return Array.isArray(l) ? l.filter(x => x && x.t === 'founder' && x.n).map(x => String(x.n).slice(0, 24)) : []; } catch (e) { return []; } })();
// 60s, no 20s. Cada tick es una petición HTTP, un proceso PHP y una conexión nueva a MySQL por
// jugador conectado: a 20 s y con 400 jugadores eran ~20 conexiones por segundo, la mitad de
// todas las que abría el servidor. A 60 s son ~7.
//
// Nada depende de esto en tiempo real (no hay ranking ni marcador), y "jugando ahora" en el
// dashboard usa una ventana de 2 minutos, así que con un ping por minuto siguen entrando dos
// dentro de la ventana. Los eventos encolados tampoco se pierden al cerrar: hay flush en
// visibilitychange y en pagehide/beforeunload — el intervalo solo cubre la sesión en marcha.
const TELEMETRY_FLUSH_MS = 60000;
let _telemetryPlayerId = null;
let _telemetrySessionId = null;
let _telemetryQueue = [];
// Real (unfocused-time-excluded) session length, tracked independently of the game's own
// _totalGameMs — that one is boost-scaled (a minute played at ×2 speed counts as two), which
// is the right thing for in-game stats but not what "how long were they actually here" means.
let _telemetrySessionStartTs = 0;
let _telemetryHiddenSinceTs = null;
let _telemetryHiddenTotalMs = 0;
let _telemetryEnded = false; // guards against beforeunload+pagehide double-firing session_end

// El intervalo real en uso. Arranca en TELEMETRY_FLUSH_MS pero el servidor puede cambiarlo en
// caliente: cada respuesta trae flush_ms (ver server_fn/telemetry_tuning.php), así que ante un
// pico se puede subir a 120 s o más editando un archivo, sin desplegar el juego. Los jugadores
// ya conectados lo aplican en su siguiente tick, sin recargar.
let _telemetryFlushMs = TELEMETRY_FLUSH_MS;
let _telemetryTimer = null;
function _telemetrySchedule(ms) {
    // Acotado también aquí: la respuesta viene de la red y un valor corrupto o malicioso no
    // debe poder dejar a este navegador martilleando el endpoint (ni callarlo del todo).
    ms = Math.max(15000, Math.min(600000, Math.round(ms) || TELEMETRY_FLUSH_MS));
    if (_telemetryTimer !== null && ms === _telemetryFlushMs) return; // ya está a ese ritmo
    _telemetryFlushMs = ms;
    if (_telemetryTimer !== null) clearInterval(_telemetryTimer);
    _telemetryTimer = setInterval(() => { trackEvent('heartbeat', {}); _telemetryFlush(); }, ms);
}

function _telemetryUuid() {
    if (window.crypto && crypto.randomUUID) return crypto.randomUUID();
    return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
}

let _telemetryInited = false; // guards against setting up the interval/listeners twice
function _telemetryInit() {
    if (_telemetryInited) return;
    _telemetryInited = true;
    try {
        let id = localStorage.getItem('fn_telemetry_player_id');
        if (!id) { id = _telemetryUuid(); localStorage.setItem('fn_telemetry_player_id', id); }
        _telemetryPlayerId = id;
    } catch (e) { _telemetryPlayerId = _telemetryUuid(); }
    _telemetrySessionId = _telemetryUuid();
    _telemetrySessionStartTs = Date.now();
    // First flush fires quickly (session_start doesn't sit unsent for a full TELEMETRY_FLUSH_MS
    // if the player closes the tab before the periodic interval below ever ticks) — the interval
    // then takes over for everything after.
    setTimeout(_telemetryFlush, 3000);
    _telemetrySchedule(TELEMETRY_FLUSH_MS);
    // Tab hidden (switched app, minimized, alt-tabbed) is NOT a session end — the player very
    // often comes back minutes or hours later and keeps playing in the same session (this used
    // to fire session_end here, which made a single continuous session look like it "ended"
    // the moment focus was lost, with more events arriving from the same session afterward).
    // Just track the hidden span (to subtract from the session's active duration) and flush
    // whatever's queued, in case the tab never comes back.
    document.addEventListener('visibilitychange', () => {
        if (document.hidden) {
            _telemetryHiddenSinceTs = Date.now();
            _telemetryFlush();
        } else if (_telemetryHiddenSinceTs !== null) {
            _telemetryHiddenTotalMs += Date.now() - _telemetryHiddenSinceTs;
            _telemetryHiddenSinceTs = null;
        }
    });
    // pagehide fires more reliably than beforeunload on mobile browsers (notably iOS Safari);
    // keep both since desktop support for pagehide isn't universal either — the _telemetryEnded
    // guard means whichever fires first wins and the second is a no-op.
    window.addEventListener('beforeunload', _telemetryEndSession);
    window.addEventListener('pagehide', _telemetryEndSession);
    // AQUÍ NO SE GUARDA LA PARTIDA. Se intentó y BORRABA PARTIDAS.
    //
    // _telemetryInit() corre durante el arranque, ANTES de loadGame() y con el menú principal
    // delante. En ese momento las variables del juego son el mundo por defecto —un centro urbano
    // y nada más—, así que un guardado disparado por beforeunload/pagehide mientras el jugador
    // está en el menú escribía ESE mundo vacío encima de su partida. Recargar la página desde el
    // menú bastaba para perderlo todo.
    //
    // El guardado forzado al salir vive en el listener de visibilitychange de init() (ver
    // 'Guardado FORZADO al irse'), que se registra DESPUÉS de cargar la partida y por tanto solo
    // puede escribir estado real. Cerrar pestaña dispara visibilitychange en los navegadores
    // actuales, así que el caso sigue cubierto.
}

function _telemetryEndSession() {
    if (_telemetryEnded) return;
    _telemetryEnded = true;
    if (_telemetryHiddenSinceTs !== null) {
        _telemetryHiddenTotalMs += Date.now() - _telemetryHiddenSinceTs;
        _telemetryHiddenSinceTs = null;
    }
    const activeMs = Math.max(0, Date.now() - _telemetrySessionStartTs - _telemetryHiddenTotalMs);
    trackEvent('session_end', { active_ms: Math.round(activeMs) });
    _telemetryFlush();
}

