const BYTEBREW_APP_VERSION = '0.15';
// Sesiones y latido ya los mide ByteBrew por su cuenta al inicializarse; reenviarlos solo
// duplicaría y gastaría cuota (heartbeat es uno por minuto y jugador).
const BYTEBREW_SKIP_EVENTS = new Set(['heartbeat', 'session_start', 'session_end']);
let _byteBrew = null;
// En local (file://, localhost, 127.0.0.1) no se envía nada, igual que GA: las pruebas no cuentan
// como jugadores. Para probar la integración a mano: localStorage.fn_bytebrew_local = '1' y recargar.
function _byteBrewInit() {
    try {
        const h = location.hostname;
        const isLocal = location.protocol === 'file:' || h === '' || h === 'localhost' || h === '127.0.0.1';
        let forceLocal = false;
        try { forceLocal = localStorage.getItem('fn_bytebrew_local') === '1'; } catch (e) {}
        if (isLocal && !forceLocal) return;
        if (window.FN_TEST_BUILD) return;   // versión de prueba (tools/build_test.js): sin ByteBrew
        if (window.FN_GAME_MODE === 'android') return;   // app de Android: sin ByteBrew (analíticas de la web de CrazyGames)
        const BB = window.ByteBrewSDK && window.ByteBrewSDK.ByteBrew;
        if (!BB) return;
        BB.initializeByteBrew(BYTEBREW_GAME_ID, BYTEBREW_SDK_KEY, BYTEBREW_APP_VERSION);
        _byteBrew = BB;
    } catch (e) { _byteBrew = null; }
}
// ByteBrew no admite espacios, puntos ni dos puntos en nombres/parámetros — todo lo que no sea
// letra, número, _ o - pasa a _. Solo valores simples (string/number/bool) y como mucho 10:
// objetos anidados se descartan en vez de aplanarse a JSON (que llevaría ':' y '.').
function _bbClean(v) { return String(v).replace(/[^A-Za-z0-9_-]/g, '_').slice(0, 64); }
function _byteBrewEvent(type, data) {
    if (!_byteBrew || BYTEBREW_SKIP_EVENTS.has(type)) return;
    try {
        const params = {};
        let n = 0;
        for (const k in (data || {})) {
            const v = data[k];
            if (v == null || typeof v === 'object' || typeof v === 'function') continue;
            params[_bbClean(k)] = typeof v === 'number' ? String(Math.round(v)) : _bbClean(v);
            if (++n >= 10) break;
        }
        if (n) _byteBrew.newCustomEvent(_bbClean(type), params);
        else _byteBrew.newCustomEvent(_bbClean(type));
    } catch (e) {}
}

// Fire-and-forget — never throws, never blocks gameplay. Call this from anywhere once
// telemetry is wired into an action (building placed, ad watched, skill picked, etc.).
function trackEvent(type, data) {
    try { _telemetryQueue.push({ type, data: data || {}, ts: Date.now() }); } catch (e) {}
    _byteBrewEvent(type, data);
}

// Código de jugador para cuando no hay CrazyGames: aleatorio, corto, legible (sin 0/O ni 1/I/L) y guardado en el navegador.
// Lo ve el jugador en Ajustes (ver _updatePlayerCodeRow) para dártelo si pide ayuda. Es de ESTE navegador: si borra sus datos
// o juega en otro dispositivo, tendrá otro.
const PLAYER_CODE_KEY = 'fn_player_code';
let _playerCodeCache = null;
function _playerCode() {
    if (_playerCodeCache) return _playerCodeCache;
    try { const saved = localStorage.getItem(PLAYER_CODE_KEY); if (saved && /^FN-[A-Z0-9]{4}-[A-Z0-9]{4}$/.test(saved)) return (_playerCodeCache = saved); } catch (e) {}
    const ABC = '23456789ABCDEFGHJKMNPQRSTUVWXYZ';
    const rnd = new Uint32Array(8);
    try { crypto.getRandomValues(rnd); } catch (e) { for (let i = 0; i < 8; i++) rnd[i] = Math.floor(Math.random() * 4294967296); }
    let s = '';
    for (let i = 0; i < 8; i++) s += ABC[rnd[i] % ABC.length];
    _playerCodeCache = 'FN-' + s.slice(0, 4) + '-' + s.slice(4);
    try { localStorage.setItem(PLAYER_CODE_KEY, _playerCodeCache); } catch (e) {}
    return _playerCodeCache;
}
window._playerCode = _playerCode;
// La fila de Ajustes con el código: solo sin SDK de CrazyGames (con él, los regalos van por su usuario)
function _updatePlayerCodeRow() {
    const row = document.getElementById('playerCodeRow');
    if (!row) return;
    const show = !window.CrazyGames;
    row.style.display = show ? 'flex' : 'none';
    if (show) { const v = document.getElementById('playerCodeValue'); if (v) v.textContent = _playerCode(); }
}
function _copyPlayerCode() {
    const code = _playerCode();
    const done = () => showBuildToast(t('settings.player_code_copied'));
    try { navigator.clipboard.writeText(code).then(done, () => { prompt(t('settings.player_code'), code); }); }
    catch (e) { prompt(t('settings.player_code'), code); }
}
window._copyPlayerCode = _copyPlayerCode;
function _telemetryFlush() {
    if (!_telemetryQueue.length || !_telemetryPlayerId) return;
    const events = _telemetryQueue;
    _telemetryQueue = [];
    let payload;
    try {
        payload = JSON.stringify({
            player_id: _telemetryPlayerId,
            session_id: _telemetrySessionId,
            slot: typeof currentSlot !== 'undefined' ? currentSlot : null,
            lang: typeof currentLang !== 'undefined' ? currentLang : null,
            // Only so the server can address a compensation gift at a specific CrazyGames
            // account (see fn_gifts in track.php). null when logged out.
            // Sin SDK de CrazyGames (otras webs, modo sin anuncios) va el código de jugador (FN-XXXX-XXXX, ver _playerCode):
            // así un regalo se le puede mandar desde el mismo panel, escribiendo ese código donde va el usuario de CrazyGames.
            cg_user: (typeof _cgUsername !== 'undefined' && _cgUsername) || (!window.CrazyGames ? _playerCode() : null),
            events,
        });
    } catch (e) { return; }
    // Deliberately NOT navigator.sendBeacon(): it always sends the request with credentials
    // (cookies) included, and browsers refuse to pair a credentialed cross-origin request
    // with a wildcard Access-Control-Allow-Origin response (which is what track.php sends,
    // since it can't know every domain the game might be embedded on) — that combination gets
    // silently blocked by CORS. fetch(..., { credentials: 'omit' }) with keepalive survives
    // page unload just as reliably and sidesteps the whole credentials/CORS conflict.
    try {
        fetch(TELEMETRY_ENDPOINT, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: payload,
            keepalive: true,
            credentials: 'omit',
        }).then(r => r.ok ? r.json() : null)
          .then(res => {
              if (!res) return;
              // El servidor manda el ritmo — ver _telemetrySchedule. Solo lo entiende track2.php;
              // contra el endpoint viejo esto no llega y el intervalo se queda como estaba.
              if (res.flush_ms) _telemetrySchedule(res.flush_ms);
              if (res.gift) _onGiftReceived(res.gift);
          })
          .catch(() => {});
    } catch (e) {}
}

// --- COMPENSATION GIFTS ------------------------------------------------------------------
// Addressed to a CrazyGames account from the telemetry dashboard (see server_fn/index.php and
// the fn_gifts table), delivered on the response to the session_start telemetry POST — no extra
// request, no polling. Two-phase on purpose: the server stamps delivered_at when it hands one
// over, but claimed_at only once the game reports back with gift_claimed, so closing the tab
// while reading the message leaves the gift pending instead of eating it.
//
// Two very different flavors of "give someone Legados", both driven by the same `legados` /
// `legados_inplace` fields — pick the one that fits what actually happened to the player:
//   · gift.legados      → brand-new city in a chosen slot, starting already at that many
//                          Legados (see the slot-picker below). For someone with nothing to lose,
//                          or who explicitly wants a fresh start with a head start.
//   · gift.legados_inplace → same bonuses, applied straight onto the city they already have
//                          loaded right now — no slot, no wipe, no reload. This is the "repair"
//                          path: a player who lost Legados/relics/achievements to a bug, a failed
//                          migration, whatever, gets them back on the SAME city instead of being
//                          handed a fresh empty one. See its own block in _claimGift.
// achievement_ids (plural, comma-separated) works the same way for logros — one gift can restore
// several at once instead of one gift per achievement. achievement_id (singular) still works too,
// only kept for whatever gift might already be in flight from before this existed.
//
// Legado tiers 5+ are `choice: true` (the player picks a package — see PRESTIGE_MILESTONES), so
// a gift can only grant the FIXED tiers, whichever field is used. Higher values are clamped here
// and in the dashboard's own form rather than half-applied.
//
// A function, not a const: this block sits far above PRESTIGE_MILESTONES' own declaration, and
// reading it at module-evaluation time would hit the temporal dead zone and take the whole
// script down. Called only from inside functions, which run long after everything is defined.
function _giftMaxLegados() { return PRESTIGE_MILESTONES.filter(m => !m.choice).length; }
let _pendingGift = null;

function _onGiftReceived(gift) {
    if (_pendingGift) return;                              // one at a time
    if (_spectatorMode || _foreignStateInMemory) return;   // never while someone else's city is loaded
    if (!gift || typeof gift.id !== 'number') return;
    _pendingGift = gift;

    // El servidor lo entrega ya en el lote de 'boot' (~3 s tras cargar), así que puede llegar con
    // la pantalla de carga todavía puesta. Sale por encima de TODO (ver el z-index del overlay),
    // así que sin esta espera se vería un regalo flotando sobre una pantalla de carga. Se aplaza
    // hasta que esa pantalla se va; el regalo no se pierde, solo espera su momento.
    const mostrar = () => {
        const ls = document.getElementById('loadingScreen');
        const cargando = ls && ls.style.display !== 'none' && getComputedStyle(ls).display !== 'none';
        if (cargando) { setTimeout(mostrar, 400); return; }
        try { _showGiftOverlay(gift); } catch (e) { console.error('[Gift] could not show', e); }
    };
    mostrar();
}

