// Sobre cachedLumberCamps, no sobre buildings. Esto lo llama _targetLimit, que a su vez lo llama
// findNearestTree UNA VEZ POR ÁRBOL: con 517 árboles y 384 edificios eran ~198.000 vueltas por
// barrido, y hay un barrido por cada aldeano que se queda sin tarea. Es de largo lo más caro que
// había escondido en el tick, y no se veía porque solo se activa con Duo Taladores.
function _isTreeInLumberZone(tx, ty, radius) {
    for (let i = 0; i < cachedLumberCamps.length; i++) {
        const lc = cachedLumberCamps[i];
        if (Math.max(Math.abs(tx - lc.tx), Math.abs(ty - lc.ty)) <= radius) return true;
    }
    return false;
}

// Tree tone bands by Chebyshev (square-ring) distance from the map center (50,50), matching how
// territory/visibility already grow outward in square rings elsewhere. Band 0 (0-15 tiles out)
// uses the base low_tree.png; each band beyond that swaps in a different-toned PNG variant (see
// the low_tree_tone1..7 optional loads in preloadAssets) — falls back to the base sprite for any
// band whose PNG hasn't been supplied yet, so nothing breaks before the art exists.
//
// Used by the 'tones' and 'types' forest views (settingForestView); the 'biome' view uses the
// biome map below instead.
const TREE_TONE_BAND_EDGES = [10, 18, 25, 30, 35, 40, 45, 50]; // 8 rings (base + tone1..7) -> widths 10, 8, 7, 5, 5, 5, 5, 5
const TREE_TYPE_RING_EDGES = [10, 18, 25, 32, 39, 47, 50];     // 7 rings (one per species)  -> widths 10, 8, 7, 7, 7, 8, 3
function _treeToneIndex(tx, ty, edges = TREE_TONE_BAND_EDGES) {
    // Desde el campamento de ESTE mundo (ver WORLDS), escalado para que el borde más lejano caiga
    // en el último anillo: en el mundo 1 es el mismo cálculo de siempre (centro 50,50, lejos 50);
    // en el 2 los anillos salen de la costa sur y se estiran hasta el norte.
    const w = _world();
    const far = Math.max(w.cx, MAP_SIZE - w.cx, w.cy, MAP_SIZE - w.cy);
    const d = Math.max(Math.abs(tx - w.cx), Math.abs(ty - w.cy)) * (50 / far);
    for (let i = 0; i < edges.length; i++) {
        if (d < edges[i]) return i;
    }
    return edges.length - 1;
}

// Biome map: assets/tree_biome_map.png is a MAP_SIZE×MAP_SIZE PNG (1 pixel = 1 map tile) whose
// color at each pixel picks which low_treeN.png species grows there — organic hand-editable
// clusters instead of rows/rings, painted with any normal image editor as long as it sticks to
// TREE_TYPE_PALETTE's exact colors (PNG is lossless, so an exact repaint decodes back exactly).
// Index 0 (low_tree.png, the original round tree) is also the fallback for any pixel color that
// doesn't match the palette and for every tile before the map/PNG has loaded.
const TREE_TYPE_PALETTE = [
    [46, 125, 50],   // 0 low_tree      — roble redondo (base)
    [123, 149, 62],  // 1 low_tree2     — acacia/sabana
    [27, 94, 32],    // 2 low_tree3     — ciprés/chopo
    [156, 175, 90],  // 3 low_tree4     — cactus/desierto
    [56, 142, 60],   // 4 low_tree5     — columnar/bambú
    [46, 204, 113],  // 5 low_tree6     — palmera/tropical
    [21, 71, 52],    // 6 low_tree7     — pino/abeto
];
// Encoded directly as a string (one digit 0-6 per tile, row-major, MAP_SIZE*MAP_SIZE chars) and
// decoded synchronously right here — NOT read back from the PNG at runtime via
// canvas.getImageData(), which throws a SecurityError ("tainted canvas") the moment the game is
// opened via file:// instead of a real server. Same class of problem villager sprite recoloring
// already hit once (see preloadAssets' own comment on that), solved the same way: ship the result
// as a static value instead of generating it live. assets/tree_biome_map.png still exists as the
// EDITABLE reference image — open it in any image editor, repaint with TREE_TYPE_PALETTE's exact
// colors, then regenerate this string from it (see the generator script) and paste the new value
// in here; nothing reads the PNG itself at runtime.
const TREE_BIOME_DATA = "";
const _treeBiomeMap = new Uint8Array(TREE_BIOME_DATA.length);
for (let _tbi = 0; _tbi < TREE_BIOME_DATA.length; _tbi++) _treeBiomeMap[_tbi] = TREE_BIOME_DATA.charCodeAt(_tbi) - 48;
// Forest view mode (settingForestView, "Vista del bosque" in display options):
//   'biome' — biome map above, species per tile.
//   'tones' — concentric rings from the map centre (_treeToneIndex): base sprite in the middle,
//             then low_tree_tone1..7 outwards.
//   'types' — same rings, but each ring gets a species (TREE_TYPE_RING_ORDER, centre -> edge).
// Indices into low_tree_types: 0=low_tree 1=low_tree2 2=low_tree3 3=low_tree4 4=low_tree5 5=low_tree6 6=low_tree7
const TREE_TYPE_RING_ORDER = [2, 0, 6, 2, 3, 4, 5]; // low_tree3, low_tree, low_tree7, low_tree3, low_tree4, low_tree5, low_tree6
// Con nieve, el dibujo del árbol ya lleva su capa de nieve (_treeSnowy): así la tienen la caché, el que tiembla al talarlo y el caído
function _treeSpriteFor(tx, ty) { return _treeSnowy(_treeSpriteForBase(tx, ty)); }
function _treeSpriteForBase(tx, ty) {
    const terr = spriteCache.terrain;
    if (!terr) return undefined;
    if (settingForestView === 'tones') {
        const tones = terr.low_tree_tones;
        return (tones && tones[_treeToneIndex(tx, ty)]) || terr.low_tree;
    }
    const types = terr.low_tree_types;
    if (!types) return terr.low_tree;
    if (settingForestView === 'types') {
        return types[TREE_TYPE_RING_ORDER[_treeToneIndex(tx, ty, TREE_TYPE_RING_EDGES)]] || terr.low_tree;
    }
    return types[_treeBiomeMap[ty * MAP_SIZE + tx]] || terr.low_tree;
}
// A tree past the halfway point of its wood draws "felled" (rotated 90°, lying down) instead of
// standing — purely visual, chopTree()/damageTree() keep hitting the exact same tile/key exactly
// as before, so a felled tree still yields wood normally until it's fully cleared. Derived
// straight from treeResources instead of a separate flag, so it can never drift out of sync:
// undefined means untouched/full health (never been hit).
function _isTreeFelled(tx, ty) {
    if (!settingShowFelledTrees) return false; // display option — every caller branches on this, so gating it here alone is enough to keep every tree drawn standing regardless of remaining wood
    const res = treeResources.get(`${tx},${ty}`);
    if (res === undefined) return false;
    return res <= getTreeMaxCapacity(tx, ty) * 0.5;
}
// Draws a felled tile's trunk (fixed, near the bottom ~22% of the native image, like a stump) +
// canopy (rotated 90°, lying to the side) exactly the same way regardless of who's calling it —
// shared by the tree-cache build (drawL3TreesAndBuildings) and by the hit-shake row-band patch in
// that same function. The rotated canopy is TILE_SIZE wide and only ~22% tall pre-rotation, so
// after the turn it spills outside its own tile square (into the tile to the right, and a little
// into the tile below-right) — kept exactly as-is (not resized to fit) because that's the look
// that was wanted; see the shake patch-back call site for why that overflow needs help staying
// visible whenever some OTHER nearby tile starts shaking.
function _paintFelledTile(targetCtx, tx, ty, tileTopWorldY, wobble = 0, ltHint) {
    const lt = ltHint || _treeSpriteFor(tx, ty);
    if (!lt) return;
    const nativeW = lt.width || 32, nativeH = lt.height || 32;
    const splitNativeY = Math.round(nativeH * 0.78) + 2;
    const splitScaledY = (splitNativeY / nativeH) * TILE_SIZE;
    const baseX = tx * TILE_SIZE;
    const pivotX = baseX + TILE_SIZE / 2, pivotY = tileTopWorldY + splitScaledY;
    const cut = spriteCache.terrain?.low_tree_cut;
    // Stump: fixed, never wobbles — it's rooted in the ground (dedicated low_tree_cut.png art,
    // same sprite _drawTreeStump uses for the post-full-chop stump, drawn as a full tile so it
    // reads as a proper stump rather than a thin sliver of the standing-tree image).
    if (cut) {
        targetCtx.drawImage(cut, baseX, tileTopWorldY, TILE_SIZE, TILE_SIZE);
    } else {
        targetCtx.drawImage(lt, 0, splitNativeY, nativeW, nativeH - splitNativeY,
            baseX, pivotY, TILE_SIZE, TILE_SIZE - splitScaledY);
    }
    // Fallen top: rotated 90° at rest around the stump's own top edge, plus `wobble` on further
    // hits — only this part moves, since it's the part actually being chopped into wood.
    targetCtx.save();
    targetCtx.translate(pivotX, pivotY);
    targetCtx.rotate(Math.PI / 2 + wobble);
    targetCtx.drawImage(lt, 0, 0, nativeW, splitNativeY,
        -TILE_SIZE / 2, -splitScaledY, TILE_SIZE, splitScaledY);
    targetCtx.restore();
}
// Draws the lingering stump left after a tree is fully chopped — see _treeStumps/
