        const y0 = Math.max(0, Math.floor((cameraY - cy0 / zoom) / TILE_SIZE) - 1), y1 = Math.min(N - 1, Math.ceil((cameraY + (canvas.height - cy0) / zoom) / TILE_SIZE) + 1);
