        spriteCache.terrainSets = { grass_base: gb, low_stone: ls };
        if (gbb) spriteCache.terrainSets.grass_base_bosque = gbb;
        {
            const _names = new Set();
            for (const w of Object.values(WORLDS)) for (const n of Object.values(w.terrain || {})) if (!spriteCache.terrainSets[n]) _names.add(n);
            const _imgs = await Promise.all([..._names].map(n => loadOptional(`assets/${n}.png`)));
            [..._names].forEach((n, i) => { if (_imgs[i]) spriteCache.terrainSets[n] = _imgs[i]; });
        }
