        // + una de alto por encima). fisher_hut.png (2×2 sin margen) queda como alternativa vieja.
        { const _fm = await loadOptional('assets/fisherman.png'); if (_fm) spriteCache.buildings.fisherman = _fm; }
        { const _lh = await loadOptional('assets/lighthouse.png'); if (_lh) spriteCache.buildings.lighthouse = _lh; }
        // Barco del dique en PNG por fases (ver _drawShipFrames). Solo si están LAS 7: con una suelta no hay barco
