        { const _sf = await Promise.all([0, 1, 2, 3, 4, 5, 6].map(k => loadOptional(`assets/ship/barco_fase${k}.png`)));
          if (_sf.every(Boolean)) { spriteCache.shipFrames = _sf; try { spriteCache.shipDiff = _shipFrameDiffBoxes(_sf); } catch (e) {} } }
        { const _fh = await loadOptional('assets/fisher_hut.png'); if (_fh) spriteCache.buildings.fisher_hut = _fh; }
        // Puente alto 3×1 (mundo 2): opcionales, ver _drawHighBridge.
        { const [_hb, _hbv] = await Promise.all([loadOptional('assets/high_bridge.png'), loadOptional('assets/high_bridge_v.png')]);
          if (_hb) spriteCache.terrain.high_bridge = _hb; if (_hbv) spriteCache.terrain.high_bridge_v = _hbv; }
        spriteCache.roadStyles = {};
        await Promise.all(ROAD_STYLES.map(async id => { const [n, c] = await Promise.all([loadOptional(`assets/roads/road_${id}.png`), loadOptional(`assets/roads/road_${id}_city.png`)]); if (n) spriteCache.roadStyles[id] = [n, c || n]; }));
        spriteCache.hbSkins = {};
        await Promise.all(HIGH_BRIDGE_SKINS.map(async id => { const [h, v] = await Promise.all([loadOptional(`assets/skins/high_bridge_${id}.png`), loadOptional(`assets/skins/high_bridge_${id}_v.png`)]); if (h) spriteCache.hbSkins[id] = { h, v }; }));
        spriteCache.terrain.low_grass     = lg;
