        // 1-6. Each optional, so missing art just falls back to the base tree for that index.
        const treeTypeImgs = await Promise.all([2, 3, 4, 5, 6, 7].map(i => loadOptional(`assets/low_tree${i}.png`)));
        spriteCache.terrain.low_tree_types = [spriteCache.terrain.low_tree, ...treeTypeImgs];

