        const decoImgs = await Promise.all(DECO_TYPES.map(k => loadOptional(`assets/deco/${k.slice('deco_'.length)}.png`)));
        DECO_TYPES.forEach((k, i) => { if (decoImgs[i]) spriteCache.buildings[k] = decoImgs[i]; });
        // Ground decorations (floor textures, e.g. tile_stone.png) — same assets/deco/ folder,
