function _relicQueuePrune() {
    const n = _relicQueue.length;
    const _now = performance.now();
    _relicQueue = _relicQueue.filter(q => q.strike || (q.bridge ? relicTiles.includes(q.relicRef) : q.iso ? (buildings.includes(q.iso) && q.iso._isolated) : (q.ach || q.boat) ? _now < q.until : (relicTiles.includes(q.relic) && !q.relic.pending)));
    if (_relicQueue.length !== n) _renderRelicQueue();
}
function _relicQueueClear() { for (const q of _relicQueue) if (q.strike) _strikeDismissed[q.strike] = q.n; _relicQueue = []; _renderRelicQueue(); }
// Debajo del minimapa, alineada con su borde izquierdo; si está cerrado, arriba a la izquierda,
// bajo la barra superior. Se recoloca al pintar la cola y cada segundo (el minimapa se puede
// redimensionar, mover o cerrar).
function _placeRelicQueue() {
    const box = document.getElementById('relicQueue');
    if (!box) return;
    // Móvil vertical: el minimapa va abajo a la derecha, pegado al panel de construir, y debajo no queda sitio (se perdían los avisos).
    // Van arriba a la izquierda, justo bajo la cabecera.
    if (_MQ_PORTRAIT.matches) {
        const tb = document.getElementById('topBar');
        const mTop = (tb ? Math.round(tb.getBoundingClientRect().bottom) : 70) + 8;
        if (box.style.top !== mTop + 'px') box.style.top = mTop + 'px';
        if (box.style.left !== '8px') box.style.left = '8px';
        return;
    }
    const mm = document.getElementById('minimapContainer');
    const r = mm && getComputedStyle(mm).display !== 'none' ? mm.getBoundingClientRect() : null;   // fixed: offsetParent siempre es null
    const top = r && r.height > 0 ? Math.round(r.bottom + 8) : 90;
    const left = r && r.height > 0 ? Math.round(r.left) : 20;
    if (box.style.top !== top + 'px') box.style.top = top + 'px';
    if (box.style.left !== left + 'px') box.style.left = left + 'px';
}
function _renderRelicQueue() {
    const box = document.getElementById('relicQueue');
    if (!box) return;
    _placeRelicQueue();
    box.innerHTML = '';
    const shown = _relicQueue.slice(-RELIC_QUEUE_MAX_SHOWN).reverse();   // la más nueva arriba
    for (const q of shown) {
        if (q.strike) { _renderStrikeChip(box, q); continue; }
        if (q.ach) { _renderAchChip(box, q); continue; }
        if (q.boat) { _renderBoatChip(box, q); continue; }
        if (q.iso) { _renderIsoChip(box, q); continue; }
        if (q.bridge) { _renderBridgeChip(box, q); continue; }
        const el = document.createElement('div');
        el.className = 'relic-chip' + (q.state === 'ready' ? ' ready' : '');
        const title = q.state === 'ready' ? t('notif.relic_ready') : q.first ? t('notif.first_relic') : t('notif.relic');
        const desc = q.state === 'ready' ? t('notif.relic_ready.desc') : q.first ? t('notif.first_relic.desc') : t('notif.relic.desc');
        el.title = (desc + ' — ' + t('notif.relic.focus_hint')).replace(/<[^>]*>/g, '');
        el.innerHTML = `<i class="rc-icon fa-solid ${q.state === 'ready' ? 'fa-hand-sparkles' : 'fa-gem'}"></i><span class="rc-text">${title}</span><button class="rc-close" title="${t('tip.close')}">&times;</button>`;
        // Pulsar: centra la cámara en la reliquia y quita el aviso (ya cumplió).
        el.onclick = () => { cameraX = q.relic.x * TILE_SIZE + TILE_SIZE / 2; cameraY = q.relic.y * TILE_SIZE + TILE_SIZE / 2; _relicQueue = _relicQueue.filter(x => x !== q); _renderRelicQueue(); };
        el.querySelector('.rc-close').onclick = ev => { ev.stopPropagation(); _relicQueue = _relicQueue.filter(x => x !== q); _renderRelicQueue(); };
        box.appendChild(el);
    }
    const hidden = _relicQueue.length - shown.length;
    if (hidden > 0) { const more = document.createElement('div'); more.className = 'rc-more'; more.textContent = '+' + hidden; box.appendChild(more); }
    // Con dos o más avisos: "Borrar todo".
    if (_relicQueue.length >= 2) {
        const clr = document.createElement('button');
        clr.className = 'rc-clear';
        clr.innerHTML = `<i class="fa-solid fa-trash-can"></i> ${t('notif.relic_clear_all')}`;
        clr.onclick = ev => { ev.stopPropagation(); _relicQueueClear(); };
        box.appendChild(clr);
    }
}

// Shows the small "a relic appeared" card (never auto-focuses the camera).
// Clicking the card focuses on the relic (and dismisses, see focusRelic); the ✕ dismisses
// without focusing. Stays open until the player does one or the other — CrazyGames review noted
// the old 3s auto-hide meant some players never finished reading it before it vanished.
function showRelicNotifCard(isFirstRelic) {
    if (!settingShowRelicFound) return;
    const r = relicTiles.length > 0 ? relicTiles[relicTiles.length - 1] : null;
    _chestNotifRelic = r;
    // Fila pequeña en la cola (ver _relicQueue). Si ya nace al lado de tu territorio, sale directamente como explorada.
    _relicQueueAdd(r, r && r.notifiedAvailable ? 'ready' : 'found', isFirstRelic);
}

// Second card, shown once a relic that WASN'T reachable yet (still behind trees) becomes
// reachable — see _checkRelicsBecameAvailable. Same non-auto-closing behavior and close-or-focus
// interaction as showRelicNotifCard above, just different text and tied to one specific relic
// tile rather than "whichever was placed last".
function showRelicAvailableNotifCard(relic) {
    if (!settingShowRelicAvailable) return;
    _chestNotifRelic = relic;
    _relicQueueAdd(relic, 'ready', false);   // la fila de esa reliquia pasa a "explorada" (o se añade)
}

// Polled rather than hooked into every single place territory can expand (chopping a tree,
// placing a building near one, prestige start-with-bonus tiles, ...) — relics are rare enough
// that checking the whole (small) array once a second is effectively free, and far simpler than
// finding every one of those call sites. Skips ones already pending a skill pick (mid-collection,
// nothing left to "become available" for) or already notified once.
function _checkRelicsBecameAvailable() {
    if (_spectatorMode) return;
    _relicQueuePrune();   // fuera de la cola las que ya se han recogido
    _strikeNotifTick();   // avisos de huelga (sin casa / sin trabajo)
    _isoHintTick();       // el primer edificio aislado: aviso con la explicación
    _astilleroAutoTick(); // astilleros en modo automático
    _bridgeHintTick();    // una reliquia al otro lado del agua: aviso de que el camino hace puentes
    // Puertos: reorienta cada segundo (barato: solo busca rutas si cambió algo). Hace falta además de la llamada de rebuildBuildingCaches porque al CARGAR una partida esa llamada puede
    // correr antes de que estén listos el agua y el mar descubierto, y no se repetiría hasta construir algo.
    if (_harborsOn() && _harborReorient()) rebuildBuildingCaches();
    if (_relicQueue.length) _placeRelicQueue();   // por si el minimapa se ha movido/cerrado
    for (const r of relicTiles) {
        if (r.pending || r.notifiedAvailable) continue;
        if (_relicReachableAt(r.x, r.y)) {
            r.notifiedAvailable = true;
            showRelicAvailableNotifCard(r);
        }
    }
}
setInterval(_checkRelicsBecameAvailable, 1000);
setInterval(_sampleResourceRates, 1000); // see _resourceRate/RES_RATE_WINDOW_MS above

function checkRelicCollection(tx, ty) {
    // Read-only viewer: relics render (see maybeSpawnChest/drawRelic) but never open the
    // skill-card picker — there's nothing to spend them on here.
    if (_spectatorMode) return false;
    const idx = relicTiles.findIndex(r => r.x === tx && r.y === ty);
    if (idx === -1) return false;
    if (!_relicReachableAt(tx, ty)) return true;
    dismissChestNotif(); // player is interacting with the relic directly, the card is no longer needed
    // Already pending — just re-open the modal (don't double-count)
    if (relicTiles[idx].pending) { showSkillCardModal(); return true; }
    // Mark as pending but leave tile intact until player makes a choice
    relicTiles[idx].pending = true;
    updateUI();
    showSkillCardModal();
    return true;
}

// Called once the player picks a skill or confirms prestige reset — finalizes the pending relic
function _finalizeRelicCollection() {
    const idx = relicTiles.findIndex(r => r.pending);
    if (idx === -1) return;
    const r = relicTiles[idx];
    const key = `${r.x},${r.y}`;
    markedTrees.delete(key);
    relicTiles.splice(idx, 1);
    _relicQueuePrune();
    if (r.coast) _coastRelicsTaken++;   // reliquia de la costa (ver _relicsCollectedCount)
    _runRelicsCollected++;
    if (prestige.lumberRelic2) rebuildVillagerStatCaches();   // Legado 9 (mundo 2): la tala sube con cada reliquia
    _totalRelicsCollected++;
    _prestigeRelicBank++;
    roadStock += 2;
    trackEvent('relic_collected', { total_relics: _totalRelicsCollected, run_relics: _runRelicsCollected });
    playSfx('relic');
    savePrestige();
    rebuildRelicTileSet();
    // Clear tree on that tile and sync treesChopped (las del mar no tienen árbol ni casilla que reclamar)
    if (!r.sea) {
        if (treeResources.has(key) || visibleTrees.has(key)) {
            treeResources.delete(key);
            visibleTrees.delete(key); _visTreeDirty = true;
            onTreeFullyChopped(r.x, r.y);
        }
        ownedTiles.add(key);
        recalculateVisibility();
    }

    // "si hay varias cuando la recoges saldrá otra vez el cartel para recogerla" — prompt for the
    // next already-reachable relic (if any) right after finishing this one's skill pick, instead
    // of leaving the player to notice it themselves. Re-shows even for one already notified once
    // before (see _checkRelicsBecameAvailable) — the point here isn't "is this the first time",
    // it's "there's still one waiting right now".
    const _nextRelic = relicTiles.find(nr => !nr.pending && _relicReachableAt(nr.x, nr.y));
    if (_nextRelic) showRelicAvailableNotifCard(_nextRelic);
}

