function togglePendingSkill(skillId) {
    if (isSkillActive(skillId)) {
        // Toggle removal of an already-active skill
        if (pendingRemove.has(skillId)) {
            pendingRemove.delete(skillId);
            // Re-check dependents: if any pending-add skill needed this one, cascade-remove it
            for (const [dep, req] of Object.entries(SKILL_PREREQS)) {
                if (req === skillId && pendingSkills.has(dep)) pendingSkills.delete(dep);
            }
        } else {
            pendingRemove.add(skillId);
            // Cascade: also mark dependent active skills for removal
            for (const [dep, req] of Object.entries(SKILL_PREREQS)) {
                if (req === skillId && isSkillActive(dep)) pendingRemove.add(dep);
            }
            // Cascade: deselect any pending-add skills that depended on this
            for (const [dep, req] of Object.entries(SKILL_PREREQS)) {
                if (req === skillId) pendingSkills.delete(dep);
            }
        }
    } else {
        // Toggle add of an inactive skill
        if (pendingSkills.has(skillId)) {
            pendingSkills.delete(skillId);
            for (const [dep, req] of Object.entries(SKILL_PREREQS)) {
                if (req === skillId) pendingSkills.delete(dep);
            }
        } else {
            // Budget = points + refunds from removals - already selected adds
            const budget = skillPoints + pendingRemove.size - pendingSkills.size;
            if (budget <= 0) return;
            const prereq = SKILL_PREREQS[skillId];
            if (prereq && !willBeActive(prereq)) return;
            pendingSkills.add(skillId);
        }
    }
    updateSkillTreePanel();
}
