    // player's Town Center (new game or resumed) instead of leaving it at whatever
    // default/leftover value it happened to have.
    const _startTc = buildings.find(b => b.type === 'town_center');
    if (_startTc) {
        cameraX = (_startTc.x + (_startTc.w || 4) * 0.5) * TILE_SIZE;
        cameraY = (_startTc.y + (_startTc.h || 4) * 0.5) * TILE_SIZE;
    }

