document.getElementById('sliderSfxVolumeMenu')?.addEventListener('change', () => { _sfxLast.click = 0; playSfx('click'); });

// Las cuatro de siempre, que ya se llaman desde todo el juego
function playChopSound(wx, wy)    { playSfx('chop', wx, wy); }
function playTCSound()            { playSfx('gold'); }
function playDepositSound(wx, wy) { playSfx('deposit', wx, wy); }
