    cameraX = worldBefore.x - (mouseX - canvas.width / 2) / zoom;
    cameraY = worldBefore.y - (mouseY - _gameCenterY) / zoom;
    
    // Constrain camera to map boundaries
    cameraX = Math.max(0, Math.min(MAP_PIXEL_SIZE, cameraX));
    cameraY = Math.max(0, Math.min(MAP_PIXEL_SIZE, cameraY));
