function _decoBaseTotal() { return _decoBaseCoins + _decoAdGemsGet(); }
function _applyDecoBase() {
    const base = _decoBaseTotal(), d = base - _decoBaseApplied;
    if (d <= 0) return;
    _decoBaseApplied = base;
    _decoCoinsTotalEarned += d;
    if (_decoInfPinned) _decoRealCoins += d; else decoCoins += d;
}
function _applyDecoInfinite() {
    _applyDecoBase();
    if (_decoInfinite()) {
        if (!_decoInfPinned) { _decoRealCoins = decoCoins; _decoInfPinned = true; }
        decoCoins = DECO_INF_COINS;
    } else if (_decoInfPinned) { decoCoins = _decoRealCoins; _decoInfPinned = false; }
    document.body.classList.toggle('deco-infinite', _decoInfPinned);
}
// --- Miniaturas en el panel de construir ---
// Sprite que dibuja cada tipo cuando no se llama igual
const BUILD_THUMB_SPRITE = Object.assign(Object.create(null), { fisher_hut: 'fisherman', zanja: 'thumb_zanja', high_bridge: 'thumb_high_bridge' });
// Los que no tienen sprite y se pintan por código: su función de dibujo y su huella (ancho, alto en casillas)
const BUILD_THUMB_DRAW = Object.assign(Object.create(null), {
    watchtower: { w: 1, h: 1, draw: (px, py) => drawWatchtower(px, py) },
    astillero:  { w: 3, h: 3, draw: (px, py) => drawAstillero(null, px, py) },
});
const BUILD_THUMB_SIZE = 52;   // ancho, en píxeles de pantalla
const BUILD_THUMB_MAX_H = 72;  // alto máximo (casas, torres...)
let _buildThumbsDone = false;
// src: imagen o lienzo; artScale: píxeles de src por píxel de arte (1 en los PNG, TILE_SIZE/16 en lo pintado por código)
function _buildThumbFor(src, artScale) {
    const c0 = document.createElement('canvas'); c0.width = src.width; c0.height = src.height;
    const g0 = c0.getContext('2d'); g0.drawImage(src, 0, 0);
    const d = g0.getImageData(0, 0, src.width, src.height).data;
    let x0 = src.width, y0 = src.height, x1 = -1, y1 = -1;
    for (let y = 0; y < src.height; y++) for (let x = 0; x < src.width; x++) if (d[(y * src.width + x) * 4 + 3] > 90) { if (x < x0) x0 = x; if (x > x1) x1 = x; if (y < y0) y0 = y; if (y > y1) y1 = y; }
    if (x1 < 0) return null;
    const w = x1 - x0 + 1, h = y1 - y0 + 1, aw = w / artScale, ah = h / artScale;
    // Todos del mismo ancho: la huella (casillas de ancho, 16 píxeles de arte cada una) ocupa BUILD_THUMB_SIZE, así un 2×2 y un 2×2 más alto
    // salen a la misma escala, y un 3×3 o un 4×4 más o menos del mismo tamaño que ellos. Lo alto crece hacia arriba hasta BUILD_THUMB_MAX_H.
    const tiles = Math.max(1, Math.round(aw / 16));
    let css = BUILD_THUMB_SIZE / (tiles * 16);
    css = Math.min(css, BUILD_THUMB_SIZE / aw, BUILD_THUMB_MAX_H / ah);
    const k = 2 * css / artScale, W = BUILD_THUMB_SIZE * 2, H = Math.max(2, Math.round(h * k));   // lienzo al doble, para que no pierda píxeles
    const c = document.createElement('canvas'); c.width = W; c.height = H;
    const g = c.getContext('2d'); g.imageSmoothingEnabled = false;
    g.drawImage(c0, x0, y0, w, h, Math.round((W - w * k) / 2), H - Math.round(h * k), Math.round(w * k), Math.round(h * k));   // apoyado abajo, como en el mapa
    return c.toDataURL();
}
// Lo que se pinta por código, en un lienzo aparte del tamaño de su huella (con sitio arriba para lo que sobresale)
function _buildThumbCanvas(spec) {
    const T = TILE_SIZE, c = document.createElement('canvas');
    c.width = spec.w * T; c.height = (spec.h + 2) * T;
    const keep = ctx;
    try { ctx = c.getContext('2d'); spec.draw(0, 2 * T); } finally { ctx = keep; }
    return c;
}
function _applyBuildThumbs() {
    if (_buildThumbsDone || !spriteCache.buildings || !spriteCache.buildings.house) return;
    _buildThumbsDone = true;
    for (const btn of document.querySelectorAll('#buildingsGrid .command-btn')) {
        const mt = (btn.getAttribute('onmouseenter') || '').match(/_showBuildInfo\(event,this,'([a-z_]+)'\)/);
        if (!mt) continue;
        const type = mt[1], ico = btn.querySelector('.btn-icon');
        if (!ico) continue;
        try {
            const img = spriteCache.buildings[BUILD_THUMB_SPRITE[type] || type];
            const url = img && img.width ? _buildThumbFor(img, 1) : BUILD_THUMB_DRAW[type] ? _buildThumbFor(_buildThumbCanvas(BUILD_THUMB_DRAW[type]), TILE_SIZE / 16) : null;
            if (!url) continue;
            ico.innerHTML = '<img class="build-thumb" alt="" src="' + url + '">';
            btn.classList.add('has-thumb');
        } catch (_) { /* si algo falla con un dibujo, ese botón se queda con su icono */ }
    }
}
function updateUI() {
    if (!_buildThumbsDone) _applyBuildThumbs();
    if (_decoFreeLocal && decoCoins < 999) decoCoins = 999;
    // En local, sin ?decogratis: lo que rellenó la prueba (y quedó guardado) se quita, y vuelven los de verdad (ganados menos gastados).
    // Solo en local: en partidas viejas el total ganado puede estar por debajo de lo real, y a un jugador no hay que quitarle nada.
    else if (!_decoFreeLocalChecked && _cgIsLocal()) {
        // Con la partida ya cargada (_saveReady). try: updateUI puede llamarse durante el arranque, antes de que exista _saveReady
        try {
            if (_saveReady && !_decoInfPinned) {
                _decoFreeLocalChecked = true;
                const real = Math.max(0, _decoCoinsTotalEarned - _decoCoinsUsed);
                if (decoCoins > real) { decoCoins = real; savePrestige(); }
            }
        } catch (_) {}
    }
    _applyDecoInfinite();
    _updateOfflineBoostUI();
    _updateDecoCoinUI();
    // "durante el reto no debería tener el header, retos, ni logros" — Retos abriría un panel que
    // enseña el progreso/mejores puntuaciones de la partida REAL con la ciudad-sandbox del propio
    // reto de fondo (confuso), y Logros directamente enseñaría datos INCORRECTOS: entrar a un
    // reto vacía _unlockedAchievements a propósito (ver startReto/_applySnapshotState, "que la
    // partida sea sin skill... como una partida nueva de verdad") para simular un perfil en
    // blanco, así que abrirlo en mitad de un reto mostraría todo como no conseguido aunque sí lo
    // esté en la partida real. "Stats tb se ven raras en el reto": mismo problema — la pestaña
    // Total mezcla lifetimeStats REAL (congelado al entrar, ver startReto) con gStats del propio
    // reto (arrancado a 0), dando un número que no es ni tu total real ni el progreso del reto.
    // Mismo criterio !_retoActive que ya usa el resto de UI que se apaga durante el reto (ver
    // _updateOfflineBoostUI/el aviso de acelerador de anuncio).
    const btnRetosHeader = document.getElementById('btnRetos');
    if (btnRetosHeader) btnRetosHeader.style.display = _retoActive ? 'none' : 'flex';
    const btnAchievementsHeader = document.getElementById('btnAchievements');
    if (btnAchievementsHeader) btnAchievementsHeader.style.display = _retoActive ? 'none' : 'flex';
    const btnStatsHeader = document.getElementById('btnStats');
    if (btnStatsHeader) btnStatsHeader.style.display = _retoActive ? 'none' : 'flex';
    const houseCost = getHouseCost();
    
    document.getElementById('woodValue').innerText = formatCompact(wood);
    document.getElementById('foodValue').innerText = formatCompact(food);
    document.getElementById('woolValue').innerText = formatCompact(wool);
    _updateResRateEl('woodRate', 'wood');
    _updateResRateEl('foodRate', 'food');
    _updateResRateEl('woolRate', 'wool');

    const hasConstructorBuilding = buildings.some(b => b.type === 'constructor');
    const hasMill2      = buildings.some(b => b.type === 'mill');
    const hasSheepFarm2 = buildings.some(b => b.type === 'sheep_farm');

    const foodCounter = document.getElementById('foodCounter');
    const woolCounter = document.getElementById('woolCounter');
    const stoneCounter = document.getElementById('stoneCounter');
    const goldCounter = document.getElementById('goldCounter');

    // "una vez que sale en el header ya no se oculte en ese run": cada recurso, al aparecer, queda
    // marcado en _hdrSeen y ya no se oculta aunque se gaste hasta 0 (fuera del Reto, que va aparte).
    const _seen = k => !_retoActive && !!_hdrSeen[k];
    const showFood  = food > 0 || hasMill2 || hasSkillInsectivoro || _seen('food');
    const showWool  = wool > 0 || hasSheepFarm2 || _seen('wool');
    const showStone = stone > 0 || _seen('stone'); // only after actually collecting a first stone — no anticipatory reveal
    const showGold  = gold > 0 || hasSkillRutaComercial || _seen('gold');
    if (!_retoActive) { if (showFood) _hdrSeen.food = 1; if (showWool) _hdrSeen.wool = 1; if (showStone) _hdrSeen.stone = 1; if (showGold) _hdrSeen.gold = 1; }

    // A resource chip appearing/disappearing changes how much content the bar has to fit —
    // remember whether any of them actually flip this call, so the degradation ladder below
    // only re-runs when it might actually need to (not on every single updateUI() call).
    const _wasFoodShown  = !!foodCounter  && foodCounter.style.display  !== 'none';
    const _wasWoolShown  = !!woolCounter  && woolCounter.style.display  !== 'none';
    const _wasStoneShown = !!stoneCounter && stoneCounter.style.display !== 'none';
    const _wasGoldShown  = !!goldCounter  && goldCounter.style.display  !== 'none';

    if (foodCounter)  foodCounter.style.display  = showFood  ? 'flex' : 'none';
    if (woolCounter)  woolCounter.style.display  = showWool  ? 'flex' : 'none';
    if (stoneCounter) { stoneCounter.style.display = showStone ? 'flex' : 'none'; }
    if (goldCounter)  goldCounter.style.display  = showGold  ? 'flex' : 'none';
    // Almas: aparece con el saldo y, como los demás, ya no se oculta en esa partida. El separador
    // va aparte porque el de los demas recursos es un hermano suyo, no un hijo.
    const soulsCounter = document.getElementById('soulsCounter');
    const soulsSep = document.querySelector('.souls-sep');
    const showSouls = souls > 0 || _seen('souls');
    if (showSouls && !_retoActive) _hdrSeen.souls = 1;
    const _wasSoulsShown = !!soulsCounter && soulsCounter.style.display !== 'none';
    if (soulsCounter) soulsCounter.style.display = showSouls ? 'flex' : 'none';
    if (soulsSep) soulsSep.style.display = showSouls ? '' : 'none';

    // A newly-revealed (or newly-hidden) resource chip changes the bar's content width — without
    // this, a chip appearing for the first time (e.g. collecting your first stone) could overflow
    // the bar's container instead of the desktop degradation ladder (hide logo/timer/labels)
    // kicking in to make room, same as it already does on window resize.
    if (_wasFoodShown !== showFood || _wasWoolShown !== showWool || _wasStoneShown !== showStone || _wasGoldShown !== showGold || _wasSoulsShown !== showSouls) {
        if (typeof _updateTopBarFit === 'function') _updateTopBarFit();
    }

    if (stoneCounter) { document.getElementById('stoneValue').innerText = formatCompact(stone); _updateResRateEl('stoneRate', 'stone'); }
    if (goldCounter) { document.getElementById('goldValue').innerText = formatCompact(gold); _updateResRateEl('goldRate', 'gold'); }
    if (showSouls) document.getElementById('soulsValue').innerText = formatCompact(souls);
    
    document.getElementById('tilesValue').innerText = formatNumber(ownedTiles.size);
    // Spectator viewer: just the headcount, no "/ cap" — the cap is only meaningful if you can
    // build a house to raise it, which a visitor never can (see the spectator-mode CSS rules).
    document.getElementById('villagerValue').innerText = _spectatorMode
        ? _popUsadaTexto()
        : `${_popUsadaTexto()} / ${formatNumber(popLimit)}`;

    const commandCard = document.getElementById('commandCard');
    if (commandCard) {
        const shouldShowCommandCard = villagers.length >= 5;
        commandCard.style.display = shouldShowCommandCard ? '' : 'none';
        // No resizeCanvas() needed when this flips anymore — the canvas is always full-viewport
        // regardless of #commandCard (see resizeCanvas's own comment), so it has nothing to react to.
    }
    
    // Update Villager Button
    // Update Villager Buttons
    const btnWood = document.getElementById('btnTrainVillagerWood');
    const btnFood = document.getElementById('btnTrainVillagerFood');
    const btnWool = document.getElementById('btnTrainVillagerWool');
    
    if (btnWood && btnFood && btnWool) {
        const isTC = selectedBuilding && selectedBuilding.type === 'town_center';
        
        btnWood.style.display = isTC ? 'flex' : 'none';
        btnFood.style.display = (isTC && purchasedVillagersWood >= 5) ? 'flex' : 'none';
        btnWool.style.display = (isTC && wool > 0) ? 'flex' : 'none';
        // Mismo criterio que el chip de la barra: sin almas, el botón no existe. Se maneja aparte
        // de los otros tres porque su coste es fijo (SOULS_COST) y no pasa por getVillagerXCost().
        const btnSouls = document.getElementById('btnTrainVillagerSouls');
        if (btnSouls) {
            btnSouls.style.display = (isTC && souls > 0) ? 'flex' : 'none';
            const lSouls = btnSouls.querySelector('.btn-cost');
            const atCap = _popUsada() >= popLimit;
            if (lSouls) {
                const capMsgS = atCap
                    ? `<br><span style="color:var(--warning);font-weight:600;font-size:10px;white-space:normal;display:inline-block;line-height:1.3;">${t('recruit.no_house')}</span>`
                    : '';
                lSouls.innerHTML = `<i class="fa-solid fa-ghost"></i> ${t('recruit.cost_souls', { cost: SOULS_COST })}${capMsgS}`;
            }
            btnSouls.style.outline = atCap ? '2px solid var(--warning)' : '';
            btnSouls.title = atCap ? t('recruit.no_house_tip') : '';
            btnSouls.disabled = souls < SOULS_COST;
        }

        if (isTC) {
            const costWood = getVillagerWoodCost();
            const costFood = getVillagerFoodCost();
            const costWool = getVillagerWoolCost();
            const atLimit = _popUsada() >= popLimit;

            const lWood = btnWood.querySelector('.btn-cost');
            const lFood = btnFood.querySelector('.btn-cost');
            const lWool = btnWool.querySelector('.btn-cost');
            
            for (const b of [btnWood, btnFood, btnWool]) b.title = atLimit ? t('recruit.no_house_tip') : '';
            if (atLimit) {
                const capMsg = `<br><span style="color:var(--warning);font-weight:600;font-size:10px;white-space:normal;display:inline-block;line-height:1.3;">${t('recruit.no_house')}</span>`;
                lWood.innerHTML = `${RES.wood} ${t('recruit.cost_wood', { cost: formatCompact(costWood) })}${capMsg}`;
                lFood.innerHTML = `${RES.food} ${t('recruit.cost_food', { cost: formatCompact(costFood) })}${capMsg}`;
                lWool.innerHTML = `${RES.wool} ${t('recruit.cost_wool', { cost: formatCompact(costWool) })}${capMsg}`;
                btnWood.style.outline = '2px solid var(--warning)';
                btnFood.style.outline = '2px solid var(--warning)';
                btnWool.style.outline = '2px solid var(--warning)';
                // Se puede comprar igual: el aldeano llega en huelga (ver trainVillagerWith)
                btnWood.disabled = wood < costWood;
                btnFood.disabled = food < costFood;
                btnWool.disabled = wool < costWool;
            } else {
                lWood.innerHTML = `${RES.wood} ${t('recruit.cost_wood', { cost: formatCompact(costWood) })}`;
                lFood.innerHTML = `${RES.food} ${t('recruit.cost_food', { cost: formatCompact(costFood) })}`;
                lWool.innerHTML = `${RES.wool} ${t('recruit.cost_wool', { cost: formatCompact(costWool) })}`;
                btnWood.style.outline = '';
                btnFood.style.outline = '';
                btnWool.style.outline = '';
                btnWood.disabled = wood < costWood;
                btnFood.disabled = food < costFood;
                btnWool.disabled = wool < costWool;
            }
        }
    }
    
    // Update House Button (Unlocked after reaching 5 villagers)
    const btnHouse = document.getElementById('btnBuildHouse');
    if (btnHouse) {
        const hasFreeHouse = _freeBuildingQueue.includes('house');
        const costLabel = btnHouse.querySelector('.btn-cost');
        if (costLabel) {
            costLabel.innerHTML = hasFreeHouse ? `<span style="color:#44cc44">${t('free')}</span>` : renderCostHTML(houseCost);
        }
        btnHouse.classList.toggle('free-gift', hasFreeHouse);
        // "quitar todos los requerimientos de otros edificios" — antes exigía tener un
        // Campamento Maderero CONSTRUIDO AHORA MISMO (buildings.filter(...).length), así que
        // demolerlo por accidente ocultaba el botón de Casa para siempre. tutorialStep es
        // permanente (sobrevive a los reinicios de Legado, ver savePrestige/loadPrestige) y solo
        // sube — nunca baja al demoler nada — así que "ya construiste un Campamento Maderero
        // alguna vez" (tutorialStep pasó de 4 a 5 al completarlo, ver updateTutorial) sigue
        // sirviendo para guiar el tutorial de primeras la primera vez sin poder volver a
        // esconderse después. En un reinicio ya sin tutorial (tutorialStep ya en 13) esto es
        // simplemente true desde el principio.
        btnHouse.style.display = (tutorialStep >= 5 || hasFreeHouse) ? 'flex' : 'none';
        btnHouse.disabled = !hasFreeHouse && (wood < houseCost.wood || food < (houseCost.food || 0)
                         || wool < (houseCost.wool || 0) || stone < (houseCost.stone || 0) || gold < (houseCost.gold || 0));
    }

    // Update Road Button — antes exigía tener una Casa CONSTRUIDA AHORA MISMO; ahora
    // tutorialStep >= 7 ("ya completaste el paso de la Casa alguna vez", permanente, ver el
    // comentario junto al botón de Casa más arriba) — demoler la última casa ya no lo esconde.
    const btnRoad = document.getElementById('btnBuildRoad');
    if (btnRoad) {
        const roadLabel = btnRoad.querySelector('.btn-cost');
        if (roadLabel) roadLabel.innerHTML = t('build.road_stock', { n: roadStock });
        btnRoad.style.display = (tutorialStep >= 7) ? 'flex' : 'none';
        btnRoad.disabled = roadStock <= 0;
    }
    const btnRoadErase = document.getElementById('btnRoadErase');
    if (btnRoadErase) { btnRoadErase.style.display = (tutorialStep >= 7) ? 'flex' : 'none'; btnRoadErase.classList.toggle('active', buildMode === 'road_erase'); }
    const roadRow = document.getElementById('roadRow');
    if (roadRow) roadRow.style.display = (tutorialStep >= 7) ? 'flex' : 'none';
    const btnRoadStyle = document.getElementById('btnRoadStyle');
    if (btnRoadStyle) { const on = tutorialStep >= 7 && _decoTabRevealed && !_spectatorMode; btnRoadStyle.style.display = on ? 'flex' : 'none'; if (!on && _roadStylePanelOpen) { _roadStylePanelOpen = false; _renderRoadStylePanel(); } }
    const btnZanja = document.getElementById('btnBuildZanja');
    if (btnZanja) {
        btnZanja.style.display = (hasSkillZanja && _waterCount > 0) ? 'flex' : 'none';
        // Cuántos cavadores (según Cuadrilla de Cavadores); el tiempo no, que depende de lo lejos del río que se cave (se ve al colocarla)
        const zc = btnZanja.querySelector('.btn-cost');
        if (zc) zc.textContent = t('build.zanja_cost', { n: _zanjaMaxWorkers({ type: 'zanja' }) });
    }
    // Cupo de cavadores de la zanja seleccionada (−/+), como los acarreadores del dique.
    const zRow = document.getElementById('zanjaWorkersRow');
    if (zRow) {
        const zb = selectedBuilding && _zanjaNeedsWork(selectedBuilding) ? selectedBuilding : null;
        zRow.style.display = zb ? 'flex' : 'none';
        if (zb) {
            const cap = _zanjaCap(zb), cur = villagers.filter(v => v.farmTarget === zb).length;
            const lbl = document.getElementById('zanjaWorkersLabel');
            _setStepperLabel(lbl, zb.type === 'astillero' ? 'fa-hammer' : 'fa-person-digging', t(zb.type === 'astillero' ? 'astillero.workers' : 'zanja.workers'), cur, _zanjaMaxWorkers(zb));   // trabajando / máximo posible (el cupo se ve subir con + y −)
            const bm = document.getElementById('btnZanjaWorkersMinus'), bp = document.getElementById('btnZanjaWorkersPlus');
            if (bm) bm.disabled = cap <= ZANJA_WORKERS_MIN;
            if (bp) bp.disabled = cap >= _zanjaMaxWorkers(zb);
        }
    }
    const btnHighBridge = document.getElementById('btnBuildHighBridge');
    if (btnHighBridge) {
        const hbLabel = btnHighBridge.querySelector('.btn-cost');
        if (hbLabel) hbLabel.innerHTML = t('build.high_bridge_stock', { n: highBridgeStock });
        btnHighBridge.style.display = (_waterCount > 0 && (highBridgeStock > 0 || prestige.highBridge5)) ? 'flex' : 'none';
        btnHighBridge.disabled = highBridgeStock <= 0;
    }

    // Update Lumber Camp Button
    const btnLumber = document.getElementById('btnBuildLumberCamp');
    if (btnLumber) {
        btnLumber.style.display = (villagers.length >= 5) ? 'flex' : 'none';
        if (villagers.length >= 5) {
            const costLabel = btnLumber.querySelector('.btn-cost');
            const cost = getLumberCampCost();
            if (costLabel) costLabel.innerHTML = cost.wood === 0
                ? `<span style="color:#7dff7d;">${t('btn.free')}</span>`
                : renderCostHTML(cost);
            btnLumber.disabled = wood < cost.wood;
        }
    }

    // Update Mill Button — antes exigía Casa Y Campamento Maderero CONSTRUIDOS AHORA MISMO; ambos
    // ya están cubiertos por tutorialStep >= 7 (la Casa se completa más tarde que el Campamento
    // Maderero en el tutorial, así que su umbral domina — ver el comentario del botón de Casa).
    const btnAstillero = document.getElementById('btnBuildAstillero');
    if (btnAstillero) {
        const show = hasSkillAstillero && _worldHasBuilding('astillero');
        btnAstillero.style.display = show ? 'flex' : 'none';
        if (show) {
            const c = getAstilleroCost(), cl = btnAstillero.querySelector('.btn-cost');
            if (cl) cl.innerHTML = renderCostHTML(c);
            btnAstillero.disabled = wood < c.wood || food < c.food || stone < c.stone;
        }
    }
    // Astillero seleccionado: botón "Construir barca" con su coste (o la razón si no se puede).
    const btnBoat = document.getElementById('btnAstilleroBoat');
    if (btnBoat) {
        const ab = selectedBuilding && selectedBuilding.type === 'astillero' ? selectedBuilding : null;
        btnBoat.style.display = ab ? 'flex' : 'none';
        if (ab) {
            const why = _astilleroBlock(ab), info = btnBoat.querySelector('.btn-cost');
            if (info) info.innerHTML = why && why !== 'astillero.no_res' ? `<span style="color:#c86a6a;white-space:normal;">${t(why)}</span>` : renderCostHTML(_astilleroBoatCost());
            btnBoat.disabled = !!why;
        }
    }
    const btnAuto = document.getElementById('btnAstilleroAuto');
    if (btnAuto) {
        const ab = selectedBuilding && selectedBuilding.type === 'astillero' ? selectedBuilding : null;
        btnAuto.style.display = ab ? 'flex' : 'none';
        if (ab) {
            btnAuto.classList.toggle('active', !!ab.autoBoat);
            const info = btnAuto.querySelector('.btn-cost');
            // Que parta en varias líneas: el texto de .btn-cost no se corta y se salía del botón
            if (info) info.innerHTML = `<span style="white-space:normal;">${t(ab.autoBoat ? 'astillero.auto_on' : 'astillero.auto_off')}</span>`;
        }
    }
    const btnLighthouse = document.getElementById('btnBuildLighthouse');
    if (btnLighthouse) {
        const show = _lighthouseOn() && !_hasLighthouse();   // edificio único (2 con Mareas): el botón se va al llegar al tope
        btnLighthouse.style.display = show ? 'flex' : 'none';
        if (show) {
            const c = getLighthouseCost(), cl = btnLighthouse.querySelector('.btn-cost');
            if (cl) cl.innerHTML = renderCostHTML(c);
            btnLighthouse.disabled = wood < c.wood || stone < c.stone;
        }
    }
    const btnWatermill = document.getElementById('btnBuildWatermill');
    if (btnWatermill) {
        const show = (hasSkillMolinoAgua || _freeWatermillPending()) && _worldHasBuilding('watermill') && _waterCount > 0;
        btnWatermill.style.display = show ? 'flex' : 'none';
        if (show) {
            const cost = getWatermillCost();
            const cl = btnWatermill.querySelector('.btn-cost');
            // Molino gratis (Cosecha del Río): "Gratis" en verde, como los demás regalos.
            const freeMill = _freeWatermillPending();
            if (cl) cl.innerHTML = freeMill ? `<span style="color:#7dff7d;">${t('btn.free')}</span>` : renderCostHTML(cost);
            btnWatermill.classList.toggle('free-gift', freeMill);
            btnWatermill.disabled = !freeMill && wood < cost.wood;
        }
    }
    const btnMill = document.getElementById('btnBuildMill');
    if (btnMill) {
        const costLabel = btnMill.querySelector('.btn-cost');
        const cost = getMillCost();
        if (costLabel) {
            costLabel.innerHTML = cost.wood === 0
                ? `<span style="color:#7dff7d;">${t('btn.free')}</span>`
                : renderCostHTML(cost);
        }
        btnMill.style.display = (tutorialStep >= 7) ? 'flex' : 'none';
        btnMill.disabled = wood < cost.wood;
    }

    // Update Farm Button — antes exigía un Molino CONSTRUIDO AHORA MISMO; ahora tutorialStep >= 8
    // ("ya completaste el paso del Molino alguna vez").
    const btnFarm = document.getElementById('btnBuildFarm');
    if (btnFarm) {
        const costLabel = btnFarm.querySelector('.btn-cost');
        const cost = getFarmCost();
        if (costLabel) costLabel.innerHTML = renderCostHTML(cost);
        btnFarm.style.display = (tutorialStep >= 8) ? 'flex' : 'none';
        btnFarm.disabled = wood < cost.wood;
    }
    // Pescador: mismo momento que la Granja (paso 8), solo donde el mundo lo incluye.
    const btnFisher = document.getElementById('btnBuildFisher');
    if (btnFisher) {
        const cost = getFisherCost();
        const costLabel = btnFisher.querySelector('.btn-cost');
        // Pescadores gratis (Legado Pescadores del Naufragio): "Gratis ×2" mientras queden.
        const freeFishers = _freeBuildingQueue.filter(x => x === 'fisher_hut').length;
        if (costLabel) costLabel.innerHTML = freeFishers > 0
            ? `<span style="color:#7dff7d;">${t('btn.free')} ×${freeFishers}</span>`
            : renderCostHTML(cost);
        btnFisher.classList.toggle('free-gift', freeFishers > 0);
        // Con pescadores gratis, el botón sale aunque el tutorial no haya llegado al paso del pescador.
        btnFisher.style.display = ((tutorialStep >= 8 || freeFishers > 0) && _worldHasBuilding('fisher_hut')) ? 'flex' : 'none';
        btnFisher.disabled = wood < cost.wood;
    }

    // Update Sheep Farm Button (Unlocked after building at least 1 Farm)
    const btnSheepFarm = document.getElementById('btnBuildSheepFarm');
    if (btnSheepFarm) {
        const hasFreeSheepFarm = _freeBuildingQueue.includes('sheep_farm');
        const cost = getSheepFarmCost();
        const costLabel = btnSheepFarm.querySelector('.btn-cost');
        if (costLabel) costLabel.innerHTML = hasFreeSheepFarm ? `<span style="color:#44cc44">${t('free')}</span>` : renderCostHTML(cost);
        btnSheepFarm.classList.toggle('free-gift', hasFreeSheepFarm);
        btnSheepFarm.style.display = (villagers.length >= 15 || hasFreeSheepFarm) ? 'flex' : 'none';
        btnSheepFarm.disabled = !hasFreeSheepFarm && (wood < cost.wood || food < cost.food);
    }

    // Update Well Button — antes exigía una Granja CONSTRUIDA AHORA MISMO; ahora tutorialStep >= 9
    // ("ya completaste el paso de la Granja alguna vez", ver el comentario del botón de Casa).
    const btnWell = document.getElementById('btnBuildWell');
    if (btnWell) {
        const cost = getWellCost();
        const hasFreeWell = _freeBuildingQueue.includes('well');
        const costLabel = btnWell.querySelector('.btn-cost');
        if (costLabel) {
            costLabel.innerHTML = hasFreeWell
                ? `<span style="color:#44cc44">${t('free')}</span>`
                : `${RES.stone} ${formatCompact(cost.stone)}`;
        }
        btnWell.classList.toggle('free-gift', hasFreeWell);
        btnWell.style.display = (tutorialStep >= 9 && (hasSkillHidraulica || hasFreeWell)) ? 'flex' : 'none';
        btnWell.disabled = !hasFreeWell && stone < cost.stone;
    }

    // Update Watchtower Button (unlocked by the torreVigilancia skill)
    const btnWatchtower = document.getElementById('btnBuildWatchtower');
    if (btnWatchtower) {
        const wtCost = getWatchtowerCost();
        const wtLabel = btnWatchtower.querySelector('.btn-cost');
        btnWatchtower.style.display = hasSkillTorreVigilancia ? 'flex' : 'none';
        // torreVigilancia may already be flagged active from an old save/test session, but the
        // building itself isn't meant to be constructible until War Mode actually ships (see the
        // skill-tree "Modo Guerra" teaser) — keep the button visible (so it doesn't look like it
        // just vanished) but greyed out with an explicit "coming soon" label instead of a cost.
        if (STK_COMING_SOON.has('torreVigilancia')) {
            if (wtLabel) wtLabel.innerHTML = t('stk.coming_soon_label');
            btnWatchtower.disabled = true;
        } else {
            if (wtLabel) wtLabel.innerHTML = renderCostHTML(wtCost);
            btnWatchtower.disabled = wood < wtCost.wood;
        }
    }

    const btnRutaComercial = document.getElementById('btnBuildRutaComercial');
    if (btnRutaComercial) {
        const rcCost = getRutaComercialCost();
        const rcLabel = btnRutaComercial.querySelector('.btn-cost');
        if (rcLabel) rcLabel.innerHTML = renderCostHTML(rcCost);
        const hasRuta = buildings.some(b => b.type === 'ruta_comercial');
        btnRutaComercial.style.display = (hasSkillRutaComercial && !hasRuta) ? 'flex' : 'none';
        btnRutaComercial.disabled = wood < rcCost.wood || stone < (rcCost.stone || 0) || gold < (rcCost.gold || 0);
    }

    const btnTesoreria = document.getElementById('btnBuildTesoreria');
    if (btnTesoreria) {
        const tsCost = getTesoreriaCost();
        const tsLabel = btnTesoreria.querySelector('.btn-cost');
        if (tsLabel) tsLabel.innerHTML = renderCostHTML(tsCost);
        const hasTesoreria = buildings.some(b => b.type === 'tesoreria');
        btnTesoreria.style.display = (hasSkillTesoreria && !hasTesoreria) ? 'flex' : 'none';
        btnTesoreria.disabled = wood < tsCost.wood || stone < (tsCost.stone || 0) || gold < (tsCost.gold || 0);
    }

    const btnMaderoMovil = document.getElementById('btnBuildMaderoMovil');
    if (btnMaderoMovil) {
        const mmCost = getMaderoMovilCost();
        const hasFreeMM = _freeBuildingQueue.includes('maderero_movil');
        const mmLabel = btnMaderoMovil.querySelector('.btn-cost');
        if (mmLabel) mmLabel.innerHTML = hasFreeMM ? `<span style="color:#44cc44">${t('free')}</span>` : renderCostHTML(mmCost);
        btnMaderoMovil.classList.toggle('free-gift', hasFreeMM);
        const hasMaderoMovil = _maderoMovilCount() >= _maderoMovilLimit();
        btnMaderoMovil.style.display = ((hasSkillMadereroMovil || hasFreeMM) && !hasMaderoMovil) ? 'flex' : 'none';
        btnMaderoMovil.disabled = !hasFreeMM && (wood < mmCost.wood || stone < (mmCost.stone || 0));
    }

    const btnSawmill = document.getElementById('btnBuildSawmill');
    if (btnSawmill) {
        const cost = getSawmillCost();
        const alreadyBuilt = buildings.some(b => b.type === 'sawmill');
        const costLabel = btnSawmill.querySelector('.btn-cost');
        if (costLabel) costLabel.innerHTML = renderCostHTML(cost);
        btnSawmill.style.display = (hasSkillAserradero && !alreadyBuilt) ? 'flex' : 'none';
        btnSawmill.disabled = wood < cost.wood || food < cost.food || wool < cost.wool || stone < cost.stone;
    }

    // Update Bakery Button
    const btnBakery = document.getElementById('btnBuildBakery');
    if (btnBakery) {
        const bkCount  = buildings.filter(b => b.type === 'bakery').length;
        const bkMax    = getMaxBakeries();
        const bkCost   = getBakeryCost();
        const costLabel = btnBakery.querySelector('.btn-cost');
        btnBakery.style.display = (hasSkillPanaderia && bkCount < bkMax) ? 'flex' : 'none';
        if (!hasSkillMaestria) {
            if (costLabel) costLabel.innerHTML = t('stk.status.locked', { req: t('skill.maestria.name') });
            btnBakery.disabled = true;
        } else {
            if (costLabel) costLabel.innerHTML = renderCostHTML(bkCost);
            btnBakery.disabled = wood < bkCost.wood || stone < bkCost.stone;
        }
    }

    const btnTeatro = document.getElementById('btnBuildTeatro');
    if (btnTeatro) {
        const tCost = getTeatroCost();
        const tLabel = btnTeatro.querySelector('.btn-cost');
        const alreadyHasTeatro = buildings.some(b => b.type === 'teatro');
        btnTeatro.style.display = (hasSkillTeatro && !alreadyHasTeatro) ? 'flex' : 'none';
        if (!hasSkillMaestria) {
            if (tLabel) tLabel.innerHTML = t('stk.status.locked', { req: t('skill.maestria.name') });
            btnTeatro.disabled = true;
        } else {
            if (tLabel) tLabel.innerHTML = renderCostHTML(tCost);
            btnTeatro.disabled = wood < tCost.wood || stone < tCost.stone;
        }
    }

    const btnRitual = document.getElementById('btnBuildRitual');
    if (btnRitual) {
        const rCost = getRitualCost();
        const rLabel = btnRitual.querySelector('.btn-cost');
        const alreadyHasRitual = buildings.some(b => b.type === 'ritual');
        btnRitual.style.display = (hasSkillRitual && !alreadyHasRitual) ? 'flex' : 'none';
        if (rLabel) rLabel.innerHTML = renderCostHTML(rCost);
        btnRitual.disabled = wood < rCost.wood || stone < rCost.stone;
    }

    // Establo: a diferencia del Teatro, NO es único — cuantos más, más rápido el contador
    // compartido de mulas gratis (ver el bucle "--- ESTABLO UPDATE ---"), así que sin límite de uno.
    const btnEstablo = document.getElementById('btnBuildEstablo');
    if (btnEstablo) {
        const eCost = getEstabloCost();
        const eLabel = btnEstablo.querySelector('.btn-cost');
        btnEstablo.style.display = hasSkillEstablo ? 'flex' : 'none';
        if (eLabel) eLabel.innerHTML = renderCostHTML(eCost);
        btnEstablo.disabled = wood < eCost.wood || food < eCost.food || stone < eCost.stone || gold < eCost.gold;
    }

    // Update Fruit Orchard Button — antes exigía una Granja CONSTRUIDA AHORA MISMO ("me quedé sin
    // granjas y no podía volver a construir huertos" — reporte real). Ahora tutorialStep >= 9
    // ("ya completaste el paso de la Granja alguna vez", permanente, ver el botón de Casa).
    const btnOrchard = document.getElementById('btnBuildFruitOrchard');
    if (btnOrchard) {
        const hasFreeOrchard = _freeBuildingQueue.includes('fruit_orchard');
        const cost = getFruitOrchardCost();
        const costLabel = btnOrchard.querySelector('.btn-cost');
        if (costLabel) costLabel.innerHTML = hasFreeOrchard ? `<span style="color:#44cc44">${t('free')}</span>` : renderCostHTML(cost);
        btnOrchard.classList.toggle('free-gift', hasFreeOrchard);
        btnOrchard.style.display = ((hasSkillArbolFrutal && tutorialStep >= 9) || hasFreeOrchard) ? 'flex' : 'none';
        btnOrchard.disabled = !hasFreeOrchard && (wood < cost.wood || food < cost.food);
    }

    // Update Cotton Plantation Button — antes exigía una Granja de Ovejas CONSTRUIDA AHORA MISMO.
    // La Granja de Ovejas no forma parte del tutorial guiado (se desbloquea por población, no por
    // tutorialStep), así que aquí no hay un umbral equivalente — se quita el requisito del todo,
    // solo queda la mejora del árbol de habilidades.
    const btnCotton = document.getElementById('btnBuildCottonPlantation');
    if (btnCotton) {
        const hasFreeCotton = _freeBuildingQueue.includes('cotton_farm');
        const cost = getCottonPlantationCost();
        const costLabel = btnCotton.querySelector('.btn-cost');
        if (costLabel) costLabel.innerHTML = hasFreeCotton ? `<span style="color:#44cc44">${t('free')}</span>` : renderCostHTML(cost);
        btnCotton.classList.toggle('free-gift', hasFreeCotton);
        btnCotton.style.display = (hasSkillPlantacion || hasFreeCotton) ? 'flex' : 'none';
        btnCotton.disabled = !hasFreeCotton && (wood < cost.wood || food < cost.food);
    }

    // Plantación Forestal — antes exigía un Campamento Maderero (o Móvil) CONSTRUIDO AHORA MISMO.
    // tutorialStep >= 5 ("ya completaste el paso del Campamento Maderero alguna vez", permanente,
    // ver el botón de Casa) cubre lo mismo sin poder volver a esconderse si se demuele.
    const btnForest = document.getElementById('btnBuildForestFarm');
    if (btnForest) {
        const cost = getForestFarmCost();
        const costLabel = btnForest.querySelector('.btn-cost');
        if (costLabel) costLabel.innerHTML = renderCostHTML(cost);
        btnForest.style.display = (hasSkillBosqueCultivado && tutorialStep >= 5) ? 'flex' : 'none';
        btnForest.disabled = food < cost.food || gold < cost.gold;
    }

    // Update Selection Panel — building card and villager card share this one panel/position
    // and are mutually exclusive (see openVillagerInfo/_handleCanvasTap), so only one of
    // #buildingSelContent / #villagerSelContent is ever shown at a time.
    const selPanel = document.getElementById('selectionPanel');
    const buildingSelContent = document.getElementById('buildingSelContent');
    const villagerSelContent = document.getElementById('villagerSelContent');
    if (selPanel) {
        // Mobile: both panels are pinned to the same bottom-of-screen strip (see their own CSS in
        // the MOBILE PORTRAIT block), and the build bar can be taller than the selection panel's
        // own max-height — its top portion (a row of small building chips) would otherwise still
        // peek out behind/above it instead of a clean full takeover. Desktop doesn't need this:
        // the two panels sit in different corners there and never overlap. No explicit "restore"
        // branch needed below — the villagers.length >= 5 check earlier in this same updateUI()
        // call already sets #commandCard's correct baseline display every render; this only ever
        // hides it FURTHER on top of that while a selection is open.
        // "cuando esta seleccionado tu personaje no puedes elegir otro edificio... ni abrir el
        // menu de construir" — el avatar-jugador es distinto de una selección normal: controlarlo
        // es una actividad de fondo que dura un buen rato (caminando por el mapa), no un vistazo
        // rápido a las estadísticas de un edificio/aldeano — bloquear el menú de construir y el
        // minimapa mientras tanto no tiene sentido, así que su ficha queda exenta de las dos cosas
        // de aquí abajo (a diferencia de building/villager normales, que sí las siguen bloqueando).
        const _blockingSelection = (_villagerInfoTarget && _villagerInfoTarget !== _playerAvatar) || selectedBuilding;
        if (_MQ_PORTRAIT.matches && _blockingSelection) {
            const ccForSel = document.getElementById('commandCard');
            if (ccForSel) ccForSel.style.display = 'none';
        }
        // "que se oculte el mapa cuando entro a una ficha de edificio o de aldeano para que no se
        // vea partido por el fondo" — the minimap's own mobile spot (bottom-right, pinned above
        // #commandCard) sits in that same bottom region the selection panel takes over. A CSS
        // class instead of touching minimapContainer.style.display directly (like toggleMinimap
        // does): that would persist to localStorage as "the player hid the map" (see
        // saveMinimapHidden) and fight the tutorial's own fn-tuto-crowded suppression — this is
        // meant to be purely transient, gone the instant the selection closes, same idiom as
        // fn-tuto-crowded itself (see body.fn-selection-crowded in index.css).
        // Tercer contenido posible del panel — el logro fijado. "en móvil no hay pantalla
        // suficiente" para tenerlo siempre a la vista sin apretar todo lo demás (selección,
        // rejilla de construir, minimapa...) — así que en móvil esto NUNCA se muestra, sea cual
        // sea el resto del estado (ver también _togglePinAchievement, que ya ni deja fijar nada
        // desde ahí en primer lugar). El resto de condiciones (sin building/villager seleccionado,
        // sin buildMode activo) siguen aplicando tal cual en desktop, donde sí hay sitio de sobra.
        // Comprobado por adelantado, no dentro del if de abajo, porque fn-selection-crowded
        // necesita saber si va a haber algo que mostrar ANTES de decidir si oculta el minimapa en
        // móvil, igual que ya hace para los otros dos.
        const pinnedAch = !_MQ_PORTRAIT.matches && !_villagerInfoTarget && !selectedBuilding && buildMode === null && _pinnedAchievementId
            ? ACHIEVEMENTS.find(x => x.id === _pinnedAchievementId && !_unlockedAchievements.has(x.id))
            : null;
        document.body.classList.toggle('fn-selection-crowded',
            _MQ_PORTRAIT.matches && !!(_blockingSelection || pinnedAch));
        // Sin building/villager seleccionado, el panel solo enseña el logro fijado — mucho más
        // ligero que la ficha completa, así que en móvil no necesita el z-index alto que sí hace
        // falta para tapar el HUD mientras se interactúa con un edificio (ver el 300 !important
        // de #selectionPanel en la media query); ahí solo estorba, tapando cosas como el
        // acelerador de boost offline. Esta clase le baja el z-index SOLO en ese caso.
        selPanel.classList.toggle('fn-pinned-ach-only', !!pinnedAch);
        const pinnedAchContent = document.getElementById('pinnedAchContent');
        if (_villagerInfoTarget) {
            requestAnimationFrame(() => selPanel.classList.add('visible'));
            if (buildingSelContent) buildingSelContent.style.display = 'none';
            if (villagerSelContent) villagerSelContent.style.display = '';
            if (pinnedAchContent) pinnedAchContent.style.display = 'none';
            _renderVillagerInfo();
        } else if (selectedBuilding) {
            requestAnimationFrame(() => selPanel.classList.add('visible'));
            if (buildingSelContent) buildingSelContent.style.display = '';
            if (villagerSelContent) villagerSelContent.style.display = 'none';
            if (pinnedAchContent) pinnedAchContent.style.display = 'none';

            const nameSpan   = document.getElementById('selectionName');
            const iconSpan   = document.getElementById('selectionIcon');
            const statusSpan = document.getElementById('selectionStatus');
            const btnDestroy = document.getElementById('btnDestroyBuilding');

            const _desc = getBuildingDescriptor(selectedBuilding);
            if (nameSpan)   nameSpan.innerText   = _desc.name;
            const _muleIco = _muleSkinIcon(selectedBuilding);
            if (iconSpan)   iconSpan.innerHTML   = _muleIco ? `<img class="selection-icon-img mule-skin-icon" src="${_muleIco}" alt="">` : _desc.icon;
            if (statusSpan) statusSpan.innerHTML = renderSelectionStatus(_desc);
            const kindSpan = document.getElementById('selectionKind');
            if (kindSpan) kindSpan.innerHTML = _buildingKindHTML(selectedBuilding.type);   // Urbano / Rural, en la esquina de la cabecera
            if (btnDestroy) btnDestroy.style.display = (_desc.canDestroy !== false) ? 'block' : 'none';
            const workersSpan = document.getElementById('selectionWorkers');
            if (workersSpan) {
                const w = _desc.workers;
                // max 0 = sin tope (el dique seco: acarrean todos los aldeanos libres). Ahí no hay
                // "3/0" que enseñar, solo cuántos están trabajando ahora mismo.
                workersSpan.innerText = w
                    ? (w.max ? t(w.max !== 1 ? 'workers.plural' : 'workers.singular', { cur: w.current, max: w.max })
                             : t('workers.uncapped', { cur: w.current }))
                    : '';
            }

            // Teatro worker +/- buttons
            const btnTeatroWorkers = document.getElementById('btnTeatroWorkers');
            if (btnTeatroWorkers) {
                if (selectedBuilding && selectedBuilding.type === 'teatro') {
                    const maxW = hasSkillTeatroCapacidad ? 20 : 10;
                    const cur = villagers.filter(v => v.farmTarget === selectedBuilding && v.state === 'teatro_working').length;
                    const hasIdle = villagers.some(v => !v.farmTarget);
                    btnTeatroWorkers.style.display = 'flex';
                    const btnAdd = document.getElementById('btnTeatroAdd');
                    const btnRem = document.getElementById('btnTeatroRemove');
                    const lbl = document.getElementById('btnTeatroCount');
                    _setStepperLabel(lbl, 'fa-masks-theater', t('teatro.workers_label'), cur, maxW);
                    if (btnAdd) btnAdd.disabled = cur >= maxW || !hasIdle;
                    if (btnRem) btnRem.disabled = cur <= 0;
                } else {
                    btnTeatroWorkers.style.display = 'none';
                }
            }

            // Ritual: oficiantes (+/- hasta 5, mismo patrón que el Teatro), víctima (elegir/quitar)
            // y el botón "Iniciar Ritual" — todo se bloquea (disabled, no oculto) mientras
            // selectedBuilding._started, así que nada cambia a media ceremonia.
            const btnRitualWorkers = document.getElementById('btnRitualWorkers');
            if (btnRitualWorkers) {
                if (selectedBuilding && selectedBuilding.type === 'ritual') {
                    const started = !!selectedBuilding._phase;
                    const hasVictim = !!(_ritualVictimVillager(selectedBuilding) || _ritualVictimMule(selectedBuilding));
                    const cur = villagers.filter(v => v.farmTarget === selectedBuilding && v.state === 'ritual_working').length;
                    const hasIdle = villagers.some(v => !v.farmTarget);
                    // Oculto del todo hasta elegir al elegido — salvo que ya hubiera oficiantes
                    // asignados de antes (p.ej. se quitó al elegido después), para poder quitarlos.
                    btnRitualWorkers.style.display = (hasVictim || cur > 0) ? 'flex' : 'none';
                    const btnAdd = document.getElementById('btnRitualAdd');
                    const btnRem = document.getElementById('btnRitualRemove');
                    const lbl = document.getElementById('btnRitualCount');
                    _setStepperLabel(lbl, 'fa-skull', t('ritual.workers_label'), cur, RITUAL_WORKERS_MAX);
                    if (btnAdd) btnAdd.disabled = started || !hasVictim || cur >= RITUAL_WORKERS_MAX || !hasIdle;
                    if (btnRem) btnRem.disabled = started || cur <= 0;
                } else {
                    btnRitualWorkers.style.display = 'none';
                }
            }
            const ritualVictimRow = document.getElementById('ritualVictimRow');
            if (ritualVictimRow) {
                if (selectedBuilding && selectedBuilding.type === 'ritual') {
                    const started = !!selectedBuilding._phase;
                    const victimV = _ritualVictimVillager(selectedBuilding);
                    const victimM = _ritualVictimMule(selectedBuilding);
                    const hasVictim = !!(victimV || victimM);
                    ritualVictimRow.style.display = 'flex';
                    const lbl = document.getElementById('ritualVictimLabel');
                    if (lbl) lbl.textContent = victimV ? victimV.name : (victimM ? t('ritual.victim_mule') : t('ritual.victim_none'));
                    const btnChoose = document.getElementById('btnRitualChooseVictim');
                    const btnRemove = document.getElementById('btnRitualRemoveVictim');
                    if (btnChoose) btnChoose.style.display = hasVictim ? 'none' : 'flex';
                    if (btnRemove) { btnRemove.style.display = hasVictim ? 'flex' : 'none'; btnRemove.disabled = started; }
                } else {
                    ritualVictimRow.style.display = 'none';
                }
            }
            const btnRitualStart = document.getElementById('btnRitualStart');
            if (btnRitualStart) {
                if (selectedBuilding && selectedBuilding.type === 'ritual') {
                    const started = !!selectedBuilding._phase;
                    // No basta con tener los 5 oficiantes asignados — deben haber LLEGADO a su puesto,
                    // y lo mismo la víctima ("que no se pueda iniciar si no está ya en su sitio").
                    btnRitualStart.style.display = (!started && _ritualVictimReady(selectedBuilding) && _ritualWorkersReady(selectedBuilding)) ? 'flex' : 'none';
                } else {
                    btnRitualStart.style.display = 'none';
                }
            }

            // Establo mule +/- buttons — mismo patrón que el Teatro, tope fijo de 2.
            const btnEstabloMules = document.getElementById('btnEstabloMules');
            if (btnEstabloMules) {
                if (selectedBuilding && selectedBuilding.type === 'establo') {
                    const cur = _establoOccupants(selectedBuilding).length;
                    const hasFree = mules.some(m => m.state !== 'stabled' && m.state !== 'to_stable');
                    btnEstabloMules.style.display = 'flex';
                    const btnAdd = document.getElementById('btnEstabloAdd');
                    const btnRem = document.getElementById('btnEstabloRemove');
                    const lbl = document.getElementById('btnEstabloCount');
                    const _muleSk = _muleHomeAnimal(selectedBuilding);
                    _setStepperLabel(lbl, 'fa-horse', _muleSk ? t('skin.' + _muleSk) : t('establo.workers_label'), cur, 2, _muleSkinIcon(selectedBuilding));
                    if (btnAdd) btnAdd.disabled = cur >= 2 || !hasFree;
                    if (btnRem) btnRem.disabled = cur <= 0;
                } else {
                    btnEstabloMules.style.display = 'none';
                }
            }

        } else if (pinnedAch) {
            requestAnimationFrame(() => selPanel.classList.add('visible'));
            if (buildingSelContent) buildingSelContent.style.display = 'none';
            if (villagerSelContent) villagerSelContent.style.display = 'none';
            if (pinnedAchContent) { pinnedAchContent.style.display = ''; pinnedAchContent.innerHTML = _achCardHTML(pinnedAch); }
        } else {
            if (pinnedAchContent) pinnedAchContent.style.display = 'none';
            selPanel.classList.remove('visible');
            _hideWstatTooltip();
        }
    }
    
    // Show/Hide and update technology upgrades based on Lumber Camp existence
    const hasLumberCamp = buildings.some(b => b.type === 'lumber_camp' || b.type === 'maderero_movil');


    // Los botones de debug del dique (vaciar 50 % / llenar / reiniciar fase) ya no existen en el
    // panel; debugDrainHalf(), debugFillDock() y debugResetShipStage() siguen disponibles desde la consola.
    // --- Mejoras del Puerto (fase 2) ---
    // Mismo patrón que el hacha justo debajo, hasta en el texto: "Mejorar X - Nv.N" con las cifras
    // de antes y después en pequeño. Viven en el panel de selección y solo aparecen con el PUERTO
    // seleccionado, porque son mejoras suyas. Se ocultan cuando el dique ya está seco: a partir de
    // ahí no hay agua que acarrear.
    //
    // Ninguna de las dos tiene tope de niveles, igual que el hacha: las limita su precio, que sube
    // ×1,5 por nivel. Y suben un 10% en vez del 5% habitual porque son exclusivas de esta fase —
    // no hay una partida entera por delante para amortizarlas.
    const _dkU = _dryDock();
    const _prU = _waterPort();
    const _showDockUpg = !!selectedBuilding && selectedBuilding.type === 'water_port' &&
                         !!_dkU && !!_prU && !_dryDockIsDry(_dkU);   // solo mientras quede agua
    // Parte común a las dos: lo que aporta la carretilla y los multiplicadores de aldeano.
    const _capBase  = (DRYDOCK_LITRES_PER_TRIP + barrowUpgradeLevel * 2) * cachedCapMult * cachedPCap;
    const _rateBase = DRYDOCK_RATE_PER_SEC * _dryDockRateMult();

    const btnDockBuckets = document.getElementById('btnUpgradeDryDock');
    if (btnDockBuckets) {
        btnDockBuckets.style.display = _showDockUpg ? 'flex' : 'none';
        if (_showDockUpg) {
            const lvl = fase2CapLevel + 1;
            // De _dryDockLitresPerTrip, la MISMA que usa el acarreo: con _capBase faltaba la
            // iglesia y el botón enseñaba menos litros de los que se cargan de verdad.
            const cur = _dryDockLitresPerTrip();
            const nxt = cur * DRYDOCK_UPG_STEP;
            const c = getDryDockUpgradeCost();
            const lbl = document.getElementById('dryDockUpgLabel');
            const cst = document.getElementById('dryDockUpgCost');
            if (lbl) lbl.innerHTML = t('upg.label.upgrade', { tool: t('upg.tool.buckets'), n: lvl }) +
                `<br><small style="opacity:.8">${t('upg.label.capacity', { cur: `${Math.round(cur)} L`, nxt: `${Math.round(nxt)} L` })}</small>`;
            if (cst) cst.innerHTML = renderCostHTML(c);
            btnDockBuckets.disabled = wood < c.wood || gold < c.gold;
        }
    }

    const btnDockSpeed = document.getElementById('btnUpgradeDockSpeed');
    if (btnDockSpeed) {
        btnDockSpeed.style.display = _showDockUpg ? 'flex' : 'none';
        if (_showDockUpg) {
            const lvl = fase2RitmoLevel + 1;
            const cur = _rateBase * Math.pow(DRYDOCK_SPEED_STEP, fase2RitmoLevel);
            const nxt = _rateBase * Math.pow(DRYDOCK_SPEED_STEP, lvl);
            const c = getDryDockSpeedCost();
            const lbl = document.getElementById('dockSpeedLabel');
            const cst = document.getElementById('dockSpeedCost');
            if (lbl) lbl.innerHTML = t('upg.label.upgrade', { tool: t('upg.tool.handling'), n: lvl }) +
                `<br><small style="opacity:.8">${t('upg.label.flow', { cur: `${Math.round(cur)} L/s`, nxt: `${Math.round(nxt)} L/s` })}</small>`;
            if (cst) cst.innerHTML = renderCostHTML(c);
            btnDockSpeed.disabled = stone < c.stone || gold < c.gold;
        }
    }

    // Con el dique YA SECO el puerto cambia de oficio y estos dos botones toman el relevo de los
    // de arriba en el mismo hueco — pero suben las MISMAS dos mejoras únicas (fase2CapLevel /
    // fase2RitmoLevel, ver FASE2_UPG_STEP); solo cambia qué cifra enseñan: carga y descarga de
    // material en vez de litros y caudal.
    const _showShipUpg = !!selectedBuilding && selectedBuilding.type === 'water_port' &&
                         !!_dkU && !!_prU && _dryDockIsDry(_dkU) && !_shipIsReady(_dkU);
    const btnCart = document.getElementById('btnUpgradeShipCart');
    if (btnCart) {
        btnCart.style.display = _showShipUpg ? 'flex' : 'none';
        if (_showShipUpg) {
            const c = getShipCartCost();
            const lbl = document.getElementById('shipCartLabel');
            const cst = document.getElementById('shipCartCost');
            // _shipCarryAmount, la MISMA que decide cuánto coge cada aldeano: antes se calculaba
            // sin la iglesia y el botón decía 962 → 1058 mientras cargaban ~2000 por viaje.
            const cur = _shipCarryAmount();
            const nxt = Math.max(1, Math.round(cachedBaseCapWood * Math.pow(SHIP_UPG_STEP, fase2CapLevel + 1) * cachedChurchMult));
            if (lbl) lbl.innerHTML = t('upg.label.upgrade', { tool: t('upg.tool.cart'), n: fase2CapLevel + 1 }) +
                `<br><small style="opacity:.8">${t('upg.label.capacity', { cur, nxt })}</small>`;
            if (cst) cst.innerHTML = renderCostHTML(c);
            btnCart.disabled = wood < c.wood || gold < c.gold;
        }
    }
    const btnHammer = document.getElementById('btnUpgradeShipHammer');
    if (btnHammer) {
        btnHammer.style.display = _showShipUpg ? 'flex' : 'none';
        if (_showShipUpg) {
            const c = getShipHammerCost();
            const lbl = document.getElementById('shipHammerLabel');
            const cst = document.getElementById('shipHammerCost');
            // Se enseña con la madera (10 s base), que es el caso largo y el que se nota.
            const cur = (10 / _shipHammerMult()).toFixed(1);
            const nxt = (10 / Math.pow(SHIP_UPG_STEP, fase2RitmoLevel + 1)).toFixed(1);
            if (lbl) lbl.innerHTML = t('upg.label.upgrade', { tool: t('upg.tool.hammer'), n: fase2RitmoLevel + 1 }) +
                `<br><small style="opacity:.8">${t('upg.label.filltime', { cur, nxt })}</small>`;
            if (cst) cst.innerHTML = renderCostHTML(c);
            btnHammer.disabled = stone < c.stone || gold < c.gold;
        }
    }

    const btnAxe = document.getElementById('btnUpgradeAxe');
    const btnBarrow = document.getElementById('btnUpgradeBarrow');

    if (btnAxe) {
        btnAxe.style.display = (selectedBuilding && (selectedBuilding.type === 'lumber_camp' || selectedBuilding.type === 'maderero_movil')) ? 'flex' : 'none';
        if (hasLumberCamp) {
            const cost = getAxeUpgradeCost();
            const label = btnAxe.querySelector('.btn-label');
            const costLabel = btnAxe.querySelector('.btn-cost');
            
            const lvl = axeUpgradeLevel + 1;
            label.innerHTML = t('upg.label.upgrade', { tool: t('upg.tool.axe'), n: lvl })
                + `<br><small style="opacity:.8">${getAxeUpgradeStats(lvl).join('<br>')}<br>${t('upg.affects.one', { a: t('villagerInfo.job.lumber') })}</small>`;
            costLabel.innerHTML = renderCostHTML(cost);
            btnAxe.disabled = wood < cost.wood || food < cost.food || wool < cost.wool;
        }
    }
    
    const hasQuarry = buildings.some(b => b.type === 'stone_quarry');
    const btnPickaxe = document.getElementById('btnUpgradePickaxe');
    if (btnPickaxe) {
        const showAtLumber = selectedBuilding && (selectedBuilding.type === 'lumber_camp' || selectedBuilding.type === 'maderero_movil') && hasSkillCanteraLogistica;
        const showAtQuarry = selectedBuilding && selectedBuilding.type === 'stone_quarry' && _retoPickaxeAtQuarry();
        btnPickaxe.style.display = (showAtLumber || showAtQuarry) ? 'flex' : 'none';
        if (hasQuarry || (hasSkillCanteraLogistica && hasLumberCamp)) {
            const cost = getPickaxeUpgradeCost();
            const label = btnPickaxe.querySelector('.btn-label');
            const costLabel = btnPickaxe.querySelector('.btn-cost');
            
            const lvl = pickaxeUpgradeLevel + 1;
            // Especialmente útil aquí: este botón vive en el Campamento Maderero (ver
            // showAtLumber arriba), no en la Cantera — sin la aclaración de a quién mejora, un
            // jugador viendo "Pico" en el panel del leñador podría pensar que sube su propia tala.
            label.innerHTML = t('upg.label.upgrade', { tool: t('upg.tool.pickaxe'), n: lvl })
                + `<br><small style="opacity:.8">${getPickaxeUpgradeStats(lvl).join('<br>')}<br>${t('upg.affects.one', { a: t('villagerInfo.job.mine') })}</small>`;
            costLabel.innerHTML = renderCostHTML(cost);
            btnPickaxe.disabled = wood < cost.wood || food < cost.food || wool < cost.wool;
        }
    }
    
    const btnRecruitMule = document.getElementById('btnRecruitMule');
    if (btnRecruitMule) {
        // En los mundos con barcas (mundo 2) el botón construye una barca, no una mula: icono de velero
        const _muleIco = btnRecruitMule.querySelector('.btn-icon i');
        if (_muleIco) _muleIco.className = _harborsOn() ? 'fa-solid fa-sailboat' : 'fa-solid fa-horse';
        const isRuta = selectedBuilding && selectedBuilding.type === 'ruta_comercial';
        btnRecruitMule.style.display = isRuta ? 'flex' : 'none';
        if (isRuta) {
            const mwc = getMuleWoodCost();
            const mfc = getMuleFoodCost();
            const mwlc = getMuleWoolCost();
            const mgc = getMuleGoldCost();
            const costLabel = btnRecruitMule.querySelector('.btn-cost');
            const atPop = _popUsada() >= popLimit;
            if (costLabel) {
                costLabel.innerHTML = renderCostHTML({ wood: mwc, food: mfc, wool: mwlc, gold: mgc })
                    + (atPop ? `<br><span style="color:var(--warning);font-weight:600;font-size:10px;white-space:normal;display:inline-block;line-height:1.3;">${t('recruit.cap_warning')}</span>` : '');
            }
            btnRecruitMule.style.outline = atPop ? '2px solid var(--warning)' : '';
            btnRecruitMule.disabled = atPop || wood < mwc || food < mfc || wool < mwlc || gold < mgc;
        }
    }

    // Mula pagada con almas — vía alternativa, no sustituye a la de arriba. Mismo criterio de
    // visibilidad que el resto de lo relacionado con almas: sin saldo, no se enseña.
    const btnRecruitMuleSouls = document.getElementById('btnRecruitMuleSouls');
    if (btnRecruitMuleSouls) {
        const isRutaS = selectedBuilding && selectedBuilding.type === 'ruta_comercial' && !_harborsOn();   // las barcas (Mundo 2) no se compran con almas
        btnRecruitMuleSouls.style.display = (isRutaS && souls > 0) ? 'flex' : 'none';
        if (isRutaS && souls > 0) {
            const atPopS = _popUsada() >= popLimit;
            const costLabelS = btnRecruitMuleSouls.querySelector('.btn-cost');
            if (costLabelS) {
                costLabelS.innerHTML = `<i class="fa-solid fa-ghost"></i> ${t('recruit.cost_souls', { cost: SOULS_COST })}`
                    + (atPopS ? `<br><span style="color:var(--warning);font-weight:600;font-size:10px;white-space:normal;display:inline-block;line-height:1.3;">${t('recruit.cap_warning')}</span>` : '');
            }
            btnRecruitMuleSouls.style.outline = atPopS ? '2px solid var(--warning)' : '';
            btnRecruitMuleSouls.disabled = atPopS || souls < SOULS_COST;
        }
    }

    const btnUpgradeMuleSpeed = document.getElementById('btnUpgradeMuleSpeed');
    if (btnUpgradeMuleSpeed) {
        const isRuta2 = selectedBuilding && selectedBuilding.type === 'ruta_comercial';
        btnUpgradeMuleSpeed.style.display = isRuta2 ? 'flex' : 'none';
        if (isRuta2) {
            const msc = getMuleSpeedUpgradeCost();
            const label = btnUpgradeMuleSpeed.querySelector('.btn-label');
            const costLabel = btnUpgradeMuleSpeed.querySelector('.btn-cost');
            // Ruedas sube las DOS cosas a la vez (ver getMuleSpeedMult/getMuleLoadMult), así que
            // la etiqueta las enseña las dos: anunciar solo velocidad escondía la mitad de lo que
            // se está comprando. Velocidad y carga van por separado porque el reparto es un dial
            // (MULE_WHEELS_SPEED_SHARE) y no tienen por qué coincidir siempre.
            const _n = muleSpeedUpgradeLevel + 1;
            const curSpd = Math.round(getMuleSpeedMult() * 100);
            const nxtSpd = Math.round(Math.pow(1.05, _n * MULE_WHEELS_SPEED_SHARE) * 100);
            const curLoad = Math.round(getMuleLoadMult() * 100);
            const nxtLoad = Math.round(Math.pow(1.05, _n * (1 - MULE_WHEELS_SPEED_SHARE)) * 100);
            // Con el nivel delante, igual que Hacha/Azada/Pico/Carretilla (ver los otros botones de
            // mejora, todos con t('upg.label.upgrade')): Ruedas era la única mejora de nivel que no
            // decía en cuál estás, y sin eso no hay forma de saber cuánto llevas invertido.
            // `_n` es el nivel que se COMPRA, no el actual — misma convención que el resto.
            if (label) label.innerHTML = t('upg.label.upgrade', { tool: t('mule.upg_wheels'), n: _n })
                + `<br><small style="opacity:.8">${t('upg.label.speed', { cur: curSpd, nxt: nxtSpd })}<br>${t('upg.label.load', { cur: curLoad, nxt: nxtLoad })}</small>`;
            if (costLabel) costLabel.innerHTML = renderCostHTML(msc);
            btnUpgradeMuleSpeed.disabled = wood < msc.wood || wool < msc.wool || gold < msc.gold;
        }
    }

    if (btnBarrow) {
        // Con trinquete (ver _upgReveal): la condición solo sirve para no enseñarla en el primer
        // minuto; demoler el campamento después no la esconde.
        btnBarrow.style.display = (selectedBuilding && selectedBuilding.type === 'town_center' && _upgReveal('barrow', villagers.length >= 6 && hasLumberCamp)) ? 'flex' : 'none';
        const cost = getBarrowUpgradeCost();
        const label = btnBarrow.querySelector('.btn-label');
        const costLabel = btnBarrow.querySelector('.btn-cost');
        const lvlB = barrowUpgradeLevel + 1;
        // La única de las cinco que sube la capacidad de TODOS los oficios de recolección a la
        // vez (ver barrCap en rebuildVillagerStatCaches) — de ahí upg.affects.all en vez de
        // enumerar leñador/granjero/frutero/minero/pastor/algodonero uno a uno.
        label.innerHTML = t('upg.label.upgrade', { tool: t('upg.tool.transport'), n: lvlB })
            + `<br><small style="opacity:.8">${getBarrowUpgradeStats(lvlB).join('<br>')}<br>${t('upg.affects.all')}</small>`;
        costLabel.innerHTML = renderCostHTML(cost);
        btnBarrow.disabled = wood < cost.wood || food < cost.food || wool < cost.wool;
    }

    _updatePhase2UI();   // fase 2: dique, cubos, barco y zarpar — ver su propia función

    // Show/Hide and update Farm upgrades based on Mill existence
    const hasMill = buildings.some(b => b.type === 'mill');
    const btnUpgradeFarm = document.getElementById('btnUpgradeFarm');
    if (btnUpgradeFarm) {
        btnUpgradeFarm.style.display = (selectedBuilding && selectedBuilding.type === 'mill') ? 'flex' : 'none';
        if (hasMill) {
            const cost = getFarmUpgradeCost();
            const label = btnUpgradeFarm.querySelector('.btn-label');
            const costLabel = btnUpgradeFarm.querySelector('.btn-cost');
            
            const lvl = farmUpgradeLevel + 1;
            // t('wstat.bd.tool_hoe'), no t('upg.tool.farms') — con esto y el rate breakdown de
            // granjas/huertos (ver 'farm'/'fruit_orchard' en _workerStatsFor) ya solo hay un
            // nombre para la misma herramienta, no dos ("Hoe" en uno, "Upgrade Farm" en el otro).
            // El aviso de a quién mejora hace falta AQUÍ y no en Hacha/Pico porque el Molino no
            // tiene trabajadores propios donde ya sea obvio (y de hecho son DOS oficios, no uno).
            label.innerHTML = t('upg.label.upgrade', { tool: t('wstat.bd.tool_hoe'), n: lvl })
                + `<br><small style="opacity:.8">${getFarmUpgradeStats(lvl).join('<br>')}<br>${t('upg.affects.two', { a: t('villagerInfo.job.farm'), b: t('villagerInfo.job.orchard') })}</small>`;
            costLabel.innerHTML = renderCostHTML(cost);
            btnUpgradeFarm.disabled = wood < cost.wood || food < cost.food || wool < cost.wool;
        }
    }
    
    // Caña de pescar: en el granero (Molino o Molino de Agua), como la Azada y el Cayado, en cuanto
    // hay algún Pescador (con trinquete: vista una vez, se queda — ver _upgReveal).
    const btnUpgradeFishRod = document.getElementById('btnUpgradeFishRod');
    if (btnUpgradeFishRod) {
        const hasFisher = _upgReveal('fish_rod', buildings.some(b => b.type === 'fisher_hut'));
        const onFisher = !!(selectedBuilding && selectedBuilding.type === 'mill' && hasFisher);   // la caña solo se mejora en el Molino
        btnUpgradeFishRod.style.display = onFisher ? 'flex' : 'none';
        if (onFisher) {
            const cost = getFishRodCost(), lvl = fishRodLevel + 1;
            btnUpgradeFishRod.querySelector('.btn-label').innerHTML = t('upg.label.upgrade', { tool: t('wstat.bd.tool_rod'), n: lvl })
                + `<br><small style="opacity:.8">${getFishRodStats(lvl).join('<br>')}<br>${t('upg.affects.one', { a: t('villagerInfo.job.fish') })}</small>`;
            btnUpgradeFishRod.querySelector('.btn-cost').innerHTML = renderCostHTML(cost);
            btnUpgradeFishRod.disabled = wood < cost.wood || food < cost.food || wool < cost.wool;
        }
    }

    // Show/Hide and update Shepherd upgrades based on Mill and Sheep Farm existence
    const btnUpgradeShepherd = document.getElementById('btnUpgradeShepherd');
    if (btnUpgradeShepherd) {
        // Ovejas O algodón (el Cayado mejora a los dos oficios), y con trinquete: visto una vez,
        // se queda aunque se demuelan (ver _upgReveal).
        const hasSheepFarm = _upgReveal('shepherd', buildings.some(b => b.type === 'sheep_farm' || b.type === 'cotton_farm'));
        btnUpgradeShepherd.style.display = (selectedBuilding && selectedBuilding.type === 'mill' && hasSheepFarm) ? 'flex' : 'none';
        if (selectedBuilding && selectedBuilding.type === 'mill' && hasSheepFarm) {
            const cost = getShepherdUpgradeCost();
            const label = btnUpgradeShepherd.querySelector('.btn-label');
            const costLabel = btnUpgradeShepherd.querySelector('.btn-cost');
            
            const lvl = shepherdUpgradeLevel + 1;
            // Igual que la Azada: se compra en el Molino y mejora DOS oficios, no uno (ver
            // 'sheep_farm'/'cotton_farm' en _workerStatsFor, ambos leen shepherdUpgradeLevel).
            // t('wstat.bd.tool_staff'), no t('upg.tool.shepherd') — mismo motivo que la Azada:
            // el rate breakdown de esos dos oficios ya dice "Cayado/Staff", no "Pastoreo/Herding".
            label.innerHTML = t('upg.label.upgrade', { tool: t('wstat.bd.tool_staff'), n: lvl })
                + `<br><small style="opacity:.8">${getShepherdUpgradeStats(lvl).join('<br>')}<br>${t('upg.affects.two', { a: t('villagerInfo.job.herd'), b: t('villagerInfo.job.cotton') })}</small>`;
            costLabel.innerHTML = renderCostHTML(cost);
            btnUpgradeShepherd.disabled = wood < cost.wood || food < cost.food || wool < cost.wool;
        }
    }
    
    // Update Tavern Button
    const btnTavern = document.getElementById('btnBuildTavern');
    // Cuenta, no "hay alguna": con Segunda Taberna el tope es 2 (ver _maxTaverns).
    const nTaverns = buildings.filter(b => b.type === 'tavern').length;
    if (btnTavern) {
        const cost = getTavernCost();
        const costLabel = btnTavern.querySelector('.btn-cost');
        btnTavern.style.display = (hasSkillTaberna && nTaverns < _maxTaverns()) ? 'flex' : 'none';
        if (!hasSkillMaestria) {
            if (costLabel) costLabel.innerHTML = t('stk.status.locked', { req: t('skill.maestria.name') });
            btnTavern.disabled = true;
        } else {
            if (costLabel) costLabel.innerHTML = renderCostHTML(cost);
            btnTavern.disabled = wood < cost.wood || food < cost.food || stone < (cost.stone || 0);
        }
    }
    
    // Tavern upgrades now shown inline in the descriptor panel — hide legacy sidebar buttons
    const btnBeds = document.getElementById('btnUpgradeBeds');
    if (btnBeds) btnBeds.style.display = 'none';
    const btnCrit = document.getElementById('btnUpgradeCrit');
    if (btnCrit) btnCrit.style.display = 'none';

    // Update Market Buttons
    const btnMarket = document.getElementById('btnBuildMarket');
    const hasMarket = buildings.some(b => b.type === 'market');
    if (btnMarket) {
        const cost = getMarketCost();
        const costLabel = btnMarket.querySelector('.btn-cost');
        if (costLabel) {
            // getMarketCost() already returns all-zero for Banca Real, so the disabled check below
            // stays correct either way — this only changes the label from "0 0 0" to a clean "Free".
            costLabel.innerHTML = prestige.marketFromStart
                ? `<span style="color:#44cc44">${t('free')}</span>`
                : renderCostHTML(cost);
        }
        btnMarket.classList.toggle('free-gift', !!prestige.marketFromStart);
        // Banca Real (Legado): the Market is buildable from the very start, no gremioMercaderes needed.
        btnMarket.style.display = ((hasSkillGremioMercaderes || prestige.marketFromStart) && !hasMarket) ? 'flex' : 'none';
        btnMarket.disabled = wood < cost.wood || food < cost.food || wool < (cost.wool || 0);
    }
    
    // Update Quarry Button
    const btnQuarry = document.getElementById('btnBuildQuarry');
    if (btnQuarry) {
        const qCost = getQuarryCost();
        const hasFreeQuarry = _freeBuildingQueue.includes('stone_quarry');
        const costLabel = btnQuarry.querySelector('.btn-cost');
        if (costLabel) {
            costLabel.innerHTML = hasFreeQuarry
                ? `<span style="color:#44cc44">${t('free')}</span>`
                : renderCostHTML(qCost);
        }
        btnQuarry.classList.toggle('free-gift', hasFreeQuarry);
        btnQuarry.style.display = (hasSkillArtePiedra || hasFreeQuarry) ? 'flex' : 'none';
        btnQuarry.disabled = !hasFreeQuarry && (wood < qCost.wood || food < qCost.food);
    }
    
    // Update Estatua de Ofrendas buttons — chain unlock: each unlocks the next
    {
        const _estatuaDefs = [
            { btn: 'btnEstatuaMadera', cost: 'costEstatuaMadera', show: hasSkillEstatuaOfrenda && !estatuaMaderaX2,                    c: { wood: 30000000 },  canAfford: wood  >= 30000000 },
            { btn: 'btnEstatuaComida', cost: 'costEstatuaComida', show: hasSkillEstatuaOfrenda && estatuaMaderaX2 && !estatuaComida,     c: { food: 10000000 },  canAfford: food  >= 10000000 },
            { btn: 'btnEstatuaTela',   cost: 'costEstatuaTela',   show: hasSkillEstatuaOfrenda && estatuaComida  && !estatuaTela,        c: { wool: 5000000 },   canAfford: wool  >= 5000000  },
            { btn: 'btnEstatuaPiedra', cost: 'costEstatuaPiedra', show: hasSkillEstatuaOfrenda && estatuaTela    && !estatuaPiedra,      c: { stone: 2000000 },  canAfford: stone >= 2000000  },
        ];
        for (const d of _estatuaDefs) {
            const btn = document.getElementById(d.btn);
            if (!btn) continue;
            btn.style.display = d.show ? 'flex' : 'none';
            if (d.show) {
                const costEl = document.getElementById(d.cost);
                if (costEl) costEl.innerHTML = renderCostHTML(d.c);
                btn.disabled = !d.canAfford;
            }
        }
    }

    // Update Church Button
    const btnChurch = document.getElementById('btnBuildChurch');
    if (btnChurch) {
        const hasChurch = buildings.some(b => b.type === 'church');
        const churchCost = getChurchCost();
        const churchCostLabel = btnChurch.querySelector('.btn-cost');
        btnChurch.style.display = (hasSkillIglesia && !hasChurch) ? 'flex' : 'none';
        if (!hasSkillMaestria) {
            if (churchCostLabel) churchCostLabel.innerHTML = t('stk.status.locked', { req: t('skill.maestria.name') });
            btnChurch.disabled = true;
        } else {
            if (churchCostLabel) churchCostLabel.innerHTML = renderCostHTML(churchCost);
            btnChurch.disabled = stone < churchCost.stone;
        }
    }
    
    // Update Constructor Button
    const btnConstructor = document.getElementById('btnBuildConstructor');
    if (btnConstructor) {
        const cost = getConstructorCost();
        btnConstructor.style.display = (hasSkillMaestria && !hasConstructorBuilding) ? 'flex' : 'none';
        btnConstructor.disabled = wood < cost.wood || food < (cost.food || 0) || stone < (cost.stone || 0);
        const cEl = document.getElementById('btnConstructorCost');
        if (cEl) cEl.innerHTML = renderCostHTML(cost);
    }

    // Constructor refund upgrade button
    const btnUpgradeConstructorRefund = document.getElementById('btnUpgradeConstructorRefund');
    if (btnUpgradeConstructorRefund) {
        const showBtn = selectedBuilding && selectedBuilding.type === 'constructor';
        btnUpgradeConstructorRefund.style.display = showBtn ? 'flex' : 'none';
        if (showBtn) {
            const cost = getConstructorUpgradeCost();
            const label = btnUpgradeConstructorRefund.querySelector('.btn-label');
            const costLabel = btnUpgradeConstructorRefund.querySelector('.btn-cost');
            if (constructorUpgradeLevel >= 2) {
                label.innerText = t('upg.constructor.max');
                costLabel.innerHTML = `<span style="color: #c5a059; font-weight: bold;">${t('upg.completed')}</span>`;
                btnUpgradeConstructorRefund.disabled = true;
            } else {
                const nextPct = 50 + constructorUpgradeLevel * 25;
                label.innerText = t('upg.constructor', { pct: nextPct, lvl: constructorUpgradeLevel + 1 });
                costLabel.innerHTML = renderCostHTML({ wood: cost.wood, stone: cost.stone });
                btnUpgradeConstructorRefund.disabled = wood < cost.wood || stone < cost.stone;
            }
        }
    }

    // Constructor discount upgrade button
    const btnConstrDisc = document.getElementById('btnUpgradeConstructorDiscount');
    if (btnConstrDisc) {
        const showBtn = selectedBuilding && selectedBuilding.type === 'constructor';
        btnConstrDisc.style.display = showBtn ? 'flex' : 'none';
        if (showBtn) {
            const cost = getConstructorDiscountCost();
            const lbl  = document.getElementById('lblConstructorDiscount');
            const cLbl = document.getElementById('costConstructorDiscount');
            const pct  = _fmtPct(1 - Math.pow(0.985, constructorDiscountLevel + 1));
            if (lbl) lbl.innerText = t('upg.constructor_discount', { pct, lvl: constructorDiscountLevel + 1 });
            if (cLbl) cLbl.innerHTML = renderCostHTML({ wood: cost.wood, stone: cost.stone });
            btnConstrDisc.disabled = wood < cost.wood || stone < cost.stone;
        }
    }

    // Constructor road-stock boost button (flat cost, no cap — see upgradeConstructorRoadBoost)
    const btnConstrRoads = document.getElementById('btnUpgradeConstructorRoads');
    if (btnConstrRoads) {
        const showBtn = selectedBuilding && selectedBuilding.type === 'constructor';
        btnConstrRoads.style.display = showBtn ? 'flex' : 'none';
        if (showBtn) {
            const cLbl = document.getElementById('costConstructorRoads');
            if (hasConstructorRoadBoost) {
                if (cLbl) cLbl.innerHTML = `<span style="color: #c5a059; font-weight: bold;">${t('upg.completed')}</span>`;
                btnConstrRoads.disabled = true;
            } else {
                const cost = getConstructorRoadBoostCost();
                if (cLbl) cLbl.innerHTML = renderCostHTML(cost);
                btnConstrRoads.disabled = wood < cost.wood;
            }
        }
    }

    // Ingeniero de Caminos: repeatable gold-for-road purchase, escalating ×1.5 each time
    const btnBuyRoadGold = document.getElementById('btnBuyRoadGold');
    if (btnBuyRoadGold) {
        const showGoldRoad = hasSkillIngenieroCaminos && selectedBuilding && selectedBuilding.type === 'constructor';
        btnBuyRoadGold.style.display = showGoldRoad ? 'flex' : 'none';
        if (showGoldRoad) {
            const grc = getGoldRoadCost();
            const costLabel = btnBuyRoadGold.querySelector('.btn-cost');
            if (costLabel) costLabel.innerHTML = renderCostHTML(grc);
            btnBuyRoadGold.disabled = wood < grc.wood || gold < grc.gold;
        }
    }

    // Destroy panel: show refund preview for selected building
    const destroyPanel = document.getElementById('destroyPanel');
    const destroyRefundInfo = document.getElementById('destroyRefundInfo');
    if (destroyPanel) {
        const showDestroy = selectedBuilding && selectedBuilding.type !== 'town_center';
        destroyPanel.style.display = showDestroy ? 'block' : 'none';
        if (showDestroy) {

            // Move cost = rebuild price after demolish − constructor refund
            const moveCostEl = document.getElementById('moveBuildingCost');
            const btnMove = document.getElementById('btnMoveBuilding');
            // Ver _UNMOVABLE_TYPES: el panel entero sale para todo lo que no sea el Centro Urbano,
            // así que sin esto el dique y el puerto ofrecían un botón de mover que no debe existir.
            if (btnMove) btnMove.style.display = (_UNMOVABLE_TYPES.has(selectedBuilding.type) || selectedBuilding.pasarela) ? 'none' : '';
            const btnFlip = document.getElementById('btnFlipDeco');
            if (btnFlip) btnFlip.style.display = _decoFlippable(selectedBuilding.type) ? '' : 'none';
            const btnFlagD = document.getElementById('btnFlagDesign');
            if (btnFlagD) btnFlagD.style.display = selectedBuilding.type === 'deco_bandera' ? '' : 'none';
            const btnEdge = document.getElementById('btnEdgeDeco');
            if (btnEdge) btnEdge.style.display = DECO_EDGE_KIND[selectedBuilding.type] ? '' : 'none';
            if (moveCostEl) {
                const mc = getMoveCost(selectedBuilding.type, selectedBuilding);
                // mc is null for anything with no cost table entry (road, well, ...) — that
                // means "free to move", not "leave the label/button as whatever they were for
                // the previously-selected building".
                const html = mc ? renderCostHTML(mc) : '';
                moveCostEl.innerHTML = html || `<span style="color:#7dbe6a">${t('btn.free')}</span>`;
                const canAfford = !mc || (wood >= (mc.wood || 0) && food >= (mc.food || 0) && wool >= (mc.wool || 0) && stone >= (mc.stone || 0) && gold >= (mc.gold || 0));
                if (btnMove) btnMove.disabled = !canAfford;
            }

            // Demolish refund
            const destroyLabel = document.getElementById('destroyBtnLabel');
            if (destroyRefundInfo) {
                if (selectedBuilding.type === 'zanja') {
                    if (destroyLabel) destroyLabel.innerHTML = t('btn.fill_ditch');
                    destroyRefundInfo.innerHTML = '';
                } else if (DECO_TYPES.includes(selectedBuilding.type)) {
                    // Decorations refund decoCoins in full and unconditionally (see
                    // destroySelectedBuilding) — no Taller needed and no percentage cut, so this
                    // skips getBuildingRefund entirely instead of showing an irrelevant "25%" label.
                    if (destroyLabel) destroyLabel.innerHTML = t('btn.demolish');
                    const decoRefund = DECO_COSTS[selectedBuilding.type] || 0;
                    // Con decoración infinita (_decoInfPinned) no se gasta nada, así que no hay nada que recuperar: ni se dice
                    destroyRefundInfo.innerHTML = decoRefund > 0 && !_decoInfPinned
                        ? `<span style="white-space:nowrap;color:#8fd0a0">${t('btn.refund_gems', { n: decoRefund })} <i class="fa-solid fa-gem" style="color:#6fd8f2;"></i></span>`   // que se lea que los diamantes se recuperan, no que cuesta
                        : '';
                } else if (_wouldReturnFreeToken(selectedBuilding.type)) {
                    if (destroyLabel) destroyLabel.innerHTML = t('btn.demolish_free');
                    destroyRefundInfo.innerHTML = '';
                } else {
                    const refund = getBuildingRefund(selectedBuilding.type, selectedBuilding);
                    if (refund) {
                        const pct = 25 + constructorUpgradeLevel * 25;
                        if (destroyLabel) destroyLabel.innerHTML = t('btn.demolish_pct', { pct });
                        destroyRefundInfo.innerHTML = renderCostHTML(refund);
                    } else {
                        if (destroyLabel) destroyLabel.innerHTML = t('btn.demolish');
                        destroyRefundInfo.innerHTML = '';
                    }
                }
            }
        }
    }

    const marketTradePanel = document.getElementById('marketTradePanel');
    if (marketTradePanel) {
        const showMarket = (selectedBuilding && selectedBuilding.type === 'market');
        marketTradePanel.style.display = showMarket ? 'block' : 'none';
        // "cuando entras al mercado que se automarque por defecto la madera": sin recurso elegido
        // todos los botones salían apagados y no se entendía por qué. Solo la primera vez (o tras
        // deseleccionar todo); si ya habías elegido otro, se respeta.
        if (showMarket && !marketRes) marketSelectRes('wood');
        else if (showMarket) updateMarketPanel();
    }

    // Mobile portrait: action icon buttons (pause/move/demolish) in selection header
    if (_MQ_PORTRAIT.matches) {
        const mobSelActions  = document.getElementById('mobSelActions');
        const mobBtnPause    = document.getElementById('mobBtnPause');
        const mobBtnMove     = document.getElementById('mobBtnMove');
        const mobBtnDemolish = document.getElementById('mobBtnDemolish');
        if (mobSelActions) {
            const showAct = !!(selectedBuilding && selectedBuilding.type !== 'town_center');
            mobSelActions.style.display = showAct ? 'flex' : 'none';
            if (showAct) {
                // "en movil un boton de pausa siempre que se pueda en ese edificio" — same
                // _PAUSABLE_TYPES gate _togglePausableBuilding itself already uses, so this can
                // never show a button for a type that isn't actually pausable. Icon (and the
                // toast-vs-toggle behavior once tapped) follows current state exactly like the
                // desktop right-click does — see _togglePausableBuilding.
                if (mobBtnPause) {
                    const canPause = _PAUSABLE_TYPES.has(selectedBuilding.type);
                    mobBtnPause.style.display = canPause ? 'flex' : 'none';
                    if (canPause) {
                        const icon = mobBtnPause.querySelector('i');
                        if (icon) icon.className = selectedBuilding.isPaused ? 'fa-solid fa-play' : 'fa-solid fa-pause';
                        mobBtnPause.title = t(selectedBuilding.isPaused ? 'btn.resume' : 'btn.pause');
                    }
                }
                const mobBtnFlip = document.getElementById('mobBtnFlip');
                if (mobBtnFlip) mobBtnFlip.style.display = _decoFlippable(selectedBuilding.type) ? 'flex' : 'none';
                const mobBtnFlagD = document.getElementById('mobBtnFlagDesign');
                if (mobBtnFlagD) mobBtnFlagD.style.display = selectedBuilding.type === 'deco_bandera' ? 'flex' : 'none';
                const mobBtnEdge = document.getElementById('mobBtnEdge');
                if (mobBtnEdge) mobBtnEdge.style.display = DECO_EDGE_KIND[selectedBuilding.type] ? 'flex' : 'none';
                if (mobBtnMove) {
                    // Igual que #btnMoveBuilding en escritorio (ver _UNMOVABLE_TYPES): el dique, el puerto y las zanjas no se mueven.
                    // En móvil faltaba y salía "Mover · Gratis" (no tienen precio de mover porque no se pueden mover).
                    mobBtnMove.style.display = (_UNMOVABLE_TYPES.has(selectedBuilding.type) || selectedBuilding.pasarela) ? 'none' : '';
                    const mc = getMoveCost(selectedBuilding.type, selectedBuilding);
                    const canAfford = !mc || (wood >= (mc.wood||0) && food >= (mc.food||0) && wool >= (mc.wool||0) && stone >= (mc.stone||0) && gold >= (mc.gold||0));
                    // NOT actually .disabled — stays tappable when unaffordable so
                    // startMoveBuilding() can show a "missing X" toast instead of nothing
                    // happening. Same dimmed look via a class instead.
                    mobBtnMove.classList.toggle('mob-act-unaffordable', !canAfford);
                    // "que quepan los precios de mover, sin que se salga" — el botón de mover en
                    // móvil solo tenía el icono, sin precio (a diferencia del panel de escritorio,
                    // que sí lo muestra vía #moveBuildingCost). Mismo renderCostHTML de siempre —
                    // ya trae formatCompact y la rejilla 2x2 para 3+ recursos — el ancho/alto que
                    // le deja crecer al botón vive en el CSS de .mob-act-move.
                    const mobCostEl = document.getElementById('mobMoveCost');
                    // Una decoración se mueve siempre gratis: no hace falta decirlo (pedido de JC)
                    if (mobCostEl) mobCostEl.innerHTML = mc ? renderCostHTML(mc) : DECO_TYPES.includes(selectedBuilding.type) ? '' : `<span style="color:#7dbe6a">${t('btn.free')}</span>`;
                }
                if (mobBtnDemolish) {
                    const _d = getBuildingDescriptor(selectedBuilding);
                    mobBtnDemolish.style.display = (_d.canDestroy !== false) ? 'flex' : 'none';
                }
            }
        }
    }
    
    // Skill area: countdown vs skill button
    const countdownEl    = document.getElementById('treeCountdown');
    const countdownValEl = document.getElementById('treeCountdownValue');
    const btnSkill       = document.getElementById('btnSkillTree');
    const nextChestInfoEl  = document.getElementById('nextChestInfo');
    const nextChestValEl   = document.getElementById('nextChestValue');
    const remaining = Math.max(0, nextChestAt - treesChopped);

    if (skillTreeUnlocked) {
        if (countdownEl) countdownEl.style.display = 'none';
        if (btnSkill) {
            btnSkill.style.display = 'flex';
            const badge = btnSkill.querySelector('.skill-badge');
            if (badge) badge.textContent = '';
            btnSkill.classList.remove('skill-has-points');
            const relicBadge = document.getElementById('relicCountBadge');
            // Current run's relics, not the lifetime total — _totalRelicsCollected survives every
            // reset, so it kept climbing well past what's actually relevant to THIS run's tree.
            if (relicBadge) relicBadge.textContent = _runRelicsCollected;
        }
        // Always show next-chest counter when more chests exist (even with active relics)
        const showNext = tutorialStep >= 10 && nextChestAt < 99999;
        if (nextChestInfoEl) {
            nextChestInfoEl.style.display = showNext ? 'flex' : 'none';
            if (showNext && nextChestValEl) nextChestValEl.textContent = remaining;
        }
    } else if (tutorialStep >= 10 && nextChestAt < 99999) {
        if (countdownEl) {
            countdownEl.style.display = 'flex';
            if (countdownValEl) countdownValEl.textContent = remaining;
        }
        if (btnSkill) btnSkill.style.display = 'none';
        if (nextChestInfoEl) nextChestInfoEl.style.display = 'none';
    } else {
        if (countdownEl) countdownEl.style.display = 'none';
        if (btnSkill) btnSkill.style.display = 'none';
        if (nextChestInfoEl) nextChestInfoEl.style.display = 'none';
    }

    // Legacy (prestige) badge — shown inside the Town Center's own selection panel, above
    // the recruit-villager buttons, instead of as a persistent top-left HUD overlay.
    const pHudBadge = document.getElementById('prestigeSelBadge');
    const pHudLines = document.getElementById('prestigeSelLines');
    if (pHudBadge && pHudLines) {
        const active = PRESTIGE_MILESTONES.filter((_, i) => i < prestige.nextIdx);
        const showBadge = active.length > 0 && selectedBuilding && selectedBuilding.type === 'town_center';
        if (showBadge) {
            pHudBadge.style.display = 'block';
            // pm.nameKey a pelo (en vez de _legacyTierDisplay) es justo el bug reportado: para un
            // tramo de elección (Sindicatos/Abundancia/Banca) esa clave es SIEMPRE la genérica
            // "Elige tu Legado" — nunca dice cuál se eligió de verdad ahí, aunque ya esté
            // reclamado. _legacyTierDisplay sí resuelve el paquete real vía
            // prestige.claimedPackages; para los tramos fijos (no elección) se comporta igual que
            // antes (cae al mismo pm.nameKey).
            // Cada línea enseña al pasar el ratón qué da ese Legado (mismo tooltip que el menú de
            // construcción, ver _showLegacyInfo). Solo se reescribe si cambia: si se rehiciera en
            // cada updateUI, la línea bajo el ratón se sustituiría y el tooltip se quedaría pegado.
            const _lhtml = active.map((pm, i) => {
                const disp = _legacyTierDisplay(i) || pm;
                return `<span style="cursor:help;" onmouseenter="_showLegacyInfo(event,this,${i})" onmouseleave="_hideBuildInfo()"><i class="fa-solid fa-check" style="color:var(--gold);font-size:9px;margin-right:4px;"></i>${t(disp.nameKey)}</span>`;
            }).join('<br>');
            if (pHudLines._html !== _lhtml) { pHudLines.innerHTML = _lhtml; pHudLines._html = _lhtml; }
        } else {
            pHudBadge.style.display = 'none';
        }
    }

    // Skill tree panel content
    updateSkillTreePanel();

    // Update tutorial state
    updateTutorial();

    _updateBuildButtonToggleLabels();
}

// "en móvil cuando selecciono una construcción y se pone la previa que en el botón de ese
// edificio ponga cancelar para saber que si pulsas otra vez lo cancelas" — solo en pantalla
// portrait/móvil (ver _MQ_PORTRAIT); en escritorio el botón se queda con su texto normal. Recorre
// TODOS los botones de construir (cualquiera con el onmouseenter de _showBuildInfo, que ya lleva
// el tipo en su tercer argumento — ver index.html) en vez de mantener una lista aparte tipo->botón
// que se desincronizaría cada vez que se añade un edificio nuevo. Restaura el texto original leyendo
// su propio data-t (mismo mecanismo que applyLang en lang.js), así sigue funcionando al cambiar de
// idioma sin tener que guardar el texto original en ningún sitio.
// El modo de colocar que arma un botón de decoración (por su onclick), o null. Las vallas comparten modo ('fence'): cualquiera cancela
function _decoBtnMode(btn) {
    const m = (btn.getAttribute('onclick') || '').match(/^(startBuildDecoration|startBuildGroundDeco|startBuildFence)\('([^']+)'\)$/);
    if (!m) return null;
    return m[1] === 'startBuildGroundDeco' ? 'ground_' + m[2] : m[1] === 'startBuildFence' ? 'fence' : m[2];
}
// Móvil vertical: tocar otra vez el botón de lo que colocas lo cancela (R va con dos dedos, ver _tap2). true si ha cancelado
function _decoTapCancel(mode) {
    if (!_MQ_PORTRAIT.matches || buildMode !== mode || moveBuilding !== null) return false;
    buildMode = null;
    updateUI();
    return true;
}
function _updateBuildButtonToggleLabels() {
    // La goma: "Cancelar" mientras está puesta (ver startBuildDecoErase)
    const _eraseLbl = document.getElementById('btnDecoEraseLabel');
    if (_eraseLbl) { const _txt = t(buildMode === 'deco_erase' ? 'build.cancel' : 'deco.erase_deco'); if (_eraseLbl.textContent !== _txt) _eraseLbl.textContent = _txt; }
    // Decoraciones, suelos y vallas: el mismo "Cancelar" en el botón de lo que se está colocando
    document.querySelectorAll('#decorationsGrid .command-btn[onclick]').forEach(btn => {
        const mode = _decoBtnMode(btn);
        const label = btn.querySelector('.btn-label');
        if (!mode || !label || !label.dataset.t) return;
        const isCancel = _MQ_PORTRAIT.matches && buildMode === mode && moveBuilding === null;
        if (btn.classList.contains('btn-cancel-mode') === isCancel) return;
        label.textContent = isCancel ? t('build.cancel') : t(label.dataset.t);
        btn.classList.toggle('btn-cancel-mode', isCancel);
    });
    document.querySelectorAll('.command-btn[onmouseenter*="_showBuildInfo"]').forEach(btn => {
        const m = btn.getAttribute('onmouseenter').match(/_showBuildInfo\(event,this,'([^']+)'\)/);
        const type = m && m[1];
        const label = btn.querySelector('.btn-label');
        if (!type || !label || !label.dataset.t) return;
        const isCancel = _MQ_PORTRAIT.matches && buildMode === type;
        label.textContent = isCancel ? t('build.cancel') : t(label.dataset.t);
        // "que sea el único texto del botón" — oculta icono/tamaño/coste (ver .btn-cancel-mode en
        // index.css), dejando solo el label centrado.
        btn.classList.toggle('btn-cancel-mode', isCancel);
    });
}

function updateSkillTreePanel() {
    if (!skillTreeOpen) return;
    renderSkillTree();
}

function _renderSkillCardTree(container) {
    const allIds = Object.keys(STK_NODE_MAP || {}).filter(id => !CARD_POOL_EXCLUDED.includes(id));

    // Build parent→children map
    const childrenOf = {};
    for (const id of allIds) {
        const pr = SKILL_PREREQS[id];
        if (pr && allIds.includes(pr)) {
            if (!childrenOf[pr]) childrenOf[pr] = [];
            childrenOf[pr].push(id);
        }
    }

    // Roots: no prereq, or prereq is excluded/outside allIds
    const roots = allIds.filter(id => {
        const pr = SKILL_PREREQS[id];
        return !pr || !allIds.includes(pr);
    });

    function cardState(id) {
        if (isSkillActive(id)) return 'active';
        const pr = SKILL_PREREQS[id];
        const prereqOk = !pr || isSkillActive(pr);
        const relicOk  = milestoneIndex >= (CARD_MIN_RELIC[id] ?? 0);
        if (prereqOk && relicOk) return 'available';
        return 'locked';
    }

    function buildNode(id) {
        const st   = cardState(id);
        const icon = SKILL_CARD_ICONS[id] || 'fa-solid fa-star';
        const name = t('skill.' + id + '.name');
        const desc = _skillDesc(id);
        const minR = CARD_MIN_RELIC[id];
        const kids = childrenOf[id] || [];

        let infoHTML = '';
        if (st === 'locked') {
            const pr = SKILL_PREREQS[id];
            const lines = [];
            if (pr && !isSkillActive(pr)) lines.push(`🔒 ${t('skill.' + pr + '.name')}`);
            if (minR) lines.push(`⚗ Reliquia ${minR}+`);
            infoHTML = lines.map(l => `<span class="sct-sub">${l}</span>`).join('');
        } else {
            infoHTML = `<span class="sct-desc">${desc}</span>`;
            if (minR) infoHTML += `<span class="sct-sub" style="opacity:0.6;">⚗ Reliquia ${minR}+</span>`;
        }

        const badge = st === 'active'    ? '<span class="sct-badge sct-badge-active">✓</span>'
                    : st === 'available' ? '<span class="sct-badge sct-badge-avail">★</span>'
                    : '';

        const cardHTML = `
            <div class="sct-card sct-${st}">
                ${badge}
                <i class="${icon} sct-icon"></i>
                <span class="sct-name">${name}</span>
                ${infoHTML}
            </div>`;

        if (!kids.length) {
            return `<div class="sct-node">${cardHTML}</div>`;
        }

        const kidsHTML = kids.map(k => buildNode(k)).join('');
        return `
            <div class="sct-node">
                ${cardHTML}
                <span class="sct-arrow">›</span>
                <div class="sct-kids-col">${kidsHTML}</div>
            </div>`;
    }

    container.innerHTML = roots.map(r => buildNode(r)).join('');
}

// True only while Settings is open AND it had to collapse an already-expanded build menu to get
// there — used to know whether to restore it on close. If the player had already minimized the
// build menu themselves before opening Settings, this stays false and closing Settings leaves it
// exactly as they left it.
let _settingsAutoCollapsedBuildMenu = false;
let _settingsAutoHidTabBar = false;
function toggleSettingsPanel() {
    try { _updatePlayerCodeRow(); } catch (e) {}
    const panel = document.getElementById('settingsPanel');
    if (!panel) return;
    const opening = panel.style.display === 'none';
    // 'flex', not 'block' — .settings-panel's own CSS rule is display:flex/flex-direction:column
    // (that's what makes .settings-body's flex:1 1 auto + overflow-y:auto actually shrink/scroll
    // instead of spilling past max-height), but an inline style always wins over a stylesheet
    // rule regardless of specificity — setting 'block' here was silently overriding it back to a
    // plain block box every time the panel opened, so the whole scroll fix never actually engaged.
    panel.style.display = opening ? 'flex' : 'none';
    if (opening) _cgModalOpenedIfEnabled('settings'); else _cgModalClosedIfEnabled('settings');

    // Mobile-only dimmed/blocking backdrop behind the now-centered panel (see index.css) — a
    // no-op on desktop, nothing there gives it any size or position. Toggled unconditionally here
    // rather than gated on _MQ_PORTRAIT so it can never drift out of sync with the panel itself.
    const backdrop = document.getElementById('settingsBackdrop');
    if (backdrop) backdrop.style.display = opening ? 'block' : 'none';

    // #settingsPanel and #commandCard share the same right-edge X — auto-collapse the build menu
    // while Settings is open so the two don't overlap, purely visual (not written to
    // localStorage, unlike a real click on the panel's own collapse button).
    const body = document.getElementById('commandCardBody');
    const btn  = document.getElementById('btnToggleCommandCard');
    if (body) {
        if (opening) {
            _settingsAutoCollapsedBuildMenu = body.style.display !== 'none';
            if (_settingsAutoCollapsedBuildMenu) {
                body.style.display = 'none';
                if (btn) btn.textContent = '▲'; // ▲ = collapsed, matches toggleCommandCard()'s convention
            }
        } else if (_settingsAutoCollapsedBuildMenu) {
            body.style.display = '';
            if (btn) btn.textContent = '▼'; // ▼ = expanded
            _settingsAutoCollapsedBuildMenu = false;
        }
        // No resizeCanvas() needed here anymore — the canvas is always full-viewport regardless
        // of #commandCard's own height now (see resizeCanvas's own comment), so auto-collapsing
        // it here has nothing left for the canvas to react to.
    }
    // #buildTabBar (the folder-style Construcciones/Cosméticos tab flap) is a sibling of
    // #commandCardBody, absolutely positioned to poke out ABOVE #commandCard's own top edge (see
    // its own rule, top:-28px) — collapsing the body above doesn't touch it, so once decorations
    // are unlocked it kept sticking up past the collapsed title bar and into #settingsPanel's own
    // reserved bottom margin, undermining the whole point of the auto-collapse above. Hide it too
    // while Settings is open (only restore it if it was actually showing, i.e. _decoTabRevealed).
    const tabBar = document.getElementById('buildTabBar');
    if (tabBar) {
        if (opening) {
            _settingsAutoHidTabBar = tabBar.style.display !== 'none';
            if (_settingsAutoHidTabBar) tabBar.style.display = 'none';
        } else if (_settingsAutoHidTabBar) {
            tabBar.style.display = '';
            _settingsAutoHidTabBar = false;
        }
    }
    _updateDecoCatBar();   // Ajustes pliega el panel: las pestañas de categoría se van con él

    // Same reasoning for the offline-boost/ad-offer strips — they dock in that same top-right
    // column too. Just hide on open; on close, re-run their OWN update functions instead of
    // forcing display back on, so a strip that stopped applying while Settings was open (bank
    // ran out, offer expired...) correctly stays hidden ("si es posible" — only if still valid).
    if (opening) {
        const boostStrip = document.getElementById('offlineBoostStrip');
        const adOfferStrip = document.getElementById('offlineAdOfferStrip');
        if (boostStrip) boostStrip.style.display = 'none';
        if (adOfferStrip) adOfferStrip.style.display = 'none';
    } else {
        _updateOfflineBoostUI();
        _updateOfflineAdOfferStrip();
    }
}

// Screenshot mode: F6-only (no on-screen button, so an accidental tap can't trigger it and
// leave a player stuck without knowing how to undo it). Hides every UI panel/number (see the
// body.fn-screenshot-mode rules in index.css) plus the canvas-drawn tree health bars (_screenshotMode
// below, checked where they're drawn). Purely a runtime/DOM flag — never written to localStorage
// or the save file, so it can't survive a reload and F5 (manual save) can't persist it either.
let _screenshotMode = false;
function _toggleScreenshotMode() {
    _screenshotMode = !_screenshotMode;
    document.body.classList.toggle('fn-screenshot-mode', _screenshotMode);
    // Re-scan visibility now (wider radius in screenshot mode, see recalculateVisibility) instead
    // of waiting for the next incidental game-state change to reveal/hide the extra tree rows.
    recalculateVisibility();
}
window._toggleScreenshotMode = _toggleScreenshotMode;

// Screensaver mode: a player-facing version of the same idea, reached from Settings instead of a
// hidden key. Piggybacks on _screenshotMode itself (not just its CSS class) so every existing
// "hide this while screenshotting" check throughout the file — canvas-drawn tree health bars,
// floating resource numbers, etc. — applies here too with no extra call sites to maintain. Goes
// one step further than F6 and also hides #btnSettings (see fn-screensaver-mode in index.css):
// safe to, unlike F6, since this has its own dedicated exit button (#btnExitScreensaver,
// bottom-right) plus Esc, instead of relying on Settings staying reachable as the only way out.
let _screensaverMode = false;
function _toggleScreensaverMode() {
    _screensaverMode = !_screensaverMode;
    _screenshotMode = _screensaverMode;
    document.body.classList.toggle('fn-screenshot-mode', _screenshotMode);
    document.body.classList.toggle('fn-screensaver-mode', _screensaverMode);
    if (_screensaverMode) {
        // Always opened from the Settings panel — close it behind, or it'd be the one thing left
        // on screen in what's otherwise meant to be an empty view.
        const panel = document.getElementById('settingsPanel');
        if (panel && panel.style.display !== 'none') toggleSettingsPanel();
    }
    recalculateVisibility();
}
window._toggleScreensaverMode = _toggleScreensaverMode;

// F7: record a fixed 5-second clip of the canvas (whatever orientation/aspect it's currently
// rendering — horizontal on desktop, vertical on a phone held upright — and auto-download it as
// a .webm for editing together later. MediaRecorder only captures the <canvas> pixel stream, not
// the page, so it's unaffected by any DOM overlay — pair with F6 (screenshot mode) beforehand for
// a clean clip with no UI/numbers, but recording doesn't require it.
// Currently NOT wired to F7 (see the keydown handler) per explicit request — kept here intact,
// just unreachable, in case recording is wanted again later.
let _isRecordingClip = false;
function _recordClip() {
    if (_isRecordingClip) return; // ignore re-press mid-recording
    if (!canvas.captureStream || typeof MediaRecorder === 'undefined') {
        showBuildToast('Grabación no soportada en este navegador');
        return;
    }
    const stream = canvas.captureStream(30);
    const mimeType = MediaRecorder.isTypeSupported('video/webm;codecs=vp9')
        ? 'video/webm;codecs=vp9'
        : (MediaRecorder.isTypeSupported('video/webm;codecs=vp8') ? 'video/webm;codecs=vp8' : 'video/webm');
    let recorder;
    try {
        recorder = new MediaRecorder(stream, { mimeType, videoBitsPerSecond: 8000000 });
    } catch (e) {
        showBuildToast('Grabación no soportada en este navegador');
        return;
    }
    _isRecordingClip = true;
    const chunks = [];
    recorder.ondataavailable = (e) => { if (e.data && e.data.size > 0) chunks.push(e.data); };
    recorder.onstop = () => {
        stream.getTracks().forEach(t => t.stop());
        _isRecordingClip = false;
        const ind = document.getElementById('recIndicator');
        if (ind) ind.style.display = 'none';
        const blob = new Blob(chunks, { type: mimeType });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `fn_clip_${Date.now()}.webm`;
        document.body.appendChild(a);
        a.click();
        a.remove();
        setTimeout(() => URL.revokeObjectURL(url), 10000);
    };
    const ind = document.getElementById('recIndicator');
    const txt = document.getElementById('recIndicatorText');
    if (ind) ind.style.display = 'block';
    let secsLeft = 5;
    if (txt) txt.textContent = `REC ${secsLeft}s`;
    const countdown = setInterval(() => {
        secsLeft--;
        if (txt) txt.textContent = `REC ${Math.max(0, secsLeft)}s`;
        if (secsLeft <= 0) clearInterval(countdown);
    }, 1000);
    recorder.start();
    setTimeout(() => { if (recorder.state !== 'inactive') recorder.stop(); }, 5000);
}
window._recordClip = _recordClip;

// Language toggle on the main menu — runs before the game itself has started, so unlike
// applySettings() this can't call updateUI() (game state isn't set up yet). Just re-translates
// the page and persists the choice into the same fn_settings blob applySettings() reads later.
function _menuSetLang(code) {
    setLang(code);
    const sel = document.getElementById('selLang');
    if (sel) sel.value = code;
    // La cabecera de la partida ("Partida 2 · Mundo 2 · La costa · jugada hace…") y la lista de partidas se montan en JS, sin
    // data-t: applyLang no las toca y se quedaban en el idioma anterior. Se vuelven a montar en el idioma nuevo.
    const head = document.getElementById('menuMainSlotLabel');
    if (head && head.style.display !== 'none' && head.innerHTML) head.innerHTML = _menuMainHeadHTML(currentSlot, _slotHasSave(currentSlot));
    const picker = document.getElementById('menuSlotPicker');
    if (picker && picker.style.display !== 'none') { try { _renderSlotPicker(); } catch (e) {} }
    try {
        const s = JSON.parse(localStorage.getItem('fn_settings') || '{}');
        s.lang = code;
        localStorage.setItem('fn_settings', JSON.stringify(s));
    } catch (e) {}
}
window._menuSetLang = _menuSetLang;

function applySettings() {
    settingShowCarryIndicator = document.getElementById('chkCarryIndicator').checked;
    settingShowUpgradeBadge   = document.getElementById('chkUpgradeBadge').checked;
    settingShowDepositText    = document.getElementById('chkDepositText').checked;
    settingShowHoverAnim      = document.getElementById('chkHoverAnim').checked;
    settingShowGatherParticles = document.getElementById('chkGatherParticles').checked;
    settingShowRelicFound     = document.getElementById('chkRelicFound').checked;
    settingShowRelicAvailable = document.getElementById('chkRelicAvailable').checked;
    settingShowPauseLabel     = document.getElementById('chkPauseLabel').checked;
    settingShowSelectRoute    = document.getElementById('chkSelectRoute').checked;
    settingShowSelectLift     = document.getElementById('chkSelectLift').checked;
    settingShowEffectZones    = document.getElementById('chkEffectZones').checked;
    settingShowFelledTrees    = document.getElementById('chkFelledTrees').checked;
    settingShowTreeStumps     = document.getElementById('chkTreeStumps').checked;
    settingShowBuildGrid      = document.getElementById('chkBuildGrid').checked;
    settingShowClouds         = document.getElementById('chkClouds')?.checked ?? true;
    settingShowCtrlHint       = document.getElementById('chkCtrlHint')?.checked ?? true;
    if (!settingShowCtrlHint) _ctrlHintHide();
    settingShowZoomButtons    = document.getElementById('chkZoomButtons')?.checked ?? true;
    document.body.classList.toggle('fn-no-zoom-btns', !settingShowZoomButtons);
    settingShowScreensaverBtn = document.getElementById('chkScreensaverBtn')?.checked ?? true;
    document.body.classList.toggle('fn-no-ss-btn', !settingShowScreensaverBtn);
    settingShowTreeHealth     = document.getElementById('chkTreeHealth').checked;
    settingShowTreeHealthBar  = document.getElementById('chkTreeHealthBar').checked;
    settingForestView         = document.getElementById('selForestView')?.value || 'biome';
    _treeBaseDirty = true; // settingShowFelledTrees changes what the cached tree canvas itself shows — force a full re-bake so already-felled trees flip immediately instead of waiting for the next incidental rebuild (camera move, new hit, ...)
    const lang = document.getElementById('selLang')?.value ?? 'es';
    setLang(lang);
    // setLang() -> applyLang() just overwrote EVERY [data-t] element (including the map show/hide
    // button) back to its static HTML attribute value, regardless of which state it was actually
    // showing — put the correct one of the two back based on the map's real current visibility.
    _updateMinimapToggleLabel();
    _tutoDisplayed = -1; // force tutorial re-render in new language
    updateTutorial();
    updateUI();
    localStorage.setItem('fn_settings', JSON.stringify({
        carryIndicator: settingShowCarryIndicator,
        upgradeBadge:   settingShowUpgradeBadge,
        depositText:    settingShowDepositText,
        hoverAnim:      settingShowHoverAnim,
        gatherParticles: settingShowGatherParticles,
        relicFound:     settingShowRelicFound,
        relicAvailable: settingShowRelicAvailable,
        pauseLabel: settingShowPauseLabel,
        selectRoute: settingShowSelectRoute,
        selectLift: settingShowSelectLift,
        effectZones: settingShowEffectZones,
        felledTrees: settingShowFelledTrees,
        treeStumps: settingShowTreeStumps,
        buildGrid: settingShowBuildGrid,
        clouds: settingShowClouds,
        ctrlHint: settingShowCtrlHint,
        zoomButtons: settingShowZoomButtons,
        screensaverBtn: settingShowScreensaverBtn,
        treeHealth: settingShowTreeHealth,
        treeHealthBar: settingShowTreeHealthBar,
        forestView: settingForestView,
        lang,
    }));
}

function loadSettings() {
    try {
        const raw = localStorage.getItem('fn_settings');
        if (!raw) { setLang('zh'); return; }   // 汉化版默认简体中文，玩家可在设置里切换
        const s = JSON.parse(raw);
        if (s.carryIndicator !== undefined) {
            settingShowCarryIndicator = s.carryIndicator;
            document.getElementById('chkCarryIndicator').checked = s.carryIndicator;
        }
        if (s.upgradeBadge !== undefined) {
            settingShowUpgradeBadge = s.upgradeBadge;
            document.getElementById('chkUpgradeBadge').checked = s.upgradeBadge;
        }
        if (s.depositText !== undefined) {
            settingShowDepositText = s.depositText;
            document.getElementById('chkDepositText').checked = s.depositText;
        }
        if (s.hoverAnim !== undefined) {
            settingShowHoverAnim = s.hoverAnim;
            document.getElementById('chkHoverAnim').checked = s.hoverAnim;
        }
        if (s.gatherParticles !== undefined) {
            settingShowGatherParticles = s.gatherParticles;
            document.getElementById('chkGatherParticles').checked = s.gatherParticles;
        }
        if (s.relicFound !== undefined) {
            settingShowRelicFound = s.relicFound;
            document.getElementById('chkRelicFound').checked = s.relicFound;
        }
        if (s.relicAvailable !== undefined) {
            settingShowRelicAvailable = s.relicAvailable;
            document.getElementById('chkRelicAvailable').checked = s.relicAvailable;
        }
        if (s.pauseLabel !== undefined) {
            settingShowPauseLabel = s.pauseLabel;
            document.getElementById('chkPauseLabel').checked = s.pauseLabel;
        }
        if (s.selectRoute !== undefined) {
            settingShowSelectRoute = s.selectRoute;
            document.getElementById('chkSelectRoute').checked = s.selectRoute;
        }
        if (s.selectLift !== undefined) {
            settingShowSelectLift = s.selectLift;
            document.getElementById('chkSelectLift').checked = s.selectLift;
        }
        if (s.effectZones !== undefined) {
            settingShowEffectZones = s.effectZones;
            document.getElementById('chkEffectZones').checked = s.effectZones;
        }
        if (s.felledTrees !== undefined) {
            settingShowFelledTrees = s.felledTrees;
            document.getElementById('chkFelledTrees').checked = s.felledTrees;
        }
        if (s.treeStumps !== undefined) {
            settingShowTreeStumps = s.treeStumps;
            document.getElementById('chkTreeStumps').checked = s.treeStumps;
        }
        if (s.buildGrid !== undefined) {
            settingShowBuildGrid = s.buildGrid;
            document.getElementById('chkBuildGrid').checked = s.buildGrid;
        }
        if (s.clouds !== undefined) {
            settingShowClouds = s.clouds;
            const c = document.getElementById('chkClouds'); if (c) c.checked = s.clouds;
        }
        if (s.ctrlHint !== undefined) {
            settingShowCtrlHint = s.ctrlHint;
            const c = document.getElementById('chkCtrlHint'); if (c) c.checked = s.ctrlHint;
        }
        if (s.screensaverBtn !== undefined) {
            settingShowScreensaverBtn = s.screensaverBtn;
            const c = document.getElementById('chkScreensaverBtn'); if (c) c.checked = s.screensaverBtn;
            document.body.classList.toggle('fn-no-ss-btn', !s.screensaverBtn);
        }
        if (s.zoomButtons !== undefined) {
            settingShowZoomButtons = s.zoomButtons;
            const c = document.getElementById('chkZoomButtons'); if (c) c.checked = s.zoomButtons;
            document.body.classList.toggle('fn-no-zoom-btns', !s.zoomButtons);
        }
        if (s.treeHealth !== undefined) {
            settingShowTreeHealth = s.treeHealth;
            document.getElementById('chkTreeHealth').checked = s.treeHealth;
        }
        if (s.treeHealthBar !== undefined) {
            settingShowTreeHealthBar = s.treeHealthBar;
            document.getElementById('chkTreeHealthBar').checked = s.treeHealthBar;
        }
        if (s.forestView === 'tones' || s.forestView === 'biome' || s.forestView === 'types') {
            settingForestView = s.forestView;
            const selFV = document.getElementById('selForestView');
            if (selFV) selFV.value = s.forestView;
        }
        if (s.lang) {
            const sel = document.getElementById('selLang');
            if (sel) sel.value = s.lang;
            setLang(s.lang);
            _tutoDisplayed = -1;
            return; // lang was saved, no need to auto-detect
        }
    } catch(e) {}
    // No saved lang — detect from browser
    _applyBrowserLang();
}

// Idioma del navegador entre los que tiene el juego: es, pt (portugués de cualquier país; los textos son de Brasil), fr, it, de, pl, tr, nl, id o en.
function _browserLangCode() {
    const b = (navigator.language || navigator.userLanguage || 'zh').toLowerCase();
    const c = b.slice(0, 2);
    // 汉化版：浏览器是中文就用中文；其它语言沿用原逻辑（未知语言回退到英语）。
    if (c === 'zh') return 'zh';
    return ['es', 'pt', 'fr', 'it', 'de', 'pl', 'tr', 'nl', 'id'].includes(c) ? c : 'en';
}
function _applyBrowserLang() {
    const lang = _browserLangCode();
    const sel = document.getElementById('selLang');
    if (sel) sel.value = lang;
    setLang(lang);
}

// ============================================================
// CANVAS SKILL TREE  –  radial layout, square nodes
// ============================================================
const STK_TILE = 40;               // px per tile unit in the skill tree
// World center from which all branches radiate
const STK_CX = 540, STK_CY = 460;
// Content bounds for initial zoom/pan
const STK_BOUNDS = { x: -280, y: -40, w: 2240, h: 1240 };
// Branch accent colours (left stripe + border tint)
const STK_BRANCH_COLOR = {
    bosque: '#4a8a2a', territorio: '#8a8a2a', aldea: '#c88030',
    construccion: '#5050b8', edificacion: '#2070c0', manual: '#b84040', obras: '#b8802a',
};

// Node positions are TOP-LEFT corners.
// Layout: 6 directions from (600,550), step 200px between node centres.
//   0°  (right)       → ALDEA
//  60°  (upper-right) → BOSQUE    [cos60=0.5, -sin60=-0.866]
// 120°  (upper-left)  → TERRITORIO[-0.5, -0.866]
// 180°  (left)        → CONSTRUCCIÓN
// 240°  (lower-left)  → MANUAL    [-0.5, +0.866]
// 300°  (lower-right) → EDIFICACIÓN[+0.5, +0.866]
// Node centre = TL + (60,60).  Step 200 → centres at 200,400,600,800 … from STK_CX/CY.

// OJO con los x/y de esta tabla: son VESTIGIALES. El layout real no los lee — lo calcula rawOf()
// dentro de renderSkillTree (radial desde el centro, ver STK_RADIAL_BASE/STEP), y encima de eso se
// aplica STK_MANUAL_POSITIONS. El único lector que les quedaba, stkHit(), pertenece al árbol en
// canvas antiguo (_OLD_renderSkillTree_canvas, sin #stkCanvas en el HTML desde hace tiempo).
// El tamaño del nodo DIBUJADO tampoco sale de aquí: son STK_CELL (64px) del render DOM, no ts×40.
// Nodos del árbol: los trae el mundo (worlds/worldN.js → skillTree.nodes), ver _applyWorldContent.
const SKILL_TREE_NODES = [];
const STK_NODE_MAP = {};   // id -> nodo, lo rellena _applyWorldContent

// Root node ids (no prereq) → used to draw decorative spokes from center
const STK_ROOT_IDS = [];   // del mundo (skillTree.roots), ver _applyWorldContent

let skillTreeOpen = false;
let stkPan  = { x: 20, y: 10 };
let stkZoom = 1;
let stkRevealAll = false;
let stkDrag = null;
let stkHov  = null;
let stkSel  = null;
let stkInit = false;

// Un padre cuenta como cumplido solo si él Y toda su cadena de padres lo están. Hace falta por las
// skills que puede dar un Legado sin su rama (Regadío Intensivo con Cosecha del Río): sin esto, sus
// hijas (Molino de Agua, Riego Extendido) se desbloqueaban sin tener las Zanjas de riego.
function _chainOk(p, activeFn = isSkillActive, seen = new Set()) {
    if (seen.has(p)) return true;
    seen.add(p);
    return activeFn(p) && _prereqList(p).every(q => _chainOk(q, activeFn, seen));
}
function stkState(id) {
    if (isSkillActive(id)) return pendingRemove.has(id) ? 'removing' : 'active';
    if (pendingSkills.has(id)) return 'pending';
    if (_prereqList(id).some(p => !_chainOk(p, willBeActive))) return 'locked';
    // Only reached once every prereq is actually owned — stays hidden behind the normal
    // locked/rubble treatment (like any other unreached node) until then.
    if (STK_COMING_SOON.has(id)) return 'soon';
    if (_isLegacyNode(id)) {
        return (_prestigeRelicBank + _stkPendingRelicBonus()) >= _legacyNodeCost(id) ? 'available' : 'locked';
    }
    const minR = CARD_MIN_RELIC[id] ?? 0;
    if (minR > 0 && _relicsCollectedCount() < minR) return 'locked';
    return 'available';
}

// Word-wrap helper: returns array of lines (max 2) fitting maxW px
function stkWrap(ctx, text, maxW) {
    const words = text.split(' ');
    const lines = [''];
    for (const w of words) {
        const cur = lines[lines.length - 1];
        const test = cur ? cur + ' ' + w : w;
        if (ctx.measureText(test).width > maxW && cur) lines.push(w);
        else lines[lines.length - 1] = test;
    }
    return lines.slice(0, 2);
}

// --- Tile hash for deterministic grass variation ---
function _stkH(tx, ty) {
    let h = (Math.imul(tx, 0x16593621) ^ Math.imul(ty, 0x0d08523f)) >>> 0;
    return (Math.imul(h ^ (h >>> 16), 0x45d9f3b)) >>> 0;
}

const STK_CELL = 64;        // small, icon-only nodes
const STK_RADIAL_BASE = 110; // distance from center to the first (root) node on each spoke
const STK_RADIAL_STEP = 130; // distance between consecutive depth levels along a spoke

// Skills that unlock (or gift) a placeable building get a square node instead of a circle
const STK_BUILDING_SKILLS = new Set([
    'panaderia', 'teatro', 'taberna', 'gremioMercaderes', 'rutaComercial', 'tesoreria', 'iglesia', 'maestria',
    'hidraulica', 'aserradero', 'madereroMovil', 'artePiedra', 'arbolFrutal', 'plantacion', 'canteras', 'donaPozo',
    'donaCasa', 'donaOvejas', 'donaAlgodon', 'donaFrutal', 'torreVigilancia', 'establo',
    // Faltaban las dos: abren su propio botón de construcción igual que las de arriba — btnRitual
    // (Altar Ritual, ver hasSkillRitual) y btnForest (Plantación Forestal, ver hasSkillBosqueCultivado).
    // La regla para saber si una habilidad va en este Set es exactamente esa: si en algún sitio hay
    // un `btnX.style.display = (hasSkillY ...)`, desbloquea un edificio colocable y su nodo va
    // cuadrado. Comprobado contra los 18 botones que existen: estas dos eran las únicas que faltaban.
    'ritual', 'bosqueCultivado',
]);

// Manual position overrides for the skill tree layout.
// { id: {x, y} } in raw/local coordinates — origin (0,0) is the tree's master center.
// Disposicion COLOCADA A MANO con el modo arreglo (tecla O / barra dev F4) sobre la rejilla de
// 100px, y volcada con el boton "Copiar".
// Comprobado al pegarla: todos los nodos con posicion, ningun par compartiendo celda y todo en
// multiplos exactos de 100 (el paso al que se imanta el modo O, ver stkGridCell).
// Las posiciones, igual que el resto del árbol, vienen del mundo (worlds/worldN.js → skillTree.positions):
// ver _applyWorldContent, que se llama aquí mismo con el mundo 1 y otra vez al cargar la partida.
const STK_MANUAL_POSITIONS = {};
_applyWorldContent((window.FN_WORLDS || {})[1]);

// Dev arrange-mode positions saved via the skill tree's "💾" button persist here across
// reloads, layered on top of the hardcoded defaults above, until copied into source for real.
// UNA CLAVE POR MUNDO (fn_stkPositionOverrides_w1, _w2...): antes era una sola para todos, y lo
// colocado y guardado en el Mundo 2 se aplicaba también al Mundo 1 — los nodos con el mismo id
// saltaban a su sitio del Mundo 2 y el árbol del 1 salía partido en dos. La clave vieja sin mundo
// ya no se lee (no se sabe de qué mundo era); se deja en el navegador por si hiciera falta.
function _stkOverridesKey(wid) { return 'fn_stkPositionOverrides_w' + (wid || 1); }
function _loadStkPositionOverrides(wid) {
    try {
        const raw = localStorage.getItem(_stkOverridesKey(wid));
        if (!raw) return;
        Object.assign(STK_MANUAL_POSITIONS, JSON.parse(raw));
    } catch (e) {}
}

let _stkRawPositions = {}; // last computed raw {x,y} per node id (see rawOf in renderSkillTree)

// Reveals every locked node (still mystery — no name/desc until unlocked) so an experienced
// player can see the full shape of the tree instead of only the current frontier.
function stkToggleShowAll() {
    if (!_adminToolsOn()) return;   // herramienta de admin: apagada salvo ADMIN_TOOLS (ver su declaración)
    stkShowAllLocked = !stkShowAllLocked;
    const btn = document.getElementById('btnStkShowAll');
    if (btn) btn.style.color = stkShowAllLocked ? '#40d0e0' : '';
    renderSkillTree();
}
window.stkToggleShowAll = stkToggleShowAll;

// Dev-only layout tool (key 'O' while the skill tree is open, see the global keydown handler):
// shows each node's raw {x,y} (the same space STK_MANUAL_POSITIONS uses) and lets you drag a
// node to reposition it. Every drop logs the full merged STK_MANUAL_POSITIONS object to the
// console, ready to paste back into source — this never persists anywhere on its own.
let stkArrangeMode = false;
let _stkShowAllBeforeArrange = false; // restored when arrange mode turns back off
// La barra dev del árbol (F4) solo se MOSTRABA — nadie la ocultaba nunca, así que al cerrar el
// árbol se quedaba flotando sobre el juego (position:fixed, z-index 10001). Era cosmético mientras
// solo tenía "Ordenar" y "Copiar"; con "Cuadricular" (mueve los 106 nodos de golpe) y "Guardar"
// (escribe en localStorage) pasa a ser un botón peligroso encima del mapa, operando además sobre un
// _stkRawPositions del último render. Un único sitio que sincroniza visibilidad con skillTreeOpen,
// llamado desde las TRES rutas de cierre (openSkillTree al plegar, _stkChooseFromTree y
// _stkReturnToCardModal), para que añadir una cuarta no vuelva a olvidarse.
function _stkSyncDevToolbar() {
    const toolbar = document.getElementById('stkDevToolbar');
    if (toolbar && !skillTreeOpen) toolbar.style.display = 'none';
}

function stkToggleArrangeMode() {
    stkArrangeMode = !stkArrangeMode;
    if (stkArrangeMode) {
        _stkShowAllBeforeArrange = stkShowAllLocked;
        stkShowAllLocked = true; // arranging needs every node visible/draggable, not just the frontier
    } else {
        stkShowAllLocked = _stkShowAllBeforeArrange;
    }
    const btn = document.getElementById('btnStkArrangeMode');
    if (btn) btn.style.color = stkArrangeMode ? '#40d0e0' : '';
    renderSkillTree();
}
window.stkToggleArrangeMode = stkToggleArrangeMode;

// Imán del modo O — MATRIZ ("una matriz del tamaño de los nodos y que pueda moverlos para que los
// nodos queden dentro de cada celda"). Sustituye al imán radial anterior (anillos de 100px +
// ángulos de 45° respecto al primer prerrequisito), que se quitó entero: un árbol en abanico se
// lee bien pero no se puede cuadricular, y lo que se busca ahora es exactamente lo contrario.
//
// Una celda = un nodo. El nodo dibujado mide STK_CELL (64px) y la coordenada guardada es su
// CENTRO, no su esquina (ver cell.style.left = c.x - STK_CELL/2 en el render) — así que el imán
// lleva el CENTRO a múltiplos exactos del paso y la rejilla se dibuja media celda desplazada, que
// es lo que deja cada nodo centrado en su hueco.
//
// El paso es ajustable en vivo desde la barra dev (botón "Celda") porque el tamaño que mejor se
// lee depende de cómo quede el árbol: 160 deja mucho aire alrededor de un nodo de 64, y 100 —
// múltiplo del redondeo a 50 que ya usa el layout automático, ver _stkRound50— lo deja más
// compacto. Se empieza en 160 y se prueba desde el botón sin tocar código.
//
// Mantén pulsado Alt mientras arrastras para desactivar el imán y colocar a mano, sin ajustar.
// 80 no esta: el nodo (64px) mas su etiqueta de dos lineas necesitan ~93px, asi que por
// debajo de 100 las etiquetas invaden el nodo de la fila siguiente (ver .stk-cell-label).
const STK_GRID_CELL_SIZES = [100, 120, 160, 200];
let stkGridCell = 100;
function _stkSnapToCell(x, y) {
    return {
        x: Math.round(x / stkGridCell) * stkGridCell,
        y: Math.round(y / stkGridCell) * stkGridCell,
    };
}
// Índice de celda (columna, fila) de una posición — para detectar dos nodos metidos en la misma
// celda, que es lo único que rompe una cuadrícula sin verse a simple vista cuando uno tapa al otro.
function _stkCellKey(p) {
    return Math.round(p.x / stkGridCell) + ',' + Math.round(p.y / stkGridCell);
}
// Botón "Celda" de la barra dev: recorre los pasos disponibles y re-imanta nada — solo cambia la
// rejilla y el paso futuro, para poder comparar a ojo sin mover ningún nodo todavía.
function _stkCycleGridCell() {
    const i = STK_GRID_CELL_SIZES.indexOf(stkGridCell);
    stkGridCell = STK_GRID_CELL_SIZES[(i + 1) % STK_GRID_CELL_SIZES.length];
    const btn = document.getElementById('btnStkGridCell');
    if (btn) btn.innerHTML = `<i class="fa-solid fa-table-cells"></i> Cell ${stkGridCell}`;
    renderSkillTree();
}
window._stkCycleGridCell = _stkCycleGridCell;
// Lleva TODOS los nodos a la celda más cercana de una pasada. Sin esto, cuadricular un árbol de 106
// nodos colocados con el imán radial viejo significaba arrastrarlos uno a uno. No persiste nada por
// su cuenta: queda en memoria hasta que se pulse "Guardar" (localStorage) o "Copiar" (al fuente),
// así que una recarga sin guardar lo descarta — es la forma de deshacer un cuadriculado que no gustó.
function _stkSnapAllToCells() {
    for (const n of SKILL_TREE_NODES) {
        const cur = STK_MANUAL_POSITIONS[n.id] || _stkRawPositions[n.id];
        if (!cur) continue;
        STK_MANUAL_POSITIONS[n.id] = _stkSnapToCell(cur.x, cur.y);
    }
    renderSkillTree();
    _stkLogManualPositions();
}
window._stkSnapAllToCells = _stkSnapAllToCells;

// Recolecta recursivamente todos los descendientes (hijos, nietos, ...) de un nodo a partir del
// mapa childrenOf de renderSkillTree() — usado por el arrastre con Ctrl para mover la rama
// entera de una vez, conservando la disposición relativa de cada hijo respecto a su padre.
function _stkCollectDescendants(id, childrenOf) {
    const result = [];
    const seen = new Set();
    const stack = (childrenOf[id] || []).slice();
    while (stack.length) {
        const cur = stack.pop();
        if (seen.has(cur)) continue;
        seen.add(cur);
        result.push(cur);
        if (childrenOf[cur]) stack.push(...childrenOf[cur]);
    }
    return result;
}

// Persists the current STK_MANUAL_POSITIONS (including anything dragged this session) to
// localStorage — so arranging survives a reload, not just the in-memory session — and also
// dumps it to the console, ready to copy into the STK_MANUAL_POSITIONS source permanently.
function _stkSavePositions() {
    try {
        localStorage.setItem(_stkOverridesKey(_world().id), JSON.stringify(STK_MANUAL_POSITIONS));
    } catch (e) {}
    _stkLogManualPositions();
    const btn = document.getElementById('btnStkSavePositions');
    if (btn) {
        const prev = btn.textContent;
        btn.textContent = '✓';
        setTimeout(() => { btn.textContent = prev; }, 800);
    }
}
window._stkSavePositions = _stkSavePositions;

// Reset (barra del modo O): borra lo guardado en este navegador con 💾 y vuelve a las posiciones por defecto del mundo (worlds/worldN.js → skillTree.positions). Pide confirmar con
// un segundo clic (2 s), como el resto de botones destructivos de la barra.
let _stkResetArmed = 0;
function _stkResetPositions() {
    const btn = document.getElementById('btnStkResetPositions');
    if (!_stkResetArmed) {
        _stkResetArmed = setTimeout(() => { _stkResetArmed = 0; if (btn) btn.innerHTML = '<i class="fa-solid fa-rotate-left"></i> Reset'; }, 2000);
        if (btn) btn.innerHTML = '<i class="fa-solid fa-rotate-left"></i> Sure?';
        return;
    }
    clearTimeout(_stkResetArmed); _stkResetArmed = 0;
    const w = _world();
    try { localStorage.removeItem(_stkOverridesKey(w.id)); } catch (e) {}
    for (const k of Object.keys(STK_MANUAL_POSITIONS)) delete STK_MANUAL_POSITIONS[k];
    Object.assign(STK_MANUAL_POSITIONS, JSON.parse(JSON.stringify((w.skillTree && w.skillTree.positions) || {})));
    if (btn) btn.innerHTML = '<i class="fa-solid fa-rotate-left"></i> Reset';
    renderSkillTree();
}
window._stkResetPositions = _stkResetPositions;

function _stkPositionsAsText() {
    const lines = Object.entries(STK_MANUAL_POSITIONS)
        .map(([id, p]) => `    ${id}: { x: ${Math.round(p.x)}, y: ${Math.round(p.y)} },`)
        .join('\n');
    return `STK_MANUAL_POSITIONS = {\n${lines}\n};`;
}
function _stkLogManualPositions() {
    console.log(_stkPositionsAsText());
}
// Same text _stkLogManualPositions() dumps to console, but straight to the clipboard — no need
// to open devtools to grab it. navigator.clipboard needs a secure context (https/localhost); the
// try/catch just leaves the button silent (still logs to console via the F4 toolbar's other
// path) rather than throwing on an insecure/older host.
function _stkCopyPositions() {
    const text = _stkPositionsAsText();
    const btn = document.getElementById('btnStkCopyPositions');
    const flash = (label) => {
        if (!btn) return;
        const prev = btn.innerHTML;
        btn.innerHTML = label;
        setTimeout(() => { btn.innerHTML = prev; }, 900);
    };
    if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text)
            .then(() => flash('<i class="fa-solid fa-check"></i> Copied'))
            .catch(() => { console.log(text); flash('<i class="fa-solid fa-xmark"></i> Ver consola'); });
    } else {
        console.log(text);
        flash('<i class="fa-solid fa-xmark"></i> Ver consola');
    }
}
window._stkCopyPositions = _stkCopyPositions;

// --- Skill tree navigation: zoom + drag (no scrollbar) ---
let stkViewZoom = 1;
let stkViewPanX = 0, stkViewPanY = 0;
let _stkTreeW = 0, _stkTreeH = 0;
let _stkViewInitialized = false;

// Girar el móvil cambia si el árbol se dibuja transpuesto o no (ver _stkTransposed en
// renderSkillTree), y eso cambia sus dimensiones por completo — de ~2500x1500 a ~1500x2500. Sin
// esto, quien gire el teléfono con el árbol abierto se queda con la disposición de la orientación
// anterior hasta cerrarlo y volverlo a abrir. Se suelta además el latch del centrado: el pan
// calculado para la forma vieja deja el árbol medio fuera de pantalla en la nueva.
_MQ_PORTRAIT.addEventListener('change', () => {
    if (!skillTreeOpen) return;
    _stkViewInitialized = false;
    renderSkillTree();
});

function _stkApplyTransform() {
    const grid = document.getElementById('stkGrid');
    if (grid) grid.style.transform = `translate(${stkViewPanX}px, ${stkViewPanY}px) scale(${stkViewZoom})`;
    // Único punto por el que pasan TODOS los cambios de pan/zoom (arrastre, rueda, pinza, centrado
    // inicial, salto desde la propia miniatura), así que el rectángulo de "dónde estoy" se mantiene
    // al día desde aquí sin que cada sitio tenga que acordarse.
    _stkDrawMinimap();
}

// Keeps at least a bit of the tree always on screen — same "don't wander into the void"
// philosophy as the main map's _clampCamera(), just in container-relative screen pixels.
function _stkClampPan() {
    const cont = document.getElementById('stkContainer');
    if (!cont) return;
    const cw = cont.clientWidth, ch = cont.clientHeight;
    const treeW = _stkTreeW * stkViewZoom, treeH = _stkTreeH * stkViewZoom;
    const marginX = Math.max(80, cw * 0.3);
    const marginY = Math.max(80, ch * 0.3);
    stkViewPanX = Math.max(cw - treeW - marginX, Math.min(marginX, stkViewPanX));
    stkViewPanY = Math.max(ch - treeH - marginY, Math.min(marginY, stkViewPanY));
}

// --- Minimapa del árbol de habilidades ---
// "en móvil es raro, se podría hacer un minimapa de los skill para que no te pierdas": el árbol
// transpuesto mide ~1000x3500 y en pantalla caben unos 390x700, o sea que se ve un 10% cada vez.
// Mismo planteamiento que el minimapa del mapa grande (ver drawMinimap): una miniatura del conjunto
// con un rectángulo que marca dónde estás, y tocar en ella te lleva allí.
//
// Los nodos se cachean en el render (no se recalculan aquí) porque esto se redibuja en CADA
// _stkApplyTransform, o sea en cada frame de arrastre.
let _stkMiniNodes = null;   // [{x, y, s}] en coordenadas del árbol, rellenado por renderSkillTree
const STK_MINI_MAX_W = 110, STK_MINI_MAX_H = 170;
const STK_MINI_COLORS = { purchased: '#d4a840', available: '#ffffff', locked: '#45483a' };

// Escala y encuadre de la miniatura, o null si no hay nada que enseñar. Compartido por el dibujo y
// por la conversión de coordenadas del toque, para que no puedan desincronizarse.
function _stkMiniGeom() {
    const cv = document.getElementById('stkMinimap');
    const cont = document.getElementById('stkContainer');
    if (!cv || !cont || !_stkMiniNodes || !_stkMiniNodes.length || !_stkTreeW || !_stkTreeH) return null;
    // Solo estorba si el árbol ya cabe entero: entonces no hay dónde perderse.
    if (_stkTreeW * stkViewZoom <= cont.clientWidth + 1 && _stkTreeH * stkViewZoom <= cont.clientHeight + 1) return null;
    const scale = Math.min(STK_MINI_MAX_W / _stkTreeW, STK_MINI_MAX_H / _stkTreeH);
    return { cv, cont, scale, w: Math.round(_stkTreeW * scale), h: Math.round(_stkTreeH * scale) };
}

function _stkDrawMinimap() {
    const g = _stkMiniGeom();
    const cv = document.getElementById('stkMinimap');
    if (!g) { if (cv) cv.style.display = 'none'; return; }
    g.cv.style.display = 'block';
    if (g.cv.width !== g.w || g.cv.height !== g.h) { g.cv.width = g.w; g.cv.height = g.h; }
    const ctx2 = g.cv.getContext('2d');
    ctx2.clearRect(0, 0, g.w, g.h);

    // Un punto por nodo. 2px mínimo: por debajo de eso un árbol de 106 nodos se ve como ruido.
    const dot = Math.max(2, Math.round(STK_CELL * g.scale));
    for (const n of _stkMiniNodes) {
        ctx2.fillStyle = STK_MINI_COLORS[n.s] || STK_MINI_COLORS.locked;
        ctx2.fillRect(n.x * g.scale - dot / 2, n.y * g.scale - dot / 2, dot, dot);
    }

    // Rectángulo de lo que se está viendo. El pan es la esquina del árbol en coordenadas del
    // contenedor, así que la esquina visible en coordenadas del ÁRBOL es -pan/zoom.
    const vx = (-stkViewPanX / stkViewZoom) * g.scale;
    const vy = (-stkViewPanY / stkViewZoom) * g.scale;
    const vw = (g.cont.clientWidth  / stkViewZoom) * g.scale;
    const vh = (g.cont.clientHeight / stkViewZoom) * g.scale;
    ctx2.strokeStyle = 'rgba(255,255,255,0.9)';
    ctx2.lineWidth = 1;
    ctx2.strokeRect(Math.round(vx) + 0.5, Math.round(vy) + 0.5, Math.max(2, Math.round(vw)), Math.max(2, Math.round(vh)));
}

// Tocar (o arrastrar) en la miniatura centra la vista en ese punto del árbol.
(function initStkMinimap() {
    const cv = document.getElementById('stkMinimap');
    if (!cv) return;
    let down = false;
    const jump = (e) => {
        const g = _stkMiniGeom();
        if (!g) return;
        const r = cv.getBoundingClientRect();
        const tx = (e.clientX - r.left) / g.scale;   // punto pulsado, en coordenadas del árbol
        const ty = (e.clientY - r.top)  / g.scale;
        stkViewPanX = g.cont.clientWidth  / 2 - tx * stkViewZoom;
        stkViewPanY = g.cont.clientHeight / 2 - ty * stkViewZoom;
        _stkClampPan();
        _stkApplyTransform();
    };
    cv.addEventListener('pointerdown', (e) => { e.preventDefault(); down = true; cv.setPointerCapture(e.pointerId); jump(e); });
    cv.addEventListener('pointermove', (e) => { if (down) jump(e); });
    cv.addEventListener('pointerup',   () => { down = false; });
    cv.addEventListener('pointercancel', () => { down = false; });
    // El arrastre del árbol NO escucha eventos pointer: #stkContainer usa mousedown/touchstart y
    // window usa mousemove/mouseup (ver initStkPanZoom). Los eventos de ratón y touch son una
    // familia aparte de los pointer, así que un stopPropagation sobre pointerdown no los frena —
    // un toque en la miniatura saltaba Y arrastraba el árbol a la vez, peleándose entre sí.
    // La miniatura es hija del contenedor, o sea que todos esos eventos pasan por ella al burbujear:
    // cortarlos aquí basta, y también alcanza a los listeners de window (window está en el mismo
    // camino de burbujeo). El wheel se corta por lo mismo: girar la rueda encima de la miniatura
    // haría zoom sobre el árbol de fondo, que no es lo que nadie espera al usarla.
    for (const ev of ['mousedown', 'mousemove', 'mouseup', 'touchstart', 'touchmove', 'touchend', 'wheel']) {
        cv.addEventListener(ev, (e) => e.stopPropagation(), { passive: false });
    }
})();

(function initStkPanZoom() {
    const cont = document.getElementById('stkContainer');
    if (!cont) return;
    let dragging = false, moved = false, startX = 0, startY = 0, startPanX = 0, startPanY = 0;

    cont.addEventListener('mousedown', (e) => {
        dragging = true; moved = false;
        startX = e.clientX; startY = e.clientY;
        startPanX = stkViewPanX; startPanY = stkViewPanY;
        cont.classList.add('stk-dragging');
    });
    window.addEventListener('mousemove', (e) => {
        if (!dragging) return;
        const dx = e.clientX - startX, dy = e.clientY - startY;
        if (Math.abs(dx) > 3 || Math.abs(dy) > 3) moved = true;
        if (moved) {
            stkViewPanX = startPanX + dx;
            stkViewPanY = startPanY + dy;
            _stkClampPan();
            _stkApplyTransform();
        }
    });
    window.addEventListener('mouseup', () => { dragging = false; cont.classList.remove('stk-dragging'); });

    cont.addEventListener('wheel', (e) => {
        e.preventDefault();
        const rect = cont.getBoundingClientRect();
        const mx = e.clientX - rect.left, my = e.clientY - rect.top;
        const oldZoom = stkViewZoom;
        const newZoom = Math.max(0.4, Math.min(2, oldZoom * (e.deltaY > 0 ? 0.9 : 1.111)));
        stkViewPanX = mx - (mx - stkViewPanX) * (newZoom / oldZoom);
        stkViewPanY = my - (my - stkViewPanY) * (newZoom / oldZoom);
        stkViewZoom = newZoom;
        _stkClampPan();
        _stkApplyTransform();
    }, { passive: false });

    // Touch: one-finger drag to pan, pinch to zoom
    let touchStartDist = 0, touchStartZoom = 1;
    cont.addEventListener('touchstart', (e) => {
        if (e.touches.length === 1) {
            dragging = true; moved = false;
            startX = e.touches[0].clientX; startY = e.touches[0].clientY;
            startPanX = stkViewPanX; startPanY = stkViewPanY;
        } else if (e.touches.length === 2) {
            dragging = false;
            const [t1, t2] = e.touches;
            touchStartDist = Math.hypot(t2.clientX - t1.clientX, t2.clientY - t1.clientY);
            touchStartZoom = stkViewZoom;
        }
    }, { passive: true });
    cont.addEventListener('touchmove', (e) => {
        if (e.touches.length === 1 && dragging) {
            const dx = e.touches[0].clientX - startX, dy = e.touches[0].clientY - startY;
            if (Math.abs(dx) > 3 || Math.abs(dy) > 3) moved = true;
            if (moved) {
                stkViewPanX = startPanX + dx;
                stkViewPanY = startPanY + dy;
                _stkClampPan();
                _stkApplyTransform();
            }
        } else if (e.touches.length === 2) {
            const rect = cont.getBoundingClientRect();
            const [t1, t2] = e.touches;
            const dist = Math.hypot(t2.clientX - t1.clientX, t2.clientY - t1.clientY);
            const mx = (t1.clientX + t2.clientX) / 2 - rect.left;
            const my = (t1.clientY + t2.clientY) / 2 - rect.top;
            const oldZoom = stkViewZoom;
            const newZoom = Math.max(0.4, Math.min(2, touchStartZoom * (dist / touchStartDist)));
            stkViewPanX = mx - (mx - stkViewPanX) * (newZoom / oldZoom);
            stkViewPanY = my - (my - stkViewPanY) * (newZoom / oldZoom);
            stkViewZoom = newZoom;
            _stkClampPan();
            _stkApplyTransform();
        }
    }, { passive: true });
    cont.addEventListener('touchend', () => { dragging = false; });
})();

function renderSkillTree() {
    const grid = document.getElementById('stkGrid');
    if (!grid) return;
    grid.innerHTML = '';
    _stkHidePickPopup(); // avoid a stale popup pointing at a cell that no longer exists

    // Column index from node position — used only as a stable sort key so root branches keep
    // roughly their original left-to-right order (logical spacing unit stays 160).
    const colOf = x => Math.round(x / 160);

    // Children-of map (inverse of prereqs) — used to fan siblings around their shared parent.
    const childrenOf = {};
    for (const n of SKILL_TREE_NODES) {
        for (const p of _prereqList(n.id)) {
            (childrenOf[p] || (childrenOf[p] = [])).push(n.id);
        }
    }
    // The legacy chain's root (legacyT1) is always manually positioned and never consults this
    // array — but it WOULD still inflate roots.length, shifting the angle of every other
    // automatically-placed root (arquitectoWood, masCartas, startVillagers4, doubleChop...) for
    // no reason. Excluded here so adding/moving legacy nodes never reshuffles the rest of the tree.
    const roots = SKILL_TREE_NODES.filter(n => _prereqList(n.id).length === 0 && _legacyIdx(n.id) === -1)
        .sort((a, b) => colOf(a.x) - colOf(b.x) || a.y - b.y);

    // Hierarchical radial layout: every node is placed a FIXED step from its OWN parent, in a
    // direction that continues outward from the parent's own incoming direction, fanned across
    // its siblings. So a node with 5 children becomes the center of its own local circle of
    // radius STK_RADIAL_STEP — distance is always relative to the immediate parent, never to
    // some shared global ring, so unrelated branches never end up "sharing a circle".
    const rawCache = {}; // id -> { x, y, dir } in an arbitrary local coordinate space (origin at master center)
    // "que la posición inicial de los nodos sean múltiplos de 50" — el cos/sin de más abajo casi
    // nunca cae en un número redondo por su cuenta; esto solo redondea las coordenadas YA
    // calculadas (x/y, nunca dir, que sigue siendo un ángulo de verdad para el resto de la
    // matemática) así que el layout automático arranca ya alineado a la misma rejilla de 50 que
    // usa el imán del modo O (ver _stkSnapToCell), sin cambiar cómo se reparten los nodos entre
    // sí. Nunca toca STK_MANUAL_POSITIONS — lo que ya se arrastró a mano se queda exacto.
    const _stkRound50 = v => Math.round(v / 50) * 50;
    const rawOf = id => {
        if (rawCache[id]) return rawCache[id];
        const prereqs = _prereqList(id);
        const manual = STK_MANUAL_POSITIONS[id];
        if (manual) {
            const dir = prereqs.length
                ? Math.atan2(manual.y - rawOf(prereqs[0]).y, manual.x - rawOf(prereqs[0]).x)
                : Math.atan2(manual.y, manual.x);
            const r = { x: manual.x, y: manual.y, dir };
            rawCache[id] = r;
            return r;
        }
        if (!prereqs.length) {
            const idx = roots.findIndex(r => r.id === id);
            const dir = (idx / roots.length) * 2 * Math.PI - Math.PI / 2;
            const r = { x: _stkRound50(STK_RADIAL_BASE * Math.cos(dir)), y: _stkRound50(STK_RADIAL_BASE * Math.sin(dir)), dir };
            rawCache[id] = r;
            return r;
        }
        const parent = prereqs[0];
        const p = rawOf(parent);
        const siblings = childrenOf[parent] || [id];
        const idx = siblings.indexOf(id);
        const n = siblings.length;
        // Skills that need more relics to unlock sit further out — distance from the immediate
        // parent isn't just a fixed hop, it grows with this node's own relic requirement.
        // A parent with more children also needs a bit more distance on top of that, split
        // between angle and radius, or a big sibling group crowds into itself.
        const baseStep = STK_RADIAL_STEP + (CARD_MIN_RELIC[id] || 0) * 4;
        const step = n > 2 ? baseStep * (1 + 0.1 * (n - 2)) : baseStep;
        const fanWidth = n > 1 ? Math.min(2.0, 0.5 * n) : 0;
        const dir = n > 1 ? (p.dir - fanWidth / 2 + (idx / (n - 1)) * fanWidth) : p.dir;
        const r = { x: _stkRound50(p.x + step * Math.cos(dir)), y: _stkRound50(p.y + step * Math.sin(dir)), dir };
        rawCache[id] = r;
        return r;
    };
    for (const n of SKILL_TREE_NODES) rawOf(n.id);
    _stkRawPositions = rawCache;

    // "en móvil queda rara, que en vez de verse horizontal y los nodos hacia abajo se vea 90 grados
    // girada" — la disposición colocada a mano es apaisada (~2500 de ancho por ~1500 de alto): las
    // ramas se reparten a lo ancho y la profundidad baja. En un móvil en vertical eso es justo del
    // revés de lo que cabe en pantalla. Aquí se transponen las coordenadas (x,y) -> (y,x) SOLO para
    // dibujar: la profundidad pasa a avanzar hacia la derecha y las ramas se apilan hacia abajo, o
    // sea ~1500 de ancho por ~2500 de alto, que es la proporción de un móvil.
    //
    // Transposición y no un giro puro a propósito: un giro real dejaría o la profundidad avanzando
    // hacia la IZQUIERDA o el orden de las ramas invertido, mientras que transponiendo los dos ejes
    // conservan su sentido de lectura natural. Y se hace con coordenadas, no con un transform CSS
    // sobre el contenedor, porque rotar el contenedor dejaría todas las etiquetas tumbadas.
    //
    // NO se aplica en modo arreglo: esa herramienta ESCRIBE en STK_MANUAL_POSITIONS y tiene que
    // seguir trabajando siempre en las coordenadas canónicas — con los ejes cambiados, un solo
    // arrastre guardaría el árbol entero transpuesto. rawCache se reconstruye en cada render, así
    // que al encender/apagar el modo arreglo se vuelve solo a las coordenadas que toquen.
    const _stkTransposed = _MQ_PORTRAIT.matches && !stkArrangeMode;
    if (_stkTransposed) {
        for (const id in rawCache) {
            const r = rawCache[id];
            const swap = r.x; r.x = r.y; r.y = swap;
        }
        // "en móviles el legado esté arriba" — y resulta que eso arregla también lo de "aparece por
        // defecto lejos y no se ve nada", porque las dos cosas son el mismo problema. El bloque de
        // Legado está colocado DEBAJO de todo el resto (y 200..600 frente a -800..100), así que al
        // transponer queda colgando a la DERECHA, separado de la masa de nodos por un hueco vacío.
        // El centro del rectángulo que envuelve todo cae justo en ese hueco: al abrir el árbol en
        // móvil la vista aterrizaba en el vacío con el 81% de los nodos fuera de pantalla.
        //
        // Se traslada el grupo entero encima del resto y alineado por la izquierda. Moverlo en
        // bloque es seguro: Legado no tiene NI UN prerrequisito que cruce a otra rama (las 7 aristas
        // cruzadas del árbol son entre aldea/obras/bosque/edificación/población), así que ninguna
        // línea de conexión se estira. Solo afecta al dibujo en móvil — STK_MANUAL_POSITIONS no se
        // toca, y en escritorio el Legado sigue donde lo colocaste.
        const _legIds = [...LEGACY_NODE_IDS, ...Object.keys(LEGACY_PKG_NODES)].filter(id => rawCache[id]);
        const _legSet = new Set(_legIds);
        const _rest = SKILL_TREE_NODES.filter(n => !_legSet.has(n.id) && rawCache[n.id]).map(n => rawCache[n.id]);
        if (_legIds.length && _rest.length) {
            const _legs = _legIds.map(id => rawCache[id]);
            // "en móvil deja esto en horizontal": la transposición de arriba convertía la fila del
            // Legado (T1→T2→T3→T4 en línea, con el abanico de paquetes a su derecha) en una columna
            // que se comía toda la altura de la pantalla. Se deshace SOLO para este grupo — vuelve a
            // sus ejes originales — y como no tiene ninguna arista con otra rama (ver arriba), su
            // orientación interna es independiente del resto. Antes de calcular _dx/_dy, para que
            // el traslado en bloque use las medidas de la fila, no de la columna.
            for (const r of _legs) { const swap = r.x; r.x = r.y; r.y = swap; }
            const _dx = Math.min(..._rest.map(r => r.x)) - Math.min(..._legs.map(r => r.x));
            const _dy = (Math.min(..._rest.map(r => r.y)) - stkGridCell * 2) - Math.max(..._legs.map(r => r.y));
            for (const r of _legs) { r.x += _dx; r.y += _dy; }
        }
    }
    // Cuántos nodos han caído en cada celda de la matriz. Con el imán activo dos nodos pueden
    // acabar exactamente encima el uno del otro y, como el de arriba tapa al de abajo, el hueco
    // "vacío" que dejan en otra parte de la cuadrícula no se explica por ningún sitio. Solo se
    // calcula en modo arreglo: fuera de él nadie lo mira y son 106 nodos por render.
    const cellCount = new Map();
    if (stkArrangeMode) {
        for (const n of SKILL_TREE_NODES) {
            const k = _stkCellKey(rawCache[n.id]);
            cellCount.set(k, (cellCount.get(k) || 0) + 1);
        }
    }

    // Fit the whole (arbitrarily-placed) layout into a properly sized, centered container
    let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
    for (const n of SKILL_TREE_NODES) {
        if (!_stkIsVisible(n.id)) continue;
        const r = rawCache[n.id];
        minX = Math.min(minX, r.x); maxX = Math.max(maxX, r.x);
        minY = Math.min(minY, r.y); maxY = Math.max(maxY, r.y);
    }
    const pad = STK_CELL / 2 + 20;
    // Sitio por ENCIMA del árbol para la tarjeta de Puntos de Legado, que se coloca 150px sobre el
    // nodo más alto del grupo (ver _stkAppendLegacyHeader) y se topa en 4. En escritorio el Legado
    // está abajo del todo y tiene hueco de sobra; en móvil el grupo va pegado al borde superior
    // (ver el bloque _stkTransposed), así que sin este margen la tarjeta se topaba y caía ENCIMA
    // de los primeros nodos. 170 = los 150 de la tarjeta + aire.
    const padTop = pad + (_stkTransposed ? 170 : 0);
    const totalW = (maxX - minX) + pad * 2;
    const totalH = (maxY - minY) + pad + padTop;
    const offX = pad - minX, offY = padTop - minY;

    const positions = new Map();
    for (const n of SKILL_TREE_NODES) {
        const r = rawCache[n.id];
        positions.set(n.id, { x: r.x + offX, y: r.y + offY });
    }
    _stkMiniNodes = []; // lo rellena el bucle de celdas de más abajo, con el estado ya resuelto

    grid.style.width  = totalW + 'px';
    grid.style.height = totalH + 'px';
    // Matriz visible del modo arreglo: una celda por nodo, en el mismo espacio de coordenadas que
    // ellos — va dentro de #stkGrid, así que pan/zoom la mueven igual. Línea por celda y otra más
    // marcada cada 5, para no perder la cuenta recorriendo 106 nodos. El tamaño va por variable
    // (stkGridCell, botón "Celda" de la barra dev), así que tanto el paso de las líneas como su
    // posición se escriben aquí en vez de quedarse fijos en la hoja de estilo.
    //
    // La MEDIA CELDA de desplazamiento es lo que centra el nodo en su hueco: el imán deja el CENTRO
    // del nodo en múltiplos del paso, así que corriendo la rejilla medio paso las líneas caen justo
    // a mitad de camino entre dos centros. background-position se recalcula en cada render porque el
    // propio div arranca en un offset (offX/offY) que no es múltiplo de nada — sin esto la rejilla
    // dibujada y el imán real no coincidirían.
    if (stkArrangeMode) {
        grid.classList.add('stk-grid-arrange');
        const gmod = (v, m) => ((v % m) + m) % m;
        const cell = stkGridCell, accent = cell * 5, half = cell / 2;
        grid.style.backgroundSize =
            `${accent}px ${accent}px, ${accent}px ${accent}px, ${cell}px ${cell}px, ${cell}px ${cell}px`;
        const ax = gmod(offX - half, accent), ay = gmod(offY - half, accent);
        const fx = gmod(offX - half, cell),   fy = gmod(offY - half, cell);
        grid.style.backgroundPosition = `${ax}px ${ay}px, ${ax}px ${ay}px, ${fx}px ${fy}px, ${fx}px ${fy}px`;
    } else {
        grid.classList.remove('stk-grid-arrange');
        grid.style.backgroundPosition = '';
        grid.style.backgroundSize = '';
    }
    _stkTreeW = totalW;
    _stkTreeH = totalH;
    if (!_stkViewInitialized) {
        const cont = document.getElementById('stkContainer');
        // Solo se da por centrado si el contenedor tiene tamaño REAL. Quien abre el panel y
        // renderiza en el mismo tick (ver _stkPeekFromCardModal, el "Ver árbol" del modal de
        // cartas) todavía no ha pasado por maquetación, así que aquí clientWidth/Height valían 0:
        // el pan salía un número enorme negativo y el árbol quedaba fuera de pantalla — y como el
        // latch ya estaba puesto, no se recentraba jamás. Se nota sobre todo en móvil, donde el
        // panel no suele haberse abierto antes con medidas buenas.
        if (cont && cont.clientWidth > 0 && cont.clientHeight > 0) {
            _stkViewInitialized = true;
            // Zoom inicial que hace CABER el árbol, en vez de entrar siempre a 1:1. A 1:1 un árbol
            // de 900x3400 (móvil) en un panel de ~390 de ancho enseña una ventana diminuta, y da
            // igual dónde la centres: "no se ve nada".
            //
            // En móvil se ajusta solo al ANCHO y se entra por ARRIBA, no encajando el árbol entero:
            // transpuesto es mucho más alto que ancho, así que meterlo completo dejaría los nodos a
            // ~17px, ilegibles. Ajustando al ancho quedan a ~27px y se baja con el dedo, que es el
            // gesto natural ahí — y como el Legado se acaba de mover arriba, lo primero que se ve
            // al abrir es justo él. En escritorio se encaja entero (ancho y alto) y se centra.
            //
            // El tope de 1 evita AMPLIAR un árbol que ya cabía; el suelo de 0.25 es el mismo mínimo
            // que admite el zoom con la rueda.
            const _fitW = cont.clientWidth / totalW, _fitH = cont.clientHeight / totalH;
            stkViewZoom = Math.max(0.25, Math.min(1, (_stkTransposed ? _fitW : Math.min(_fitW, _fitH)) * 0.95));
            stkViewPanX = (cont.clientWidth  - totalW * stkViewZoom) / 2;
            stkViewPanY = _stkTransposed ? 0 : (cont.clientHeight - totalH * stkViewZoom) / 2;
        }
    }
    _stkClampPan();
    _stkApplyTransform();

    // Connector lines: one per (node, prerequisite) pair, drawn behind the cells
    const svgNS = 'http://www.w3.org/2000/svg';
    const svg = document.createElementNS(svgNS, 'svg');
    svg.setAttribute('width', totalW);
    svg.setAttribute('height', totalH);
    svg.style.cssText = 'position:absolute;left:0;top:0;pointer-events:none;z-index:0;';
    for (const n of SKILL_TREE_NODES) {
        if (!_stkIsVisible(n.id) || !_stkSpecShow(n.id)) continue;
        for (const prId of _prereqList(n.id)) {
            const prNode = STK_NODE_MAP[prId];
            if (!prNode || !_stkSpecShow(prId)) continue;
            const a = positions.get(prId), b = positions.get(n.id);
            const satisfied = isSkillActive(prId);
            const line = document.createElementNS(svgNS, 'line');
            line.setAttribute('x1', a.x); line.setAttribute('y1', a.y);
            line.setAttribute('x2', b.x); line.setAttribute('y2', b.y);
            line.setAttribute('class', 'stk-link' + (satisfied ? ' stk-link-active' : ''));
            line.dataset.child = n.id;
            line.dataset.parent = prId;
            svg.appendChild(line);
        }
    }
    grid.appendChild(svg);

    for (const n of SKILL_TREE_NODES) {
        const id   = n.id;
        if (!_stkIsVisible(id) || !_stkSpecShow(id)) continue;
        const st   = stkState(id);
        const icon = SKILL_CARD_ICONS[id] || 'fa-solid fa-star';
        // A coming-soon teaser (see STK_COMING_SOON) always renders as locked/rubble-looking,
        // even if isSkillActive(id) is true from an old save/test session — the branch isn't
        // actually playable yet, so it should never suddenly show as purchased with its real name.
        const isSoon = STK_COMING_SOON.has(id);

        // Visual state mapping
        const isActive    = !isSoon && (st === 'active' || st === 'pending' || st === 'removing');
        const isAvail     = !isSoon && st === 'available';
        const isLocked    = isSoon || st === 'locked';
        const cssState    = isActive ? 'purchased' : isAvail ? 'available' : 'locked';

        const c = positions.get(id);
        // Cacheado para el minimapa: se redibuja en cada frame de arrastre, así que no puede
        // recorrer los 106 nodos ni recalcular estados por su cuenta (ver _stkDrawMinimap).
        _stkMiniNodes.push({ x: c.x, y: c.y, s: cssState });

        // Locked nodes with a relic minimum get a progress ring around them (behind the icon)
        // showing how close the run is to meeting it, e.g. 3/5 relics ≈ 60% of the ring filled.
        // Building-unlock skills are square, so their progress trace is a rounded rectangle
        // instead of a circle, matching the node's own shape. Only shown once every skill
        // prerequisite is already satisfied — i.e. relics are the *only* thing still blocking it.
        const legacyIdx = _legacyIdx(id);
        const isLegacy  = _isLegacyNode(id); // fixed tier OR one of the three package forks
        // Coming-soon teasers never get the relic-progress ring — they're excluded from the card
        // pool entirely (see CARD_POOL_EXCLUDED), so a ring implying "collect relics to unlock
        // this" would be actively misleading. Legado nodes skip it too: the branch's header card
        // already shows that same progress as a bar, and one number in two places is one too many.
        if (isLocked && !isSoon && !isLegacy) {
            const minR = CARD_MIN_RELIC[id] || 0;
            const curRRaw = _relicsCollectedCount();
            const ringColor = '#e8c000';
            const prereqsMet = _prereqList(id).every(p => _chainOk(p));
            if (minR > 0 && prereqsMet) {
                const curR = Math.max(0, Math.min(minR, curRRaw));
                const pct = curR / minR;
                const ringSize = STK_CELL + 14;
                const ringSvg = document.createElementNS(svgNS, 'svg');
                ringSvg.setAttribute('width', ringSize);
                ringSvg.setAttribute('height', ringSize);
                ringSvg.style.cssText = `position:absolute;left:${c.x - ringSize / 2}px;top:${c.y - ringSize / 2}px;pointer-events:none;z-index:0;`;
                if (STK_BUILDING_SKILLS.has(id)) {
                    const inset = 4, rx = 10;
                    const rw = ringSize - inset * 2, rh = ringSize - inset * 2;
                    const perimeter = 2 * (rw + rh) - 8 * rx + 2 * Math.PI * rx;
                    ringSvg.innerHTML = `
                        <rect x="${inset}" y="${inset}" width="${rw}" height="${rh}" rx="${rx}" fill="none" stroke="rgba(255,255,255,0.08)" stroke-width="4"/>
                        <rect x="${inset}" y="${inset}" width="${rw}" height="${rh}" rx="${rx}" fill="none" stroke="${ringColor}" stroke-width="4"
                            stroke-linecap="round" stroke-dasharray="${perimeter}"
                            stroke-dashoffset="${perimeter * (1 - pct)}"/>
                    `;
                } else {
                    const cxr = ringSize / 2, radius = cxr - 4;
                    const circumference = 2 * Math.PI * radius;
                    ringSvg.innerHTML = `
                        <circle cx="${cxr}" cy="${cxr}" r="${radius}" fill="none" stroke="rgba(255,255,255,0.08)" stroke-width="4"/>
                        <circle cx="${cxr}" cy="${cxr}" r="${radius}" fill="none" stroke="${ringColor}" stroke-width="4"
                            stroke-linecap="round" stroke-dasharray="${circumference}"
                            stroke-dashoffset="${circumference * (1 - pct)}"
                            transform="rotate(-90 ${cxr} ${cxr})"/>
                    `;
                }
                grid.appendChild(ringSvg);
            }
        }

        const isPeekPick = _stkCardPeekPicks && _stkCardPeekPicks.includes(id);
        const cell = document.createElement('div');
        cell.className = `stk-cell ${cssState}${STK_BUILDING_SKILLS.has(id) ? ' stk-cell-square' : ''}${isPeekPick ? ' stk-cell-peek-pick' : ''}${isLegacy ? ' stk-cell-legacy' : ''}`;
        cell.dataset.id = id;
        cell.style.position = 'absolute';
        cell.style.left = (c.x - STK_CELL / 2) + 'px';
        cell.style.top  = (c.y - STK_CELL / 2) + 'px';

        // Icon + name label under the node — full description still lives in the hover tooltip
        // (see _stkShowTooltip). Nodes never explored before stay masked as "???" so the surprise
        // isn't spoiled; nodes explored in a past run (even if not currently owned) show their
        // real name, matching the "remembered branches" behavior.
        const nameKeyText = isLegacy ? t(_legacyNodeDisplay(id).nameKey) : t('skill.' + id + '.name');
        const labelText = isSoon ? t('stk.coming_soon_label')
            : (!isLocked || isLegacy || _everExploredSkills.has(id)) ? nameKeyText : '???';
        const raw = rawCache[id];
        const debugPosHtml = stkArrangeMode
            ? `<span class="stk-cell-debug-pos" style="position:absolute;bottom:-16px;left:0;width:100%;text-align:center;font-size:9px;color:#40e0d0;background:rgba(0,0,0,.6);pointer-events:none;">${Math.round(raw.x)}, ${Math.round(raw.y)}</span>`
            : '';
        // Purchase-order badge — which numbered pick this was this run (not shown on Legado
        // nodes, which are claimed by fixed tier order already implied by their own position).
        const orderIdx = (!isLegacy && isActive) ? _skillPurchaseOrder.indexOf(id) : -1;
        const orderBadgeHtml = orderIdx !== -1 ? `<span class="stk-cell-order-badge">${orderIdx + 1}</span>` : '';
        cell.innerHTML = `
            <span class="stk-cell-icon"><i class="${icon}"></i></span>
            <span class="stk-cell-label">${labelText}</span>
            ${debugPosHtml}
            ${orderBadgeHtml}
        `;
        if (stkArrangeMode) {
            cell.style.outline = '1px dashed #40e0d0';
            cell.style.cursor = 'move';
            if ((cellCount.get(_stkCellKey(raw)) || 0) > 1) cell.classList.add('stk-cell-collision');
            cell.addEventListener('mousedown', (e) => {
                e.stopPropagation();
                const startX = e.clientX, startY = e.clientY;
                const base = STK_MANUAL_POSITIONS[id] || { x: raw.x, y: raw.y };
                const baseX = base.x, baseY = base.y;
                // Ya no hay ancla ni geometría radial: todos los nodos, con o sin prerrequisito,
                // se imantan a la MISMA matriz de celdas (ver _stkSnapToCell / STK_CELL).
                // Ctrl+arrastrar mueve la RAMA ENTERA (todos los descendientes) junto con el
                // nodo, conservando la posición relativa de cada uno — se decide al empezar el
                // arrastre (no a media pulsación) para que no dé tirones si Ctrl se suelta o
                // pulsa a mitad de camino. Las posiciones base de cada descendiente se capturan
                // aquí una sola vez; el resto del drag solo les aplica el mismo delta que al nodo
                // arrastrado, después de su propio imán/snap.
                const moveBranch = e.ctrlKey;
                const branchBases = moveBranch
                    ? _stkCollectDescendants(id, childrenOf).map(cid => ({
                        id: cid,
                        base: STK_MANUAL_POSITIONS[cid] || rawCache[cid],
                    }))
                    : [];
                let moved = false;
                const onMove = (me) => {
                    const dx = (me.clientX - startX) / stkViewZoom;
                    const dy = (me.clientY - startY) / stkViewZoom;
                    if (Math.abs(dx) > 1 || Math.abs(dy) > 1) moved = true;
                    let next = { x: baseX + dx, y: baseY + dy };
                    if (!me.altKey) next = _stkSnapToCell(next.x, next.y);
                    STK_MANUAL_POSITIONS[id] = next;
                    if (moveBranch) {
                        const appliedDx = next.x - baseX, appliedDy = next.y - baseY;
                        for (const b of branchBases) {
                            STK_MANUAL_POSITIONS[b.id] = { x: b.base.x + appliedDx, y: b.base.y + appliedDy };
                        }
                    }
                    renderSkillTree();
                };
                const onUp = () => {
                    window.removeEventListener('mousemove', onMove);
                    window.removeEventListener('mouseup', onUp);
                    if (moved) _stkLogManualPositions();
                };
                window.addEventListener('mousemove', onMove);
                window.addEventListener('mouseup', onUp);
            });
        }

        const prs = _prereqList(id);
        cell.addEventListener('mouseenter', (e) => {
            if (isLocked && prs.length) {
                for (const pr of prs) {
                    const prereqCell = grid.querySelector(`[data-id="${pr}"]`);
                    if (prereqCell) prereqCell.classList.add('stk-cell-prereq-highlight');
                }
                svg.querySelectorAll(`line[data-child="${id}"]`).forEach(l => l.classList.add('stk-link-highlight'));
            }
            _stkShowTooltip(id, cell);
        });
        cell.addEventListener('mouseleave', () => {
            if (isLocked && prs.length) {
                for (const pr of prs) {
                    const prereqCell = grid.querySelector(`[data-id="${pr}"]`);
                    if (prereqCell) prereqCell.classList.remove('stk-cell-prereq-highlight');
                }
                svg.querySelectorAll(`line[data-child="${id}"]`).forEach(l => l.classList.remove('stk-link-highlight'));
            }
            _stkHideTooltip();
        });
        if (isPeekPick) {
            cell.addEventListener('click', (e) => {
                e.stopPropagation();
                _stkShowPickPopup(id, cell);
            });
        } else if (isLegacy && isAvail) {
            cell.addEventListener('click', (e) => {
                e.stopPropagation();
                // A package fork always claims the NEXT free slot (prestige.nextIdx) — which slot
                // that is depends only on how many packages you've already taken — and arrives
                // with itself preselected, since clicking that node IS the choice.
                const slotIdx = legacyIdx !== -1 ? legacyIdx : prestige.nextIdx;
                showPrestigeConfirm(slotIdx, _stkPendingRelicBonus() > 0, _legacyPkgId(id));
            });
        }

        grid.appendChild(cell);
    }

    _stkAppendLegacyHeader(grid, positions);
    // Al final a propósito: el _stkApplyTransform() de más arriba corre ANTES de que el bucle de
    // celdas haya rellenado _stkMiniNodes, así que ese primer dibujo saldría vacío.
    _stkDrawMinimap();
}

// Header card floating above the Legado branch: how many Legado points you've banked, and a bar
// running 0→cost-of-the-next-one (0-20, then 0-30, ...). Lives in tree space (inside #stkGrid),
// so it pans and zooms with the branch it belongs to rather than floating loose over the panel.
function _stkAppendLegacyHeader(grid, positions) {
    // "quita el tema de legados durante el reto" — este panel usa _stkIsVisible, no _stkSpecShow
    // (esa otra función solo gobierna los nodos/líneas en sí), así que necesita su propio corte.
    if (_retoActive) return;
    const ids = [...LEGACY_NODE_IDS, ...Object.keys(LEGACY_PKG_NODES)].filter(id => positions.has(id) && _stkIsVisible(id));
    if (!ids.length) return;
    let minX = Infinity, maxX = -Infinity, minY = Infinity;
    for (const id of ids) {
        const p = positions.get(id);
        minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x); minY = Math.min(minY, p.y);
    }

    // The headline number is what you HOLD right now — Legado points earned and not yet spent —
    // not a lifetime tally of tiers already claimed. Those are gone; they're on the tree as owned
    // nodes. Walk the remaining slots paying for each one the bank can cover: whatever the bank
    // still buys is what you have, and the leftover is the progress toward the one after.
    let points = 0;
    let rest = _prestigeRelicBank + _stkPendingRelicBonus();
    let slot = prestige.nextIdx;
    while (PRESTIGE_MILESTONES[slot] && rest >= PRESTIGE_MILESTONES[slot].relic) {
        rest -= PRESTIGE_MILESTONES[slot].relic;
        points++;
        slot++;
    }
    const cost  = PRESTIGE_MILESTONES[slot] ? PRESTIGE_MILESTONES[slot].relic : Infinity;
    const done  = !isFinite(cost);
    const ready = points > 0;
    const pct   = done ? 1 : Math.max(0, Math.min(1, rest / cost));

    const statusText = done  ? t('legacy.panel.all')
                     : ready ? t('legacy.panel.ready')
                             : t('legacy.panel.next');
    // Muted on purpose: this is ambient context sitting behind the branch, not a call to action.
    // Only the "ready to spend" state is allowed to warm up, so it reads as the exception.
    const barColor = ready || done ? 'rgba(216,184,120,.85)' : 'rgba(168,112,112,.6)';
    const accent   = ready || done ? '#d8b878' : 'rgba(198,184,164,.65)';

    const W = 210;
    const el = document.createElement('div');
    el.className = 'stk-legacy-header';
    // Clamped so a Legado branch sitting near the top of the tree can't push the card off the
    // grid entirely. pointer-events:none below means that even if it ends up overlapping a node,
    // hovering and clicking still reach the node underneath — EXCEPT the rebuild button, which
    // opts back into pointer-events:auto on itself so it stays clickable despite the parent.
    const top = Math.max(4, minY - 150);
    el.style.cssText = `position:absolute;left:${(minX + maxX) / 2 - W / 2}px;top:${top}px;width:${W}px;`
        + 'box-sizing:border-box;padding:9px 14px 10px;background:rgba(18,15,12,.66);'
        + 'border:1px solid rgba(200,160,80,.18);border-radius:8px;text-align:center;'
        + 'pointer-events:none;z-index:2;';
    // "Reconstruir Ciudad" vive AQUÍ, no en Ajustes — justo donde se ve el Legado, que es de lo
    // que depende (pide todos los tramos reclamados). Solo aparece cuando done es true; el resto
    // del tiempo esta tarjeta sigue siendo puramente informativa.
    const rebuildBtn = done && !_spectatorMode && !_foreignStateInMemory
        ? `<button onclick="_openRebuildCityModal()" style="pointer-events:auto;width:100%;margin-top:8px;
             background:linear-gradient(160deg,#dfb256,#a97d2f);border:1px solid #6a4a1a;border-radius:6px;
             padding:7px 8px;font-family:'Cinzel',serif;font-size:11px;font-weight:700;color:#2a1e10;
             cursor:pointer;white-space:nowrap;"><i class="fa-solid fa-city"></i> ${t('settings.rebuild_city')}</button>`
        : '';
    el.innerHTML = `
        <div style="font-size:8px;letter-spacing:1.6px;text-transform:uppercase;color:rgba(198,184,164,.5);">${t('legacy.panel.title')}</div>
        <div style="font-family:'Cinzel',serif;font-size:20px;color:${accent};line-height:1.35;">${points}</div>
        <div style="height:4px;background:rgba(255,255,255,.07);border-radius:2px;overflow:hidden;margin:5px 0 4px;">
            <div style="height:100%;width:${(pct * 100).toFixed(1)}%;background:${barColor};"></div>
        </div>
        <div style="font-family:'Roboto Mono',monospace;font-size:10px;color:rgba(198,184,164,.55);">${done ? '—' : `${rest} / ${cost}`}</div>
        <div style="font-size:9px;line-height:1.45;margin-top:3px;color:${ready || done ? accent : 'rgba(198,184,164,.42)'};">${statusText}</div>
        ${rebuildBtn}
    `;
    grid.appendChild(el);
}

// Big hover tooltip: name + description (or, if locked, why) — replaces the text that used
// to live inline in each (now icon-only) node.
function _stkShowTooltip(id, cellEl) {
    const tip = document.getElementById('stkTooltip');
    if (!tip) return;
    const st = stkState(id);
    const isLocked = st === 'locked';
    const icon = SKILL_CARD_ICONS[id] || 'fa-solid fa-star';
    const li = _legacyIdx(id);
    const isLegacy = _isLegacyNode(id); // fixed tier OR one of the three package forks
    let bodyHTML;
    if (STK_COMING_SOON.has(id)) {
        // Always the "Modo Guerra" teaser, even if isSkillActive(id) is true from an old
        // save/test session — see the matching override in renderSkillTree's cell rendering.
        const soonKey = 'skill.' + id + '.soon_desc';
        const soonText = t(soonKey);
        const desc = (soonText === soonKey) ? t('stk.coming_soon_desc') : soonText;
        bodyHTML = `<div class="stk-tip-name"><i class="${icon}"></i> ${t('stk.coming_soon_label')}</div><div class="stk-tip-desc">${desc}</div>`;
    } else if (isLocked) {
        const unmetPrereqs = _prereqList(id).filter(p => !isSkillActive(p));
        const minR = isLegacy ? _legacyNodeCost(id) : (CARD_MIN_RELIC[id] || 0);
        const curR = isLegacy ? (_prestigeRelicBank + _stkPendingRelicBonus()) : _relicsCollectedCount();
        const lines = [];
        if (unmetPrereqs.length === 1) lines.push(t('stk.lock.needs_skill'));
        else if (unmetPrereqs.length > 1) lines.push(t('stk.lock.needs_skills', { n: unmetPrereqs.length }));
        // Only show relic progress once prereqs are the sole remaining blocker — otherwise a
        // node with plenty of relics banked (e.g. 25/6) looks "ready" while still locked on
        // an unrelated skill requirement. Legado nodes are exempt: the branch's own header card
        // already shows that exact count as a bar, so repeating it here was pure duplication.
        if (minR && !isLegacy && unmetPrereqs.length === 0) lines.push(`⚗ ${curR}/${minR} ${t('stk.lock.relics')}`);
        // Already explored in a past run — show the real name/description instead of masking it,
        // the lock reason still follows underneath. Legacy tiers are a known fixed progression,
        // so their name/desc is never masked even before enough relics are banked.
        const isKnown = isLegacy || _everExploredSkills.has(id);
        const knownName = isKnown ? (isLegacy ? t(_legacyNodeDisplay(id).nameKey) : t('skill.' + id + '.name')) : '???';
        const knownDesc = isKnown ? `${isLegacy ? t(_legacyNodeDisplay(id).descKey) : _skillDesc(id)}<br>` : '';
        bodyHTML = `<div class="stk-tip-name"><i class="${icon}"></i> ${knownName}</div><div class="stk-tip-desc">${knownDesc}${lines.join('<br>')}</div>`;
    } else if (isLegacy) {
        const disp = _legacyNodeDisplay(id);
        const extra = st === 'available' ? `<br><span style="color:var(--gold-bright);font-weight:bold;">${t('prestige.tip.click_to_reset')}</span>` : '';
        bodyHTML = `<div class="stk-tip-name"><i class="${icon}"></i> ${t(disp.nameKey)}</div><div class="stk-tip-desc">${t(disp.descKey)}${extra}</div>`;
    } else {
        bodyHTML = `<div class="stk-tip-name"><i class="${icon}"></i> ${t('skill.' + id + '.name')}</div><div class="stk-tip-desc">${_skillDesc(id)}</div>`;
    }
    tip.innerHTML = bodyHTML;
    tip.style.display = 'block';

    // Position it beside the node, flipping to stay inside the scroll container's viewport.
    // On narrow mobile screens, left/right often doesn't fit either way — stack it above (or
    // below, if there's no room above) the node instead, so it never gets clipped off-screen.
    const contRect = document.getElementById('stkContainer').getBoundingClientRect();
    const cellRect = cellEl.getBoundingClientRect();
    const tipRect = tip.getBoundingClientRect();
    let left, top;
    if (_MQ_PORTRAIT.matches) {
        left = cellRect.left + cellRect.width / 2 - tipRect.width / 2;
        left = Math.max(contRect.left + 8, Math.min(contRect.right - tipRect.width - 8, left));
        top = cellRect.top - tipRect.height - 12;
        if (top < contRect.top + 8) top = cellRect.bottom + 12;
    } else {
        left = cellRect.right + 12;
        if (left + tipRect.width > contRect.right) left = cellRect.left - tipRect.width - 12;
        top = cellRect.top + cellRect.height / 2 - tipRect.height / 2;
        top = Math.max(contRect.top + 8, Math.min(contRect.bottom - tipRect.height - 8, top));
    }
    tip.style.left = left + 'px';
    tip.style.top  = top + 'px';
}
function _stkHideTooltip() {
    const tip = document.getElementById('stkTooltip');
    if (tip) tip.style.display = 'none';
}

// Click popup for a relic-card candidate node while peeking at the tree (see
// _stkPeekFromCardModal): shows what the skill does plus a button that picks it right
// there, without needing to go back to the card modal first.
function _stkShowPickPopup(id, cellEl) {
    const pop = document.getElementById('stkPickPopup');
    if (!pop) return;
    // A tap fires a synthetic mouseenter before the click on touch devices, which would leave
    // the hover tooltip (_stkShowTooltip) open underneath/behind this popup — hide it here so
    // only one of the two ever shows at once.
    _stkHideTooltip();
    const icon = SKILL_CARD_ICONS[id] || 'fa-solid fa-star';
    pop.innerHTML = `
        <button class="stk-pick-popup-close" onclick="_stkHidePickPopup()" title="${t('tip.close')}">&times;</button>
        <div class="stk-tip-name"><i class="${icon}"></i> ${t('skill.' + id + '.name')}</div>
        <div class="stk-tip-desc">${_skillDesc(id)}</div>
        <button class="stk-pick-popup-btn" onclick="_stkChooseFromTree('${id}')">${t('card.choose_this')}</button>
    `;
    pop.style.display = 'block';

    // See _stkShowTooltip: same left/right-vs-stack-above logic, mobile screens are too
    // narrow for the beside-the-node placement to ever land fully on screen.
    const contRect = document.getElementById('stkContainer').getBoundingClientRect();
    const cellRect = cellEl.getBoundingClientRect();
    const popRect = pop.getBoundingClientRect();
    let left, top;
    if (_MQ_PORTRAIT.matches) {
        left = cellRect.left + cellRect.width / 2 - popRect.width / 2;
        left = Math.max(contRect.left + 8, Math.min(contRect.right - popRect.width - 8, left));
        top = cellRect.top - popRect.height - 12;
        if (top < contRect.top + 8) top = cellRect.bottom + 12;
    } else {
        left = cellRect.right + 12;
        if (left + popRect.width > contRect.right) left = cellRect.left - popRect.width - 12;
        top = cellRect.top + cellRect.height / 2 - popRect.height / 2;
        top = Math.max(contRect.top + 8, Math.min(contRect.bottom - popRect.height - 8, top));
    }
    pop.style.left = left + 'px';
    pop.style.top  = top + 'px';
}
function _stkHidePickPopup() {
    const pop = document.getElementById('stkPickPopup');
    if (pop) pop.style.display = 'none';
}
window._stkHidePickPopup = _stkHidePickPopup;
function _stkChooseFromTree(id) {
    _stkHidePickPopup();
    _stkCardPeekPicks = null;
    const panel = document.getElementById('skillTreePanel');
    if (panel) panel.style.display = 'none';
    skillTreeOpen = false;
    _stkSyncDevToolbar();
    const backBtn = document.getElementById('stkBackToCardsBtn');
    if (backBtn) backBtn.style.display = 'none';
    // This exit path (picking straight from the tree, instead of going back to the card modal
    // or closing the tree via its own title bar) was missing the same cleanup those two other
    // paths already do — left #btnSettings hidden and the "Watch ad: +N cards" button stuck on
    // screen (see _stkReturnToCardModal / openSkillTree for the equivalent restore logic).
    const _btnSettingsForPeek = document.getElementById('btnSettings');
    if (_btnSettingsForPeek) _setBtnSettingsHidden(_spectatorMode);
    _skillCardUpdateMoreBtn();
    _activateSkill(id);
}
window._stkChooseFromTree = _stkChooseFromTree;

// Legacy canvas stubs (no longer used but referenced)
function _stkH() {}
function _OLD_renderSkillTree_canvas() {
    const canvas = document.getElementById('stkCanvas');
    if (!canvas) return;

    ctx.fillStyle = '#080700';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.save();
    ctx.translate(stkPan.x, stkPan.y);
    ctx.scale(stkZoom, stkZoom);

    // --- 1. Grass tile background ---
    const T = STK_TILE; // must equal STK_TILE so node corners align to grid
    const wx0 = Math.floor((-stkPan.x / stkZoom - T) / T);
    const wy0 = Math.floor((-stkPan.y / stkZoom - T) / T);
    const wx1 = Math.ceil(((canvas.width  - stkPan.x) / stkZoom + T) / T);
    const wy1 = Math.ceil(((canvas.height - stkPan.y) / stkZoom + T) / T);
    const GRASS = ['#3c5020','#3a4e1e','#425621','#3d531f','#415420','#3e5220','#435821'];
    for (let ty = wy0; ty <= wy1; ty++) {
        for (let tx = wx0; tx <= wx1; tx++) {
            const h = _stkH(tx, ty);
            const px = tx * T, py = ty * T;
            ctx.fillStyle = GRASS[h % 7];
            ctx.fillRect(px, py, T, T);
            const det = (h >> 4) % 10;
            if (det === 0) {
                ctx.fillStyle = '#2e3d17';
                ctx.fillRect(px + (h >> 8) % 20 + 4, py + (h >> 12) % 20 + 4, 3, 5);
                ctx.fillRect(px + (h >> 8) % 18 + 8, py + (h >> 12) % 18 + 8, 3, 4);
            } else if (det === 1) {
                ctx.fillStyle = '#50483a';
                ctx.fillRect(px + (h >> 8) % 22 + 3, py + (h >> 12) % 22 + 3, 6, 4);
            }
        }
    }

    // --- 1b. Tile grid overlay (subtle lines every STK_TILE px) ---
    ctx.strokeStyle = 'rgba(0,0,0,0.18)'; ctx.lineWidth = 1;
    for (let tx = wx0; tx <= wx1; tx++) {
        ctx.beginPath(); ctx.moveTo(tx*T, wy0*T); ctx.lineTo(tx*T, wy1*T); ctx.stroke();
    }
    for (let ty = wy0; ty <= wy1; ty++) {
        ctx.beginPath(); ctx.moveTo(wx0*T, ty*T); ctx.lineTo(wx1*T, ty*T); ctx.stroke();
    }

    // --- 2. Dirt roads — only between visible nodes (active or available) ---
    ctx.lineCap = 'round';
    for (const rid of STK_ROOT_IDS) {
        const rn = STK_NODE_MAP[rid]; if (!rn) continue;
        if (!stkRevealAll && stkState(rid) === 'locked') continue;
        const rs = (rn.ts || 3) * STK_TILE;
        _stkRoad(ctx, STK_CX, STK_CY, rn.x + rs / 2, rn.y + rs / 2);
    }
    for (const [cid, pid] of Object.entries(SKILL_PREREQS)) {
        const cn = STK_NODE_MAP[cid], pn = STK_NODE_MAP[pid];
        if (!cn || !pn) continue;
        if (!stkRevealAll && stkState(cid) === 'locked' && !STK_COMING_SOON.has(cid)) continue;
        const ps = (pn.ts || 3) * STK_TILE, cs = (cn.ts || 3) * STK_TILE;
        _stkRoad(ctx, pn.x + ps / 2, pn.y + ps / 2, cn.x + cs / 2, cn.y + cs / 2);
    }
    ctx.lineCap = 'butt';

    // --- 3. Center landmark ---
    _stkCenter(ctx);

    // --- 4. Skill buildings — skip locked nodes entirely, except coming-soon teasers (see
    // STK_COMING_SOON), which are meant to be seen — as clearly blocked — before they're reachable.
    for (const n of SKILL_TREE_NODES) {
        if (stkRevealAll || stkState(n.id) !== 'locked' || STK_COMING_SOON.has(n.id)) stkDrawNode(ctx, n);
    }

    ctx.restore();
}

function _stkRoad(ctx, x1, y1, x2, y2) {
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2);
    ctx.strokeStyle = '#2e1e08'; ctx.lineWidth = 28; ctx.stroke();
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2);
    ctx.strokeStyle = '#5a3e18'; ctx.lineWidth = 18; ctx.stroke();
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2);
    ctx.strokeStyle = '#6e4e28'; ctx.lineWidth = 10; ctx.stroke();
}

function _stkCenter(ctx) {
    const cx = STK_CX, cy = STK_CY;
    // Stone plaza
    ctx.fillStyle = '#3e3c30';
    ctx.beginPath(); ctx.arc(cx, cy, 46, 0, Math.PI * 2); ctx.fill();
    // Cobblestones
    const cpos = [[-18,-10],[0,-22],[18,-10],[-24,5],[-8,12],[10,10],[24,4],[0,-4]];
    for (const [dx, dy] of cpos) {
        ctx.fillStyle = '#302e24'; ctx.fillRect(cx+dx-8, cy+dy-5, 15, 9);
        ctx.fillStyle = '#4e4c3e'; ctx.fillRect(cx+dx-6, cy+dy-3, 11, 6);
    }
    // Obelisk shaft
    ctx.fillStyle = '#2a2818'; ctx.fillRect(cx-5, cy-32, 10, 36);
    ctx.fillStyle = '#3a3828'; ctx.fillRect(cx-4, cy-31, 8, 34);
    // Gold tip
    ctx.fillStyle = '#b8801a';
    ctx.beginPath(); ctx.moveTo(cx-5, cy-32); ctx.lineTo(cx, cy-46); ctx.lineTo(cx+5, cy-32); ctx.fill();
    ctx.fillStyle = '#d8a030';
    ctx.beginPath(); ctx.moveTo(cx-3, cy-32); ctx.lineTo(cx, cy-44); ctx.lineTo(cx+3, cy-32); ctx.fill();
    // Plaza border
    ctx.strokeStyle = '#5a5040'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(cx, cy, 46, 0, Math.PI * 2); ctx.stroke();
    // Label
    ctx.textAlign = 'center'; ctx.textBaseline = 'top';
    ctx.font = 'bold 9px "Trebuchet MS",sans-serif';
    ctx.fillStyle = '#6a5c28'; ctx.fillText('HABILIDADES', cx, cy + 50);
    ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
}

function stkDrawNode(ctx, node) {
    const { x, y, id } = node;
    const st  = stkState(id);
    // Always true for a coming-soon teaser, even if some old save/test session left it flagged
    // 'active' — the branch isn't actually playable yet, so it should never suddenly reveal its
    // real name/art just because the skill flag happens to be set.
    const isSoon = STK_COMING_SOON.has(id);
    // Everything below that decides HOW the node is drawn (rubble vs scaffold vs finished
    // building, green checkmark badge, ...) reads effSt instead of the raw st — otherwise a
    // coming-soon node that happens to be flagged 'active' (old save/test session) would still
    // render as a finished, checkmarked building despite the name/label already saying "soon".
    const effSt = isSoon ? 'soon' : st;
    const name = isSoon ? t('stk.coming_soon_label') : t('skill.' + id + '.name');
    const hov = stkHov === id, sel = stkSel === id;
    const N   = (node.ts || 3) * STK_TILE;  // pixel size of this node

    // Ground clearing (dirt patch)
    ctx.fillStyle = '#3e3420';
    ctx.fillRect(x + 4, y + 4, N - 8, N - 8);

    // Scale all drawing to fit this node's N×N area (building code assumes 120×120)
    ctx.save();
    const s = N / 120;
    ctx.translate(x, y); ctx.scale(s, s); ctx.translate(-x, -y);

    if (effSt === 'locked' || effSt === 'soon') {
        _stkRubble(ctx, x, y);
    } else if (effSt === 'available') {
        _stkScaffold(ctx, x, y, STK_BRANCH_COLOR[node.branch] || '#808060');
    } else {
        _stkBuilding(ctx, x, y, node.branch);
        if (effSt === 'removing') {
            ctx.strokeStyle = 'rgba(200,40,40,0.65)'; ctx.lineWidth = 2;
            ctx.beginPath(); ctx.moveTo(x+25,y+15); ctx.lineTo(x+52,y+62); ctx.lineTo(x+47,y+84); ctx.stroke();
            ctx.beginPath(); ctx.moveTo(x+80,y+22); ctx.lineTo(x+64,y+52); ctx.stroke();
            ctx.fillStyle = 'rgba(160,30,30,0.14)'; ctx.fillRect(x+6, y+6, 108, 108);
        }
    }
    ctx.restore();

    // Active skill: green glow border + checkmark badge
    if (effSt === 'active' || effSt === 'removing') {
        const gc = effSt === 'removing' ? '#cc3030' : '#38c850';
        ctx.strokeStyle = gc;
        ctx.lineWidth = 3;
        ctx.strokeRect(x + 1, y + 1, N - 2, N - 2);
        // inner glow line
        ctx.strokeStyle = effSt === 'removing' ? 'rgba(220,80,80,0.35)' : 'rgba(80,220,100,0.35)';
        ctx.lineWidth = 5;
        ctx.strokeRect(x + 4, y + 4, N - 8, N - 8);
        // ✓ badge in top-right corner
        const bs = Math.max(10, Math.round(14 * s));
        ctx.fillStyle = effSt === 'removing' ? '#cc3030' : '#28a840';
        ctx.fillRect(x + N - bs - 2, y + 2, bs + 2, bs + 2);
        ctx.fillStyle = '#fff';
        ctx.font = `bold ${Math.max(7, Math.round(9 * s))}px sans-serif`;
        ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
        ctx.fillText(effSt === 'removing' ? '✕' : '✓', x + N - (bs / 2) - 2, y + (bs / 2) + 2);

        // Purchase-order badge (top-left) — which numbered pick this was this run, e.g. "3" for
        // the 3rd skill ever bought, so both the owning player and a read-only city visitor can
        // see the order the tree was filled in, not just which nodes are owned.
        if (effSt === 'active') {
            const ord = _skillPurchaseOrder.indexOf(id);
            if (ord !== -1) {
                const label = String(ord + 1);
                const obh = Math.max(11, Math.round(15 * s));
                const obw = obh + label.length * Math.round(6 * s);
                ctx.fillStyle = 'rgba(20,16,10,0.85)';
                ctx.beginPath(); ctx.roundRect(x + 2, y + 2, obw, obh, 3); ctx.fill();
                ctx.strokeStyle = 'rgba(255,224,128,0.8)'; ctx.lineWidth = 1;
                ctx.strokeRect(x + 2, y + 2, obw, obh);
                ctx.fillStyle = '#ffe080';
                ctx.font = `bold ${Math.max(8, Math.round(10 * s))}px sans-serif`;
                ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
                ctx.fillText(label, x + 2 + obw / 2, y + 2 + obh / 2 + 1);
            }
        }
    } else if (effSt === 'pending') {
        ctx.strokeStyle = '#6080e8';
        ctx.lineWidth = 2;
        ctx.strokeRect(x + 1, y + 1, N - 2, N - 2);
    }

    // Hover / selected border (on top of green)
    if (hov || sel) {
        ctx.strokeStyle = sel ? '#ffe080' : '#b09040';
        ctx.lineWidth = sel ? 3 : 2;
        ctx.strokeRect(x + 2, y + 2, N - 4, N - 4);
    }

    // Skill name label — font size scales with tile size
    const fs = Math.max(8, Math.round(10 * s));
    ctx.textAlign = 'center'; ctx.textBaseline = 'alphabetic';
    ctx.font = `bold ${fs}px "Trebuchet MS",sans-serif`;
    const lc = isSoon            ? '#e8c060'
        : effSt === 'locked'   ? '#3a3626'
        : effSt === 'active'   ? '#60e870'
        : effSt === 'removing' ? '#ff8080'
        : effSt === 'pending'  ? '#88b4e0'
        : '#a09050';
    ctx.fillStyle = '#0a0908';
    ctx.fillText(name, x + N/2 + 1, y + N - 3);
    ctx.fillStyle = lc;
    ctx.fillText(name, x + N/2, y + N - 4);
    ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic';
}

function _stkRubble(ctx, nx, ny) {
    const stones = [
        [nx+12,ny+70,22,10],[nx+40,ny+66,16,9],[nx+62,ny+74,20,8],
        [nx+86,ny+68,18,10],[nx+26,ny+82,14,7],[nx+70,ny+84,16,6],
        [nx+48,ny+56,12,8],[nx+18,ny+56,10,7]
    ];
    for (const [sx,sy,sw,sh] of stones) {
        ctx.fillStyle = '#48433a'; ctx.fillRect(sx, sy, sw, sh);
        ctx.fillStyle = '#363228'; ctx.fillRect(sx+2, sy+sh-3, sw-4, 3);
        ctx.fillStyle = '#58534a'; ctx.fillRect(sx+2, sy+1, sw-4, 3);
    }
    // Broken wall stumps
    ctx.fillStyle = '#3c3628'; ctx.fillRect(nx+12,ny+44,12,28); ctx.fillRect(nx+96,ny+50,12,22);
    ctx.fillStyle = '#2c2820'; ctx.fillRect(nx+12,ny+69,12,3); ctx.fillRect(nx+96,ny+69,12,3);
}

function _stkScaffold(ctx, nx, ny, N, bc) {
    // Dirt foundation
    ctx.fillStyle = '#382c18'; ctx.fillRect(nx+12, ny+82, N-24, 10);
    // Wooden posts
    ctx.fillStyle = '#6a4820';
    for (const px of [nx+14, nx+42, nx+70, nx+96]) ctx.fillRect(px, ny+18, 7, 64);
    // Beams
    ctx.fillStyle = '#58380e';
    ctx.fillRect(nx+14, ny+18, 89, 6);
    ctx.fillRect(nx+14, ny+48, 89, 4);
    ctx.fillRect(nx+14, ny+78, 89, 4);
    // Diagonal braces
    ctx.strokeStyle = '#4a2c08'; ctx.lineWidth = 4;
    ctx.beginPath(); ctx.moveTo(nx+14,ny+18); ctx.lineTo(nx+42,ny+48); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(nx+70,ny+18); ctx.lineTo(nx+96,ny+48); ctx.stroke();
    // Branch accent bar
    ctx.fillStyle = bc + '70'; ctx.fillRect(nx+12, ny+14, N-24, 5);
}

function _stkBuilding(ctx, nx, ny, branch) {
    // NOTE: these case labels are capitalized ('Bosque', 'Territorio'...) and node.branch is
    // lowercase (see SKILL_TREE_NODES), so they never matched anything pre-existing — every
    // other branch has always silently rendered as the default House. Left as-is here to avoid
    // changing the look of every already-shipped node as a side effect; only 'territorio' is
    // added (lowercase, so it actually matches) to give the new torreVigilancia node its
    // dedicated watchtower art. Worth revisiting/fixing for the other branches later if wanted.
    switch (branch) {
        case 'territorio':   _stkB_Tower(ctx, nx, ny);    break;
        case 'Bosque':       _stkB_Hut(ctx, nx, ny);      break;
        case 'Territorio':   _stkB_Tower(ctx, nx, ny);    break;
        case 'Aldea':        _stkB_House(ctx, nx, ny);    break;
        case 'Construcción': _stkB_Workshop(ctx, nx, ny); break;
        case 'Edificación':  _stkB_Stone(ctx, nx, ny);    break;
        case 'Manual':       _stkB_Barn(ctx, nx, ny);     break;
        case 'Obras':        _stkB_Chapel(ctx, nx, ny);   break;
        default:             _stkB_House(ctx, nx, ny);    break;
    }
}

// Bosque — timber woodcutter's hut
function _stkB_Hut(ctx, nx, ny) {
    // Walls (dark timber)
    ctx.fillStyle = '#4a2e10'; ctx.fillRect(nx+14, ny+52, 92, 36);
    ctx.fillStyle = '#3a2008';
    for (let i = 0; i < 4; i++) ctx.fillRect(nx+14, ny+57+i*8, 92, 3);
    // Door
    ctx.fillStyle = '#1a0c06'; ctx.fillRect(nx+52, ny+65, 16, 23);
    ctx.fillStyle = '#2e1a0a'; ctx.fillRect(nx+52,ny+70,4,3); ctx.fillRect(nx+64,ny+70,4,3);
    // Windows
    ctx.fillStyle = '#6a5420'; ctx.fillRect(nx+22,ny+56,16,12); ctx.fillRect(nx+82,ny+56,16,12);
    ctx.fillStyle = '#4a2e10';
    ctx.fillRect(nx+29,ny+56,2,12); ctx.fillRect(nx+22,ny+62,16,2);
    ctx.fillRect(nx+89,ny+56,2,12); ctx.fillRect(nx+82,ny+62,16,2);
    // Roof (mossy steep)
    ctx.fillStyle = '#2a3a14';
    ctx.beginPath(); ctx.moveTo(nx+6,ny+54); ctx.lineTo(nx+60,ny+10); ctx.lineTo(nx+114,ny+54); ctx.fill();
    ctx.fillStyle = '#1e2c0e'; ctx.fillRect(nx+57,ny+10,6,44);
    ctx.fillStyle = '#223010';
    for (let i=0;i<5;i++){const rw=12+i*20; ctx.fillRect(nx+60-rw/2,ny+22+i*7,rw,3);}
    ctx.fillStyle = '#3a2a0e'; ctx.fillRect(nx+6,ny+52,108,5);
}

// Territorio — stone watchtower
function _stkB_Tower(ctx, nx, ny) {
    ctx.fillStyle = '#565448'; ctx.fillRect(nx+30, ny+18, 60, 70);
    ctx.fillStyle = '#424038';
    for (let i=0;i<8;i++) ctx.fillRect(nx+30,ny+26+i*8,60,2);
    ctx.fillStyle = '#3e3c34';
    for (let r=0;r<8;r++) for(let c=0;c<3;c++) ctx.fillRect(nx+30+(r%2)*10+c*20,ny+22+r*8,1,6);
    // Crenellations
    ctx.fillStyle = '#565448';
    for (let i=0;i<4;i++) ctx.fillRect(nx+30+i*15,ny+10,10,12);
    // Arrow slit
    ctx.fillStyle = '#1a1814'; ctx.fillRect(nx+57,ny+35,6,22); ctx.fillRect(nx+54,ny+42,12,8);
    // Door arch
    ctx.fillStyle = '#1a1814'; ctx.fillRect(nx+47,ny+68,26,20);
    ctx.beginPath(); ctx.arc(nx+60,ny+68,13,Math.PI,0); ctx.fill();
    // Corner quoins
    ctx.fillStyle = '#6a6858';
    for(let i=0;i<5;i++){ctx.fillRect(nx+30,ny+18+i*12,8,8); ctx.fillRect(nx+82,ny+18+i*12,8,8);}
}

// Aldea — half-timbered house
function _stkB_House(ctx, nx, ny) {
    ctx.fillStyle = '#8a7248'; ctx.fillRect(nx+12, ny+52, 96, 36);
    ctx.fillStyle = '#4a2a10';
    ctx.fillRect(nx+12,ny+52,6,36); ctx.fillRect(nx+102,ny+52,6,36);
    ctx.fillRect(nx+12,ny+52,96,5); ctx.fillRect(nx+54,ny+52,6,36);
    ctx.fillRect(nx+12,ny+74,96,4);
    // Windows
    ctx.fillStyle = '#6a5830'; ctx.fillRect(nx+20,ny+57,26,18); ctx.fillRect(nx+74,ny+57,26,18);
    ctx.fillStyle = '#4a2a10';
    ctx.fillRect(nx+32,ny+57,2,18); ctx.fillRect(nx+20,ny+65,26,2);
    ctx.fillRect(nx+86,ny+57,2,18); ctx.fillRect(nx+74,ny+65,26,2);
    // Door
    ctx.fillStyle = '#2a1808'; ctx.fillRect(nx+48,ny+68,24,20);
    ctx.beginPath(); ctx.arc(nx+60,ny+68,12,Math.PI,0); ctx.fill();
    // Roof
    ctx.fillStyle = '#602818';
    ctx.beginPath(); ctx.moveTo(nx+4,ny+54); ctx.lineTo(nx+60,ny+12); ctx.lineTo(nx+116,ny+54); ctx.fill();
    ctx.fillStyle = '#4a1e10';
    for(let i=1;i<6;i++){const rw=i*20; ctx.fillRect(nx+60-rw/2,ny+12+i*7,rw,3);}
    // Chimney
    ctx.fillStyle = '#504038'; ctx.fillRect(nx+78,ny+16,14,30);
    ctx.fillStyle = '#3a302a'; ctx.fillRect(nx+76,ny+14,18,6);
    ctx.fillStyle = '#686058'; ctx.fillRect(nx+83,ny+8,4,4);
}

// Construcción — stone workshop
function _stkB_Workshop(ctx, nx, ny) {
    ctx.fillStyle = '#484e58'; ctx.fillRect(nx+10, ny+44, 100, 44);
    ctx.fillStyle = '#383e48';
    for(let r=0;r<4;r++) for(let c=0;c<5;c++) ctx.fillRect(nx+10+c*20+(r%2)*10,ny+44+r*10,18,8);
    // Roof
    ctx.fillStyle = '#2a3040';
    ctx.beginPath(); ctx.moveTo(nx+6,ny+46); ctx.lineTo(nx+60,ny+24); ctx.lineTo(nx+114,ny+46); ctx.fill();
    ctx.fillStyle = '#20283a'; ctx.fillRect(nx+6,ny+44,108,6);
    // Large door
    ctx.fillStyle = '#101420'; ctx.fillRect(nx+44,ny+60,32,28);
    ctx.beginPath(); ctx.arc(nx+60,ny+60,16,Math.PI,0); ctx.fill();
    // Chimney + forge glow
    ctx.fillStyle = '#303848'; ctx.fillRect(nx+72,ny+18,18,28);
    ctx.fillStyle = '#202830'; ctx.fillRect(nx+70,ny+14,22,8);
    ctx.fillStyle = 'rgba(255,100,20,0.28)'; ctx.fillRect(nx+46,ny+72,28,14);
    ctx.fillStyle = 'rgba(255,150,40,0.18)'; ctx.fillRect(nx+50,ny+74,20,10);
    // Tool rack
    ctx.fillStyle = '#5a4830'; ctx.fillRect(nx+12,ny+50,24,3);
    ctx.fillStyle = '#3a3028'; for(let i=0;i<4;i++) ctx.fillRect(nx+14+i*6,ny+46,2,7);
}

// Edificación — Gothic stone hall
function _stkB_Stone(ctx, nx, ny) {
    ctx.fillStyle = '#5a6878'; ctx.fillRect(nx+10, ny+44, 100, 44);
    ctx.fillStyle = '#484e60';
    for(let r=0;r<4;r++) for(let c=0;c<4;c++) ctx.fillRect(nx+10+c*25+(r%2)*12,ny+44+r*10,22,8);
    // Buttresses
    ctx.fillStyle = '#4a5870'; ctx.fillRect(nx+10,ny+30,14,58); ctx.fillRect(nx+96,ny+30,14,58);
    // Gothic roof
    ctx.fillStyle = '#3a4858';
    ctx.beginPath(); ctx.moveTo(nx+10,ny+46); ctx.lineTo(nx+60,ny+10); ctx.lineTo(nx+110,ny+46); ctx.fill();
    ctx.strokeStyle = '#2a3848'; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(nx+60,ny+10); ctx.lineTo(nx+20,ny+46); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(nx+60,ny+10); ctx.lineTo(nx+100,ny+46); ctx.stroke();
    // Gothic window
    ctx.fillStyle = '#2a3848'; ctx.fillRect(nx+48,ny+50,24,22);
    ctx.beginPath(); ctx.arc(nx+60,ny+50,12,Math.PI,0); ctx.fill();
    ctx.beginPath(); ctx.moveTo(nx+48,ny+50); ctx.lineTo(nx+60,ny+38); ctx.lineTo(nx+72,ny+50); ctx.fill();
    ctx.strokeStyle = '#4a5870'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(nx+60,ny+38); ctx.lineTo(nx+60,ny+72); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(nx+48,ny+58); ctx.lineTo(nx+72,ny+58); ctx.stroke();
    // Door
    ctx.fillStyle = '#1a2030'; ctx.fillRect(nx+48,ny+68,24,20);
    ctx.beginPath(); ctx.arc(nx+60,ny+68,12,Math.PI,0); ctx.fill();
}

// Manual — wide barn
function _stkB_Barn(ctx, nx, ny) {
    ctx.fillStyle = '#4a2820'; ctx.fillRect(nx+6, ny+46, 108, 42);
    ctx.fillStyle = '#3a1c14'; for(let i=0;i<8;i++) ctx.fillRect(nx+6,ny+50+i*5,108,2);
    ctx.fillStyle = '#321810'; for(let i=0;i<6;i++) ctx.fillRect(nx+6+i*18,ny+46,3,42);
    // Gambrel roof
    ctx.fillStyle = '#301410';
    ctx.beginPath(); ctx.moveTo(nx+2,ny+48); ctx.lineTo(nx+22,ny+24); ctx.lineTo(nx+98,ny+24); ctx.lineTo(nx+118,ny+48); ctx.fill();
    ctx.fillStyle = '#241010';
    ctx.beginPath(); ctx.moveTo(nx+22,ny+24); ctx.lineTo(nx+60,ny+10); ctx.lineTo(nx+98,ny+24); ctx.fill();
    // Double doors
    ctx.fillStyle = '#200c08'; ctx.fillRect(nx+36,ny+60,22,28); ctx.fillRect(nx+62,ny+60,22,28);
    ctx.strokeStyle = '#3a1810'; ctx.lineWidth = 3;
    ctx.strokeRect(nx+36,ny+60,22,28); ctx.strokeRect(nx+62,ny+60,22,28);
    ctx.fillStyle = '#3a1810'; ctx.fillRect(nx+57,ny+60,6,28);
    // Hay bale
    ctx.fillStyle = '#8a6820'; ctx.fillRect(nx+8,ny+72,20,14);
    ctx.fillStyle = '#6a5018'; for(let i=0;i<3;i++) ctx.fillRect(nx+8,ny+76+i*4,20,2);
    // Vent
    ctx.fillStyle = '#1a0a06'; ctx.fillRect(nx+52,ny+28,16,8);
}

// Obras — stone chapel with bell tower
function _stkB_Chapel(ctx, nx, ny) {
    // Main nave
    ctx.fillStyle = '#6a5a42'; ctx.fillRect(nx+10, ny+44, 72, 44);
    ctx.fillStyle = '#5a4c38';
    for(let r=0;r<4;r++) for(let c=0;c<3;c++) ctx.fillRect(nx+10+c*24+(r%2)*12,ny+44+r*10,20,8);
    // Bell tower
    ctx.fillStyle = '#5a4c38'; ctx.fillRect(nx+80,ny+26,32,62);
    ctx.fillStyle = '#4a3e30'; for(let r=0;r<6;r++) ctx.fillRect(nx+80,ny+30+r*8,32,3);
    // Steeple
    ctx.fillStyle = '#3a3028';
    ctx.beginPath(); ctx.moveTo(nx+80,ny+26); ctx.lineTo(nx+96,ny+6); ctx.lineTo(nx+112,ny+26); ctx.fill();
    // Cross
    ctx.fillStyle = '#b87820'; ctx.fillRect(nx+94,ny+6,4,14); ctx.fillRect(nx+89,ny+11,14,4);
    // Nave roof
    ctx.fillStyle = '#4a3e2c';
    ctx.beginPath(); ctx.moveTo(nx+6,ny+46); ctx.lineTo(nx+46,ny+22); ctx.lineTo(nx+86,ny+46); ctx.fill();
    // Bell opening
    ctx.fillStyle = '#1a1410'; ctx.fillRect(nx+86,ny+32,18,14);
    ctx.beginPath(); ctx.arc(nx+95,ny+32,9,Math.PI,0); ctx.fill();
    ctx.fillStyle = '#8a7230'; ctx.fillRect(nx+91,ny+35,8,7);
    // Door
    ctx.fillStyle = '#1a1410'; ctx.fillRect(nx+34,ny+68,20,20);
    ctx.beginPath(); ctx.arc(nx+44,ny+68,10,Math.PI,0); ctx.fill();
    // Window
    ctx.fillStyle = '#2a2018'; ctx.fillRect(nx+18,ny+52,16,14);
    ctx.beginPath(); ctx.arc(nx+26,ny+52,8,Math.PI,0); ctx.fill();
}

function stkXY(e) {
    const r = document.getElementById('stkCanvas').getBoundingClientRect();
    return { x: (e.clientX - r.left - stkPan.x) / stkZoom, y: (e.clientY - r.top - stkPan.y) / stkZoom };
}
function stkHit(wx, wy) {
    for (const n of SKILL_TREE_NODES) {
        const ns = (n.ts || 3) * STK_TILE;
        if (wx >= n.x && wx <= n.x + ns && wy >= n.y && wy <= n.y + ns) return n.id;
    }
    return null;
}
function stkMD(e) { stkDrag = { sx: e.clientX, sy: e.clientY, px: stkPan.x, py: stkPan.y, moved: false }; }
function stkMM(e) {
    if (stkDrag) {
        const dx = e.clientX - stkDrag.sx, dy = e.clientY - stkDrag.sy;
        if (Math.abs(dx) > 4 || Math.abs(dy) > 4) stkDrag.moved = true;
        if (stkDrag.moved) { stkPan.x = stkDrag.px + dx; stkPan.y = stkDrag.py + dy; renderSkillTree(); return; }
    }
    const { x, y } = stkXY(e);
    const hit = stkHit(x, y);
    if (hit !== stkHov) { stkHov = hit; renderSkillTree(); }
    e.currentTarget.style.cursor = hit ? 'pointer' : (stkDrag ? 'grabbing' : 'grab');
}
function stkMU(e) {
    if (stkDrag && !stkDrag.moved) {
        const { x, y } = stkXY(e);
        const hit = stkHit(x, y);
        if (hit) { stkSel = hit; stkUpdateInfo(hit); renderSkillTree(); }
    }
    stkDrag = null;
}
function stkWH(e) {
    e.preventDefault();
    const r = e.currentTarget.getBoundingClientRect();
    const mx = e.clientX - r.left, my = e.clientY - r.top;
    const nz = Math.max(0.25, Math.min(3, stkZoom * (e.deltaY > 0 ? 0.88 : 1.14)));
    stkPan.x = mx - (mx - stkPan.x) * (nz / stkZoom);
    stkPan.y = my - (my - stkPan.y) * (nz / stkZoom);
    stkZoom = nz; renderSkillTree();
}

function stkCloseCard() { stkSel = null; renderSkillTree(); }
window.stkCloseCard = stkCloseCard;

function stkToggleReveal() {
    stkRevealAll = !stkRevealAll;
    const btn = document.getElementById('btnStkReveal');
    if (btn) btn.textContent = t(stkRevealAll ? 'stk.hide' : 'stk.reveal');
    renderSkillTree();
}
window.stkToggleReveal = stkToggleReveal;

function stkUpdateInfo(id) {
    const node = STK_NODE_MAP[id]; if (!node) return;
    const card  = document.getElementById('stkInfo');
    const nameEl = document.getElementById('stkInfoName');
    const descEl = document.getElementById('stkInfoDesc');
    const stEl   = document.getElementById('stkInfoState');
    const btn    = document.getElementById('stkBuyBtn');
    const brEl   = document.getElementById('stkInfoBranch');
    if (!nameEl) return;

    if (card) card.style.display = 'flex';
    if (brEl) brEl.textContent = t('skill.branch.' + node.branch);

    const st = stkState(id);
    // Always true for a coming-soon teaser (see stkDrawNode) — never its real name/desc, even if
    // an old save/test session left the skill flagged 'active'.
    const isSoon = STK_COMING_SOON.has(id);

    if (isSoon) {
        nameEl.textContent = t('stk.coming_soon_label');
        // Per-node flavor text (falls back to the generic one) — torreVigilancia's own hints at
        // what the Watchtower will actually be for once War Mode ships (spotting enemy camps),
        // instead of a one-size-fits-all "coming soon" message.
        const soonKey = 'skill.' + id + '.soon_desc';
        const soonText = t(soonKey);
        descEl.textContent = (soonText === soonKey) ? t('stk.coming_soon_desc') : soonText;
        stEl.textContent = t('stk.status.soon');
    } else {
        nameEl.textContent = t('skill.' + id + '.name');
        descEl.textContent = _skillDesc(id);
        if (st === 'locked') {
            const unmetPrereqs = _prereqList(id).filter(p => !willBeActive(p));
            stEl.textContent = unmetPrereqs.length === 1 ? t('stk.lock.needs_skill')
                              : unmetPrereqs.length > 1  ? t('stk.lock.needs_skills', { n: unmetPrereqs.length })
                              : t('stk.status.locked', { req: '?' });
        } else {
            stEl.textContent = t('stk.status.' + st);
        }
    }

    // Read-only mode: hide the buy/action button
    if (btn) btn.style.display = 'none';
}

function stkBuySelected() {
    // Read-only mode: skills are unlocked via relic card modal, not from the tree
}
window.stkBuySelected = stkBuySelected;

function initSkillTree() {
    renderSkillTree();
}
window.initSkillTree = initSkillTree;

// Shared renderer for both the "Statistics" button panel and the one-time end-game screen —
// previously these were two separately-maintained near-duplicate functions that had already
// drifted apart (missing translations, missing rows) by the time this was unified. Every number
// here is a LIFETIME total: lifetimeStats holds everything folded in from completed runs (see
// _foldRunStatsIntoLifetime, called from doPrestigeReset before the per-run save gets wiped),
// and this run's still-live counters (gStats, treesChopped, _totalClicks, ...) are added on top —
// the same pattern _runTimes + the current run's elapsed time already used for the time section.
// mode: 'run' shows only THIS run's own numbers (gStats/treesChopped/etc. as tracked, never
// touching lifetimeStats); 'total' shows the grand total across every run including this one
// (lifetimeStats + this run's still-live counters, the panel's original/only behavior before
// the two tabs existed). A handful of counters (buildings built/moved/demolished, roads,
// statues, mule trips, market trades, tax houses visited, gold spent, skills explored) were
// only ever tracked lifetime — there's no shadow "this run only" value for them without adding
// a whole second set of counters, so the "extra" section is 'total'-only rather than showing
// fabricated/misleading zeros on the 'run' tab.
function _buildStatsPanelHTML(mode) {
    const fmt = n => formatNumber(Math.floor(n));
    // Spectator viewer: read the copy frozen the instant the snapshot loaded (see
    // _applySnapshotState), not the live globals — those keep ticking in the background for as
    // long as someone watches (villagers still "chop" and "deposit"), and Stats must show the
    // ORIGINAL shared run, not that run plus whatever accumulated during this viewing.
    const L = _spectatorMode ? _specFrozenLifetimeStats : lifetimeStats;
    const G = _spectatorMode ? _specFrozenGStats : gStats;
    const _treesChoppedView = _spectatorMode ? _specFrozenTreesChopped : treesChopped;
    const _totalClicksView  = _spectatorMode ? _specFrozenTotalClicks  : _totalClicks;
    const isTotal = mode === 'total';
    const base = (v) => isTotal ? v : 0; // folds in the lifetime side only for the 'total' tab

    const wood  = { manual: base(L.wood.manual) + G.wood.manual, villager: base(L.wood.villager) + G.wood.villager, sawmill_bonus: base(L.wood.sawmill_bonus) + G.wood.sawmill_bonus, marketSold: base(L.wood.marketSold) + G.wood.marketSold, marketBought: base(L.wood.marketBought) + G.wood.marketBought };
    const food  = { manual: base(L.food.manual) + G.food.manual, farm: base(L.food.farm) + G.food.farm, fish: base(L.food.fish || 0) + (G.food.fish || 0), orchard: base(L.food.orchard) + G.food.orchard, insectivoro: base(L.food.insectivoro) + G.food.insectivoro, bakery: base(L.food.bakery) + G.food.bakery, sheep: base(L.food.sheep) + G.food.sheep, cotton: base(L.food.cotton) + G.food.cotton, marketSold: base(L.food.marketSold) + G.food.marketSold, marketBought: base(L.food.marketBought) + G.food.marketBought };
    const wool  = { manual: base(L.wool.manual) + G.wool.manual, sheep: base(L.wool.sheep) + G.wool.sheep, cotton: base(L.wool.cotton) + G.wool.cotton, marketSold: base(L.wool.marketSold) + G.wool.marketSold, marketBought: base(L.wool.marketBought) + G.wool.marketBought, fishBoots: base(L.wool.fishBoots || 0) + (G.wool.fishBoots || 0) };
    const stone = { manual: base(L.stone.manual) + G.stone.manual, quarry: base(L.stone.quarry) + G.stone.quarry, pedernal: base(L.stone.pedernal) + G.stone.pedernal, marketSold: base(L.stone.marketSold) + G.stone.marketSold, marketBought: base(L.stone.marketBought) + G.stone.marketBought, fishBoots: base(L.stone.fishBoots || 0) + (G.stone.fishBoots || 0), zanja: base(L.stone.zanja || 0) + (G.stone.zanja || 0) };
    const gold  = { mule: base(L.gold.mule) + G.gold.mule, marketSold: base(L.gold.marketSold) + G.gold.marketSold, marketBought: base(L.gold.marketBought) + G.gold.marketBought, tesoreria: base(L.gold.tesoreria) + G.gold.tesoreria, vetaDeOro: base(L.gold.vetaDeOro) + G.gold.vetaDeOro, fishBoots: base(L.gold.fishBoots || 0) + (G.gold.fishBoots || 0) };

    // "debería marcar tanto lo comprado como lo vendido en la suma total" — marketSold y
    // marketBought SÍ entran ahora en el total de cada sección (antes se dejaban fuera para que
    // una gran venta no lo arrastrase a 0/negativo — ver `section()` más abajo, que ya no
    // depende únicamente del signo del total para decidir si mostrar la sección).
    const woodTotal  = wood.manual + wood.villager + wood.sawmill_bonus + wood.marketSold + wood.marketBought;
    const foodTotal  = food.manual + food.farm + food.fish + food.orchard + food.insectivoro + food.bakery + food.sheep + food.cotton + food.marketSold + food.marketBought;
    const woolTotal  = wool.manual + wool.sheep + wool.cotton + wool.marketSold + wool.marketBought + wool.fishBoots;
    const stoneTotal = stone.manual + stone.quarry + stone.pedernal + stone.marketSold + stone.marketBought + stone.fishBoots + stone.zanja;
    const goldTotal  = gold.mule + gold.marketSold + gold.marketBought + gold.tesoreria + gold.vetaDeOro + gold.fishBoots;

    // Almas. Única sección cuyo total cuadra EXACTAMENTE con el saldo que llevas encima, porque es
    // el único recurso con una sola entrada (el Altar Ritual) y solo dos salidas (comprar aldeano o
    // mula): liberadas − gastadas = lo que te queda, sin más sumideros.
    //
    // Las liberadas de ESTA partida no se guardan en ningún contador propio, así que se deducen del
    // saldo: si tienes X almas y has gastado N compras a SOULS_COST cada una, liberaste X + N·coste.
    // En la pestaña de totales se usa directamente L.ritualSoulsFreed, que a diferencia del resto de
    // lifetimeStats se incrementa en caliente (ver el ritual) y por tanto YA incluye la partida en
    // curso — sumarle la parte del run la contaría dos veces.
    const soulsVillagers = base(L.villagersSouls) + purchasedVillagersSouls;
    const soulsMules     = base(L.mulesSouls)     + _runMulesSouls;
    // Menos las traídas de partidas anteriores (_soulsCarried; hoy siempre 0, ver su declaración):
    // están en el saldo pero no se liberaron aquí. Van en su propia fila para que el total de la sección siga siendo el saldo.
    const soulsCarried   = isTotal ? 0 : _soulsCarried;
    const soulsFreed     = isTotal ? (L.ritualSoulsFreed || 0)
                                   : souls - soulsCarried + SOULS_COST * (purchasedVillagersSouls + _runMulesSouls);
    const soulsSpent     = SOULS_COST * (soulsVillagers + soulsMules);
    const soulsTotal     = soulsFreed + soulsCarried - soulsSpent;

    const treesTotal  = base(L.treesChopped) + _treesChoppedView;
    const clicksTotal = base(L.totalClicks) + _totalClicksView;
    const relicsTotal = isTotal ? _totalRelicsCollected : _runRelicsCollected;

    const _currentRunMs = _spectatorMode ? _specFrozenTotalGameMs : (_totalGameMs + _sessionBoostedMs); // actually the grand total across every run, despite the name
    const _currentRunOnlyMs = Math.max(0, _currentRunMs - _runTimes.reduce((a, b) => a + Math.max(0, b), 0)); // this run's own duration, not the grand total
    const secs = Math.floor((isTotal ? _currentRunMs : _currentRunOnlyMs) / 1000);
    const h = Math.floor(secs/3600), m = Math.floor((secs%3600)/60), s = secs%60;
    const timeStr = h > 0 ? `${h}h ${m}m ${s}s` : `${m}m ${s}s`;
    const _fmtMs = (ms) => { const rs=Math.floor(ms/1000),rh=Math.floor(rs/3600),rm=Math.floor((rs%3600)/60),rsec=rs%60; return rh>0?`${rh}h ${rm}m ${rsec}s`:`${rm}m ${rsec}s`; };

    const ico = (name) => `<img src="assets/icon_${name}.png" style="width:16px;height:16px;image-rendering:pixelated;vertical-align:middle;margin-right:5px;">`;

    function section(title, icon, total, rows) {
        // El total ahora SÍ incluye marketSold/marketBought (ver arriba), así que puede quedar en
        // 0 o negativo tras una gran venta aunque la sección tenga producción real que mostrar —
        // por eso el criterio de "nunca se ha tocado esto" ya no es total<=0 a secas, sino que
        // además ninguna fila tenga contenido (rows.some).
        if (total <= 0 && !rows.some(r => r[1] !== 0)) return '';
        // r[1] !== 0 (not > 0): a few rows (Market) are net-negative — resource sold off — and
        // still worth showing, just tinted red instead of the usual gold.
        const rowsHTML = rows.filter(r => r[1] !== 0).map(([label, val]) =>
            `<div style="display:flex;justify-content:space-between;padding:3px 0 3px 16px;color:#bdae93;font-size:12px;">
                <span>${label}</span><span style="font-family:'Roboto Mono',monospace;${val < 0 ? 'color:#d07070;' : ''}">${fmt(val)}</span>
            </div>`
        ).join('');
        return `
        <div style="margin-bottom:16px;">
            <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px;">
                <span style="font-family:'Cinzel',serif;color:#e8d5a0;font-size:13px;">${icon} ${title}</span>
                <span style="font-family:'Roboto Mono',monospace;${total < 0 ? 'color:#d07070;' : 'color:#f4e8d3;'}font-size:14px;font-weight:700;">${fmt(total)}</span>
            </div>
            ${rowsHTML}
            <div style="border-top:1px solid #3a2e1e;margin-top:6px;"></div>
        </div>`;
    }
    // Plain two-column list without a header/total row, for the activity/counters section.
    // Optional 3rd tuple element (disp) overrides the displayed text while val still drives the
    // >0 visibility filter — used by achievements below to show "3 / 35" instead of a bare count.
    function plainRows(rows) {
        return rows.filter(r => r[1] > 0).map(([label, val, disp]) =>
            `<div style="display:flex;justify-content:space-between;padding:3px 0;color:#bdae93;font-size:12px;"><span>${label}</span><span style="font-family:'Roboto Mono',monospace;">${disp !== undefined ? disp : fmt(val)}</span></div>`
        ).join('');
    }

    const byJob = { lumber:0, farm:0, mine:0, herd:0, bake:0, teatro:0, collect:0, drain:0, ship:0, idle:0 };
    villagers.forEach(v => {
        const ft = v.farmTarget?.type;
        if (ft === 'farm' || ft === 'fruit_orchard' || ft === 'fisher_hut') byJob.farm++;
        // El Plantación Forestal cuenta como leñador: produce madera con el ritmo del hacha.
        else if (ft === 'forest_farm') byJob.lumber++;
        else if (ft === 'sheep_farm' || ft === 'cotton_farm') byJob.herd++;
        else if (ft === 'stone_quarry') byJob.mine++;
        else if (ft === 'bakery') byJob.bake++;
        else if (ft === 'teatro') byJob.teatro++;
        else if (ft === 'tesoreria') byJob.collect++;
        else if (ft === 'dry_dock' && (v.state === 'draining' || v.state === 'hauling_water')) byJob.drain++;
        else if (ft === 'dry_dock' && (v.state === 'ship_fetch' || v.state === 'ship_haul')) byJob.ship++;
        else if (v._targetKey || v.woodCarried > 0) byJob.lumber++;
        else byJob.idle++;
    });
    const teatroTotal = buildings.filter(b => b.type === 'teatro').reduce((s, b) => s + (b._spawnCount || 0), 0);
    const jobRows = [
        [t('stats.vill.lumber'),  byJob.lumber],
        [t('stats.vill.farm'),    byJob.farm],
        [t('stats.vill.mine'),    byJob.mine],
        [t('stats.vill.herd'),    byJob.herd],
        [t('stats.vill.bake'),    byJob.bake],
        [t('stats.vill.teatro'),  byJob.teatro],
        [t('stats.vill.collect'), byJob.collect],
        [t('stats.vill.drain'),   byJob.drain],
        [t('stats.vill.ship'),    byJob.ship],
        [t('stats.vill.idle'),    byJob.idle],
    ].filter(r => r[1] > 0);
    const originRows = [
        [t('stats.vill.wood'),        base(L.villagersWood)      + purchasedVillagersWood],
        [t('stats.vill.food'),        base(L.villagersFood)      + purchasedVillagersFood],
        [t('stats.vill.wool'),        base(L.villagersWool)      + purchasedVillagersWool],
        [t('stats.vill.souls'),       base(L.villagersSouls)     + purchasedVillagersSouls],
        [t('stats.vill.migra'),       base(L.villagersMigracion) + _migracionGiven],
        [t('stats.vill.teatro_born'), base(L.villagersTeatro)    + teatroTotal],
    ].filter(r => r[1] > 0);

    return `
        <div style="display:flex;justify-content:space-between;margin-bottom:14px;font-size:12px;color:#8a7050;flex-wrap:wrap;gap:6px;">
            <span>${t('stats.trees')}: <b style="color:#c8a050;">${fmt(treesTotal)}</b></span>
            <span>${t('stats.relics')}: <b style="color:#c8a050;">${fmt(relicsTotal)}</b></span>
            <span>${t('stats.time')}: <b style="color:#c8a050;">${timeStr}</b></span>
            <span>${t('stats.clicks')}: <b style="color:#c8a050;">${fmt(clicksTotal)}</b></span>
        </div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;align-items:start;">
            <div>
                ${section(t('stats.wood'), ico('wood'), woodTotal, [
                    [t('stats.manual'),    wood.manual],
                    [t('stats.villager'),  wood.villager],
                    [t('stats.sawmill'),   wood.sawmill_bonus],
                    [t('stats.market_bought'), wood.marketBought],
                    [t('stats.market_sold'),   wood.marketSold],
                ])}
                ${section(t('stats.food'), ico('food'), foodTotal, [
                    [t('stats.manual'),      food.manual],
                    [t('stats.farm'),        food.farm],
                    ...(food.fish ? [[t('stats.fish'), food.fish]] : []),
                    [t('stats.orchard'),     food.orchard],
                    [t('stats.insectivoro'), food.insectivoro],
                    [t('stats.bakery'),      food.bakery],
                    [t('stats.sheep_food'),  food.sheep],
                    [t('stats.cotton_food'), food.cotton],
                    [t('stats.market_bought'), food.marketBought],
                    [t('stats.market_sold'),   food.marketSold],
                ])}
                ${section(t('stats.wool'), ico('wool'), woolTotal, [
                    [t('stats.manual'),      wool.manual],
                    [t('stats.shepherd'),    wool.sheep],
                    [t('stats.cotton_wool'), wool.cotton],
                    ...(wool.fishBoots ? [[t('stats.fishBoots'), wool.fishBoots]] : []),
                    [t('stats.market_bought'), wool.marketBought],
                    [t('stats.market_sold'),   wool.marketSold],
                ])}
                ${section(t('stats.stone'), ico('stone'), stoneTotal, [
                    [t('stats.manual'),   stone.manual],
                    [t('stats.quarry'),   stone.quarry],
                    [t('stats.pedernal'), stone.pedernal],
                    ...(stone.zanja ? [[t('stats.zanja'), stone.zanja]] : []),
                    ...(stone.fishBoots ? [[t('stats.fishBoots'), stone.fishBoots]] : []),
                    [t('stats.market_bought'), stone.marketBought],
                    [t('stats.market_sold'),   stone.marketSold],
                ])}
                ${section(t('stats.gold'), ico('gold'), goldTotal, [
                    [t('stats.mule'),      gold.mule],
                    [t('stats.market_sold'),   gold.marketSold],
                    [t('stats.market_bought'), gold.marketBought],
                    [t('stats.tesoreria'), gold.tesoreria],
                    [t('stats.vetaDeOro'), gold.vetaDeOro],
                    ...(gold.fishBoots ? [[t('stats.fishBoots'), gold.fishBoots]] : []),
                ])}
                ${section(t('stats.souls'), '<i class="fa-solid fa-ghost" style="color:#b9a7d8;"></i>', soulsTotal, [
                    [t('stats.souls_ritual'),    soulsFreed],
                    [t('stats.souls_carried'),   soulsCarried],
                    [t('stats.souls_villagers'), -SOULS_COST * soulsVillagers],
                    [t('stats.souls_mules'),     -SOULS_COST * soulsMules],
                ])}
            </div>
            <div>
                ${section(t('stats.villagers'), '<i class="fa-solid fa-people-group" style="color:#a0c080;"></i>', base(L.villagersTotal) + villagers.length, [
                    ...jobRows,
                    ...(originRows.length ? [['──', null]] : []),
                    ...originRows,
                ].filter(r => r[1] !== null))}
                ${_harborsOn() ? (() => {
                    // Mundos con barcas: las tres procedencias por separado, y el total es lo que hay (las compradas en el Puerto Rural + las construidas en el Astillero + las 2 de regalo).
                    // Antes todo iba en "Compradas" (las del Astillero contaban como compradas y las de regalo no salían en ningún sitio: el total quedaba por debajo de las barcas reales).
                    const bBought = base(L.mulesBought) + Math.max(0, _mulesBoughtWithResources() - _boatsOrderedShipyard());
                    const bBuilt  = base(L.boatsBuilt || 0) + astilleroBoatsBuilt;
                    const bGift   = base(L.boatsGift || 0) + (harborGiftGiven ? 2 : 0);
                    const bEstablo = base(L.mulesEstablo) + _establoFreeMulesGenerated, bSouls = base(L.mulesSouls) + _runMulesSouls;
                    return section(t('stats.mules_section'), '<i class="fa-solid fa-sailboat" style="color:#c8a060;"></i>', bBought + bBuilt + bGift + bEstablo + bSouls, [
                        [t('stats.boat_bought'), bBought],
                        [t('stats.boat_built'),  bBuilt],
                        [t('stats.boat_gift'),   bGift],
                        ...(bEstablo > 0 ? [[t('stats.mule_establo'), bEstablo]] : []),   // de partidas del mundo 1 (el lifetime es de todos los mundos)
                        ...(bSouls > 0 ? [[t('stats.mule_souls'), bSouls]] : []),
                    ]);
                })() : section(t('stats.mules_section'), '<i class="fa-solid fa-horse" style="color:#c8a060;"></i>', base(L.mulesBought) + base(L.mulesEstablo) + base(L.mulesSouls) + mulesRecruited, [
                    // mulesRecruited incluye TANTO compradas como nacidas en establo (se
                    // incrementa en los dos sitios) — "compradas" de verdad es mulesRecruited
                    // menos las nacidas en establo, no el total. El encabezado de arriba ya no
                    // suma _establoFreeMulesGenerated aparte porque eso contaría esas mulas dos
                    // veces (ya van dentro de mulesRecruited).
                    // "Compradas" = con recursos; las de almas van en su propia fila (_runMulesSouls),
                    // así las tres filas suman el total de arriba sin contar nada dos veces.
                    [t('stats.mule_bought'),  base(L.mulesBought)  + _mulesBoughtWithResources()],
                    [t('stats.mule_establo'), base(L.mulesEstablo) + _establoFreeMulesGenerated],
                    [t('stats.mule_souls'),   base(L.mulesSouls)   + _runMulesSouls],
                ])}
                <div style="margin-bottom:16px;">
                    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px;">
                        <span style="font-family:'Cinzel',serif;color:#e8d5a0;font-size:13px;">⏱ ${t('stats.time')}</span>
                    </div>
                    ${isTotal ? `
                    ${_runTimes.map((ms, i) => `
                        <div style="display:flex;justify-content:space-between;padding:3px 0 3px 16px;color:#bdae93;font-size:12px;">
                            <span>${t('stats.run_n', { n: i + 1 })}</span><span style="font-family:'Roboto Mono',monospace;">${_fmtMs(Math.max(0, ms))}</span>
                        </div>`).join('')}
                    <div style="display:flex;justify-content:space-between;padding:3px 0 3px 16px;color:#e0d0a0;font-size:12px;">
                        <span>${t('stats.run_n', { n: _runTimes.length + 1 })} <span style="color:#888;font-size:11px;">(${t('stats.run_current')})</span></span>
                        <span style="font-family:'Roboto Mono',monospace;">${_fmtMs(_currentRunOnlyMs)}</span>
                    </div>
                    <div style="border-top:1px solid #3a2e1e;margin:4px 0 2px;"></div>
                    <div style="display:flex;justify-content:space-between;padding:3px 0 3px 16px;color:#c8a050;font-size:12px;font-weight:700;">
                        <span>Total</span><span style="font-family:'Roboto Mono',monospace;">${_fmtMs(_runTimes.reduce((a,b)=>a+Math.max(0,b),0)+_currentRunOnlyMs)}</span>
                    </div>` : `
                    <div style="display:flex;justify-content:space-between;padding:3px 0 3px 16px;color:#e0d0a0;font-size:12px;">
                        <span>${t('stats.run_current')}</span><span style="font-family:'Roboto Mono',monospace;">${_fmtMs(_currentRunOnlyMs)}</span>
                    </div>`}
                    <div style="border-top:1px solid #3a2e1e;margin-top:6px;"></div>
                </div>
                <div style="margin-bottom:16px;">
                    <div style="font-family:'Cinzel',serif;color:#e8d5a0;font-size:13px;margin-bottom:8px;">⚡ ${t('stats.extra')}</div>
                    ${plainRows(isTotal ? [
                        [t('stats.clicks'),           clicksTotal],
                        [t('stats.relics'),           relicsTotal],
                        [t('stats.trees'),            treesTotal],
                        [t('stats.runs'),             _runTimes.length + 1],
                        [t('stats.skills'),           _everExploredSkills.size],
                        [t('stats.achievements'),     _achProgress().n, `${_achProgress().n} / ${_achProgress().total}`],
                        [t('stats.buildings_built'),  L.buildingsBuilt],
                        [t('stats.buildings_moved'),  L.buildingsMoved],
                        [t('stats.buildings_demolished'), L.buildingsDemolished],
                        [t('stats.roads'),            L.roadsPlaced],
                        [t('stats.statues'),          L.statuesBuilt],
                        [t('stats.mule_trips'),       L.muleTrips],
                        [t('stats.market_trades'),    L.marketTrades],
                        [t('stats.tax_houses'),       L.taxHousesVisited],
                        [t('stats.gold_spent'),       L.goldSpent],
                        [t('ritual.stat.souls'),      L.ritualSoulsFreed],
                    ] : [
                        [t('stats.clicks'), clicksTotal],
                        [t('stats.relics'), relicsTotal],
                        [t('stats.trees'),  treesTotal],
                    ])}
                    <div style="border-top:1px solid #3a2e1e;margin-top:6px;"></div>
                </div>
            </div>
        </div>
    `;
}

// 'run' = only this run's own numbers; 'total' = grand total across every run (the panel's
// original/only behavior before these tabs existed — still the default landing view, and what
// the end-game screen always forces regardless of whichever tab was last open).
let _statsPanelMode = 'total';

function _switchStatsTab(mode) {
    _statsPanelMode = mode;
    const runBtn = document.getElementById('statsTabRun');
    const totalBtn = document.getElementById('statsTabTotal');
    if (runBtn) runBtn.classList.toggle('active', mode === 'run');
    if (totalBtn) totalBtn.classList.toggle('active', mode === 'total');
    const body = document.getElementById('statsPanelBody');
    if (body) body.innerHTML = _buildStatsPanelHTML(mode);
}
window._switchStatsTab = _switchStatsTab;


// Cartel de fin de FASE 2 (zarpó la expedición). Reutiliza el mismo panel de estadísticas que el
// de fase 1 en vez de montar un modal nuevo: es el mismo momento narrativo, solo que un escalón
// más arriba, y así hereda pestañas, botón de cerrar y estilos sin duplicar nada.
function showPhase2EndScreen() {
    const tc = buildings.find(b => b.type === 'town_center');
    const dock = _dryDock();
    // La cámara va al DIQUE, no al Centro Urbano: lo que el jugador quiere ver es el barco
    // saliendo, no la plaza del pueblo.
    const focus = dock || tc;
    if (focus) {
        cameraX = (focus.x + (focus.w || 4) * 0.5) * TILE_SIZE;
        cameraY = (focus.y + (focus.h || 4) * 0.5) * TILE_SIZE;
    }
    setTimeout(() => {
        const panel = document.getElementById('statsPanel');
        if (!panel) return;
        const titleEl = panel.querySelector('h2');
        if (titleEl) titleEl.textContent = '⛵ ' + t('stats.phase2_title') + ' ⛵';
        panel.style.display = 'flex';
        _cgModalOpenedIfEnabled('stats');
        _switchStatsTab('total');
        const body = document.getElementById('statsPanelBody');
        if (body) {
            body.insertAdjacentHTML('afterbegin', `
                <div style="text-align:center;margin-bottom:18px;padding:12px;background:rgba(60,130,180,0.12);border:1px solid #2f5c8a;border-radius:6px;">
                    <div style="font-family:'Cinzel',serif;color:#8fc4e8;font-size:13px;letter-spacing:2px;">
                        ${t('phase2.end_subtitle', { n: EXPEDITION_VILLAGERS })}
                    </div>
                    <!-- "guarda esta partida para el nuevo mundo": la continuación partirá de esta
                         partida, así que se dice claro y se ofrece la copia a un clic (la misma
                         exportación que el botón de descarga del selector de partidas). -->
                    <div style="color:#e8d5a0;font-size:13px;line-height:1.5;margin-top:10px;">${t('phase2.end_keep')}</div>
                    <button class="menu-btn menu-btn-secondary" style="margin-top:10px;padding:7px 16px;font-size:12px;"
                        onclick="saveGame(true); exportSlot(currentSlot);"><i class="fa-solid fa-download"></i> ${t('phase2.end_download')}</button>
                    ${prestige.worldId === 1 ? `<button class="menu-btn" style="margin:10px 0 0 8px;padding:7px 16px;font-size:12px;"
                        onclick="_goToWorld2()"><i class="fa-solid fa-water"></i> ${t('world.go_w2')}</button>` : ''}
                </div>`);
        }
    }, 900);
}
// El cartel abierto ahora mismo es el de fin de FASE 1 (y no el de estadísticas normal ni el de
// zarpar). Lo mira closeStatsPanel para arrancar el tutorial de la fase 2 justo al cerrarlo.
let _phase1CardOpen = false;

function showEndGameStats() {
    _endGameShown = true;
    // El tutorial de fase 2 (ver closeStatsPanel) solo debe arrancar si de verdad hay fase 2 que
    // enseñar — o sea, solo en la rama con Legado 8 ya reclamado, de ahí el && de aquí abajo.
    _phase1CardOpen = prestige.phase2Unlocked;
    // Fin de la FASE 1 — se ve una única vez por partida (guarda phase1Done, ver su declaración).
    if (!phase1Done) { phase1Done = true; saveGame(); }

    // Focus camera on town center
    const tc = buildings.find(b => b.type === 'town_center');
    if (tc) {
        cameraX = (tc.x + (tc.w || 4) * 0.5) * TILE_SIZE;
        cameraY = (tc.y + (tc.h || 4) * 0.5) * TILE_SIZE;
    }

    // Short delay so player sees the camera move before the panel appears
    setTimeout(() => {
        const panel = document.getElementById('statsPanel');
        if (!panel) return;
        const titleEl = panel.querySelector('h2');
        // Sin Legado 8 (prestige.phase2Unlocked), esto es de verdad el final — el mismo cartel de
        // "partida completada" de antes de que la Fase 2 existiera, con ancla o trofeo según toque
        // seguir o no. Con Legado 8 ya reclamado, es el cartel de siempre: "fase 1 completada".
        if (titleEl) titleEl.textContent = prestige.phase2Unlocked
            ? '⚓ ' + t('stats.phase1_title') + ' ⚓'
            : '🏆 ' + t('stats.end_title') + ' 🏆';
        panel.style.display = 'flex';
        // Bypasses openStatsPanel() (sets display directly, above) — needs its own open hook for
        // the same reason, its close button still goes through the shared closeStatsPanel().
        _cgModalOpenedIfEnabled('stats');
        _switchStatsTab('total'); // the run that just ended IS the lifetime total's newest slice
        // Aviso de que la partida NO se acaba aquí: sin esto el cartel dice "fase 1 completada"
        // y el jugador no tiene forma de saber qué es la fase 2 ni por dónde empieza. Solo con
        // Legado 8 ya reclamado — de lo contrario la partida SÍ se acaba aquí de verdad, hasta
        // que se reinicie hacia ese tramo (ver el body de abajo).
        if (prestige.phase2Unlocked) showBuildToast(t('phase2.unlocked'));
        const body = document.getElementById('statsPanelBody');
        if (body) {
            // Achievements earned this run/lifetime, right alongside the numbers — a compact icon
            // strip (name on hover), not the full catalog grid (that's what the real Logros panel
            // is for). Only actually-unlocked ones show; nothing locked/greyed-out clutters this.
            const unlockedList = ACHIEVEMENTS.filter(a => _unlockedAchievements.has(a.id));
            const achHTML = unlockedList.length ? `
                <div style="text-align:center;margin-bottom:18px;">
                    <div style="font-family:'Cinzel',serif;color:#c8a050;font-size:11px;letter-spacing:1px;margin-bottom:8px;">
                        ${t('stats.end_achievements', { n: unlockedList.length, total: _achProgress().total })}
                    </div>
                    <div style="display:flex;flex-wrap:wrap;gap:8px;justify-content:center;">
                        ${unlockedList.map(a => `
                            <div class="ach-card-icon unlocked-inline" title="${t('ach.' + a.id + '.name')}">
                                <i class="fa-solid ${a.icon}"></i>
                            </div>
                        `).join('')}
                    </div>
                </div>` : '';
            // Tres variantes del bloque de "hacia dónde vas": con Legado 8, el aviso de siempre
            // invitando a la Fase 2 (dique/puerto/barco). Sin él pero con relics suficientes para
            // reclamar el SIGUIENTE tramo de Legado ahora mismo, un botón real que lleva directo
            // al árbol — el nodo rojo ya está listo, esto es lo primero que puede hacer. Solo si
            // ni eso, cae en el aviso genérico de que hace falta llegar hasta el Legado 8, la
            // puerta real a la Fase 2 (ver PRESTIGE_MILESTONES). Este cartel sigue siendo una
            // FELICITACIÓN, no un manual: dice lo que has hecho y qué haría falta para seguir.
            const _egRest = _prestigeRelicBank + _stkPendingRelicBonus();
            const _egSlot = prestige.nextIdx;
            const _legacyReadyNow = !!(PRESTIGE_MILESTONES[_egSlot] && _egRest >= PRESTIGE_MILESTONES[_egSlot].relic);
            const nextStepHTML = prestige.phase2Unlocked ? `
                <div style="text-align:center;margin-bottom:18px;padding:14px;background:rgba(45,106,140,0.14);border:1px solid #2f5c8a;border-radius:6px;">
                    <div style="color:#a8cfe6;font-size:13px;line-height:1.6;margin-bottom:10px;">${t('stats.phase2_lead')}</div>
                    <div style="font-family:'Cinzel',serif;color:#6fb0e0;font-size:16px;letter-spacing:3px;">
                        <i class="fa-solid fa-sailboat"></i> ${t('stats.phase2_call')}
                    </div>
                </div>` : _legacyReadyNow ? `
                <div style="text-align:center;margin-bottom:18px;padding:14px;background:rgba(168,48,48,0.12);border:1px solid #a83030;border-radius:6px;">
                    <div style="color:#e6b8b8;font-size:13px;line-height:1.6;margin-bottom:10px;">${t('stats.legacy_ready_lead')}</div>
                    <button onclick="closeStatsPanel();openSkillTree();" style="cursor:pointer;border:1px solid #a83030;background:rgba(200,40,40,0.12);border-radius:6px;padding:8px 16px;font-family:'Cinzel',serif;color:#e05050;font-size:16px;letter-spacing:3px;">
                        <i class="fa-solid fa-crown"></i> ${t('stats.legacy_ready_call')}
                    </button>
                </div>` : !PHASE2_ENABLED ? '' : `
                <div style="text-align:center;margin-bottom:18px;padding:14px;background:rgba(200,160,80,0.1);border:1px solid #6a4a1a;border-radius:6px;">
                    <div style="color:#e0cfa0;font-size:13px;line-height:1.6;margin-bottom:10px;">${t('stats.legado8_lead')}</div>
                    <div style="font-family:'Cinzel',serif;color:#d8b878;font-size:16px;letter-spacing:3px;">
                        <i class="fa-solid fa-crown"></i> ${t('stats.legado8_call')}
                    </div>
                </div>`;
            body.innerHTML = `
                <div style="text-align:center;margin-bottom:8px;padding:10px;background:rgba(200,160,80,0.08);border:1px solid #5a4a2a;border-radius:6px;">
                    <div style="font-family:'Cinzel',serif;color:#c8a050;font-size:11px;letter-spacing:2px;">${t('stats.end_subtitle')}</div>
                </div>
                ${nextStepHTML}
                ${achHTML}
            ` + body.innerHTML;
        }
    }, 800);
}
window.showEndGameStats = showEndGameStats;

function openStatsPanel() {
    const panel = document.getElementById('statsPanel');
    if (!panel) return;
    const willShow = panel.style.display === 'none' || panel.style.display === '';
    if (!willShow) { closeStatsPanel(); return; } // re-clicking the header button while open closes it

    // Restore normal title in case end-game panel changed it
    const titleEl = panel.querySelector('h2');
    if (titleEl) { titleEl.setAttribute('data-t', 'stats.title'); titleEl.textContent = t('stats.title'); }

    panel.style.display = 'flex';
    _cgModalOpenedIfEnabled('stats');
    _switchStatsTab('run'); // default to the current run — showEndGameStats() overrides to 'total'
}
window.openStatsPanel = openStatsPanel;
// Was a bare inline onclick on the ✕ button (index.html) — pulled out into its own function so
// both that button AND the header toggle-close branch above share one exit point.
function closeStatsPanel() {
    const panel = document.getElementById('statsPanel');
    if (panel) panel.style.display = 'none';
    _cgModalClosedIfEnabled('stats');
    // Al cerrar el cartel de fin de fase 1 arranca el tutorial de la fase 2. Va aquí y no en
    // showEndGameStats a propósito: mientras el panel está abierto el jugador está mirando
    // estadísticas, y un cartel de "construye el dique" detrás de un modal no lo ve nadie.
    if (_phase1CardOpen) {
        _phase1CardOpen = false;
        if (phase2Tuto === 0) { phase2Tuto = _phase2TutoStepFor(); saveGame(true); }
        updateTutorial();
    }
}
window.closeStatsPanel = closeStatsPanel;

// ─── ACHIEVEMENTS (visual catalog only for now) ────────────────────────────
// Just the panel/data for browsing the full list — no unlock-condition tracking wired up yet
// (that's a separate pass). id matches the ach.<id>.name/ach.<id>.desc keys in lang.js. tier is
// purely a display grouping (see ACHIEVEMENT_TIER_ORDER), roughly common → legendary rarity.
// goal/current are optional — only set where a clean live number already exists in game state;
// achievements that are order-based, positional, or need tracking that doesn't exist yet (login
// streaks, lifetime building-move counts, etc.) just render without a progress bar.
const _achManualTotal = () => ['wood', 'food', 'wool', 'stone']
    .reduce((s, r) => s + (lifetimeStats[r].manual || 0) + (gStats[r].manual || 0), 0);
const _achPlaytimeMs = () => _totalGameMs + _sessionBoostedMs;
// Same total, minus whatever came from the offline ad-offer's flat resource grant (see
// _offlineBonusMs) — for achievements that measure real dedication (unRatito/unDiaEntero/
// unaSemana), never for Talador Relámpago (a speed LIMIT, which correctly wants that time
// counted — see _achCurrentRunMs, which deliberately still reads _achPlaytimeMs()).
const _achRealPlaytimeMs = () => Math.max(0, _achPlaytimeMs() - _offlineBonusMs);
// Tiempo de ESTA partida en concreto, no el acumulado de todas las anteriores — mismo cálculo
// que usa el panel de Estadísticas (_currentRunOnlyMs): playtime total menos la suma de las
// runs ya cerradas en _runTimes. Sin esto, alguien que ya ha reseteado unas cuantas veces
// empezaría esta run con parte del presupuesto de horas ya "gastado" antes de plantar el primer
// árbol (Talador Relámpago es un reto de una sola partida, no de vida entera — reportado real:
// "1:16 restantes" con solo el 14% del bosque talado, porque _achPlaytimeMs solo sumaba).
const _achCurrentRunMs = () => Math.max(0, _achPlaytimeMs() - _runTimes.reduce((a, b) => a + Math.max(0, b), 0));
// Shared by "Agua para Todos" — same ±1-tile adjacency test the well's own descriptor uses
// (see the 'well' case in _getBuildingDescriptorInner), just checked from the farm's side
// against every well instead of one well against every farm.
function _achIsNearWell(b, wells) {
    for (let fy = b.y; fy < b.y + (b.h || 1); fy++)
        for (let fx = b.x; fx < b.x + (b.w || 1); fx++)
            for (const w of wells)
                if (Math.abs(w.x - fx) <= 1 && Math.abs(w.y - fy) <= 1) return true;
    return false;
}
const _achFarmsSheep = () => buildings.filter(b => b.type === 'farm' || b.type === 'sheep_farm');
const _achAllWatered = () => {
    const wells = buildings.filter(b => b.type === 'well');
    return _achFarmsSheep().every(b => _achIsNearWell(b, wells));
};
// La Banca Siempre Gana (antes "Precio de Saldo", que medía lo hundido que estaba el precio de un
// recurso — ese sistema de precio adaptativo se quitó, ver MARKET_COMMISSION). Ahora mide el valor
// en oro que la comisión fija del 20% te ha ido quitando, acumulado — lifetimeStats.marketCommissionGold.
// Pluriempleado: the SEVEN distinct trades one single villager must each have logged a full
// minute in. Reads the per-villager jobTime accumulator (seconds — see Villager.update), which
// is why 'orchard'/'cotton' had to be split out of the lumped 'farm'/'herd' keys: without that
// split, orchard and cotton work were indistinguishable from farm and sheep work.
const _ACH_PLURI_JOBS = ['lumber', 'farm', 'herd', 'mine', 'bake', 'orchard', 'cotton'];
const _ACH_PLURI_SEC = 60;
// Progress = the best single villager's count of qualifying trades, so the bar reads "4/7" for
// whoever is closest rather than mixing several villagers' partial careers together.
const _achPluriempleadoBest = () => {
    let best = 0;
    for (const v of villagers) {
        if (!v.jobTime) continue;
        let n = 0;
        for (const k of _ACH_PLURI_JOBS) if ((v.jobTime[k] || 0) >= _ACH_PLURI_SEC) n++;
        if (n > best) best = n;
    }
    return best;
};

// ── The 7 achievements that had no check at all — each needed either new per-run state (set at
// the one real event site) or a pure live computation. ──────────────────────────────────────

// Ir al Grano: which of stone/wool crossed zero FIRST. Polled (see _checkAchievements) rather
// than hooked at every production site (stone/wool are gained from a dozen+ places — villagers,
// market, Pedernal, statues...) — cheap enough, and "undecided until observed" is fine since the
// achievements panel/checker runs every few seconds anyway. Per-run: reset with every new game
// (see loadGame/init), same as _runRoadsBuiltOrDemolished above.
let _achStoneBeforeWool = null; // null=undecided, true=met, false=disqualified (wool arrived first, or both arrived together)
function _achPollStoneWoolOrder() {
    if (_achStoneBeforeWool !== null) return;
    if (stone > 0 && wool > 0) { _achStoneBeforeWool = false; return; } // can't tell which came first anymore — don't award it
    if (stone > 0) _achStoneBeforeWool = true;
    else if (wool > 0) _achStoneBeforeWool = false;
}

// Equidad / Monopolio share the same live per-profession headcount (mirrors the byJob breakdown
// in _buildStatsPanelHTML, just the 4 primary-resource jobs — bakery/theatre/treasury aren't one
// of "the 4 resources" either achievement is about).
function _achJobCounts() {
    const c = { lumber: 0, farm: 0, mine: 0, herd: 0 };
    for (const v of villagers) {
        const ft = v.farmTarget?.type;
        if (ft === 'farm' || ft === 'fruit_orchard') c.farm++;
        else if (ft === 'forest_farm') c.lumber++;
        else if (ft === 'sheep_farm' || ft === 'cotton_farm') c.herd++;
        else if (ft === 'stone_quarry') c.mine++;
        else if (v._targetKey || v.woodCarried > 0) c.lumber++;
    }
    return c;
}
const _achEquidadMet = () => {
    const c = _achJobCounts();
    const vals = [c.lumber, c.farm, c.mine, c.herd];
    return vals.every(v => v > 0) && vals.every(v => v === vals[0]);
};
const _achMonopolioMet = () => {
    if (villagers.length < 50) return false;
    const c = _achJobCounts();
    // Lumber used to be excluded on purpose (see the old ach.monopolio.desc wording), but with
    // 50+ population wood is the one resource every other job's upkeep still depends on — a
    // farm/mine/herd monopoly starves itself of wood long before reaching 50, making the
    // achievement not just hard but actually unreachable. Allowing lumber too is what makes it
    // completable at all.
    return c.lumber === villagers.length || c.farm === villagers.length || c.mine === villagers.length || c.herd === villagers.length;
};

// Verlos Crecer: per-slot daily login streak — genuinely new subsystem, nothing like this
// existed before. Runs once per boot (see the call in init()). Stored in forest_prestige (same
// place as _unlockedAchievements — see that var's own comment), so it survives prestige resets
// within a slot but does not carry over when you switch slots.
// Ruta Completa: el mayor numero de paradas DISTINTAS que una sola ruta ha llegado a tocar. Se
// guarda el maximo historico en vez de comprobarlo en vivo porque el logro se evalua a menudo y
// recalcular la ruta de cada mula ahi seria caro — se actualiza una vez por viaje cobrado, que es
// cuando la ruta ya esta calculada de todos modos (ver Mule._depositGold).
let _achRouteStopsMax = 0;
// Todas las paradas que puede tocar una ruta, contando las tabernas POR SEPARADO: Iglesia,
// Tesoreria, Teatro, Aserradero, Constructor y las DOS tabernas = 7. Se cuentan entradas y no
// tipos a proposito — "Ruta Completa" significa todas las paradas posibles, no una de cada clase.
// Eso hace que el logro dependa tambien de Taberna Doble (sin ella _maxTaverns() es 1 y el techo
// se queda en 6), que es parte de lo que lo hace legendario. Los siete tienen que estar ademas
// FUNCIONANDO a la vez (ni aislados ni en pausa), porque _muleWaypointBonuses ya no devuelve
// entrada para un edificio parado.
// Si alguna vez se anade otra parada a _muleWaypointBonuses, subir este numero con ella.
const ROUTE_STOPS_TOTAL = 7;
let _achLoginStreak = 0;
let _achLastLoginDate = null; // 'YYYY-MM-DD'
function _achUpdateLoginStreak() {
    const today = new Date().toISOString().slice(0, 10);
    if (_achLastLoginDate === today) return; // already counted today
    if (_achLastLoginDate) {
        const prev = new Date(_achLastLoginDate + 'T00:00:00');
        const diffDays = Math.round((new Date(today + 'T00:00:00') - prev) / 86400000);
        _achLoginStreak = diffDays === 1 ? _achLoginStreak + 1 : 1;
    } else {
        _achLoginStreak = 1;
    }
    _achLastLoginDate = today;
    savePrestige();
}

// Cuatro Elementos: food/wool/stone come from one _collectBuildingsInRadius pulse (already
// batched into a single `totals` object there). Wood usually comes from the separate manual
// tree-chop action, so "at once" is approximated as "within 800ms of a manual chop" rather than
// the exact same tick — the two systems don't share a single event to hook. See the call sites
// in _collectBuildingsInRadius and the manual-chop tap handler. BUT a forest_farm (plantación
// maderera) caught in the same collection radius pays wood straight into this very `totals`
// object (see collectFromBuilding), so that counts too, no 800ms guess needed — it's already
// the same pulse.
let _achLastManualWoodTs = 0;
let _achFourElementsUnlocked = false;
function _achCheckFourElements(totals) {
    if (_achFourElementsUnlocked || !totals) return;
    const hasFood = (totals.food || 0) > 0, hasWool = (totals.wool || 0) > 0, hasStone = (totals.stone || 0) > 0;
    const hasWood = (totals.wood || 0) > 0 || (performance.now() - _achLastManualWoodTs) < 800;
    if (hasFood && hasWool && hasStone && hasWood) {
        _achFourElementsUnlocked = true;
    }
}

// Fin del Mapa: how far territory has pushed out toward the edge in its closest-to-the-border
// direction — the starting 6×6 area (radius 3) already reads as 3/50, growing every time
// ownedTiles gains a tile further out than anything claimed so far (tree fells add to
// ownedTiles — see damageTree). Pure computation over live state, no event flag needed.
function _achFrontierDistance() {
    // Centre is 49.5, not 50: tiles run 0..99, so measuring from 50 made the two halves of the
    // map disagree — the left/top borders scored 50 while the right/bottom ones capped at 49,
    // and reaching those edges could never finish the achievement. Off 49.5 every border scores
    // 49.5, which rounds to the 50 goal, and the starting 6×6 (x,y 47..52) still reads 3.
    let maxD = 0;
    for (const key of ownedTiles) {
        const ci = key.indexOf(',');
        const d = Math.max(Math.abs(+key.slice(0, ci) - 49.5), Math.abs(+key.slice(ci + 1) - 49.5));
        if (d > maxD) maxD = d;
    }
    return Math.round(maxD);
}

