    // Al historial del servidor (con el código del jugador: si pierde los extras, se le devuelven desde el panel)
    _shopLogPurchase(p, 'play-' + tx.transactionId, 'paid', tx.amountMicros ? { price: tx.amountMicros / 1e6, currency: tx.currency || null } : {});
    trackEvent('shop_paid', { sku: id, store: 'play' });
    playBuildSound();
    showBuildToast(t('shop.done'));
