async function _shopBuy(id) {
    if (!_shopVisible()) return;   // en la app de CrazyGames o sin conexión no se compra (ver _cgInApp)
    if (_androidApp) { _playBuy(id); return; }   // app de Android: Google Play Billing
    if (SHOP_FAKE) { _shopFakeBuy(id); return; }   // en local: se entrega al momento, sin cobrar
    if (!SHOP_ENABLED || !XSOLLA_PROJECT_ID) { _shopNote('shop.soon'); return; }
    if (!_cgUserLoggedIn) { _shopNote('shop.login'); return; }   // CrazyGames: los invitados no pueden comprar
    // Se abre YA, antes de esperar a Xsolla: abrirla después de un await es lo que bloquean los navegadores
    const win = window.open('about:blank', '_blank');
    if (!win) { _shopNote('shop.popup'); return; }
    try {
        const r = await fetch('https://store.xsolla.com/api/v2/project/' + XSOLLA_PROJECT_ID + '/payment/item/' + encodeURIComponent(id), {
            method: 'POST',
            headers: { Authorization: 'Bearer ' + await _shopXsollaToken(), 'Content-Type': 'application/json' },
            body: JSON.stringify({ sandbox: SHOP_SANDBOX }),
        });
        if (!r.ok) throw new Error('HTTP ' + r.status);
        const order = await r.json();
        win.location.href = 'https://' + (SHOP_SANDBOX ? 'sandbox-secure' : 'secure') + '.xsolla.com/paystation4/?token=' + encodeURIComponent(order.token);
        trackEvent('shop_order', { sku: id });
        // Al historial del servidor, con el usuario: abierto ahora, y pagado cuando Xsolla lo confirme (_shopWatchOrder)
        const pack = SHOP_PACKS.find(x => x.id === id);
        if (pack && order.order_id) { _shopLogPurchase(pack, order.order_id, 'created', { test: SHOP_SANDBOX ? 1 : 0 }); _shopWatchOrder(pack, order.order_id); }
        // Se vuelve a leer el inventario un rato: es lo que manda (CrazyGames lo da como la forma más segura), no lo que diga esta ventana
        let n = 0;
        const timer = setInterval(() => { _shopRefreshPerks(); if (++n >= 60) clearInterval(timer); }, 5000);
    } catch (e) {
        console.warn('[Tienda] no se pudo crear el pedido', e);
        try { win.close(); } catch (e2) {}
        _shopNote('shop.error');
    }
}
window._shopBuy = _shopBuy;

// Créditos → "¡Gracias por vuestro apoyo!": la última lista guardada al momento (también sin conexión) y la del servidor al llegar
function _renderSupporters(list) {
    const box = document.getElementById('creditsSupporters'), el = document.getElementById('creditsSupportersList');
    if (!box || !el) return;
    if (!Array.isArray(list) || !list.length) { box.style.display = 'none'; return; }
    const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
    const f = list.filter(x => x.t === 'founder').map(x => esc(x.n)), s = list.filter(x => x.t !== 'founder').map(x => esc(x.n));
    el.innerHTML = (f.length ? '<div style="font-size:15px;color:#ffdf80;font-weight:bold;"><i class="fa-solid fa-crown" style="font-size:12px;color:#dfb256;"></i> ' + f.join(' · ') + '</div>' : '') +
                   (s.length ? '<div style="font-size:13px;color:#f0e0c0;font-weight:bold;margin-top:2px;">' + s.join(' · ') + '</div>' : '');
    box.style.display = '';
}
// Aplica la lista: nombres de los Founder para los aldeanos (y se renombran los que ya hay) y la sección de Créditos
function _applySupporters(list) {
    if (!Array.isArray(list)) return;
    _founderNames = list.filter(x => x && x.t === 'founder' && x.n).map(x => String(x.n).slice(0, 24));
    try { for (const v of villagers) if (!v._isPlayerAvatar && v.id != null) v.name = _villagerNameForId(v.id); } catch (e) {}
    _renderSupporters(list);
}
function _loadSupporters() {
    try { _applySupporters(JSON.parse(localStorage.getItem('fn_supporters') || '[]')); } catch (e) {}
    fetch(SUPPORTERS_ENDPOINT, { credentials: 'omit' }).then(r => r.ok ? r.json() : null).then(d => {
        if (!d || !Array.isArray(d.supporters)) return;
        try { localStorage.setItem('fn_supporters', JSON.stringify(d.supporters)); } catch (e) {}
        _applySupporters(d.supporters);
    }).catch(() => {});
}
setTimeout(_loadSupporters, 3000);   // al arrancar, para los nombres de los aldeanos (con la partida ya cargada)
function openCreditsPanel() {
    const panel = document.getElementById('creditsPanel');
    if (!panel) return;
    _loadSupporters();
    _cgModalOpened('credits');
    panel.style.display = 'flex';
}
window.openCreditsPanel = openCreditsPanel;
function closeCreditsPanel() {
    const panel = document.getElementById('creditsPanel');
    if (panel && panel.style.display !== 'none') { panel.style.display = 'none'; _cgModalClosed('credits'); }
}
window.closeCreditsPanel = closeCreditsPanel;
function closeChangelogPanel() {
    const panel = document.getElementById('changelogPanel');
    if (panel) panel.style.display = 'none';
    _cgModalClosed('changelog');
}
window.closeChangelogPanel = closeChangelogPanel;

// --- VILLAGER INFO CARD: click any villager on the map (see _handleCanvasTap) to see their
// name, current job, and personal lifetime resource totals. ---
// Raw category key — shared by the live "current job" label and the per-villager jobTime
// accumulator (see Villager.update()), so the two can never drift out of sync with each other.
// 'orchard' and 'cotton' are appended LAST on purpose: villager job times are persisted as a
// positional array (see the `jt` field in saveGame/loadGame), so appending keeps every existing
// save readable — the two new slots simply come back as 0. 'farm'/'herd' used to double as
// orchard/cotton respectively; time banked under the old lumped keys stays where it is.
// 'ritual' apéndice al final por la misma razón que 'orchard'/'cotton' (ver comentario de arriba):
// las jobTime se guardan como array posicional (campo "jt"), así que añadir al final no rompe
// ninguna partida guardada — las nuevas simplemente empiezan en 0.
// 'fish' (pescador) al final por lo mismo: array posicional guardado, lo nuevo siempre detrás.
const VILLAGER_JOB_KEYS = ['lumber', 'farm', 'mine', 'herd', 'bake', 'teatro', 'collect', 'idle', 'orchard', 'cotton', 'ritual', 'fish', 'dig', 'shipyard', 'drain', 'ship'];   // drain/ship (dique, Fase 2) al final por lo mismo: el guardado es posicional
function _villagerJobKey(v) {
    const ft = v.farmTarget?.type;
    if (ft === 'farm')                                 return 'farm';
    if (ft === 'fisher_hut')                           return 'fish';
    if (ft === 'zanja')                                return 'dig';
    if (ft === 'astillero')                            return 'shipyard';
    if (ft === 'fruit_orchard')                        return 'orchard';
    if (ft === 'sheep_farm')                           return 'herd';
    if (ft === 'cotton_farm')                          return 'cotton';
    if (ft === 'forest_farm')                          return 'lumber';
    if (ft === 'stone_quarry')                         return 'mine';
    if (ft === 'bakery')                                return 'bake';
    if (ft === 'teatro')                                return 'teatro';
    // Solo los oficiantes (state 'ritual_working') cuentan como "ritual" — el elegido (state
    // 'ritual_captive') también apunta farmTarget al altar pero no está trabajando, así que cae
    // a los siguientes checks (y normalmente a 'idle'), no se le suma tiempo de oficiante.
    if (ft === 'ritual' && v.state === 'ritual_working') return 'ritual';
    if (ft === 'tesoreria')                             return 'collect';
    if (ft === 'dry_dock' && (v.state === 'draining' || v.state === 'hauling_water')) return 'drain';
    if (ft === 'dry_dock' && (v.state === 'ship_fetch' || v.state === 'ship_haul'))   return 'ship';
    if (v._targetKey || v.woodCarried > 0)              return 'lumber';
    return 'idle';
}
function _villagerJobLabel(v) {
    if (v.state === 'strike') return t('villagerInfo.job.strike');   // no tiene clave propia de tiempo (jobTime/guardado): solo etiqueta
    return t('villagerInfo.job.' + _villagerJobKey(v));
}

let _villagerInfoTarget = null; // the Villager instance currently shown, or null

function openVillagerInfo(v) {
    _villagerInfoTarget = v;
    selectedBuilding = null; // building card and villager card are mutually exclusive
    updateUI();
}
window.openVillagerInfo = openVillagerInfo;

// Prev/next buttons flanking the villager's name — jumps the card (and camera, so the newly
// picked villager is actually visible instead of immediately triggering the off-screen
// auto-close below) to the next villager in list order, wrapping around at the ends.
function _cycleVillagerInfo(dir) {
    if (!_villagerInfoTarget || villagers.length === 0) return;
    let idx = villagers.indexOf(_villagerInfoTarget);
    if (idx === -1) idx = 0;
    idx = (idx + dir + villagers.length) % villagers.length;
    const next = villagers[idx];
    cameraX = next.x; cameraY = next.y;
    _clampCamera();
    openVillagerInfo(next);
}
window._cycleVillagerInfo = _cycleVillagerInfo;

// Live portrait: not a re-drawn sprite — an actual crop of the main game canvas at the
// villager's current on-screen position, so it's a real "photo" of them exactly as they
// look in the world right now (current animation frame, tilt, walk-bob, whatever's
// overlapping them), not a static lookup — y nada más: el recorte es TODO lo que se pinta, no se
// vuelve a dibujar el aldeano encima. draw() renders the sprite as a 48x48 world-px
// square centered on (x, y - roadYOffset) — 64 gives a little breathing room around it.
// Called every frame from gameLoop() (not just on the ~1/sec updateUI() refresh) so the
// crop tracks the villager's movement/animation smoothly instead of looking frozen.
function _updateVillagerPortraitCapture() {
    const v = _villagerInfoTarget;
    if (!v) return;
    const portrait = document.getElementById('villagerInfoPortrait');
    if (!portrait) return;
    const pctx = portrait.getContext('2d');
    pctx.imageSmoothingEnabled = false;
    pctx.clearRect(0, 0, portrait.width, portrait.height);
    const screenX = (v.x - cameraX) * zoom + canvas.width / 2;
    const screenY = (v.y - cameraY) * zoom + _gameCenterY;
    const captureSize = 96 * zoom; // 64 * 1.5 — wider crop so the villager reads smaller/further away, less of a tight close-up
    try {
        pctx.drawImage(canvas, screenX - captureSize / 2, screenY - captureSize / 2, captureSize, captureSize, 0, 0, portrait.width, portrait.height);
    } catch (e) {} // off-canvas source rect (villager currently off-screen) — leave it blank
    // Aquí había un segundo dibujado del aldeano ENCIMA del recorte, a un zoom fijo de 2.2, para
    // que no se viera borroso con el mapa muy alejado. Quitado a propósito: se veía como una
    // figura nítida pegada delante de la foto, a otra escala y sin encajar con ella. "no pasa nada
    // si se ve pixelado" — la ficha es el recorte real del canvas y nada más.
}

// Called from openVillagerInfo and again every updateUI() tick while the card is open, so the
// resource totals keep climbing live instead of freezing at whatever they were on the click.
function _renderVillagerInfo() {
    const v = _villagerInfoTarget;
    if (!v) return;
    // The villager could vanish while the card is open (its building got destroyed and workers
    // released — villagers themselves are never removed in this game, but stay defensive).
    // El aldeano-jugador (easter egg) nunca vive en villagers[] a propósito — ver su propia
    // excepción aquí, y _maybeSpawnPlayerAvatar, que ya cierra esta ficha él solo si deja de
    // existir (población por debajo de 50 de nuevo).
    if (v !== _playerAvatar && !villagers.includes(v)) { closeVillagerInfo(); return; }

    const nameEl = document.getElementById('villagerInfoName');
    if (nameEl) nameEl.textContent = v.name;
    const jobEl = document.getElementById('villagerInfoJob');

    _updateVillagerPortraitCapture();

    // "un aldeano que sea el jugador... si lo pulsas hay un easter egg" — su ficha no tiene
    // curro ni recursos que mostrar (nunca trabaja), así que en su lugar dice quién es de verdad
    // y cómo moverlo. Nada de esto pasa por _villagerJobLabel/las filas de abajo, pensadas para
    // aldeanos reales.
    if (v === _playerAvatar) {
        if (jobEl) jobEl.textContent = t('villagerInfo.itsYou');
        const statsEl = document.getElementById('villagerInfoStats');
        // "que hacemos con modo movil, que pueda pulsar en el mapa... y un boton de dejar de
        // controlar" — no keyboard on mobile, so the hint text switches to the tap-based
        // instructions (see _handleCanvasTap/_updatePlayerAvatar) and a real "stop controlling"
        // button replaces just letting go of WASD (there's no equivalent gesture for that on a
        // touchscreen). Shown regardless of _MQ_PORTRAIT too — harmless shortcut on desktop.
        if (statsEl) {
            const hint = _MQ_PORTRAIT.matches ? t('villagerInfo.tapHint') : t('villagerInfo.wasdHint');
            // class="villager-avatar-hint"/"villager-stop-btn" — the blanket mobile button-shrink
            // rule (#villagerSelContent button, meant only for the ◀/▶ cycle arrows above) was
            // ALSO squashing this one down to their tiny 18px circle, wrapping its own label text
            // across two lines ("el boton mas grande de dejar de seguir y el bocadillo se ve muy
            // pequeño" — real bug report). These classes let the mobile CSS target each kind on
            // its own instead of every <button> in the panel getting the nav-arrow treatment.
            statsEl.innerHTML = `
                <div class="villager-avatar-hint" style="color:var(--text-muted);font-size:12px;font-style:italic;padding:6px 0;text-align:center;">${hint}</div>
                <button class="villager-stop-btn" onclick="_stopControllingAvatar()" style="display:block;margin:4px auto 0;padding:6px 14px;background:rgba(0,0,0,0.25);border:1px solid var(--panel-border);border-radius:4px;color:var(--gold);font-size:12px;cursor:pointer;">${t('villagerInfo.stopControl')}</button>`;
        }
        const jtEl = document.getElementById('villagerInfoJobTimes');
        if (jtEl) jtEl.innerHTML = '';
        return;
    }
    if (jobEl) jobEl.textContent = _villagerJobLabel(v);

    const ico = (name) => `<img src="assets/icon_${name}.png" style="width:15px;height:15px;image-rendering:pixelated;vertical-align:middle;margin-right:6px;">`;
    const rows = [
        ['wood',  v.lifetimeCollected.wood],
        ['food',  v.lifetimeCollected.food],
        ['wool',  v.lifetimeCollected.wool],
        ['stone', v.lifetimeCollected.stone],
        ['gold',  v.lifetimeCollected.gold],
    ].filter(([, val]) => val > 0);

    // Almas liberadas como oficiante — no es un recurso normal (sin icon_soul.png que pasarle a
    // ico()), así que usa el mismo icono de calavera que el propio Altar; reutiliza ritual.stat.souls,
    // ya existente en la ficha del edificio, en vez de una clave nueva para el mismo concepto.
    const soulsRowHTML = v.ritualSoulsFreed > 0
        ? `<div style="display:flex;justify-content:space-between;align-items:center;padding:4px 0;border-bottom:1px solid rgba(139,90,43,0.2);">
                <span style="color:var(--text-light);font-size:13px;"><i class="fa-solid fa-skull" style="width:15px;text-align:center;vertical-align:middle;margin-right:6px;color:var(--gold);"></i>${t('ritual.stat.souls')}</span>
                <span style="font-family:'Roboto Mono',monospace;color:var(--gold);font-size:13px;">${formatNumber(v.ritualSoulsFreed)}</span>
            </div>`
        : '';

    const statsEl = document.getElementById('villagerInfoStats');
    if (statsEl) {
        statsEl.innerHTML = (rows.length || soulsRowHTML)
            ? rows.map(([res, val]) => `
                <div style="display:flex;justify-content:space-between;align-items:center;padding:4px 0;border-bottom:1px solid rgba(139,90,43,0.2);">
                    <span style="color:var(--text-light);font-size:13px;">${ico(res)}${t('stats.' + res)}</span>
                    <span style="font-family:'Roboto Mono',monospace;color:var(--gold);font-size:13px;">${formatNumber(val)}</span>
                </div>`).join('') + soulsRowHTML
            : `<div style="color:var(--text-muted);font-size:12px;font-style:italic;padding:6px 0;">${t('villagerInfo.none_yet')}</div>`;
    }

    // Time spent per job, biggest first — skips idle/zero entries so a specialist doesn't show
    // a wall of zeroes for every job it's never done.
    const jtEl = document.getElementById('villagerInfoJobTimes');
    if (jtEl) {
        const jobRows = VILLAGER_JOB_KEYS
            .filter(k => k !== 'idle' && v.jobTime[k] > 0)
            .sort((a, b) => v.jobTime[b] - v.jobTime[a]);
        jtEl.innerHTML = jobRows.length
            ? `<div style="border-top:1px solid #3a2e1e;margin:8px 0 6px;padding-top:8px;color:var(--text-muted);font-size:10px;text-transform:uppercase;letter-spacing:.5px;">${t('villagerInfo.time_per_job')}</div>`
                + jobRows.map(k => `
                    <div style="display:flex;justify-content:space-between;padding:2px 0;">
                        <span style="color:var(--text-light);font-size:12px;">${t('villagerInfo.job.' + k)}</span>
                        <span style="font-family:'Roboto Mono',monospace;color:var(--gold);font-size:12px;">${_fmtBoostDur(v.jobTime[k])}</span>
                    </div>`).join('')
            : '';
    }
}

function closeVillagerInfo() {
    _villagerInfoTarget = null;
    updateUI();
}
window.closeVillagerInfo = closeVillagerInfo;

// "un boton de dejar de controlar" — the explicit mobile equivalent of just letting go of WASD
// (no such gesture exists on a touchscreen): ends control the same way closing the panel already
// does on desktop (_villagerInfoTarget === p gates _updatePlayerAvatar's controlled branch), and
// drops any pending tap-to-move target so a later re-open doesn't immediately resume an old walk.
function _stopControllingAvatar() {
    if (_playerAvatar) _playerAvatar._walkTarget = null;
    closeVillagerInfo();
}
window._stopControllingAvatar = _stopControllingAvatar;

function openSkillTree() {
    const panel = document.getElementById('skillTreePanel');
    if (!panel) return;
    const willShow = panel.style.display === 'none';
    if (willShow && !_spectatorMode && !_retoActive) _ensureLastLegadoAffordable();
    panel.style.display = willShow ? 'flex' : 'none';
    skillTreeOpen = willShow;
    _stkSyncDevToolbar();
    // Shared 'skillFlow' key with showSkillCardModal/closeSkillCardModal below — the relic card
    // modal's own "Ver árbol" peek (_stkPeekFromCardModal) bypasses this function entirely (hides
    // the card modal, shows this panel, both without going through openSkillTree), so tracking
    // both ends under ONE key means neither side has to know about the other's transitions: the
    // Set-based _cgBlockingModals just stays non-empty for as long as either the tree or the card
    // modal is genuinely on screen, however the player got there or back.
    if (willShow) _cgModalOpenedIfEnabled('skillFlow'); else _cgModalClosedIfEnabled('skillFlow');
    // The skill tree is its own fullscreen takeover (like the main menu) — the always-on-top
    // settings button would otherwise float visibly over it despite the tree's own z-index.
    // Hiding needs setProperty(...,'important') — a mobile stylesheet rule forces #btnSettings
    // to display:flex !important, which a plain .style.display='none' can't beat; showing it
    // back is fine as a normal assignment since that just clears the inline override entirely.
    const _btnSettingsForTree = document.getElementById('btnSettings');
    if (_btnSettingsForTree) {
        if (willShow) _btnSettingsForTree.style.setProperty('display', 'none', 'important');
        else _setBtnSettingsHidden(_spectatorMode); // a visit keeps the gear hidden (see initSpectatorMode)
    }
    if (!willShow && _stkCardPeekPicks) {
        // Closed the tree while peeking from the card modal, without going back to it or
        // picking anything — same as canceling via the card modal's own close button: drop
        // the peek state (so it doesn't stick around and wrongly highlight nodes next time),
        // AND un-pend the relic, since walking away here leaves both the tree and the card
        // modal closed with no way back into this relic's flow except clicking it again.
        _stkCardPeekPicks = null;
        const backBtn = document.getElementById('stkBackToCardsBtn');
        if (backBtn) backBtn.style.display = 'none';
        _skillCardUpdateMoreBtn();
        const idx = relicTiles.findIndex(r => r.pending);
        if (idx !== -1) relicTiles[idx].pending = false;
    }
    updateSkillTreePanel();
    if (willShow) renderSkillTree();
}
window.openSkillTree = openSkillTree;
window.toggleSettingsPanel = toggleSettingsPanel;
window.applySettings = applySettings;

// "Ver árbol" from inside the relic card modal: hide the modal (the pending relic stays
// pending — this is a peek, not a cancel, so unlike the modal's own close button this does
// NOT un-pend it) and show the tree with the current candidate cards highlighted so the
// player can see where each one sits before picking.
function _stkPeekFromCardModal() {
    _stkCardPeekPicks = _skillCardPickIds.slice();
    const modal = document.getElementById('skillCardModal');
    if (modal) modal.style.display = 'none';
    const panel = document.getElementById('skillTreePanel');
    if (panel) panel.style.display = 'flex';
    skillTreeOpen = true;
    // Same reasoning as openSkillTree(): the tree is a fullscreen takeover and #btnSettings'
    // always-on-top z-index would otherwise sit right over its title-bar "✕", blocking it —
    // this path bypasses openSkillTree() entirely (it's opened FROM the card modal, not toggled
    // from the game), so it has to hide/restore #btnSettings itself.
    const _btnSettingsForPeek = document.getElementById('btnSettings');
    if (_btnSettingsForPeek) _btnSettingsForPeek.style.setProperty('display', 'none', 'important');
    const backBtn = document.getElementById('stkBackToCardsBtn');
    if (backBtn) {
        backBtn.style.display = 'block';
        backBtn.textContent = t('card.back_to_cards');
    }
    _skillCardUpdateMoreBtn();
    // Lectura forzada de layout: el panel acaba de pasar a display:flex justo arriba, y
    // renderSkillTree() necesita el tamaño real de #stkContainer para centrar la vista. Sin esto
    // mide 0 y el árbol aparece fuera de pantalla (ver el centrado en renderSkillTree).
    const _contForPeek = document.getElementById('stkContainer');
    if (_contForPeek) void _contForPeek.offsetHeight;
    renderSkillTree();
}
window._stkPeekFromCardModal = _stkPeekFromCardModal;

function _stkReturnToCardModal() {
    _stkCardPeekPicks = null;
    const panel = document.getElementById('skillTreePanel');
    if (panel) panel.style.display = 'none';
    skillTreeOpen = false;
    _stkSyncDevToolbar();
    const backBtn = document.getElementById('stkBackToCardsBtn');
    if (backBtn) backBtn.style.display = 'none';
    const _btnSettingsForPeek = document.getElementById('btnSettings');
    if (_btnSettingsForPeek) _setBtnSettingsHidden(_spectatorMode);
    _skillCardUpdateMoreBtn();
    const modal = document.getElementById('skillCardModal');
    if (modal) modal.style.display = 'flex';
}
window._stkReturnToCardModal = _stkReturnToCardModal;

let _tutoDisplayed = -1;
// Last step updateTutorial() has already reacted to for the auto-expand-on-step-change rule (see
// there). Separate from _tutoDisplayed, which tracks the step whose CONTENT is on screen and only
// catches up after _tutoAnimate's swap animation finishes.
let _tutoLastStepSeen = -1;
let _tutoSkillPicked = false; // set to true when player picks first skill card

function _tutoSetContent(panel, step) {
    const indicator = panel.querySelector('.step-indicator');
    const title     = panel.querySelector('h2');
    const desc      = panel.querySelector('p');
    const closeBtn  = document.getElementById('btnCloseTutorial');
    if (closeBtn) closeBtn.style.display = (step >= 12) ? 'block' : 'none';

    // Tutorial de la fase 2 (21-24). Numeración aparte para no pisar los pasos 1-12 del tutorial
    // original, que sigue guardado en su propio contador. Ver updateTutorial.
    if (step >= 21 && step <= 24) {
        const n = step - 20;
        indicator.innerText = t('tuto.p2.step', { n });
        title.innerText     = t('tuto.p2.' + n + '.title');
        desc.innerHTML      = t('tuto.p2.' + n + '.desc');
        return;
    }

    // Old 8-step gameplay tutorial
    if (step === 1) {
        indicator.innerText = t('tuto.step', { n: 1 });
        title.innerText     = t('tuto.1.title');
        desc.innerHTML      = t('tuto.1.desc', { n: wood, res: RES.wood });
    } else if (step === 2) {
        indicator.innerText = t('tuto.step', { n: 2 });
        const _o2 = _tutoOverride(2);   // el mundo puede cambiar este paso (mundo 2: ya empiezas con 2 supervivientes)
        title.innerText     = t(_o2 ? _o2.title : 'tuto.2.title');
        desc.innerHTML      = t(_o2 ? _o2.desc : 'tuto.2.desc');
    } else if (step === 3) {
        indicator.innerText = t('tuto.step', { n: 3 });
        title.innerText     = t('tuto.3.title');
        desc.innerHTML      = t('tuto.3.desc', { n: villagers.length, res: `<i class="fa-solid fa-person-digging"></i>` });
    } else if (step === 4) {
        indicator.innerText = t('tuto.step', { n: 4 });
        title.innerText     = t('tuto.4.title');
        desc.innerHTML      = t('tuto.4.desc', { res: RES.wood });
    } else if (step === 5) {
        indicator.innerText = t('tuto.step', { n: 5 });
        title.innerText     = t('tuto.5.title');
        desc.innerHTML      = t('tuto.5.desc');
    } else if (step === 6) {
        indicator.innerText = t('tuto.step', { n: 6 });
        title.innerText     = t('tuto.6.title');
        desc.innerHTML      = t('tuto.6.desc', { res: RES.wood });
    } else if (step === 7) {
        indicator.innerText = t('tuto.step', { n: 7 });
        title.innerText     = t('tuto.7.title');
        desc.innerHTML      = t('tuto.7.desc');
    } else if (step === 8) {
        indicator.innerText = t('tuto.step', { n: 8 });
        const _o8 = _tutoOverride(8);   // el mundo puede cambiar este paso (mundo 2: el Pescador)
        title.innerText     = t(_o8 ? _o8.title : 'tuto.8.title');
        desc.innerHTML      = t(_o8 ? _o8.desc : 'tuto.8.desc');
    } else if (step === 9) {
        // Still framed as "Paso 9" (not a descriptive indicator like the relic phases below) —
        // this is still teaching the core basics, not the relic-hunting phase that starts next.
        indicator.innerText = t('tuto.step', { n: 9 });
        title.innerText     = t('tuto.9.title');
        desc.innerHTML      = t('tuto.9.desc', { n: Math.min(2, buildings.filter(b => b.type === 'road').length) });
    // Relic phases — appear after the 9-step tutorial, never repeat
    } else if (step === 10) {
        const rem = Math.max(0, nextChestAt - treesChopped);
        indicator.innerText = t('tuto.10.indicator');
        title.innerText     = t('tuto.10.title');
        desc.innerHTML      = t('tuto.10.desc', { n: rem, plural: rem === 1 ? t('tuto.10.tree') : t('tuto.10.trees') });
    } else if (step === 11) {
        indicator.innerText = t('tuto.11.indicator');
        title.innerText     = t('tuto.11.title');
        desc.innerHTML      = t('tuto.11.desc');
    } else if (step === 12) {
        indicator.innerText = t('tuto.12.indicator');
        title.innerText     = t('tuto.12.title');
        desc.innerHTML      = t('tuto.12.desc');
    }
}

function _tutoAnimate(panel, step) {
    if (_tutoDisplayed === -1) {
        _tutoSetContent(panel, step);
        _tutoDisplayed = step;
        return;
    }
    panel.classList.remove('tuto-in');
    panel.classList.add('tuto-out');
    setTimeout(() => {
        panel.classList.remove('tuto-out');
        _tutoSetContent(panel, step);
        _tutoDisplayed = step;
        panel.classList.add('tuto-in');
        setTimeout(() => panel.classList.remove('tuto-in'), 400);
    }, 220);
}

// Maps each tutorial step to the id of whatever button it wants the player to press next — used
// by _tutoApplyHighlight() to add a strong, hard-to-miss marker (see .tuto-highlight in
// index.css) instead of relying on the sign's text alone. Steps not listed here (1: hover a
// tree, 10/11: chop toward/click a relic) don't point at any one button. Every id here is a
// SHARED control that only actually becomes visible once the right thing is selected (the
// villager/axe buttons live in the Town Center/Lumber Camp's own selection panel) — harmless to
// tag with the highlight class even while hidden, since it just does nothing until CSS display
// makes the element visible on its own.
const TUTORIAL_HIGHLIGHT_TARGETS = {
    2: 'btnTrainVillagerWood',
    3: 'btnTrainVillagerWood',
    4: 'btnBuildLumberCamp',
    5: 'btnUpgradeAxe',
    6: 'btnBuildHouse',
    7: 'btnBuildMill',
    8: 'btnBuildFarm',
    9: 'btnBuildRoad',
};
// Lo mismo para la fase 2. Los dos primeros salen en el menú de construcción y los otros dos en
// el panel del dique, pero da igual: la clase se puede poner en un botón oculto sin efecto.
// "que se retome el tutorial por el paso que aún no has hecho": el paso que toca según lo que YA
// existe en la partida — 1 sin dique, 2 sin puerto, 3 con el dique aislado, 4 hasta que se pulsa
// "Vaciar dique". 5 = ya no queda nada que enseñar (vaciando, seco o zarpado). Lo usan el arranque
// y la reanudación tras un F5, para no volver al paso 1 ni desaparecer con el dique ya hecho.
function _phase2TutoStepFor() {
    const d = _dryDock();
    if (!d) return 1;
    if (d.draining || d.sailed || _dryDockIsDry(d)) return 5;
    if (!_waterPort()) return 2;
    if (d._isolated) return 3;
    return 4;
}
const PHASE2_TUTO_TARGETS = {
    1: 'btnBuildDryDock',
    2: 'btnBuildPort',
    3: 'btnBuildRoad',
    4: 'btnStartDraining',
};
let _tutoHighlightedEl = null;
function _tutoApplyHighlight() {
    let targetId = null;
    if (!_spectatorMode) {
        if (phase2Tuto >= 1 && phase2Tuto <= 4) targetId = PHASE2_TUTO_TARGETS[phase2Tuto];
        else if (tutorialStep < 13)             targetId = (_tutoOverride(tutorialStep) || {}).target || TUTORIAL_HIGHLIGHT_TARGETS[tutorialStep];
    }
    const target = targetId ? document.getElementById(targetId) : null;
    if (target === _tutoHighlightedEl) return;
    if (_tutoHighlightedEl) _tutoHighlightedEl.classList.remove('tuto-highlight');
    _tutoHighlightedEl = target;
    if (_tutoHighlightedEl) _tutoHighlightedEl.classList.add('tuto-highlight');
}

// "poder minimizar el tutorial y al cerrarlo se queda el titulo del paso" — in-memory only (not
// persisted): unlike #commandCard's collapse, this is a quick declutter toggle a player might hit
// several times per tutorial, not a set-and-forget preference to remember across sessions. See
// #tutorialPanel.tuto-collapsed in index.css for what actually hides (the <p> description + the
// close button; the step-indicator/title stay). Purely about the dialog's own height now — the
// minimap/offline-strip crowding it used to help with is handled independently (see
// _updateMobileTutoCrowding/_positionMobileOfflineStripsNow), so this no longer needs to touch
// either.
let _tutoCollapsed = false;
// Single place that writes the collapsed state, so the class and the arrow can never drift apart
// — updateTutorial()'s auto-expand-on-step-change calls this too, not just the button.
function _setTutorialCollapsed(collapsed) {
    _tutoCollapsed = collapsed;
    const panel = document.getElementById('tutorialPanel');
    if (panel) panel.classList.toggle('tuto-collapsed', _tutoCollapsed);
    const btn = document.getElementById('btnToggleTutorial');
    // "el botón de minimizar y maximizar está al revés la flecha" — the arrow shows the ACTION,
    // not the current state: expanded shows ▲ (press to fold it up), collapsed shows ▼ (press to
    // drop it back open). This is the reverse of #btnToggleCommandCard's own convention, which
    // still shows the state instead — flipped here only, since only this one was reported.
    if (btn) btn.textContent = _tutoCollapsed ? '▼' : '▲';
}
function _toggleTutorialCollapse() {
    _setTutorialCollapsed(!_tutoCollapsed);
}
window._toggleTutorialCollapse = _toggleTutorialCollapse;

// "que el mapa no se vea durante el tutorial" — hides the minimap (see body.fn-tuto-crowded in
// index.css, mobile-only) for the WHOLE tutorial, independent of _tutoCollapsed — not just while
// the dialog happens to be expanded and physically overlapping it. Called on every
// updateTutorial() (so it's always correct regardless of which of its early returns fires —
// spectator, tutorial done, or the normal path).
function _updateMobileTutoCrowding() {
    const crowding = typeof _MQ_PORTRAIT !== 'undefined' && _MQ_PORTRAIT.matches &&
        !_spectatorMode && tutorialStep < 13;
    const changed = document.body.classList.contains('fn-tuto-crowded') !== crowding;
    document.body.classList.toggle('fn-tuto-crowded', crowding);
    // Settings' map button reads _minimapDisabledByTutorial() (this same class) to decide its
    // label — keep it in sync the moment the tutorial starts/ends instead of waiting for whatever
    // next opens the Settings panel to happen to refresh it.
    if (changed) _updateMinimapToggleLabel();
    _updateTutoBoostScale();
}

// "calcula la distancia del tutorial y el espacio que queda a la derecha para que el timeboost
// nunca se tape por el tuto, que se haga mas pequeño si es necesario automaticamente" — "el div de
// recurso extra puede tb escalarse como el de tiempo?" — #offlineBoostStrip AND #offlineAdOfferStrip
// both sit right-anchored on desktop (the ad-offer strip just below the boost strip), which a
// narrower browser window can push into #tutorialPanel's own top-right corner (centered but not
// full-width, so it doesn't claim that whole corner the way mobile's layout does). Earlier attempts
// hid strips outright, moved the dialog, or shrank by a flat guessed percentage regardless of
// whether it actually needed it — this instead measures the real live gap every time and shrinks
// only by exactly what's needed (never more), scaling each strip from its own top-right corner (its
// anchor point) so that corner never moves. "si la pantalla es mas estrecha hasta el minimo de
// timebank entonces que siga reduciendose pero el panel de tutorial" — once EVERY visible strip has
// hit its own floor and there's still not enough room, #tutorialPanel starts shrinking too (from its
// own top-center, since it's horizontally centered) to keep closing the gap. Desktop only — mobile
// already lays these strips out independently of the tutorial dialog's position. Called both on
// every _updateMobileTutoCrowding (tutorial step changes), every frame from _updateOfflineBoostUI
// (a strip's own natural width can change frame to frame as its content does), and directly from the
// window resize listener (see _positionTutorialPanelNow) so a live window drag doesn't lag a frame
// behind visibly.
function _updateTutoBoostScale() {
    const tuto = document.getElementById('tutorialPanel');
    const stripEls = ['offlineBoostStrip', 'offlineAdOfferStrip']
        .map(id => document.getElementById(id))
        .filter(Boolean);
    if (!tuto || !stripEls.length) return;
    if (typeof _MQ_PORTRAIT !== 'undefined' && _MQ_PORTRAIT.matches) {
        stripEls.forEach(el => el.style.transform = '');
        tuto.style.transform = '';
        tuto.style.removeProperty('--tuto-scale');
        return;
    }
    const visibleStrips = stripEls.filter(el => getComputedStyle(el).display !== 'none');
    if (!visibleStrips.length || tuto.style.display === 'none') {
        stripEls.forEach(el => el.style.transform = '');
        tuto.style.transform = '';
        tuto.style.removeProperty('--tuto-scale');
        return;
    }
    const STRIP_FLOOR = 0.55;
    const TUTO_FLOOR = 0.75; // dialog text needs to stay legible longer than a strip's buttons/label
    const margin = 12;

    // "sin hacer nada el boost time hace escalado de grande a pequeño cada 0.5s o asi" — an
    // earlier version reset transform to 'none' and forced a synchronous reflow to measure the
    // natural size, THEN reapplied the scaled value. That reset was real (not just theoretical):
    // forcing the reflow while unscaled genuinely committed the element to its full size for a
    // moment, so every recheck — including ones where nothing had actually changed — replayed a
    // real "full size → scaled" transition. offsetWidth sidesteps this: it's pure layout geometry,
    // never affected by a transform already applied, so the natural width reads correctly with no
    // reset needed at all.
    const tutoNaturalWidth = tuto.offsetWidth;

    // getBoundingClientRect() DOES reflect the current transform, but both anchors — each strip's
    // top-right corner, tuto's top-center — are exactly the points each element's own scale is
    // anchored on (transform-origin below), so they read correctly straight off the CURRENT rect
    // regardless of whatever scale is already applied. No reset needed for these either.
    const tutoRect = tuto.getBoundingClientRect();
    const tutoCenterX = (tutoRect.left + tutoRect.right) / 2;
    const naturalTutoRight = tutoCenterX + tutoNaturalWidth / 2;

    // First pass: each visible strip's own scale, independently, assuming tuto stays at its
    // natural (unshrunk) size — the common case, and cheap to just try first.
    const strips = visibleStrips.map(el => {
        const naturalWidth = el.offsetWidth;
        const right = el.getBoundingClientRect().right; // invariant under this element's own scale
        const available = right - naturalTutoRight - margin;
        const scale = available >= naturalWidth ? 1 : Math.max(STRIP_FLOOR, available / naturalWidth);
        return { el, naturalWidth, right, scale };
    });

    // Any strip that hit its own floor and is STILL too tight? Track the tightest constraint any
    // of them puts on tuto's right edge — tuto has to satisfy all of them at once.
    let tutoScale = 1;
    let tightestMaxTutoRight = Infinity;
    strips.forEach(s => {
        if (s.scale <= STRIP_FLOOR + 0.001) {
            const leftAtFloor = s.right - s.naturalWidth * STRIP_FLOOR;
            const maxTutoRight = leftAtFloor - margin;
            if (maxTutoRight < naturalTutoRight) tightestMaxTutoRight = Math.min(tightestMaxTutoRight, maxTutoRight);
        }
    });
    if (tightestMaxTutoRight < Infinity) {
        const neededHalfWidth = tightestMaxTutoRight - tutoCenterX;
        tutoScale = Math.max(TUTO_FLOOR, Math.min(1, (neededHalfWidth * 2) / tutoNaturalWidth));
    }

    strips.forEach(s => {
        s.el.style.transformOrigin = 'top right';
        s.el.style.transform = s.scale < 0.999 ? `scale(${s.scale.toFixed(3)})` : '';
    });
    tuto.style.transformOrigin = 'top center';
    tuto.style.transform = tutoScale < 0.999
        ? `translateX(-50%) scale(${tutoScale.toFixed(3)})`
        : 'translateX(-50%)';
    // "calcula bien el escalado del tutorial antes de la animacion para que no haga escalado raro
    // despues de la animacion" — .tuto-in/.tuto-out (see the keyframes below) drive `transform`
    // themselves while active, completely overriding the inline value above for their duration, so
    // without this the sign-in animation always played at full (unscaled) size and only snapped to
    // the correct scale once it ended. Read back inside those keyframes via var(--tuto-scale, 1),
    // this is already current by the time any animation starts — _updateMobileTutoCrowding calls
    // this function before updateTutorial() ever reaches _tutoAnimate().
    tuto.style.setProperty('--tuto-scale', tutoScale.toFixed(3));
}

// Shared by every tutorial-step building highlight (Town Center for the villager steps, Lumber
// Camp for the axe upgrade, ...): a green pulsing double-ring around the building plus a bouncing
// arrow pointing at it from the right side. Not above the building: for a freshly-started city
// that's exactly where the tutorial dialog DOM panel sits, confirmed via a live render test that
// an arrow drawn there rendered maybe one visible pixel around that opaque panel's edge, the rest
// hidden behind it. The right side clears every other fixed UI at these steps (minimap top-left,
// tutorial dialog top-center, command card bottom-right — hidden until 5 villagers anyway).
function _drawTutoBuildingPointer(bx, by, bw, bh) {
    const t2 = performance.now() / 500;
    const pulse = 0.55 + 0.35 * Math.sin(t2);
    ctx.save();
    ctx.lineWidth = 7;
    ctx.strokeStyle = `rgba(60, 230, 60, ${pulse * 0.35})`;
    ctx.strokeRect(bx + 2, by + 2, bw - 4, bh - 4);
    ctx.lineWidth = 3;
    ctx.strokeStyle = `rgba(90, 255, 90, ${pulse})`;
    ctx.strokeRect(bx + 2, by + 2, bw - 4, bh - 4);
    ctx.restore();
    const ax = bx + bw + 14 + Math.sin(Date.now() / 220) * 6;
    const ay = by + bh / 2;
    ctx.save();
    ctx.fillStyle = '#5eff5e';
    ctx.strokeStyle = '#1a3a1a';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(ax - 16, ay);       // tip, pointing left at the building
    ctx.lineTo(ax + 6, ay - 12);
    ctx.lineTo(ax + 6, ay - 5);
    ctx.lineTo(ax + 20, ay - 5);
    ctx.lineTo(ax + 20, ay + 5);
    ctx.lineTo(ax + 6, ay + 5);
    ctx.lineTo(ax + 6, ay + 12);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.restore();
}
// Tutorial step 5 ("mejora el hacha") only lights up the Lumber Camp once the upgrade is actually
// affordable — same idea as the Town Center's wood >= getVillagerWoodCost() gate, just checking
// all three resources since the axe upgrade can also cost food/wool at higher levels.
function _tutoAxeAffordable() {
    const c = getAxeUpgradeCost();
    return wood >= c.wood && food >= c.food && wool >= c.wool;
}

let _tutoPollT = 0;   // último repaso del tutorial desde el bucle principal (ver allí)
function updateTutorial() {
    _tutoApplyHighlight();
    _updateMobileTutoCrowding();
    const panel = document.getElementById('tutorialPanel');
    if (!panel) return;

    // A visited city's tutorialStep is whatever the ORIGINAL sharer's save had — showing "chop
    // 10 wood" instructions on someone else's frozen, read-only city makes no sense, and nothing
    // in it can ever be completed anyway (every action is blocked in spectator mode).
    if (_spectatorMode) { panel.style.display = 'none'; return; }

    // --- TUTORIAL DE LA FASE 2 ---
    // Va ANTES del corte de tutorialStep >= 13 porque para entonces el tutorial normal lleva
    // horas terminado y el cartel estaría oculto. Reusa el mismo panel, la misma animación de
    // cambio de paso y el mismo resaltado verde: para el jugador es el tutorial de siempre
    // volviendo con lo nuevo, no otra cosa distinta.
    if (phase2Tuto >= 1 && phase2Tuto <= 4) {
        const _d = _dryDock(), _p = _waterPort();
        // saveGame(true): un guardado normal con la nube activa se agrupa hasta 30 s, y un F5
        // dentro de esa ventana perdía el paso (y con el dique ya hecho, el tutorial entero).
        // Son cuatro guardados en toda la fase, así que forzarlos no cuesta nada.
        const _next = n => { phase2Tuto = n; playTCSound(); saveGame(true); };
        if      (phase2Tuto === 1 && _d)                     _next(2);
        else if (phase2Tuto === 2 && _p)                     _next(3);
        else if (phase2Tuto === 3 && _d && !_d._isolated)    _next(4);
        else if (phase2Tuto === 4 && _d && _d.draining)      _next(5);
        if (phase2Tuto > 4) {   // terminado: el cartel se va y no vuelve
            panel.style.display = 'none';
            _tutoDisplayed = -1; _tutoLastStepSeen = -1;
            _cgMaybeShowBanner();
            return;
        }
        panel.style.display = 'flex';
        _positionTutorialPanel();
        // 20 + paso: el mismo hueco de numeración que usa _tutoSetContent para distinguirlos de
        // los pasos 1-12 del tutorial original sin pisarlos.
        const _paso = 20 + phase2Tuto;
        if (_paso !== _tutoLastStepSeen) {
            _tutoLastStepSeen = _paso;
            if (_tutoCollapsed) _setTutorialCollapsed(false);
        }
        panel.classList.toggle('tuto-collapsed', _tutoCollapsed);
        // El menú de construcción, abierto: los dos primeros pasos resaltan un botón que vive
        // dentro, y resaltarlo con el panel plegado no lo ve nadie.
        const _body2 = document.getElementById('commandCardBody');
        if (_body2 && _body2.style.display === 'none') toggleCommandCard();
        if (_paso !== _tutoDisplayed) _tutoAnimate(panel, _paso);
        return;
    }

    if (tutorialStep >= 13) {
        panel.style.display = 'none';
        _tutoDisplayed = -1;
        _tutoLastStepSeen = -1; // reset alongside _tutoDisplayed so a fresh city starts clean
        // Tutorial finished — this is the point the bottom banner is allowed to appear. Covers
        // both cases without extra hooks: finishing it now, and booting a save that already had.
        _cgMaybeShowBanner();
        return;
    }
    panel.style.display = 'flex';
    _positionTutorialPanel();
    // "si está minimizado el tutorial pero cambio de step, este se maximice" — a new step is new
    // instructions the player hasn't read yet, so it always comes back up expanded; collapsing is
    // a per-step declutter, not a sticky preference.
    // Its own counter rather than reusing _tutoDisplayed: that one is only advanced INSIDE
    // _tutoAnimate's 220ms swap timeout, so for the whole of that window every unrelated
    // updateTutorial call (a live counter tick, a toast, a resize — it runs often) still reads as
    // "the step changed" and would re-expand a dialog the player had just collapsed. This fires
    // exactly once per distinct step, synchronously, independent of the animation.
    if (tutorialStep !== _tutoLastStepSeen) {
        _tutoLastStepSeen = tutorialStep;
        if (_tutoCollapsed) _setTutorialCollapsed(false);
    }
    panel.classList.toggle('tuto-collapsed', _tutoCollapsed);
    // The collapsed/expanded preference is global, not per-save (see _loadCommandCardCollapsed)
    // — a player who collapsed it in an earlier city could otherwise start a brand new tutorial
    // with it already hidden, with no way to see whatever step is highlighted in there short of
    // noticing the collapse arrow themselves. Same idiom _switchBuildTab uses to auto-expand.
    const _tutoBody = document.getElementById('commandCardBody');
    if (_tutoBody && _tutoBody.style.display === 'none') toggleCommandCard();

    function advance(next, msg) {
        tutorialStep = next;
        if (msg) { playTCSound(); }
        saveGame();
        updateTutorial();
        // Los botones que desbloquea el paso nuevo (Granja/Pescador en el 8, etc.) dependen de
        // tutorialStep dentro de updateUI, y avanzar no la llamaba: el catálogo seguía como en el
        // paso anterior hasta la siguiente acción — "construye tu Pescador" sin botón. En diferido
        // porque advance puede venir desde dentro del propio updateUI (vía updateTutorial).
        setTimeout(updateUI, 0);
    }

    // Old 8 steps, plus step 9 (roads) added later — players said the roads/connectivity
    // mechanic wasn't clear from step 6's description alone, so this makes placing some an
    // explicit, checked step instead of just a paragraph to read.
    if      (tutorialStep === 1 && wood >= 10)                                     advance(2, "¡Paso 1 Completado! 🎉");
    else if (tutorialStep === 2 && villagers.length >= (_world().startVillagers || 0) + 1) advance(3, "¡Paso 2 Completado! 🎉");   // el aldeano que contratas, además de los de serie
    else if (tutorialStep === 3 && villagers.length >= 5)                          advance(4, "¡Paso 3 Completado! 🎉");
    else if (tutorialStep === 4 && buildings.some(b => b.type === 'lumber_camp'))  advance(5, "¡Paso 4 Completado! 🎉");
    else if (tutorialStep === 5 && axeUpgradeLevel >= 1)                           advance(6, "¡Paso 5 Completado! 🎉");
    else if (tutorialStep === 6 && buildings.some(b => b.type === 'house'))        advance(7, "¡Paso 6 Completado! 🎉");
    else if (tutorialStep === 7 && buildings.some(b => b.type === 'mill'))         advance(8, "¡Paso 7 Completado! 🎉");
    else if (tutorialStep === 8 && buildings.some(b => b.type === ((_tutoOverride(8) || {}).building || 'farm'))) advance(9, "¡Paso 8 Completado! 🎉");
    else if (tutorialStep === 9 && buildings.filter(b => b.type === 'road').length >= 2) {
        // Reset relic countdown so player always gets "tala 5 árboles" from this point
        nextChestAt = treesChopped + 5;
        advance(10, "¡Tutorial Completado! 🎉");
    }
    // Relic phases (never reset)
    else if (tutorialStep === 10 && relicTiles.length > 0)  advance(11);
    else if (tutorialStep <= 11  && _tutoSkillPicked)        advance(12);

    // Animate sign swap only on step change
    if (tutorialStep !== _tutoDisplayed) _tutoAnimate(panel, tutorialStep);

    // Live counter updates (no animation)
    if (tutorialStep === 1) {
        const d = panel.querySelector('p');
        if (d) d.innerHTML = t('tuto.1.desc', { n: wood, res: RES.wood });
    } else if (tutorialStep === 3) {
        const d = panel.querySelector('p');
        if (d) d.innerHTML = t('tuto.3.desc', { n: villagers.length, res: `<i class="fa-solid fa-person-digging"></i>` });
    } else if (tutorialStep === 9) {
        const d = panel.querySelector('p');
        if (d) d.innerHTML = t('tuto.9.desc', { n: Math.min(2, buildings.filter(b => b.type === 'road').length) });
    } else if (tutorialStep === 10) {
        const rem = Math.max(0, nextChestAt - treesChopped);
        const d = panel.querySelector('p');
        if (d) d.innerHTML = t('tuto.10.desc', { n: rem, plural: rem === 1 ? t('tuto.10.tree') : t('tuto.10.trees') });
    }
}

function closeTutorial() {
    // El botón de cerrar sirve para los dos tutoriales; cada uno se marca como visto en su propio
    // contador. Sin este caso, cerrar durante la fase 2 habría reescrito tutorialStep y dejado el
    // cartel del dique en pantalla para siempre.
    if (phase2Tuto >= 1 && phase2Tuto <= 4) {
        phase2Tuto = 5;
        saveGame();
        updateTutorial();
        return;
    }
    tutorialStep = 13;
    saveGame();
    updateTutorial();
}
window.closeTutorial = closeTutorial;

function toggleCommandCard() {
    const body = document.getElementById('commandCardBody');
    const btn = document.getElementById('btnToggleCommandCard');
    if (!body || !btn) return;
    const collapsed = body.style.display === 'none';
    // Collapsing (not expanding — that direction is never blocked, so this can't strand anyone
    // with an un-openable panel) while the tutorial is still guiding the player through it would
    // hide whatever step is highlighted in there (see TUTORIAL_HIGHLIGHT_TARGETS) — updateTutorial
    // would just force it back open on its own next tick anyway, so blocking it outright here
    // instead of letting it flash shut-then-open reads much less like a bug.
    if (!collapsed && !_spectatorMode && tutorialStep < 13) {
        showBuildToast(t('tuto.cant_minimize'));
        return;
    }
    body.style.display = collapsed ? '' : 'none';
    // ▼ = expanded (maximized), ▲ = collapsed (minimized) — explicit user convention.
    // Must match _loadCommandCardCollapsed()'s convention below.
    btn.textContent = collapsed ? '▼' : '▲';
    localStorage.setItem('fn_commandCardCollapsed', collapsed ? '0' : '1');
    _updateDecoCatBar();
    // No resizeCanvas() needed here anymore — the canvas is always full-viewport regardless of
    // #commandCard's own height now (see resizeCanvas's own comment), so collapsing/expanding the
    // build bar has nothing left for it to react to.
}
window.toggleCommandCard = toggleCommandCard;

// Construcciones / Cosméticos tabs atop the build bar (see #buildTabBar) — swaps which of
// #buildingsGrid/#decorationsGrid is showing and which tab reads active.
let _activeBuildTab = 'build'; // read by _updateDecoCoinUI to decide whether the coin balance shows
// Categorías de decoración. 'all' enseña todo y 'floors' son los suelos y la Plaza Discord. Una decoración nueva que no se
// añada a ninguna lista solo saldría en 'all'. El botón del anuncio no se filtra: se ve siempre.
const DECO_CATS = {
    nature: ['deco_flor_amarilla', 'deco_flor_blanca', 'deco_lavanda', 'deco_amapolas', 'deco_margaritas', 'deco_nomeolvides', 'deco_flor_rosa', 'deco_calendulas', 'deco_violetas', 'deco_tulipanes', 'deco_dientes_leon', 'deco_cardos', 'deco_lirios', 'deco_campanillas', 'deco_trebol', 'deco_helecho', 'deco_espadanas', 'deco_rosal', 'deco_bayas', 'deco_arbusto', 'deco_arbolito', 'deco_setas', 'deco_mojon', 'deco_estanque'],
    field: ['deco_carretilla', 'deco_sacos', 'deco_heno', 'deco_espantapajaros', 'deco_aguaypala', 'deco_tend_cuero', 'deco_tocon', 'deco_lena', 'deco_lena2', 'deco_lena3', 'deco_cesta', 'deco_cesta_naranjas', 'deco_cesta_limones', 'deco_cesta_ciruelas', 'deco_cesta_tomates', 'deco_cesta_patatas', 'deco_cesta_cerezas', 'deco_cesta_fresas', 'deco_cesta_uvas', 'deco_cesta_uvas_blancas', 'deco_cesta_lechugas', 'deco_cesta_coles', 'deco_cesta_zanahorias', 'deco_cesta_maiz', 'deco_cesta_pan', 'deco_cesta_pescado', 'deco_cesta_setas', 'deco_cesta_huevos', 'deco_cesta_trigo', 'deco_calabazas', 'deco_colmena', 'deco_estafermo', 'deco_estafermo2'],
    town: ['deco_bandera', 'deco_yunque', 'deco_anfora', 'deco_maceta', 'deco_mesa_piedra', 'deco_mesa_piedra_platos', 'deco_mesa_redonda', 'deco_mesa_redonda_piedra', 'deco_mesa_redonda_grande', 'deco_cartel', 'deco_barril', 'deco_banco', 'deco_mesapicnic', 'deco_mesapicnic2', 'deco_columna', 'deco_fuente', 'deco_tumba', 'deco_cruz', 'deco_tumba_cruz', 'deco_ancla', 'deco_nasa', 'deco_tenderete', 'deco_tend_sabanas'],   // con lo que eran Cementerio y Costa, y los tendederos de ropa y sábanas
    ruins: ['deco_columna', 'deco_columna_rota', 'deco_columna_tocon', 'deco_columna_alta', 'deco_columna_musgo', 'deco_portico', 'deco_muro_ruina', 'deco_muro_bajo', 'deco_muro_hiedra', 'deco_muro_v', 'deco_muro_v_hiedra', 'deco_muro_v_corto', 'deco_muro_ventana', 'deco_altar', 'tile_ruina', 'tile_ruina_hiedra', 'tile_piedras', 'tile_piedras_hiedra'],
    fences: ['deco_bandera'],   // los demás botones son los de FENCE_STYLES (ver _applyDecoCat); la bandera va junto a las guirnaldas, que comparten colores
    lights: ['deco_bandera', 'deco_fogata', 'deco_brasero', 'deco_antorcha', 'deco_farola', 'deco_farol', 'deco_vela', 'deco_vela_pocas', 'deco_farolillo_rojo', 'deco_farolillo_azul', 'deco_farolillo_verde', 'deco_guirnalda', 'deco_xhoguera'],
    xmas: ['deco_bandera', 'deco_guirnalda', 'deco_xhoguera', 'deco_xarbol', 'deco_xmunieco', 'deco_xregalos', 'deco_xbaston', 'deco_xcorona', 'deco_xreno', 'deco_xabeto', 'deco_xarbol_grande'],
};
// Lo navideño que no son objetos: sale también en la pestaña Navidad, además de en Suelos y Vallas
const DECO_XMAS_FLOORS = new Set(['tile_nieve', 'tile_hielo', 'tile_alfombra_x', 'tile_alfombra_copos', 'tile_alfombra_caramelo', 'tile_alfombra_abetos']);
const DECO_XMAS_FENCES = new Set(['candy', 'gate_candy', 'arch_candy']);
let _decoCat = 'all';
try { _decoCat = localStorage.getItem('fn_decoCat') || 'all'; } catch (e) {}
// Costa solo tiene decoraciones del Mundo 2: en los demás sobra su pestaña
function _decoCatAvailable(cat) {
    if (cat === 'all' || cat === 'floors' || cat === 'favs') return true;
    if (!DECO_CATS[cat]) return false;
    return true;
}
// En la rejilla los botones no llevan el nombre a la vista: sale como tooltip al pasar por encima, leído del propio botón (así va en el
// idioma que toque). Los de vallas y guirnaldas ya tienen su ficha flotante con el nombre (_showBuildInfo).
document.getElementById('decorationsGrid')?.addEventListener('mouseover', e => {
    const b = e.target.closest('.command-btn');
    if (!b || b.id === 'btnDecoAd' || b.id === 'btnDecoShop' || b.hasAttribute('onmouseenter')) return;
    const l = b.querySelector('.btn-label');
    if (l) b.title = l.textContent.trim();
});
// --- Favoritas ---
// Son de la cuenta, no de la partida (van con _fnStorage, así que en CrazyGames viajan en la nube) y sirven en los dos mundos.
// La clave de cada botón es su id. La estrella va AL LADO del botón, dentro de un envoltorio, y no dentro: un botón sin monedas
// está "disabled" y el navegador no le pasa los clics a lo que lleva dentro, y una favorita se tiene que poder marcar igual.
const DECO_FAVS_KEY = 'fn_deco_favs';
function _decoFavs() {
    try { const a = JSON.parse(_fnStorageGet(DECO_FAVS_KEY) || '[]'); return new Set(Array.isArray(a) ? a : []); } catch (e) { return new Set(); }
}
function _toggleDecoFav(id) {
    const favs = _decoFavs();
    if (favs.has(id)) favs.delete(id); else favs.add(id);
    _fnStorageSet(DECO_FAVS_KEY, JSON.stringify([...favs]));
    _applyDecoCat();
}
function _decoFavButtons() {
    return [...DECO_TYPES.map(k => 'btnDeco_' + k), ...GROUND_DECO_TYPES.map(k => 'btnGroundDeco_' + k), ...Object.keys(FENCE_STYLES).map(k => 'btnFence_' + k)]
        .map(id => document.getElementById(id)).filter(Boolean);
}
function _initDecoFavStars() {
    for (const btn of _decoFavButtons()) {
        if (btn.parentElement.classList.contains('deco-btn-wrap')) continue;
        const wrap = document.createElement('div');
        wrap.className = 'deco-btn-wrap';
        btn.parentElement.insertBefore(wrap, btn);
        wrap.appendChild(btn);
        const star = document.createElement('button');
        star.type = 'button';
        star.className = 'deco-fav';
        star.id = 'decoFav_' + btn.id;
        star.dataset.tTitle = 'deco.fav.toggle';
        star.title = t('deco.fav.toggle');
        star.setAttribute('aria-label', t('deco.fav.toggle'));
        star.innerHTML = '<i class="fa-solid fa-star"></i>';
        star.addEventListener('click', e => { e.stopPropagation(); _toggleDecoFav(btn.id); });
        wrap.appendChild(star);
    }
    const grid = document.getElementById('decorationsGrid');
    if (grid && !document.getElementById('decoFavEmpty')) {
        const msg = document.createElement('div');
        msg.id = 'decoFavEmpty';
        msg.className = 'deco-fav-empty deco-cat-hidden';
        msg.dataset.t = 'deco.fav.empty';
        msg.textContent = t('deco.fav.empty');
        grid.insertBefore(msg, grid.firstChild);
    }
}
function _applyDecoFavs(favs) {
    let shown = 0;
    for (const btn of _decoFavButtons()) {
        const on = favs.has(btn.id), star = document.getElementById('decoFav_' + btn.id);
        if (star) { star.classList.toggle('is-fav', on); star.setAttribute('aria-pressed', on); }
        if (on && !(DECO_WORLD_ONLY[btn.id.slice('btnDeco_'.length)] && DECO_WORLD_ONLY[btn.id.slice('btnDeco_'.length)] !== _world().id)) shown++;
    }
    const msg = document.getElementById('decoFavEmpty');
    if (msg) msg.classList.toggle('deco-cat-hidden', _decoCat !== 'favs' || shown > 0);
}
function _applyDecoCat() {
    if (!_decoCatAvailable(_decoCat)) _decoCat = 'all';
    _initDecoFavStars();
    const favs = _decoFavs(), showFavs = _decoCat === 'favs';
    const showAll = _decoCat === 'all', showFloors = showAll || _decoCat === 'floors';
    const wanted = new Set(DECO_CATS[_decoCat] || []);
    for (const type of DECO_TYPES) {
        const btn = document.getElementById('btnDeco_' + type);
        if (btn) btn.classList.toggle('deco-cat-hidden', !showAll && !wanted.has(type) && !(showFavs && favs.has(btn.id)));
    }
    for (const type of GROUND_DECO_TYPES) {
        const btn = document.getElementById('btnGroundDeco_' + type);
        if (btn) btn.classList.toggle('deco-cat-hidden', !showFloors && !wanted.has(type) && !(_decoCat === 'xmas' && DECO_XMAS_FLOORS.has(type)) && !(showFavs && favs.has(btn.id)));
    }
    const plaza = document.getElementById('btnPlazaDiscord');
    if (plaza) plaza.classList.toggle('deco-cat-hidden', !showFloors);
    for (const st of Object.keys(FENCE_STYLES)) {
        const btn = document.getElementById('btnFence_' + st);
        if (btn) btn.classList.toggle('deco-cat-hidden', !showAll && _decoCat !== 'fences' && !(_decoCat === 'xmas' && DECO_XMAS_FENCES.has(st)) && !(FENCE_STYLES[st].high && (_decoCat === 'lights' || _decoCat === 'xmas')) && !(showFavs && favs.has(btn.id)));
    }
    document.querySelectorAll('#decorationsGrid .deco-section-label:not(.deco-fence-label)').forEach(l => l.classList.toggle('deco-cat-hidden', !showFloors));
    document.querySelectorAll('#decorationsGrid .deco-fence-label').forEach(l => l.classList.toggle('deco-cat-hidden', !showAll && _decoCat !== 'fences' && !(_decoCat === 'xmas' && l.dataset.t === 'deco.fencegrp.candy') && !(l.dataset.garland && (_decoCat === 'lights' || _decoCat === 'xmas')) && !(l.dataset.colors && _decoCat === 'town')));
    _applyDecoFavs(favs);
    document.querySelectorAll('.deco-cat-btn').forEach(tab => {
        const cat = tab.id.slice('decoCat_'.length);
        tab.classList.toggle('active', cat === _decoCat);
        tab.style.display = _decoCatAvailable(cat) ? '' : 'none';
    });
    // Cuántas pestañas se ven: el CSS da al panel la altura para todas (ver #commandCard en index.css)
    const _cc = document.getElementById('commandCard');
    if (_cc) _cc.style.setProperty('--deco-cats', [...document.querySelectorAll('.deco-cat-btn')].filter(b => b.style.display !== 'none').length);
}
function _setDecoCat(cat) {
    _decoCat = cat;
    try { localStorage.setItem('fn_decoCat', cat); } catch (e) {}
    _applyDecoCat();
    const body = document.getElementById('commandCardBody');
    if (body) body.scrollTop = 0;   // la lista cambia de largo: que no se quede a media altura
}
window._setDecoCat = _setDecoCat;
// Las pestañas se ven solo con Decoración abierta y el panel desplegado; plegado, quedarían colgando junto a la barra de título
function _updateDecoCatBar() {
    const bar = document.getElementById('decoCatBar'), body = document.getElementById('commandCardBody');
    if (!bar || !body) return;
    bar.style.display = (_decoTabRevealed && _activeBuildTab === 'deco' && body.style.display !== 'none') ? 'flex' : 'none';
}
function _switchBuildTab(tab) {
    const buildBtn  = document.getElementById('buildTabBtnBuild');
    const decoBtn   = document.getElementById('buildTabBtnDeco');
    const buildGrid = document.getElementById('buildingsGrid');
    const decoGrid  = document.getElementById('decorationsGrid');
    const weatherBtn  = document.getElementById('buildTabBtnWeather');
    const weatherGrid = document.getElementById('weatherGrid');
    const title     = document.getElementById('buildPanelTitle');
    if (!buildBtn || !decoBtn || !buildGrid || !decoGrid) return;
    const showDeco = tab === 'deco', showWeather = tab === 'weather';
    _activeBuildTab = tab;
    if (weatherBtn) weatherBtn.classList.toggle('active', showWeather);
    if (weatherGrid) weatherGrid.style.display = showWeather ? '' : 'none';
    if (!showWeather) _wxPreview = null;
    document.body.classList.toggle('wx-tab', showWeather);
    if (showWeather) _renderWeatherGrid();
    buildBtn.classList.toggle('active', !showDeco && !showWeather);
    decoBtn.classList.toggle('active', showDeco);
    buildGrid.style.display = (showDeco || showWeather) ? 'none' : '';
    decoGrid.style.display  = showDeco ? '' : 'none';
    // Icon-only tabs (see .build-tab-btn) — the panel's own title is the only text saying which
    // one is actually open, so it has to track the switch instead of staying a static label.
    if (title) title.textContent = t(showWeather ? 'panel.weather' : showDeco ? 'panel.decorations' : 'panel.buildings');
    // Switching tabs mid-placement would leave buildMode pointing at a button that isn't even
    // showing anymore — cancel cleanly instead of leaving that dangling.
    if (buildMode !== null) { buildMode = null; updateUI(); }
    _updateDecoCoinUI();
    // The tab flaps sit above #commandCard's own box (see .build-tab-bar), so they're still
    // tappable even while the panel is collapsed — but the switch itself was invisible from
    // there (body stays display:none), reading as an unresponsive tap. Auto-expanding gives
    // it the same immediate feedback tapping the collapse arrow itself would.
    const body = document.getElementById('commandCardBody');
    // "en decoración que sea el mismo alto que el build pero sus botones serán más pequeños,
    // caben 5 por fila" — #commandCardBody is shared by both tabs (see its own CSS), so its
    // grid-template-columns/button sizing has to switch based on which one is actually showing —
    // this class is that hook (see index.css's own #commandCardBody.deco-tab-active rules).
    if (body) body.classList.toggle('deco-tab-active', showDeco);
    if (body && body.style.display === 'none') toggleCommandCard();
    if (showDeco) _applyDecoCat();
    _updateDecoCatBar();
}
window._switchBuildTab = _switchBuildTab;

// Tab bar (not just the Cosméticos button) hidden until the first coin is ever earned (see
// _decoTabRevealed) — with only one real tab, showing a tab row at all just repeats the panel's
// own title for nothing. The coin balance itself only ever shows while that tab is the one
// actually open — it's meaningless anywhere else.

// --- FASE 2: visibilidad y estado de sus cuatro botones ---
// Encadenados a propósito: cada uno solo aparece cuando el anterior ya no tiene sentido, así que
// el menú nunca muestra dos pasos de la misma cadena a la vez y el jugador siempre ve UNA cosa
// que hacer. Sin esto, la fase 2 serían cuatro botones grises simultáneos sin explicar el orden.
function _updatePhase2UI() {
    const dock = _dryDock();
    const dry = _dryDockIsDry(dock);
    const ready = _shipIsReady(dock);
    const sailed = !!(dock && dock.sailed);

    // Puerta a la Fase 2: SOLO Legado 8 (prestige.phase2Unlocked — ver PRESTIGE_MILESTONES), sin
    // exigir el bosque talado. Así el dique está disponible desde el minuto uno de cualquier
    // partida que ya tenga el Legado — nada que esperar horas para poder tocar, y la propia
    // partida en la que se reclama el Legado 8 puede aprovecharlo de inmediato, no la siguiente.
    // Sin Legado 8, no se muestra ningún botón aquí — la ficha del árbol de habilidades ya
    // explica que reclamar el Legado reinicia la partida (ver _stkAppendLegacyHeader).
    const bBuild = document.getElementById('btnBuildDryDock');
    if (bBuild) {
        bBuild.style.display = (prestige.phase2Unlocked && !dock) ? 'flex' : 'none';
        if (prestige.phase2Unlocked && !dock) {
            const c = getDryDockCost();
            const lbl = document.getElementById('dryDockCostLabel');
            if (lbl) lbl.innerHTML = renderCostHTML(c);
            bBuild.disabled = stone < c.stone || gold < c.gold;
        }
    }

    // El puerto aparece en cuanto existe el dique y desaparece al construirlo: es el paso 2 de
    // la cadena, entre "construir el dique" y "mejorar los cubos".
    const bPort = document.getElementById('btnBuildPort');
    if (bPort) {
        const show = !!dock && !_waterPort() && !dry;
        bPort.style.display = show ? 'flex' : 'none';
        if (show) {
            const c = getPortCost();
            const lbl = document.getElementById('portCostLabel');
            if (lbl) lbl.innerHTML = renderCostHTML(c);
            bPort.disabled = wood < c.wood;
        }
    }

    // "Vaciar dique": solo con el dique seleccionado y mientras quede agua sin empezar.
    // Desaparece en cuanto arranca — a partir de ahí lo que informa es la propia ficha.
    const bDrain = document.getElementById('btnStartDraining');
    if (bDrain) {
        // El !dock.flooding importa: durante la salida el dique vuelve a tener agua y draining
        // está apagado, o sea que sin esto reaparecería "Vaciar dique" justo mientras el barco
        // está flotando — invitando a mandar aldeanos a achicar el mar por el que acaba de salir.
        const show = !!dock && !dry && !dock.draining && !dock.flooding &&
                     !!selectedBuilding && selectedBuilding.type === 'dry_dock';
        bDrain.style.display = show ? 'flex' : 'none';
        if (show) {
            const info = document.getElementById('startDrainInfo');
            // Se deja PULSABLE aunque falte el camino o el puerto: pulsarlo es lo que hace que el
            // juego diga qué falta (ver startDraining). Un botón gris no explica nada.
            const falta = dock._isolated ? t('phase2.needs_road_short')
                        : !_waterPort()  ? t('phase2.needs_port_short') : '';
            if (info) info.innerHTML = falta ? `<span style="color:#c86a6a">${falta}</span>` : '';
        }
    }

    const wRow = document.getElementById('dockWorkersRow');
    if (wRow) {
        const show = !!dock && !dry && !dock.flooding && !!selectedBuilding && selectedBuilding.type === 'dry_dock';
        wRow.style.display = show ? 'flex' : 'none';
        if (show) {
            const cap = _dryDockWorkerCap(dock), cur = _dryDockWorkers(dock);
            _setStepperLabel(document.getElementById('dockWorkersLabel'), 'fa-bucket', t('phase2.workers'), cur, cap);
            const bm = document.getElementById('btnDockWorkersMinus'), bp = document.getElementById('btnDockWorkersPlus');
            if (bm) bm.disabled = cap <= DRYDOCK_WORKERS_MIN;
            if (bp) bp.disabled = cap >= DRYDOCK_WORKERS_MAX;
        }
    }
    const mRow = document.getElementById('dockMulesRow');
    if (mRow) {
        const show = !!dock && !dry && !dock.flooding && !!selectedBuilding && selectedBuilding.type === 'dry_dock';
        mRow.style.display = show ? 'flex' : 'none';
        if (show) {
            const cap = _dockMuleCap(dock), cur = _dockMules(dock);
            _setStepperLabel(document.getElementById('dockMulesLabel'), 'fa-horse', t('phase2.mules'), cur, cap);
            const bm = document.getElementById('btnDockMulesMinus'), bp = document.getElementById('btnDockMulesPlus');
            if (bm) bm.disabled = cap <= 0;
            if (bp) bp.disabled = cap >= DOCK_MULE_CAP_MAX;
        }
    }
    const sRow = document.getElementById('shipWorkersRow');
    if (sRow) {
        const show = !!dock && dry && !ready && !sailed && !!selectedBuilding && selectedBuilding.type === 'dry_dock';
        sRow.style.display = show ? 'flex' : 'none';
        if (show) {
            const cap = _shipWorkerCap(dock), cur = villagers.filter(v => v.farmTarget === dock && _isShipWorker(v)).length;
            _setStepperLabel(document.getElementById('shipWorkersLabel'), 'fa-hammer', t('phase2.ship_workers'), cur, cap);
            const bm = document.getElementById('btnShipWorkersMinus'), bp = document.getElementById('btnShipWorkersPlus');
            if (bm) bm.disabled = cap <= DRYDOCK_WORKERS_MIN;
            if (bp) bp.disabled = cap >= DRYDOCK_WORKERS_MAX;
        }
    }
    const smRow = document.getElementById('shipMulesRow');
    if (smRow) {
        const show = !!dock && dry && !ready && !sailed && !!selectedBuilding && selectedBuilding.type === 'dry_dock';
        smRow.style.display = show ? 'flex' : 'none';
        if (show) {
            const cap = _shipMuleCap(dock), cur = _shipMules(dock);
            _setStepperLabel(document.getElementById('shipMulesLabel'), 'fa-horse', t('phase2.mules'), cur, cap);
            const bm = document.getElementById('btnShipMulesMinus'), bp = document.getElementById('btnShipMulesPlus');
            if (bm) bm.disabled = cap <= 0;
            if (bp) bp.disabled = cap >= DOCK_MULE_CAP_MAX;
        }
    }
    const bShip = document.getElementById('btnBuildShipStage');
    if (bShip) {
        const show = !!dock && dry && !ready && !sailed &&
                     !!selectedBuilding && selectedBuilding.type === 'dry_dock';
        bShip.style.display = show ? 'flex' : 'none';
        if (show) {
            const idx = _shipStageIndex(dock);
            const cost = SHIP_STAGES[idx].cost;
            const lbl = document.getElementById('shipStageLabel');
            const cst = document.getElementById('shipStageCost');
            const nombre = t('phase2.stage.' + SHIP_STAGES[idx].key);
            if (!_shipStarted(dock)) {
                // Iniciar la fase cuesta SOLO los planos, en oro (SHIP_STAGES.plans). El material
                // se descuenta viaje a viaje, así que se enseña aparte, como lo que es —lo que va a
                // hacer falta en total—, no como un precio a pagar ya. El botón se agrisa solo por
                // el oro de los planos, nunca por el material.
                const plans = _shipPlansCost(dock);
                bShip.disabled = gold < plans;
                if (lbl) lbl.textContent = t('phase2.start', { n: idx + 1, total: SHIP_STAGES.length, name: nombre });
                // Cada etiqueta en su línea y su coste debajo: en una sola fila "Material (se lleva
                // por viajes): 50M" se salía del botón (.btn-cost va en nowrap).
                if (cst) cst.innerHTML =
                    `<div style="white-space:normal">${t('phase2.plans')}:</div>` +
                    `<div>${renderCostHTML({ gold: plans })}</div>` +
                    `<div style="white-space:normal;opacity:.8;font-size:11px;margin-top:4px">${t('phase2.material')}:</div>` +
                    `<div style="opacity:.8">${renderCostHTML(cost)}</div>`;
            } else {
                // En obra: ya no se pulsa, solo informa. Se desglosa POR MATERIAL porque el casco
                // III pide dos cosas y un total sumado no dice cuál de las dos va atrasada.
                bShip.disabled = true;
                if (lbl) lbl.textContent = t('phase2.building', { n: idx + 1, total: SHIP_STAGES.length, name: nombre });
                const hecho = _shipDone(dock);
                // El PORCENTAJE en grande y solo, y debajo una fila por material.
                //
                // Antes iba todo seguido en una línea de 11px, y era la información que el jugador
                // mira cada pocos minutos durante horas: quería leerse de un vistazo, sin buscar.
                // Y en el casco III, con dos materiales, la línea se salía del botón.
                //
                // Dos decimales: con miles de viajes por fase, un entero se queda clavado en el
                // mismo número durante minutos y parece que no avanza.
                const filas = Object.keys(cost).map(r =>
                    `<div style="display:flex;justify-content:space-between;gap:10px;white-space:nowrap">` +
                        `<span>${RES[r]}</span>` +
                        `<span>${formatCompact(hecho[r] || 0)} / ${formatCompact(cost[r])}</span>` +
                    `</div>`).join('');
                if (cst) cst.innerHTML =
                    `<div style="font-size:22px;font-weight:700;line-height:1.15;color:#7dbe6a">` +
                        `${(_shipWorkFrac(dock) * 100).toFixed(2)}%</div>` +
                    `<div style="color:#e8d5a0;margin-top:3px">${filas}</div>`;
            }
        }
    }

    // Pausar/reanudar la obra. Solo con una fase ya iniciada: sin obra en marcha no hay nada que
    // pausar, y el botón suelto solo confundiría.
    const bPause = document.getElementById('btnPauseShip');
    if (bPause) {
        const show = !!dock && dry && !ready && !sailed && _shipStarted(dock) &&
                     !!selectedBuilding && selectedBuilding.type === 'dry_dock';
        bPause.style.display = show ? 'flex' : 'none';
        if (show) {
            // El botón refleja SOLO la pausa manual: es lo único que él controla. Si la obra está
            // parada por falta de camino, el botón sigue diciendo "Pausar" y quien lo explica es
            // la línea de estado del panel — pulsarlo ahí serviría igualmente para que no se
            // reanude sola al reconectar.
            const pausado = !!dock.shipPaused;
            const lbl = document.getElementById('shipPauseLabel');
            if (lbl) lbl.textContent = t(pausado ? 'phase2.resume' : 'phase2.pause');
            const ic = bPause.querySelector('.btn-icon i');
            if (ic) ic.className = pausado ? 'fa-solid fa-play' : 'fa-solid fa-pause';
            bPause.style.background = pausado ? '#3a2a12' : '';
            bPause.style.borderColor = pausado ? '#8a6a2a' : '';
        }
    }

    const bLaunch = document.getElementById('btnLaunchExpedition');
    if (bLaunch) {
        // Una vez abierto el dique el botón desaparece: a partir de ahí no hay nada que pulsar,
        // solo que mirar. Es la única parte de la fase 2 que se juega sola, a propósito.
        const show = !!dock && ready && !sailed && !dock.flooding &&
                     !!selectedBuilding && selectedBuilding.type === 'dry_dock';
        bLaunch.style.display = show ? 'flex' : 'none';
        if (show) {
            const lbl = document.getElementById('launchLabel');
            const cst = document.getElementById('launchCost');
            // Tres momentos del mismo botón: Embarcar (cuenta 148/200), Embarcando (a bordo X/200,
            // sin pulsar) y Zarpar (todos en cubierta).
            if (dock.aboard) {
                if (lbl) lbl.textContent = t('phase2.sail');
                if (cst) cst.innerHTML = `<i class="fa-solid fa-people-group"></i> ${EXPEDITION_VILLAGERS} / ${EXPEDITION_VILLAGERS}`;
                bLaunch.disabled = false;
            } else if (dock.boarding) {
                const aBordo = villagers.filter(v => v.state === 'aboard' && v.farmTarget === dock).length;
                if (lbl) lbl.textContent = t('phase2.boarding_progress');
                if (cst) cst.innerHTML = `<i class="fa-solid fa-people-group"></i> ${aBordo} / ${EXPEDITION_VILLAGERS}`;
                bLaunch.disabled = true;
            } else {
                if (lbl) lbl.textContent = t('phase2.open_dock');
                // Cuenta de aldeanos en vez de un coste: es el único "precio" que tiene zarpar, y
                // verlo como 148/200 dice a la vez qué falta y cuánto.
                if (cst) cst.innerHTML = `<i class="fa-solid fa-people-group"></i> ${villagers.length} / ${EXPEDITION_VILLAGERS}`;
                bLaunch.disabled = villagers.length < EXPEDITION_VILLAGERS;
            }
        }
    }
}
function _updateDecoCoinUI() {
    const tabBar = document.getElementById('buildTabBar');
    if (tabBar) tabBar.style.display = _decoTabRevealed ? 'flex' : 'none';
    const coinDisplay = document.getElementById('decoCoinDisplay');
    const coinValue = document.getElementById('decoCoinValue');
    if (coinValue) coinValue.textContent = _decoInfPinned ? '∞' : formatNumber(decoCoins);
    if (coinDisplay) coinDisplay.style.display = (_decoTabRevealed && (_activeBuildTab === 'deco' || _activeBuildTab === 'weather')) ? 'flex' : 'none';
    _updateEraseOpts();
    _updateDecoCatBar();
    // Grayed out (same .command-btn:disabled treatment every resource-cost building button
    // already gets) once decoCoins can't cover that button's own price — ids are 'btnDeco_' +
    // the type string for object decorations, 'btnGroundDeco_' + type for the ground one(s).
    for (const type of DECO_TYPES) {
        const btn = document.getElementById('btnDeco_' + type);
        if (btn) {
            btn.disabled = decoCoins < (DECO_COSTS[type] || 0);
            if (DECO_WORLD_ONLY[type]) btn.style.display = DECO_WORLD_ONLY[type] === _world().id ? 'flex' : 'none';
        }
    }
    for (const type of GROUND_DECO_TYPES) {
        const btn = document.getElementById('btnGroundDeco_' + type);
        if (btn) btn.disabled = decoCoins < (GROUND_DECO_COSTS[type] || 0);
    }
    for (const st of Object.keys(FENCE_STYLES)) {
        const btn = document.getElementById('btnFence_' + st);
        if (btn) btn.disabled = decoCoins < FENCE_STYLES[st].cost;
    }
    // Plaza Discord: siempre visible (es la propia promoción — ver startBuildPlazaDiscord, que
    // abre el modal de canjeo si aún no hay código), salvo que ya haya una colocada en la ciudad
    // (solo puede haber una a la vez, ver _hasPlazaDiscordBuilt).
    const btnPlazaDiscord = document.getElementById('btnPlazaDiscord');
    if (btnPlazaDiscord) btnPlazaDiscord.style.display = _hasPlazaDiscordBuilt() ? 'none' : 'flex';
    // Watch-an-ad button (see DECO_AD_COOLDOWN_MS/watchAdForDecoCoins) — never gated on decoCoins
    // itself, only on its own cooldown/in-flight state, so it stays its own loop instead of
    // joining the affordability one above.
    const shopBtn = document.getElementById('btnDecoShop');   // la tienda, al lado del anuncio
    if (shopBtn) shopBtn.style.display = _shopVisible() ? 'flex' : 'none';
    const adBtn = document.getElementById('btnDecoAd');
    if (adBtn && _noAdsMode) adBtn.style.display = 'none';   // sin anuncios no hay monedas por vídeo
    if (adBtn && !_noAdsMode) {
        const remaining = _decoAdCooldownRemainingMs();
        adBtn.disabled = remaining > 0 || _decoAdWatching;
        // El "+N" de la derecha, que estaba escrito a mano en el HTML y por tanto se quedaba
        // clavado en +5 mientras la escalera subía. Se actualiza aquí, junto a la etiqueta, para
        // que las dos cifras del botón salgan siempre del mismo sitio y no puedan discrepar.
        const rew = document.getElementById('decoAdReward');
        if (rew) rew.innerHTML = `<i class="fa-solid fa-gem" style="color:#6fd8f2;"></i> +${_decoAdReward()}`;
        const lbl = document.getElementById('decoAdLabel');
        // La etiqueta solo dice qué hace el botón; la cifra vive en el precio de la derecha,
        // como en todos los demás. Tenerla en los dos sitios era repetirla.
        if (lbl) lbl.textContent = remaining > 0 ? _fmtCooldown(remaining) : t('decoad.watch');
    }
}

