    roads:   { k: 3, list: ['roads/road_rd_piedra', 'roads/road_rd_ladrillo', 'roads/road_rd_madera', 'roads/road_rd_musgo', 'roads/road_rd_terracota', 'roads/road_rd_pizarra'] },
