    if (!tabs.some(tb => tb.id === _howtoTab)) _howtoTab = tabs[0].id;
    tabsEl.innerHTML = tabs.map(tb => '<button class="howto-tab' + (tb.id === _howtoTab ? ' active' : '') + '" onclick="_howtoSetTab(\'' + tb.id + '\')"><i class="fa-solid ' + tb.icon + '"></i> <span>' + t('howto2.tab.' + tb.id) + '</span></button>').join('');
    const tab = tabs.find(tb => tb.id === _howtoTab);
    body.innerHTML = tab.items
        .filter(it => (!it.w || it.w === wid) && !(it.desktop && mobile) && !(it.mobile && !mobile) && (!it.cond || it.cond()))
        .map(it => it.block ? HOWTO_BLOCKS[it.block]() : it.fig ? _howtoFigHTML(it) :
            '<div class="controls-row">' + (it.k ? '<span class="key">' + t(it.k) + '</span>' : '<i class="fa-solid ' + it.i + ' howto-icon"></i>') +
            '<div class="controls-row-text"><div class="controls-row-title">' + t(it.t) + '</div><div class="controls-row-desc">' + t(it.d) + '</div>' + (it.pics ? _howtoPicsHTML(it.pics) : '') + '</div></div>')
        .join('');
