// --- VILLAGER GAME LOGIC & ENTITY ---

// Shared cost table — Wood uses offset 0, Food offset +1, Wool offset +2
const VILLAGER_COST_TABLE = [
    10, 20, 40, 80, 140, 350, 600, 1000, 1500, 2000,
    2500, 3000, 4000, 5000, 7000, 9000, 13000, 17000, 25000, 33000,
    49000, 65000, 97000, 130000, 195000, 260000,
];

function _villagerCostAt(i) {
    if (i < VILLAGER_COST_TABLE.length) return VILLAGER_COST_TABLE[i];
    return Math.round(VILLAGER_COST_TABLE[VILLAGER_COST_TABLE.length - 1] * Math.pow(1.5, i - (VILLAGER_COST_TABLE.length - 1)));
}

function _villagerDiscount() {
    // Multiplicativo (0.985^nivel) — ver el comentario de aldeanoDescuentoLevel: "1 - nivel*0.02"
    // llegaba a 0 (aldeanos gratis para siempre) en el nivel 50.
    let d = Math.pow(0.985, aldeanoDescuentoLevel) * (prestige.villCheaper ? 0.5 : 1) * (prestige.villCheaper25 ? 0.75 : 1);   // 25%: Riberas Anchas (mundo 2)
    // "precio de los aldeanos la mitad" — único de Tala Rápido (ver RETO_TYPES.tala.halfVillagerCost).
    if (_retoActive && RETO_TYPES[_retoType]?.halfVillagerCost) d *= 0.5;
    return d;
}
function getVillagerWoodCost() { return Math.max(1, Math.round(_villagerCostAt(purchasedVillagersWood) * _villagerDiscount())); }
function getVillagerFoodCost() { return Math.max(1, Math.round(_villagerCostAt(purchasedVillagersFood + 1) * _villagerDiscount())); }
function getVillagerWoolCost() { return Math.max(1, Math.round(_villagerCostAt(purchasedVillagersWool + 2) * _villagerDiscount())); }

// --- MULE (RUTA COMERCIAL) RECRUITING ---
// Mule cost reuses the exact same escalating villager cost table, offset so the first mule
// costs what the 15th wood villager, 10th food villager and 5th wool villager would — each
// subsequent mule shifts every index by +1, same escalation shape as purchasedVillagersX.
// Every mule costs gold from the very first one — starting at 50 (the table's own base, idx 0,
// ×5) and escalating the same relative shape as _villagerCostAt from there.
let mulesRecruited = 0;
// Establo: cuánto ha producido la red de establos esta partida (encarece el siguiente, ver la
// tabla 10/15/20/25... min en el bucle de update), y cuánto lleva acumulado el contador
// COMPARTIDO por todos los establos a la vez hacia la siguiente mula gratis.
let _establoFreeMulesGenerated = 0;
let _establoTimer = 0;
// Logro "Adopta, No Compres": solo cuenta las mulas COMPRADAS de verdad (recruitMule) esta
// partida — las nacidas gratis en un establo no suman aquí, ver su propio mules.push más abajo.
let _runMulesPurchased = 0;
// "la cría de mula incrementa el precio de las mulas y no debería" — bug real: mulesRecruited
// sube TANTO al comprar una mula (recruitMule) como al nacer gratis en un establo (ver su propio
// mulesRecruited++ más abajo), así que cada nacimiento gratis encarecía la SIGUIENTE compra sin
// que el jugador hubiera comprado nada. mulesRecruited - _establoFreeMulesGenerated es el mismo
// "compradas de verdad" que ya usan el logro "Adopta, No Compres" y el panel de Estadísticas —
// aquí hacía falta la misma resta para que solo lo comprado encarezca lo comprado.
// Y lo mismo con las almas — "no debería subir el precio de las mulas compradas por comprar una
// con almas": recruitMule con paidWith='souls' también pasa por _finishRecruitMule (mulesRecruited++),
// así que cada mula por almas encarecía la siguiente de recursos. Las almas tienen precio fijo
// (SOULS_COST), igual que los aldeanos por almas, que tampoco tocan las curvas de madera/comida/lana.
// Mulas compradas con RECURSOS esta partida: las únicas que mueven la curva de precios.
function _mulesBoughtWithResources() { return mulesRecruited - _establoFreeMulesGenerated - _runMulesSouls; }
// BARCAS (mundos con puerto, ver _harborsOn): no siguen la tabla de aldeanos con su ×1,5 fijo, que a la barca 50 pide
// billones. El factor de cada barca arranca en ×1,4 y baja 0,01 por barca hasta un mínimo de ×1,045 (un 4,5% más cara que la
// anterior): precio(n) = precio(1) × Π(k=1..n-1) max(1,045; 1,4 − 0,01·k). (Antes ×1,5, −0,006 y mínimo ×1,05: la barca 100 pedía billones.)
// Misma curva para el Puerto Rural y para el Astillero (que cobra la mitad, ver _astilleroBoatCost). Las mulas del
// mundo 1 siguen con la tabla de siempre.
const BOAT_PRICE_START = 1.4, BOAT_PRICE_DECAY = 0.01, BOAT_PRICE_MIN = 1.045;
const _boatMultCache = [1];
function _boatPriceMult(k) {
    while (_boatMultCache.length <= k) {
        const j = _boatMultCache.length;
        _boatMultCache.push(_boatMultCache[j - 1] * Math.max(BOAT_PRICE_MIN, BOAT_PRICE_START - BOAT_PRICE_DECAY * j));
    }
    return _boatMultCache[k];
}
// Las barcas NO llevan los descuentos de aldeanos (mejora de descuento del Centro Urbano, Riberas Anchas, etc.): su precio sale solo de esta curva. La madera de la primera es BOAT_WOOD_BASE (10.000);
// la comida y el textil siguen saliendo de la tabla de aldeanos (índices 10 y 6) y el oro de la suya, todos multiplicados por _boatPriceMult.
const BOAT_WOOD_BASE = 10000;
function _boatCost(baseIdx) { return Math.max(1, Math.round(_villagerCostAt(baseIdx) * _boatPriceMult(_mulesBoughtWithResources()))); }
function getMuleWoodCost() { if (_harborsOn()) return Math.max(1, Math.round(BOAT_WOOD_BASE * _boatPriceMult(_mulesBoughtWithResources()))); return Math.max(1, Math.round(_villagerCostAt(14 + _mulesBoughtWithResources()) * _villagerDiscount())); }
function getMuleFoodCost() { if (_harborsOn()) return _boatCost(10); return Math.max(1, Math.round(_villagerCostAt(10 + _mulesBoughtWithResources()) * _villagerDiscount())); }
function getMuleWoolCost() { if (_harborsOn()) return _boatCost(6); return Math.max(1, Math.round(_villagerCostAt(6 + _mulesBoughtWithResources()) * _villagerDiscount())); }
function getMuleGoldCost() {
    if (_harborsOn()) return Math.max(1, Math.round(_villagerCostAt(0) * 5 * 0.25 * _boatPriceMult(_mulesBoughtWithResources())));   // sin descuento de aldeanos (ver _boatCost)
    // ×5 rebases the curve so the first mule would cost 50 gold (table's idx-0 value of 10 × 5)
    // before the ×0.25 discount below — every later mule keeps the exact same relative growth
    // shape as _villagerCostAt, just at a quarter of what that curve would otherwise charge
    // (halved once, then halved again).
    return Math.max(1, Math.round(_villagerCostAt(_mulesBoughtWithResources()) * 5 * 0.25 * _villagerDiscount()));
}

// --- MULE SPEED UPGRADE (Ruedas) ---
// +5% mule speed per level (same curve as axe/pickaxe), costing wood + wool + gold — no cap,
// extrapolates past level 10 the same way every other tool upgrade does.
function getMuleSpeedUpgradeCost() {
    const w  = [3000, 6000, 12000, 20000, 35000, 55000, 85000, 130000, 200000, 300000];
    const wl = [500, 1000, 2000, 3500, 5500, 8500, 13000, 20000, 30000, 45000];
    const g  = [15, 30, 60, 100, 160, 250, 380, 570, 850, 1250];
    const lvl = muleSpeedUpgradeLevel;
    if (lvl < 10) return { wood: w[lvl], wool: wl[lvl], gold: g[lvl] };
    const f = Math.pow(1.2, lvl - 9);
    return { wood: Math.round(w[9] * f), wool: Math.round(wl[9] * f), gold: Math.round(g[9] * f) };
}
// Ruedas reparte su multiplicador ENTRE VELOCIDAD Y CARGA en vez de meterlo todo en velocidad.
// El total no cambia — velocidad × carga sigue siendo 1,05^nivel, o sea EXACTAMENTE el mismo
// oro/segundo que antes en cada nivel — pero la mula deja de ir a 60 tiles/s y pasa a llevar más
// oro por viaje. A nivel 84 eran 60,2 t/s; ahora son 7,76 t/s con ×7,76 de carga.
//
// Por qué hacía falta, además de que 60 t/s se ve absurdo: el movimiento avanza como mucho UN
// nodo de camino por frame (ver Mule.update), así que la velocidad real está topada en "FPS
// tiles/segundo" pasara lo que pasara en la fórmula. A partir del nivel ~84 cada mejora no hacía
// literalmente nada, y a 3 FPS las mulas iban a 3 t/s cobrando una vigésima parte de lo que decía
// el panel. Todo lo que vive en la carga es inmune a las dos cosas.
//
// La mitad es una constante y no un 0,5 suelto porque es el único dial de todo esto: subirla da
// más velocidad y menos carga, bajarla al revés, y el producto se mantiene solo.
const MULE_WHEELS_SPEED_SHARE = 0.5;   // √ del multiplicador a cada lado: 1,05^(n/2) ≈ +2,47%/nivel en cada uno
function getMuleSpeedMult() { return Math.pow(1.05, muleSpeedUpgradeLevel * MULE_WHEELS_SPEED_SHARE); }
// Cuánto oro extra lleva la mula por viaje. Se aplica en _muleGoldForDistance, que es por donde
// pasa TODO el oro de mulas (ver Mule._depositGold), así que no hay una segunda vía que se quede
// sin el multiplicador.
function getMuleLoadMult()  { return Math.pow(1.05, muleSpeedUpgradeLevel * (1 - MULE_WHEELS_SPEED_SHARE)); }
function upgradeMuleSpeed() {
    const hasRuta = buildings.some(b => b.type === 'ruta_comercial');
    if (!hasRuta) return;
    const cost = getMuleSpeedUpgradeCost();
    if (wood < cost.wood || wool < cost.wool || gold < cost.gold) return;
    wood -= cost.wood; wool -= cost.wool; gold -= cost.gold;
    lifetimeStats.goldSpent += cost.gold;
    muleSpeedUpgradeLevel++;
    trackEvent('upgrade_purchased', { upgrade: 'mule_speed', level: muleSpeedUpgradeLevel });
    playTCSound(); updateUI(); saveGame();
}
window.upgradeMuleSpeed = upgradeMuleSpeed;

// paidWith === 'souls': vía alternativa a la compra normal, precio fijo en almas en vez de los
// cuatro recursos de siempre. Comparte todo lo demás (tope de población, contadores, spawn) para
// que una mula comprada con almas sea indistinguible de cualquier otra a partir de ese momento.
function recruitMule(building, paidWith) {
    if (!building || !buildingSet.has(building)) return;
    if (_popUsada() >= popLimit) { showBuildToast(t('mule.pop_full')); return; }
    if (paidWith === 'souls') {
        if (souls < SOULS_COST || _harborsOn()) return;   // barcas: sin almas
        souls -= SOULS_COST;
        _runMulesSouls++;
        _finishRecruitMule(building);
        return;
    }
    const woodCost = getMuleWoodCost();
    const foodCost = getMuleFoodCost();
    const woolCost = getMuleWoolCost();
    const goldCost = getMuleGoldCost();
    if (wood < woodCost || food < foodCost || wool < woolCost || gold < goldCost) return;
    wood -= woodCost;
    food -= foodCost;
    wool -= woolCost;
    gold -= goldCost;
    lifetimeStats.goldSpent += goldCost;
    _finishRecruitMule(building);
}
// El nacimiento en sí, compartido por las dos formas de pago (recursos o almas) — extraído para que
// añadir una tercera no obligue a duplicar contadores ni spawn.
function _finishRecruitMule(building, alreadyCounted = false) {
    if (!alreadyCounted) mulesRecruited++;   // el astillero ya sumó la suya al encargar la barca
    _runMulesPurchased++;
    let cx = (building.x + building.w / 2) * TILE_SIZE;
    let cy = (building.y + building.h / 2) * TILE_SIZE;
    const _dockC = _harborsOn() && _harborDockCenter(building);
    if (_dockC) { cx = _dockC.x; cy = _dockC.y; }   // la barca nace en el agua del muelle
    mules.push(new Mule(cx, cy, building));
    playTCSound();
    updateUI();
    saveGame();
}
window.recruitMule = recruitMule;

function trainVillagerWith(type) {
    // Sin casa libre también se puede reclutar: el nuevo entra en huelga (_updateStrikers) hasta que haya
    // sitio. El botón lo avisa (recruit.no_house). Sin tope: lo pidió JC así.
    
    let hasResources = false;
    if (type === 'wood') {
        const cost = getVillagerWoodCost();
        if (wood >= cost) {
            wood -= cost;
            purchasedVillagersWood++;
            hasResources = true;
        }
    } else if (type === 'food') {
        const cost = getVillagerFoodCost();
        if (food >= cost) {
            food -= cost;
            purchasedVillagersFood++;
            hasResources = true;
        }
    } else if (type === 'wool') {
        const cost = getVillagerWoolCost();
        if (wool >= cost) {
            wool -= cost;
            purchasedVillagersWool++;
            hasResources = true;
        }
    } else if (type === 'souls') {
        // Precio fijo (SOULS_COST), no escalado: ver su declaración. No suma a ningún
        // purchasedVillagersX — esos tres alimentan las estadísticas por recurso de siempre
        // (lifetimeStats.villagersWood/Food/Wool) y meter aquí las almas las falsearía.
        if (souls >= SOULS_COST) {
            souls -= SOULS_COST;
            purchasedVillagersSouls++;
            hasResources = true;
        }
    }

    if (hasResources) {
        // Spawn villager near center Town Center
        const cx = _spawnCenterX();
        const cy = _spawnCenterY();
        
        // Random drift spawn offset
        const vx = cx + (Math.random() - 0.5) * 80;
        const vy = cy + (Math.random() - 0.5) * 80;
        
        villagers.push(new Villager(vx, vy));
        trackEvent('villager_bought', { paid_with: type });

        playTCSound();
        updateUI();

        saveGame(); // Save progress immediately
    }
}
window.trainVillagerWith = trainVillagerWith;

// --- HOUSE CONSTRUCTION LOGIC ---
function startBuildHouse() {
    const hasFreeHouse = _freeBuildingQueue.includes('house');
    // "si me dan un edificio gratis pero aún no lo tengo para comprar, con Ctrl me deja colocar
    // más de una" — el botón del menú ya se oculta sin esto (ver su propio tutorialStep>=5) pero
    // eso NO protege una llamada directa a esta función (ver _startBuildAgain, que la llama sin
    // pasar por el botón/su display:none) — mismo criterio que ya usan startBuildWell/
    // startBuildFruitOrchard/startBuildCottonPlantation, que si se guardan a sí mismas.
    if (tutorialStep < 5 && !hasFreeHouse) return;
    const cost = getHouseCost();
    if (hasFreeHouse || (wood >= cost.wood && food >= (cost.food || 0) && wool >= (cost.wool || 0) && stone >= (cost.stone || 0))) {
        buildMode = 'house';
        updateUI();
    }
}
window.startBuildHouse = startBuildHouse;

let _buildToastTimer = null;
function showBuildToast(msg) {
    const el = document.getElementById('buildToast');
    if (!el) return;
    el.textContent = msg;
    el.style.display = '';
    if (_buildToastTimer) clearTimeout(_buildToastTimer);
    _buildToastTimer = setTimeout(() => { el.style.display = 'none'; _buildToastTimer = null; }, 2500);
}
// Dismisses right now instead of waiting out the usual 2.5s fade — see _clearRoadToast, the only
// caller: the road/city-adjacency "can't place here" toast needs to disappear the instant the
// hovered tile becomes valid, not linger for however much of its timer was still left.
function hideBuildToastNow() {
    const el = document.getElementById('buildToast');
    if (el) el.style.display = 'none';
    if (_buildToastTimer) { clearTimeout(_buildToastTimer); _buildToastTimer = null; }
}

// Returns true if two buildings share a cardinal edge (any tile of A orthogonally touches any tile of B)
function areBuildingsCardinallyAdjacent(a, b) {
    // Descarte rápido: dos edificios solo pueden ser contiguos en cruz si sus cajas se tocan (como
    // mucho a 1 casilla). Sin esto, _findChainBridge (que compara todos contra todos) tardaba cientos
    // de ms en ciudades de 1.000+ edificios — se notaba al cargar una ciudad grande.
    if (b.x > a.x + a.w || a.x > b.x + b.w || b.y > a.y + a.h || a.y > b.y + b.h) return false;
    for (let ay = a.y; ay < a.y + a.h; ay++) {
        for (let ax = a.x; ax < a.x + a.w; ax++) {
            for (let by2 = b.y; by2 < b.y + b.h; by2++) {
                for (let bx = b.x; bx < b.x + b.w; bx++) {
                    if ((ax === bx && Math.abs(ay - by2) === 1) ||
                        (ay === by2 && Math.abs(ax - bx) === 1)) return true;
                }
            }
        }
    }
    return false;
}

// BFS from town center through roads only — houses no longer propagate connectivity to each
// other (a house is never itself a valid "bridge"), matching the same rule placement already
// enforces: only a road counts as being part of "the city". Returns the Set of roads reachable
// from the Town Center — used by _wouldStrandOtherRoads to detect a demolition that would
// disconnect part of the network.
function getConnectedRoads() {
    const tc = buildings.find(b => b.type === 'town_center');
    if (!tc) return new Set();
    const connected = new Set();
    const visited = new Set([tc]);
    const queue = [tc];
    let head = 0;
    while (head < queue.length) {
        const cur = queue[head++];
        // Traverses roads only — the Town Center is just the seed, never a stepping stone
        // between two otherwise-disconnected road runs. b._demolishing (se está hundiendo tras
        // pulsar Demoler, ver destroySelectedBuilding) NO cuenta como puente: sigue en
        // `buildings` unos instantes por la animación, pero está tan condenado como si ya
        // hubiera desaparecido — sin esto, un trazo de borrado rápido sobre varios caminos
        // conectados podría dejar pasar combinaciones que en realidad sí aíslan algo.
        for (const b of _roadNeighborsOf(cur)) {
            if (b.type !== 'road' || b._demolishing || visited.has(b)) continue;
            visited.add(b);
            connected.add(b);
            queue.push(b);
        }
    }
    return connected;
}

// BFS an ordered tile path along the road network (+ Town Center as a node) from one
// building to another — used by Mule to walk a literal route rather than teleporting, and to
// get the one-way tile distance for its gold formula. Returns an array of {x,y} node
// coordinates (road tiles and/or the Town Center's corner), or null if no path exists.
// A path node's world position is (node.x*TILE_SIZE + TILE_SIZE/2, ...) at every call site (see
// Mule.update and _advanceToDropoff/_advanceFromDropoff) — correct for a plain 1x1 road tile, but
// the Town Center can also be used as a graph node (it counts as "a road" for connectivity), and
// its footprint is much bigger than 1x1. Storing (realX + w/2 - 0.5) instead of the building's raw
// top-left x/y makes that same "+TILE_SIZE/2" convention resolve to its true center for any node
// size, while staying a no-op for 1x1 roads (w=1 → +0.5-0.5 = +0, unchanged).
function _pathNodeXY(node) {
    return { x: node.x + (node.w || 1) / 2 - 0.5, y: node.y + (node.h || 1) / 2 - 0.5 };
}
// Tile → road/Town-Center lookup. The path search used to find a node's neighbours by scanning
// the ENTIRE buildings array on every dequeue: with ~230 roads and ~340 buildings that's ~80,000
// adjacency tests per search, and rebuildBuildingCaches fires hundreds of searches in one go, so
// placing a single farm froze the game for the best part of a second. With this index a
// neighbour is one Map lookup, turning each search from O(roads × buildings) into O(roads).
// Invalidated (set to null) in rebuildBuildingCaches — the one choke point every building
// placement, move and demolition already goes through — and rebuilt on next use.
// Clave del índice de caminos para una casilla, o -1 si cae fuera del 100×100.
