// El guarda NO es paranoia: la clave es plana (y*MAP_SIZE + x), así que una casilla al este del
// mapa se solapa con una del borde oeste de la fila siguiente — (100,30) y (0,31) dan las dos
// 3100. Mientras solo hubo caminos y Centro Urbano daba igual, porque todos viven dentro; desde
// que existen el dique seco y el puerto hay edificios en coordenadas fuera de rango, y cualquier
// consulta con las suyas devolvería el camino equivocado en silencio.
function _roadKeyAt(x, y) {
    if (x < 0 || x >= MAP_SIZE || y < 0 || y >= MAP_SIZE) return -1;
    return y * MAP_SIZE + x;
}
let _roadNodeAt = null;
function _roadNodeIndex() {
    if (_roadNodeAt) return _roadNodeAt;
    const m = new Map();
    for (const b of buildings) {
        if (b.type !== 'road' && b.type !== 'town_center') continue;
        for (let dy = 0; dy < (b.h || 1); dy++) {
            for (let dx = 0; dx < (b.w || 1); dx++) {
                const k = _roadKeyAt(b.x + dx, b.y + dy);
                if (k >= 0) m.set(k, b);   // clave numérica, y solo dentro del mapa
            }
        }
    }
    _roadNodeAt = m;
    return m;
}
