// dibujaba una línea de ruta hacia el campamento y calculaba stubs de camino, todo inservible.
//
// Lo mismo pasaría con 'toString', 'valueOf' o 'hasOwnProperty' si algún día un edificio se
// llamara así. Sin prototipo, solo existen las claves puestas aquí.
const DEPOSIT_ROUTE_RESOURCE = Object.assign(Object.create(null), {
    farm: 'food', fisher_hut: 'food', fruit_orchard: 'food', sheep_farm: 'food', cotton_farm: 'food',
    stone_quarry: 'stone', forest_farm: 'wood',
});
// "tx,ty" -> Set of directions ('n'/'s'/'e'/'w') a road tile should show a stub toward — only
// the ONE specific road tile each building's workers actually walk through (path[0] of its
// cached deposit route), never every tile that merely touches the building's footprint. Each
// BUILDING only ever contributes exactly one lateral direction (see _markDepositConnectionStub),
// but a single road tile CAN legitimately need more than one arm at once — e.g. sitting between
// two separate farms, one on each side, each routing through it. Deduped by direction (a Set,
// not a list) so if two buildings both compute the same direction at the same tile it still only
// draws once. Rebuilt fully in rebuildBuildingCaches() so it never goes stale.
const _depositConnectionStubs = new Map();

// True if every road tile a cached path actually walks through is still there — used to decide
// whether an old deposit route can be trusted without re-running the full BFS (see
// _getHomeDepositRoute's stability tie-break).
function _isPathStillValid(path) {
    for (const node of path) {
        if (!Number.isInteger(node.x) || !Number.isInteger(node.y)) continue; // Town Center's own fractional center node — always fine
        if (!_isRoadNetworkAt(node.x, node.y)) return false;
    }
    return true;
}

// Distancia Manhattan (mínima, en tiles) de un edificio a un tile — 0 si el tile cae dentro de su
// propia huella. "más de X tiles no debería tocar esta ruta" (ver rebuildBuildingCaches): esto es
// lo que hace esa comprobación segura de verdad, porque caminar de un punto a otro SIEMPRE cuesta
// como mínimo su distancia Manhattan — nunca menos, así que si un tile ya está más lejos en
// Manhattan que la ruta actual, tampoco puede estarlo caminando.
function _footprintManhattan(b, tx, ty) {
    const dx = Math.max(b.x - tx, tx - (b.x + (b.w || 1) - 1), 0);
    const dy = Math.max(b.y - ty, ty - (b.y + (b.h || 1) - 1), 0);
    return dx + dy;
}

function _getHomeDepositRoute(homeBuilding, resourceType, chainTypeCache) {
    const dropoffList = getDropoffPoints(resourceType);
    if (!dropoffList.length) return null;
    const cached = _depositPathCache.get(homeBuilding);
    if (cached && cached.version === _depositPathVersion) {
        return { drop: cached.drop, path: cached.path };
    }
    // Pegado a un almacén (p. ej. una ovejera que toca el Centro Urbano): descarga ahí DIRECTAMENTE, sin ruta por caminos ni por cadena. Sin esto, con Cadena de Ovejas / Granjas / etc.
    // el edificio pegado al Centro Urbano no contaba su propia adyacencia (la búsqueda directa excluye el Centro Urbano como paso) y salía por otro de su cadena hasta un camino y daba
    // toda la vuelta. Una ruta de longitud 0 (path vacío) hace que _advanceToDropoff vaya en línea recta al almacén, que está pegado.
    for (const dp of dropoffList) {
        if (dp.building === homeBuilding || !areBuildingsCardinallyAdjacent(homeBuilding, dp.building)) continue;
        const path0 = (cached && cached.drop === dp && cached.path.length === 0) ? cached.path : [];
        _depositPathCache.set(homeBuilding, { version: _depositPathVersion, drop: dp, path: path0, entry: homeBuilding, len: 0 });
        return { drop: dp, path: path0 };
    }
    // Pick the dropoff with the shortest ACTUAL road route, not straight-line distance to its
    // center — a dropoff that looks closer on the map can require a much longer detour to really
    // reach if the road network doesn't run directly there (e.g. a sheep farm routing to a Mill
    // that's "nearer" in tile coordinates but only reachable via a long way around, while a
    // farther-looking Mill sits right on its own road).
    let bestDrop = null, bestPath = null, bestLen = Infinity;
    // Desde dónde arranca DE VERDAD el tramo por caminos — el propio edificio si va directo, o el
    // "puente" del cluster si va por cadena (ver _findChainBridge). Se guarda en la caché junto al
    // largo total (ver el atajo de distancia en rebuildBuildingCaches, "más lejos que mi ruta
    // actual no puede afectarme") — para un edificio encadenado, esa distancia se mide desde el
    // puente, no desde él mismo, porque el tramo de cadena (edificio→puente) no usa caminos.
    let bestEntry = homeBuilding;
    // Directo: UNA sola búsqueda "araña" contra TODOS los almacenes candidatos a la vez (ver
    // _findNearestDropoffPath) — antes se lanzaba un _findRoadPath completo por cada almacén por
    // separado, reexplorando el mismo terreno de caminos una y otra vez. "cuando encuentra el
    // primero que es el más cercano, se detiene": por construcción de BFS eso YA es el más cercano
    // alcanzable de verdad, sin tener que comparar resultados de varias búsquedas.
    const direct = _findNearestDropoffPath(homeBuilding, dropoffList, true);
    if (direct) {
        let len = 0;
        for (let i = 1; i < direct.path.length; i++) {
            len += Math.hypot(direct.path[i].x - direct.path[i - 1].x, direct.path[i].y - direct.path[i - 1].y);
        }
        bestDrop = direct.drop; bestPath = direct.path; bestLen = len; bestEntry = homeBuilding;
    }
    // Cadena (huerto/algodonar sin camino propio, ver _findChainBridge) — se prueba SIEMPRE que la
    // mejora esté activa, no solo cuando el directo falla del todo: un edificio puede tener camino
    // directo a un almacén lejano Y a la vez un puente de cadena a otro mucho más cerca, así que
    // hay que comparar los dos y quedarse con el que sea más corto de verdad, no conformarse con
    // "el directo existe" sin más.
    const chainOk = (homeBuilding.type === 'farm' && hasSkillCadenaGranjas) ||
                    (homeBuilding.type === 'sheep_farm' && hasSkillCadenaOvejas) ||
                    (homeBuilding.type === 'fruit_orchard' && hasSkillCadenaFrutales) ||
                    (homeBuilding.type === 'cotton_farm' && hasSkillCadenaAlgodon);
    if (chainOk) {
        // chainTypeCache (opcional, ver rebuildBuildingCaches): "edificios del mismo tipo" es la
        // MISMA lista para todos los edificios de ese tipo en la misma ronda — compartirla evita
        // recorrer TODO `buildings` una vez por cada uno de ellos.
        let sameType;
        if (chainTypeCache) {
            sameType = chainTypeCache.get(homeBuilding.type);
            if (!sameType) {
                sameType = buildings.filter(b => b.type === homeBuilding.type);
                chainTypeCache.set(homeBuilding.type, sameType);
            }
        }
        // Primero la cadena que acaba en un edificio pegado a un almacén (sin caminos): si es más corta que lo ya encontrado, gana.
        const chainDrop = _findChainToDropoff(homeBuilding, sameType, dropoffList);
        if (chainDrop) {
            const hp = _pathNodeXY(homeBuilding);
            let len = Math.hypot(chainDrop.prefix[0].x - hp.x, chainDrop.prefix[0].y - hp.y);
            for (let i = 1; i < chainDrop.prefix.length; i++) len += Math.hypot(chainDrop.prefix[i].x - chainDrop.prefix[i - 1].x, chainDrop.prefix[i].y - chainDrop.prefix[i - 1].y);
            if (len < bestLen) { bestLen = len; bestDrop = chainDrop.drop; bestPath = chainDrop.prefix; bestEntry = homeBuilding; }
        }
        const chainBridge = _findChainBridge(homeBuilding, sameType);
        if (chainBridge) {
            const viaBridge = _findNearestDropoffPath(chainBridge.bridge, dropoffList, true);
            if (viaBridge) {
                const path = [...chainBridge.prefix, ...viaBridge.path];
                let len = 0;
                for (let i = 1; i < path.length; i++) {
                    len += Math.hypot(path[i].x - path[i - 1].x, path[i].y - path[i - 1].y);
                }
                if (len < bestLen) { bestLen = len; bestDrop = viaBridge.drop; bestPath = path; bestEntry = chainBridge.bridge; }
            }
        }
    }
    // Stability tie-break: _depositPathVersion is bumped by ANY building/road change anywhere on
    // the map, not just ones actually relevant to THIS building — recomputing the BFS from
    // scratch every single time can flip which of several EQUALLY-short routes gets used, purely
    // from how the search happens to explore ties on this particular pass. That flip visibly
    // moves the building's road connector arm to a different side for no real gain (see the
    // "building a road elsewhere changed my sheep farm's connector" report). If the previous
    // route is still fully intact, still ends at a still-valid dropoff, and isn't actually worse
    // than what was just found, keep it instead of switching to a "new" route that isn't any
    // better — only a genuinely SHORTER alternative is allowed to win.
    if (cached && cached.drop && cached.path.length &&
        dropoffList.some(dp => dp.building === cached.drop.building) &&
        _isPathStillValid(cached.path)) {
        let oldLen = 0;
        for (let i = 1; i < cached.path.length; i++) {
            oldLen += Math.hypot(cached.path[i].x - cached.path[i - 1].x, cached.path[i].y - cached.path[i - 1].y);
        }
        if (oldLen <= bestLen + 0.01) {
            bestDrop = cached.drop; bestPath = cached.path; bestLen = oldLen; bestEntry = cached.entry || homeBuilding;
        }
    }
    if (!bestDrop) {
        // No dropoff reachable by any road at all — fall back to straight-line nearest so
        // _advanceToDropoff's direct-line fallback still has a sensible target. bestLen se queda
        // en Infinity y bestEntry en homeBuilding — así el atajo de distancia de arriba nunca
        // "confía" en este caso (cualquier tile cae siempre dentro de un radio infinito), y sigue
        // intentando un recálculo real cada vez hasta que de verdad encuentre una ruta por camino.
        const hcx = (homeBuilding.x + homeBuilding.w / 2) * TILE_SIZE;
        const hcy = (homeBuilding.y + homeBuilding.h / 2) * TILE_SIZE;
        let minDist = Infinity;
        for (const dp of dropoffList) {
            const d = Math.hypot(dp.x - hcx, dp.y - hcy);
            if (d < minDist) { minDist = d; bestDrop = dp; }
        }
        bestPath = [];
    }
    // _depositPathVersion is bumped by ANY building change anywhere on the map (see
    // rebuildBuildingCaches), not just ones actually relevant to this building's route — so this
    // recomputes far more often than the real route ever changes. A villager mid-trip tracks
    // progress by the PATH ARRAY'S IDENTITY (see _advanceToDropoff/_advanceFromDropoff), so handing
    // back a new-but-otherwise-identical array here would reset their walk index and yank them back
    // toward the start mid-road. Keep the old array when the route is actually unchanged.
    const path = (cached && cached.drop === bestDrop && _pathsEqual(cached.path, bestPath))
        ? cached.path : bestPath;
    _depositPathCache.set(homeBuilding, { version: _depositPathVersion, drop: bestDrop, path, entry: bestEntry, len: bestLen });
    return { drop: bestDrop, path };
}
function _pathsEqual(a, b) {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
        if (a[i].x !== b[i].x || a[i].y !== b[i].y) return false;
    }
    return true;
}

// Marks (in _depositConnectionStubs) the single road tile a building's cached deposit route
// actually starts from — path[0] — so _drawRoadTileShape can draw a stub reaching toward that
// building there. Deliberately tied to the REAL route (not just building-adjacency) so the
// visual connector always matches the side the villager actually walks out of — a purely
// geometric version (pick whichever road tile touches the building first) was tried and reverted
// because it could point a different way than the real route on a multi-tile-wide building face,
// which read as even more wrong than the rare route-flip this depends on _getHomeDepositRoute's
// own stability tie-break to minimize. Skipped if the building connects directly to the Town
// Center with no road tile in between (path[0] would be the Town Center's own fractional center,
// not an integer road tile — see _pathNodeXY), since there's no rendered road tile to attach a
// stub to in that case.
function _markDepositConnectionStub(homeBuilding, path) {
    if (!path.length) return;
    const entry = path[0];
    if (!Number.isInteger(entry.x) || !Number.isInteger(entry.y)) return;
    const roadTile = buildings.find(b => b.type === 'road' && b.x === entry.x && b.y === entry.y);
    if (!roadTile) return;
    let dir = null;
    if (roadTile.y === homeBuilding.y - 1 && roadTile.x >= homeBuilding.x && roadTile.x < homeBuilding.x + homeBuilding.w) dir = 's';
    else if (roadTile.y === homeBuilding.y + homeBuilding.h && roadTile.x >= homeBuilding.x && roadTile.x < homeBuilding.x + homeBuilding.w) dir = 'n';
    else if (roadTile.x === homeBuilding.x - 1 && roadTile.y >= homeBuilding.y && roadTile.y < homeBuilding.y + homeBuilding.h) dir = 'e';
    else if (roadTile.x === homeBuilding.x + homeBuilding.w && roadTile.y >= homeBuilding.y && roadTile.y < homeBuilding.y + homeBuilding.h) dir = 'w';
    if (!dir) return;
    const key = `${roadTile.x},${roadTile.y}`;
    // Add this direction to the tile's set — a tile between two different buildings (one on
    // each side) legitimately needs both arms at once; the Set just prevents the same exact
    // direction from being counted twice.
    let set = _depositConnectionStubs.get(key);
    if (!set) { set = new Set(); _depositConnectionStubs.set(key, set); }
    set.add(dir);
}

// Moves `v` one frame toward (tx,ty); returns true once within `arrival` px. Deliberately does
// NOT snap exactly onto the point once arrived — for a big building (e.g. a 5x5 quarry, or the
// Town Center) that "arrival" radius can be over 100px, and snapping across that whole gap in one
// frame looked like a teleport. Stopping wherever the villager actually is once close enough is
// visually identical for anything this small, and removes the jump entirely.
// The effective arrival radius is never smaller than one frame's worth of movement (v.speed*_dt):
// with a fixed tiny radius (the 4px used for road waypoints), a fast time-boost multiplier (×10
// offline-boost speed) covers more than 4px in a single frame, so the villager would overshoot the
// point every frame, bounce back the other way next frame, and never land inside a 4px window —
// stuck oscillating in place instead of advancing to the next waypoint.
function _stepToward(v, tx, ty, arrival) {
    const dx = tx - v.x, dy = ty - v.y;
    const step = v.speed * _dt;
    if (Math.hypot(dx, dy) > Math.max(arrival, step)) {
        v.angle = _navAtan2(v, dy, dx);
        v.x += Math.cos(v.angle) * step;
        v.y += Math.sin(v.angle) * step;
        return false;
    }
    return true;
}

// Advances `v` one frame along its home building's cached road route (see
// _getHomeDepositRoute) and returns the target dropoff-list entry {building,x,y,size} once truly
// arrived (all waypoints walked, then within the dropoff's own arrival radius) — or null while
// still travelling. If `homeBuilding` is null (its building was demolished mid-trip) this falls
// back to the original straight-line-to-nearest-dropoff behavior, since there's no building left
// to route from.
function _advanceToDropoff(v, homeBuilding, resourceType) {
    if (!homeBuilding) {
        const dropoffList = getDropoffPoints(resourceType);
        let closestDrop = null, minDist = Infinity;
        for (const dp of dropoffList) {
            const d = Math.hypot(dp.x - v.x, dp.y - v.y);
            if (d < minDist) { minDist = d; closestDrop = dp; }
        }
        if (!closestDrop) return null;
        return _stepToward(v, closestDrop.x, closestDrop.y, closestDrop.size / 2 + 10) ? closestDrop : null;
    }
    const route = _getHomeDepositRoute(homeBuilding, resourceType);
    if (!route) {
        if (window._debugDepositRoutes) console.warn('[deposit-route] no dropoff at all for', homeBuilding.type, homeBuilding.x, homeBuilding.y, resourceType);
        return null;
    }
    const { drop, path } = route;
    if (!path.length) {
        // No road path found (e.g. building temporarily isolated) — fall back to a direct line
        // rather than stranding the villager in place.
        if (window._debugDepositRoutes) console.warn('[deposit-route] FALLBACK direct line for', homeBuilding.type, homeBuilding.x, homeBuilding.y, '-> dropoff', drop.building?.type, drop.building?.x, drop.building?.y);
        return _stepToward(v, drop.x, drop.y, drop.size / 2 + 10) ? drop : null;
    }
    if (v._depositPathRef !== path) { v._depositPathRef = path; v._depositPathIdx = 0; }
    if (v._depositPathIdx < path.length) {
        const node = path[v._depositPathIdx];
        const tx = node.x * TILE_SIZE + TILE_SIZE / 2, ty = node.y * TILE_SIZE + TILE_SIZE / 2;
        if (_stepToward(v, tx, ty, 4)) v._depositPathIdx++;
        return null;
    }
    return _stepToward(v, drop.x, drop.y, drop.size / 2 + 10) ? drop : null;
}

// Mirror of _advanceToDropoff for the trip back out to work: retraces the same cached road path
// in reverse, from the dropoff back to the home building, before the normal walk-to-harvest-node
// logic resumes — otherwise a worker would cut straight across the map back to a new node right
// after depositing, ignoring the very road it just walked in on. Returns true once back at the
// building (or immediately if there's no path to retrace — e.g. it fell back to a direct line on
// the way in), false while still travelling.
function _advanceFromDropoff(v, homeBuilding) {
    if (!homeBuilding) return true;
    const path = v._depositPathRef;
    if (!path || !path.length) return true;
    if (v._returnPathRef !== path) { v._returnPathRef = path; v._returnPathIdx = path.length - 1; }
    if (v._returnPathIdx >= 0) {
        const node = path[v._returnPathIdx];
        const tx = node.x * TILE_SIZE + TILE_SIZE / 2, ty = node.y * TILE_SIZE + TILE_SIZE / 2;
        if (_stepToward(v, tx, ty, 4)) v._returnPathIdx--;
        return false;
    }
    // Small fixed tolerance, NOT size-based like the dropoff arrival radius — a big building's
    // "size/2+10" would already contain the last waypoint, so _stepToward's exact-snap would jump
    // the villager straight to the building's center from wherever the road happened to end,
    // looking like a teleport. pickNewNode() below walks them the rest of the way in naturally.
    const hcx = (homeBuilding.x + homeBuilding.w / 2) * TILE_SIZE;
    const hcy = (homeBuilding.y + homeBuilding.h / 2) * TILE_SIZE;
    if (!_stepToward(v, hcx, hcy, 16)) return false;
    v._returnPathRef = null;
    // Also clear the OUTBOUND path ref — _advanceToDropoff only resets _depositPathIdx when the
    // path REFERENCE changes, but the cache (see _getHomeDepositRoute) deliberately reuses the
    // same array across trips when the route hasn't changed (that's what fixed the mid-trip
    // resets). Without this, a second deposit trip would see the SAME reference as the first,
    // skip the reset, find _depositPathIdx already at path.length from the finished first trip,
    // and fall straight through to the direct-line final approach — exactly the "first trip
    // follows the road, second goes direct" bug.
    v._depositPathRef = null;
    return true;
}

// Parada Comercial: extra gold when the mule's ACTUAL road path (not just distance) runs past
// certain buildings — +20% church, +15% treasury, +10% PER tavern (0-2 of them). Additive, not
// compounding: a route touching all four adds up to +55%, not four separate multipliers.
// "Passing by" = a road tile in the path is cardinally adjacent to the building's footprint —
// same adjacency test the game already uses to decide if a building itself touches a road
// (areBuildingsCardinallyAdjacent), just applied to each 1×1 road tile in the path instead of a
// building footprint.
// One entry per waypoint building the path actually passes AND that is actually working (see the
// `stop` helper below) — nameKey is the SAME building-name lang key every other panel already uses
// (church.name/tesoreria.name/tavern.name), so the breakdown line reads "Parada Comercial (Iglesia)
// +20%" with no separate label table to keep in sync. Two taverns both touched means two separate
// 'tavern.name' entries, on purpose — that mirrors "+10% por cada taberna" literally instead of
// collapsing them into one doubled line.
// Objeto de trabajo reutilizado para preguntar "¿toca este tile?". Crear uno por casilla y por
// edificio era basura de verdad: con el indicador de oro llamando a esto una vez por mula y por
// frame salían decenas de miles de objetos por segundo. areBuildingsCardinallyAdjacent solo lee
// x/y/w/h y no se lo queda, así que reutilizarlo es seguro.
const _wpNode = { x: 0, y: 0, w: 1, h: 1 };
// `desde` permite mirar solo la COLA del camino (la parte ya recorrida en el viaje de vuelta) sin
// cortar el array: el indicador de la mula lo necesita cada frame y el slice era una copia entera
// del camino por mula y por frame. Por defecto 0 = el camino completo, que es lo que quiere todo
// el mundo salvo ese indicador.
function _muleWaypointBonuses(path, desde = 0) {
    if (!hasSkillParadaComercial || !path || !path.length) return [];
    const ini = desde > 0 ? desde : 0;
    const touches = (bld) => {
        for (let i = ini; i < path.length; i++) {
            _wpNode.x = path[i].x; _wpNode.y = path[i].y;
            if (areBuildingsCardinallyAdjacent(bld, _wpNode)) return true;
        }
        return false;
    };
    // Sobre cachedMuleStops (ver su declaración), no barriendo `buildings` seis veces: son los
    // mismos candidatos, ya separados por tipo, y en el orden en que tienen que salir.
    //
    // Una parada solo cuenta si el edificio esta FUNCIONANDO: sin camino a la ciudad (_isolated) o
    // en pausa no hay con quien comerciar, asi que pasar al lado no deberia pagar. Es la misma
    // condicion que usa el resto del juego para los bonus de edificio (ver cachedHasChurch /
    // cachedHasSawmill en rebuildBuildingCaches).
    //
    // Recorrer TODOS los del tipo y no solo el primero no es un detalle: con dos Teatros, el
    // primero podia estar aislado y tapar al segundo, que si tocaba el camino.
    //
    // Ruta del Arte: tres paradas mas, con su propia habilidad. Porcentajes menores que los de
    // Parada Comercial (10/10/5 frente a 20/15/10) a proposito: Teatro, Aserradero y Constructor son
    // edificios baratos y que ya sueles tener, asi que premiarlos igual regalaria el bonus. El
    // desglose del panel se construye solo a partir de lo que esta lista devuelve (ver
    // _muleGoldForDistance -> goldLines): anadir una entrada a MULE_STOP_TYPES ya pinta su linea
    // "(Teatro) +10%" sin tocar la interfaz ni mantener una tabla de etiquetas.
    const out = [];
    for (let s = 0; s < MULE_STOP_TYPES.length; s++) {
        const def = MULE_STOP_TYPES[s];
        if (def.skill === 'rutaArtesania' && !hasSkillRutaArtesania) continue;
        for (const bld of cachedMuleStops[s]) {
            if (bld._isolated || bld.isPaused || !touches(bld)) continue;
            out.push({ skill: def.skill, nameKey: def.nameKey, mult: def.mult });
            if (!def.todas) break;   // solo la taberna suma una entrada por edificio
        }
    }
    return out;
}

// Parada Comercial: extra gold when the mule's ACTUAL road path (not just distance) runs past
// certain buildings — +20% church, +15% treasury, +10% PER tavern (0-2 of them). Additive, not
// compounding: a route touching all four adds up to +55%, not four separate multipliers.
// "Passing by" = a road tile in the path is cardinally adjacent to the building's footprint —
// same adjacency test the game already uses to decide if a building itself touches a road
// (areBuildingsCardinallyAdjacent), just applied to each 1×1 road tile in the path instead of a
// building footprint.
function _muleWaypointBonusPct(path, desde = 0) {
    return _muleWaypointBonuses(path, desde).reduce((sum, b) => sum + (b.mult - 1), 0);
}

// Gold earned per round trip for a one-way tile distance — see Mule._depositGold. +2% bonus
// per tile of the outbound distance (10 tiles = 10 + 20% = 12; 20 tiles = 20 + 40% = 28).
// `path` is optional (only needed for Parada Comercial's waypoint bonus) — every call site that
// has one in scope passes it; the couple that don't (a pure distance estimate with no live mule)
// just lose that one bonus in their number, which was already true before this skill existed.
function _muleGoldForDistance(d, path, desde = 0) {
    const base = 0.2 * d * (1 + 0.02 * d);
    const withSkill = hasSkillMercaderExperto ? base * 1.25 : base;
    const withWaypoints = withSkill * (1 + _muleWaypointBonusPct(path, desde));
    // Ruedas: la mitad de la mejora es carga (ver getMuleLoadMult). Dentro del round, no fuera:
    // redondear antes y multiplicar después convertiría el error de redondeo en oro de verdad.
    const withLoad = withWaypoints * getMuleLoadMult();
    // Barcas (mundo 2): la Iglesia multiplica su oro igual que la producción de los aldeanos
    // (cachedChurchMult: +10% por nivel de mejora de la Iglesia). A las mulas no les afecta.
    const withChurch = withLoad * (_harborsOn() ? cachedChurchMult : 1);
    return Math.round(withChurch * (prestige.goldX2 || prestige.boatGold2 ? 2 : 1) * (prestige.boatCap2 && _harborsOn() ? 2 : 1)); // Banca Real / Flota Mercante / Mareas (barcas más grandes)
}

// Manhattan (horizontal + vertical, no diagonal shortcut) tile distance between two buildings'
// centers — used ONLY for the gold formula, deliberately NOT the actual road path length.
// Manhattan, not Chebyshev: roads only ever connect orthogonally (see areBuildingsCardinallyAdjacent),
// a mule can never actually move diagonally, so the reward shouldn't assume it can either. A
// mule still walks the real road (so a zig-zagging road genuinely costs more travel time), but
// a zig-zag can never pad the payout: the reward is fixed by how far apart the two buildings are.
// Distancia que paga un viaje de comercio. Barcas (mundo 2): la longitud de la ruta real por el agua
// (casillas navegadas, la más corta posible) — un río con curvas o una ruta por la costa paga lo que
// mide de verdad. Mulas: la de siempre, en línea recta entre los dos edificios (ver abajo).
function _tradeDistance(home, market, path) {
    if (_harborsOn() && path && path.length > 1) return path.length - 1;
    return _rawBuildingDistance(home, market);
}
function _rawBuildingDistance(a, b) {
    const dx = (b.x + b.w / 2) - (a.x + a.w / 2);
    const dy = (b.y + b.h / 2) - (a.y + a.h / 2);
    return Math.round(Math.abs(dx) + Math.abs(dy));
}

// The Town Center itself counts as "a road" for adjacency purposes — it's where every road
// network starts from, so a house/city building flush against it needs no road in between.
function _isAdjacentToRoadNetwork(footprint) {
    if (buildings.some(b => b.type === 'road' && areBuildingsCardinallyAdjacent(b, footprint))) return true;
    const tc = buildings.find(b => b.type === 'town_center');
    return !!tc && areBuildingsCardinallyAdjacent(tc, footprint);
}

// Square footprint size for every buildMode that requires road adjacency (see
// isValidXPlacement) — used only to decide whether the "needs a road" toast applies to a failed
// placement/move attempt, not for the actual validity check (each isValidXPlacement already
// re-checks this itself). `well` and `watchtower` are deliberately absent — both are exempt
// from the road requirement.
// Every OTHER building type is deliberately absent too now — house/tavern/market/church/
// constructor/sawmill/bakery/teatro/tesoreria and every production building/statue can all be
// placed disconnected from any road (see isValidHousePlacement/isValidFarmPlacement/
// isValidEstatuaPlacement/etc.), so warning "needs a road" here would be actively wrong for any
// of them; the hover-preview's yellow outline covers this instead (_wouldBePlacementIsolated).
// Only `road` itself and `ruta_comercial` (genuinely useless without a real path) still gate on
// this.
const ROAD_REQUIRED_FOOTPRINT = {
    road: 1, ruta_comercial: 4,
};

// True only while the currently-visible build toast is one of THIS function's own "needs a
// road/city neighbor" messages — lets _clearRoadToast (called from the hover render loop the
// instant the tile becomes valid, see its own call site) dismiss it immediately instead of
// leaving it to fade out on the usual 2.5s timer, WITHOUT also swallowing some unrelated toast
// (e.g. "not enough wood") that happens to be showing for a completely different reason.
let _roadToastShowing = false;
function _clearRoadToast() {
    if (!_roadToastShowing) return;
    _roadToastShowing = false;
    hideBuildToastNow();
}

// Called once per tap (see _handleCanvasTap), not from isValidXPlacement itself (which runs
// every frame for the ghost preview and would spam this) — if the target tile is otherwise
// placeable (owned + empty) but fails only the road-adjacency check, say so directly instead of
// just silently refusing. Covers both a fresh placement and moving an existing building, since
// buildMode holds the type being placed either way.
function _maybeShowRoadRequiredToast(mode, tx, ty) {
    const size = ROAD_REQUIRED_FOOTPRINT[mode];
    if (!size) { _clearRoadToast(); return; }
    for (let dy = 0; dy < size; dy++) {
        for (let dx = 0; dx < size; dx++) {
            const k = `${tx + dx},${ty + dy}`;
            if (!ownedTiles.has(k) || getBuildingAt(tx + dx, ty + dy) !== null) { _clearRoadToast(); return; }
        }
    }
    // Only `road`/`ruta_comercial` ever reach here now — every other type was removed from
    // ROAD_REQUIRED_FOOTPRINT when placement stopped requiring city/road adjacency (see its own
    // comment), so the old CITY_GROUND_TYPES branch that used to live here (needs BOTH a road AND
    // a neighboring city building, reporting whichever side was missing) is gone with it.
    const footprint = { x: tx, y: ty, w: size, h: size };
    const isValidNearby = _isAdjacentToRoadNetwork(footprint);
    if (!isValidNearby) {
        showBuildToast(t('build.needs_road'));
        _roadToastShowing = true;
    } else {
        _clearRoadToast();
    }
}

// Marks isolated buildings — everything except the Town Center, a road (which uses its own
// stranding guard, see _wouldStrandOtherRoads) and the well/ritual/statues (explicitly exempt
// from the road requirement, see isValidWellPlacement/isValidEstatuaPlacement — all passive
// bonuses with no worker to walk anywhere) counts as isolated once it's no longer adjacent to a
// road or the Town Center (every placed road is always reachable from the Town Center, since
// isValidRoadPlacement and _wouldStrandOtherRoads together guarantee a road can never end up
// orphaned, so a plain adjacency check here is exactly equivalent to reachability without
// needing another BFS). Isolated buildings can't be worked (see updateFarmWorkers) or accept
// deliveries (see _buildDropoffList); houses additionally just stop counting toward population.
// water_port: va pegado al dique (ver _portFootprintAt), así que el camino que llega al dique ya le
// sirve — "haz que el puerto no requiera camino, ya es adyacente". Sin esto salía marcado como
// aislado (contorno amarillo) aunque todo funcionara.
const _ROAD_EXEMPT_TYPES = new Set(['town_center', 'road', 'zanja', 'well', 'ritual', 'watchtower', 'maderero_movil', 'water_port', 'estatua_madera', 'estatua_comida', 'estatua_tela', 'estatua_piedra', ...DECO_TYPES]);

// Edificios que NO se pueden mover. No vale con reutilizar canDestroy:false — el Mercado o la
// Iglesia tampoco se demuelen y sí se mueven. El dique y el puerto van fuera del mapa, con una
// orientación deducida del borde y una huella que solo encaja en dos sitios: moverlos con el
// sistema genérico (que asume huella cuadrada dentro del 100×100) los dejaría en un estado que
// ninguna de sus validaciones contempla.
const _UNMOVABLE_TYPES = new Set(['town_center', 'dry_dock', 'water_port', 'zanja']);   // zanja: no se mueve, solo se rellena
// Types with their own pause/unpause toggle (see toggleFarmPause, teatro/bakery's right-click
// pause) — for these, isolation reuses the SAME pause mechanism (worker release, canvas overlay,
// descriptor text) instead of a second parallel system, so it can't drift out of sync with it.
// _isolatedPause marks a pause that isolation itself imposed, so reconnecting can lift it again
// without also resuming a pause the player set deliberately (both can be true at once).
const _PAUSABLE_TYPES = new Set(['farm', 'fisher_hut', 'sheep_farm', 'stone_quarry', 'bakery', 'teatro', 'fruit_orchard', 'cotton_farm', 'forest_farm', 'tesoreria', 'establo']);

// Flood-fill through same-type neighbors: any building of `type` that's already connected makes
// its cardinally-adjacent same-type neighbors connected too, and so on — so a whole cluster only
// needs ONE of them actually touching the road network. Used by cadenaGranjas/cadenaOvejas
// (see updateBuildingConnectivity) so a field of farms/sheep farms can act "as one".
function _propagateChainConnectivity(type) {
    const group = buildings.filter(b => b.type === type);
    const queue = group.filter(b => !b._isolated);
    const visited = new Set(queue);
    while (queue.length > 0) {
        const cur = queue.shift();
        for (const b of group) {
            if (visited.has(b) || !b._isolated) continue;
            if (areBuildingsCardinallyAdjacent(cur, b)) {
                b._isolated = false;
                visited.add(b);
                queue.push(b);
            }
        }
    }
}

// Shared adjacency graph for CITY_GROUND_TYPES buildings (Town Center excluded), rebuilt once per
// updateBuildingConnectivity() pass and reused by _resolveCityConnectivity AND _getUrbanCoreInfo
// (the building panel's on-demand cluster lookup) instead of each re-scanning connectedRoads per
// CANDIDATE PAIR on their own — that repeated O(cityBuildings × connectedRoads) rescan inside a
// BFS that itself runs per queue-pop is what froze a real city (83 houses × 648 roads) for 700ms+
// on a single building placement, and kept costing the same every frame a building panel was open
// (getBuildingDescriptor → _getUrbanCoreInfo runs on every updateUI() tick). Building the graph
// itself is still one honest O(cityBuildings² + cityBuildings × connectedRoads) pass — the fix is
// doing that ONCE, not once per pair — everything downstream is then plain O(1) Set lookups.
let _cachedCityAdjacency = null;    // Map<building, Set<building>> — direct touch OR shared road tile
let _cachedCityTouchesOwnRoad = null; // Map<building, boolean>
let _cachedCityBuildingsOnRoad = null; // Map<road, building[]> — used by the not-yet-placed preview
let _cachedCityBridgeBuildings = null;   // id de puente alto -> edificios de ciudad que tocan alguna de sus casillas (ver _buildCityAdjacency)

function _buildCityAdjacency(connectedRoads) {
    const cityBuildings = buildings.filter(b => CITY_GROUND_TYPES.has(b.type) && b.type !== 'town_center');
    const adj = new Map();
    for (const b of cityBuildings) adj.set(b, new Set());
    for (let i = 0; i < cityBuildings.length; i++) {
        for (let j = i + 1; j < cityBuildings.length; j++) {
            if (areBuildingsCardinallyAdjacent(cityBuildings[i], cityBuildings[j])) {
                adj.get(cityBuildings[i]).add(cityBuildings[j]);
                adj.get(cityBuildings[j]).add(cityBuildings[i]);
            }
        }
    }
    const touchesOwnRoad = new Map();
    const buildingsOnRoad = new Map();
    for (const b of cityBuildings) {
        let has = false;
        for (const r of connectedRoads) {
            if (areBuildingsCardinallyAdjacent(r, b)) {
                has = true;
                if (!buildingsOnRoad.has(r)) buildingsOnRoad.set(r, []);
                buildingsOnRoad.get(r).push(b);
            }
        }
        touchesOwnRoad.set(b, has);
    }
    for (const touching of buildingsOnRoad.values()) {
        for (let i = 0; i < touching.length; i++) {
            for (let j = i + 1; j < touching.length; j++) {
                adj.get(touching[i]).add(touching[j]);
                adj.get(touching[j]).add(touching[i]);
            }
        }
    }
    // PUENTES ALTOS: las casillas de un mismo puente alto cuentan como UNA sola casilla de camino compartida. Una
    // casa pegada a un extremo y otra pegada al otro quedan encadenadas, igual que dos casas que tocan el mismo
    // trozo de camino: la ciudad "cruza" el río por el puente y sigue al otro lado sin pedir un núcleo de 10.
    // Ambas siguen necesitando su propio camino conectado (touchesOwnRoad), como en cualquier encadenado.
    const byBridge = new Map();
    for (const [r, list] of buildingsOnRoad) {
        if (!r.high || !r.hb) continue;
        if (!byBridge.has(r.hb)) byBridge.set(r.hb, new Set());
        for (const b of list) byBridge.get(r.hb).add(b);
    }
    for (const set of byBridge.values()) {
        const arr = [...set];
        for (let i = 0; i < arr.length; i++) {
            for (let j = i + 1; j < arr.length; j++) {
                adj.get(arr[i]).add(arr[j]);
                adj.get(arr[j]).add(arr[i]);
            }
        }
    }
    _cachedCityBridgeBuildings = byBridge;
    _cachedCityAdjacency = adj;
    _cachedCityTouchesOwnRoad = touchesOwnRoad;
    _cachedCityBuildingsOnRoad = buildingsOnRoad;
    return { cityBuildings, adj, touchesOwnRoad };
}

// Resolves which CITY_GROUND_TYPES buildings (Town Center excluded — it's its own separate,
// always-sufficient seed, see touchesTC) count as genuinely connected. Two ways in:
//   1. Chain propagation — starting from buildings that touch the Town Center directly, expand
//      through the adjacency graph, but ONLY into a neighbor that ALSO touches its own connected
//      road. This is the "un edificio necesita camino Y (tocar directamente el centro urbano O
//      estar adyacente a otro edificio YA conectado)" rule — a neighbor only counts if IT is
//      itself validated as connected, not just because it happens to be some city-type building
//      sitting there (that let a building "leech" connectivity through a neighbor that was itself
//      isolated — closed here).
//   2. Núcleo urbano — a self-contained cluster (via the same adjacency) of NUCLEO_URBANO_SIZE
//      (10) or more buildings, where EVERY member touches its own connected road, counts as
//      connected even with no chain back to the Town Center at all. This is what unblocks the
//      chicken-and-egg case a pure chain can never bootstrap on its own: a whole real, road-served
//      neighborhood that just doesn't happen to have any single building touching the Town Center
//      or an already-validated building — "puede ser un pueblo aparte, independiente".
function _resolveCityConnectivity(tc, connectedRoads) {
    const { cityBuildings, adj, touchesOwnRoad } = _buildCityAdjacency(connectedRoads);
    const connected = new Set();
    const queue = [];
    // "una carretera que separe el centro urbano de un edificio deberia considerarse adyacente
    // como pasa entre casas y tal" — a road tile sitting between the Town Center and a building
    // should count the same way a shared road tile already counts between two ordinary city
    // buildings (see buildingsOnRoad in _buildCityAdjacency). Found in O(connectedRoads) once
    // (only the handful of road tiles actually touching the TC matter) via the already-built
    // buildingsOnRoad index, not with a per-building rescan.
    const tcRoadNeighbors = new Set();
    if (tc && _cachedCityBuildingsOnRoad) {
        for (const r of connectedRoads) {
            if (!areBuildingsCardinallyAdjacent(tc, r)) continue;
            for (const b of (_cachedCityBuildingsOnRoad.get(r) || [])) tcRoadNeighbors.add(b);
        }
    }
    for (const b of cityBuildings) {
        if (tc && (areBuildingsCardinallyAdjacent(tc, b) || tcRoadNeighbors.has(b))) { connected.add(b); queue.push(b); }
    }
    let qi = 0;
    while (qi < queue.length) {
        const cur = queue[qi++];
        for (const b of adj.get(cur)) {
            if (connected.has(b) || !touchesOwnRoad.get(b)) continue;
            connected.add(b);
            queue.push(b);
        }
    }
    // Núcleo urbano clusters are found over the ROAD-touching subgraph only — a building without
    // its own road can never be a member, and just as importantly can't act as a bridge linking
    // two halves of an otherwise-qualifying group either. Walking the FULL adjacency graph and
    // then checking "does every member have a road" afterward (the old approach) failed the whole
    // physical block over a single straggler — "Grupo de 33 — 1 sin camino propio" blocked ALL 33
    // instead of just the 1, even when the other 32 are perfectly capable of forming their own
    // independent núcleo without it: "por que no todo forma un nucleo urbano menos ese edificio?".
    const visited = new Set();
    for (const start of cityBuildings) {
        if (visited.has(start) || !touchesOwnRoad.get(start)) continue;
        const cluster = [start];
        visited.add(start);
        let ci = 0;
        while (ci < cluster.length) {
            const cur = cluster[ci++];
            for (const b of adj.get(cur)) {
                if (visited.has(b) || !touchesOwnRoad.get(b)) continue;
                visited.add(b);
                cluster.push(b);
            }
        }
        if (cluster.length >= NUCLEO_URBANO_SIZE) {
            for (const b of cluster) connected.add(b);
        }
    }
    return connected;
}

// For the building info panel: which group of city buildings `b` currently sits in (via the
// cached adjacency graph above), and whether that group is big enough (NUCLEO_URBANO_SIZE+, every
// member with its own road) to actually count as a núcleo urbano — "que en la ficha del edificio
// ponga si esta en algún nucleo urbano y la cantidad de edificios". Called from
// getBuildingDescriptor on every UI refresh while a panel is open, so it leans entirely on the
// cache built by the last updateBuildingConnectivity() pass rather than re-deriving it — see the
// comment on _cachedCityAdjacency for why that matters. Returns null for a lone building not
// grouped with anything (nothing useful to show).
function _getUrbanCoreInfo(b) {
    if (!CITY_GROUND_TYPES.has(b.type) || b.type === 'town_center') return null;
    const adj = _cachedCityAdjacency || _buildCityAdjacency(cachedConnectedRoads).adj;
    const touchesOwnRoad = _cachedCityTouchesOwnRoad;
    const neighbors = adj.get(b);
    if (!neighbors) return null;
    // "por que no todo forma un nucleo urbano menos ese edificio?" — if `b` itself has no road, IT
    // can never be a núcleo urbano member (matches _resolveCityConnectivity), but that must not
    // drag its neighbors down: report the surrounding PHYSICAL group (ignoring road, same as
    // before) purely as context for why this one specific building is stuck, never as a núcleo.
    if (!touchesOwnRoad.get(b)) {
        const cluster = [b];
        const visited = new Set([b]);
        let ci = 0;
        while (ci < cluster.length) {
            const cur = cluster[ci++];
            for (const other of adj.get(cur)) {
                if (visited.has(other)) continue;
                visited.add(other);
                cluster.push(other);
            }
        }
        if (cluster.length < 2) return null;
        let withoutRoad = 0;
        for (const m of cluster) if (!touchesOwnRoad.get(m)) withoutRoad++;
        return { size: cluster.length, withoutRoad, isNucleo: false };
    }
    // `b` touches its own road — walk the núcleo urbano SUBGRAPH (only nodes that also touch
    // their own road count as members or bridges, see _resolveCityConnectivity), so a roadless
    // neighbor elsewhere in the same physical block doesn't understate this cluster's real count.
    const cluster = [b];
    const visited = new Set([b]);
    let ci = 0;
    while (ci < cluster.length) {
        const cur = cluster[ci++];
        for (const other of adj.get(cur)) {
            if (visited.has(other) || !touchesOwnRoad.get(other)) continue;
            visited.add(other);
            cluster.push(other);
        }
    }
    if (cluster.length < 2) return null;
    return { size: cluster.length, withoutRoad: 0, isNucleo: cluster.length >= NUCLEO_URBANO_SIZE };
}

// "al entrar al juego si encuentra muchos edificios aislados que indique el nuevo sistema, con un
// cartel" — one-time (per save) notice explaining the reworked city-connectivity rules when an
// EXISTING city ends up with several isolated city buildings after loading (this session's rework
// changed what counts as "connected" more than once, so a layout that used to read as fine can
// come back genuinely isolated the first time it's opened again). Called once from the boot
// sequence, after loadGame() has already run updateBuildingConnectivity — never fires on a fresh
// city (an empty/new city has nothing to be isolated in the first place).
function _maybeShowCityIsolationNotice() {
    if (cityIsolationNoticeShown) return;
    const isolatedCity = buildings.filter(b => CITY_GROUND_TYPES.has(b.type) && b.type !== 'town_center' && b._isolated);
    const marketIsolated = buildings.some(b => b.type === 'market' && b._isolated);
    if (isolatedCity.length < 3 && !marketIsolated) return;
    cityIsolationNoticeShown = true;
    saveGame();
    const modal = document.getElementById('cityIsolationNoticeModal');
    if (!modal) return;
    const bodyEl = document.getElementById('cityIsolationNoticeBody');
    if (bodyEl) bodyEl.innerHTML = t('isolnotice.body', { n: isolatedCity.length });
    const marketEl = document.getElementById('cityIsolationNoticeMarket');
    if (marketEl) {
        marketEl.style.display = marketIsolated ? 'block' : 'none';
        if (marketIsolated) marketEl.innerHTML = t('isolnotice.market');
    }
    modal.style.display = 'flex';
}
window._maybeShowCityIsolationNotice = _maybeShowCityIsolationNotice;

// "cuando se rompe la ruta todas las mulas iran inmediatamente a su lugar de mercado mas cercano
// por caminos si es posible y se iniciara la ruta" — an idle mule only retries _tryStartRoute()
// on its own ~1s timer (see Mule.update), so a mule stuck idle because its home/the Market was
// isolated could sit for up to a second after the ROAD NETWORK ITSELF already fixed that (a new
// road placed, an old one removed, the Market or a Ruta Comercial moved). Called once at the end
// of updateBuildingConnectivity — the one place every placement/move/demolition already funnels
// through (see rebuildBuildingCaches) — so any topology change wakes every idle mule to retry on
// its very next update() instead of waiting out its timer. Only idle mules: one already walking a
// path keeps following it untouched (see the AskUserQuestion this was scoped to).
function _wakeIdleMules() {
    for (const m of mules) {
        if (m.state === 'idle') m._retryTimer = 0;
    }
}
function updateBuildingConnectivity() {
    let _lighthouseVisDirty = false;
    let _popDirty = false; // alguna casa/taberna cambió de aislada↔conectada — ver el bucle final
    // _isAdjacentToRoadNetwork only checks LOCAL touch (is there any road tile right next to me),
    // not whether that road tile is actually part of a network that traces back to the Town
    // Center — a road segment orphaned by demolishing/moving whatever used to link it back would
    // still count. getConnectedRoads() already does the real BFS (used by _wouldStrandOtherRoads
    // for exactly this reason) — reuse it here so isolation reflects TRUE connectivity, not just
    // "something road-shaped is adjacent".
    const tc = buildings.find(b => b.type === 'town_center');
    const connectedRoads = getConnectedRoads();
    cachedConnectedRoads = connectedRoads;
    if (window._debugConnectivity) {
        console.log('[CityChain] getConnectedRoads() found', connectedRoads.size, 'roads reachable from TC:', [...connectedRoads].map(r => `${r.x},${r.y}`));
    }
    // City buildings (house/bakery/church/constructor/tesoreria/tavern/market/teatro/sawmill) are
    // resolved all together up front — see _resolveCityConnectivity for the full rule (touch the
    // Town Center directly, OR touch your own connected road AND chain off an already-connected
    // neighbor, OR be part of a núcleo urbano cluster of 10+). Every OTHER isolatable type keeps
    // the simple rule below (just needs to touch the Town Center or a connected road, no neighbor
    // requirement at all — see the cadenaGranjas/cadenaOvejas same-type chain further down too).
    const cityConnected = _resolveCityConnectivity(tc, connectedRoads);
    for (const b of buildings) {
        // Exento = nunca aislado. Poner la marca a false y no solo saltárselo: un edificio que pasó a
        // ser exento (el puerto) podía traer _isolated = true de una partida guardada antes.
        if (_ROAD_EXEMPT_TYPES.has(b.type)) { b._isolated = false; continue; }
        const touchesTC = !!tc && areBuildingsCardinallyAdjacent(tc, b);
        let touchesConnectedRoad = false;
        let viaRoad = null;
        for (const r of connectedRoads) {
            if (areBuildingsCardinallyAdjacent(r, b)) { touchesConnectedRoad = true; viaRoad = r; break; }
        }
        if (CITY_GROUND_TYPES.has(b.type)) {
            b._isolated = !cityConnected.has(b);
            // "pone Aislado. sin conexion a un camino, pero en realidad si tiene camino... es
            // aislado sin conexion al centro urbano" — building.isolated used to always blame "no
            // road", even when the real cause was the OTHER half of the requirement (has a road,
            // but no valid chain/núcleo to the Town Center). Recorded here so renderSelectionStatus
            // can show the actual reason instead of a misleading fixed message.
            if (b._isolated) b._isolatedReason = touchesConnectedRoad ? 'neighbor' : 'road';
        } else {
            b._isolated = !(touchesTC || touchesConnectedRoad);
            if (b._isolated) b._isolatedReason = 'road';
        }
        if (window._debugConnectivity && CITY_GROUND_TYPES.has(b.type)) {
            console.log(`[CityChain] first pass ${b.type}@${b.x},${b.y}: isolated=${b._isolated} touchesTC=${touchesTC} touchesConnectedRoad=${touchesConnectedRoad}${viaRoad ? ` (via road@${viaRoad.x},${viaRoad.y})` : ''}`);
        }
    }
    // cadenaGranjas/cadenaOvejas: a farm/sheep farm chained to another connected one of its own
    // kind counts as connected too — only the "front" one needs to actually touch a road.
    if (hasSkillCadenaGranjas) _propagateChainConnectivity('farm');
    if (hasSkillCadenaOvejas) _propagateChainConnectivity('sheep_farm');
    if (hasSkillCadenaFrutales) _propagateChainConnectivity('fruit_orchard');
    if (hasSkillCadenaAlgodon) _propagateChainConnectivity('cotton_farm');
    for (const b of buildings) {
        if (_ROAD_EXEMPT_TYPES.has(b.type)) continue;
        const wasIsolated = !!b._wasIsolatedLastCheck;
        b._wasIsolatedLastCheck = b._isolated;
        // Casas y tabernas cuentan para el límite de población solo conectadas (ver
        // _applyPopLimit) — si alguna cambia de estado, el límite cambia con ella.
        if ((b.type === 'house' || b.type === 'tavern') && !!b._isolated !== wasIsolated) _popDirty = true;
        if (b.type === 'lighthouse' && !!b._isolated !== wasIsolated) _lighthouseVisDirty = true;   // se enciende/apaga: cambia lo que alumbra
        if (b._isolated && !wasIsolated) {
            // Newly isolated (its connecting road was just removed) — anyone already working
            // there has to stop immediately, not just be refused for future assignment.
            _releaseBuildingWorkers(b);
            if (_PAUSABLE_TYPES.has(b.type) && !b.isPaused) {
                b.isPaused = true;
                b._isolatedPause = true;
            }
        } else if (!b._isolated && wasIsolated && b._isolatedPause) {
            // Reconnected — lift the pause isolation imposed (but leave a manual pause alone).
            b.isPaused = false;
            b._isolatedPause = false;
        }
    }
    _wakeIdleMules();
    if (_popDirty) { _applyPopLimit(); _uiDirty = true; }
    if (_lighthouseVisDirty) { recalculateVisibility(); _minimapDirty = true; }
}

// Predicts whether a NOT-YET-PLACED footprint would come out isolated, mirroring
// updateBuildingConnectivity's exact rule (including the chain-skill exception below) — used only
// for the hover-preview outline color. A placement can be perfectly legal (a Lumber Camp is
// deliberately allowed off-road, see isValidLumberCampPlacement, so it can push toward fresh trees
// ahead of the road reaching them) and still land disconnected from any road/Town Center, pausing
// it uselessly until a road actually reaches it — that gets its own warning color instead of
// looking identical to a normal working placement.
function _wouldBePlacementIsolated(footprint, type) {
    if (_ROAD_EXEMPT_TYPES.has(type)) return false;
    const tc = buildings.find(b => b.type === 'town_center');
    if (tc && areBuildingsCardinallyAdjacent(tc, footprint)) return false;
    let touchesConnectedRoad = false;
    // "una carretera que separe el centro urbano de un edificio deberia considerarse adyacente" —
    // a road tile touching BOTH the footprint and the TC counts the same as touching the TC
    // directly (mirrors the fix in _resolveCityConnectivity). Checked in the same pass as
    // touchesConnectedRoad, no extra scan.
    let touchesTCViaRoad = false;
    for (const r of cachedConnectedRoads) {
        if (!areBuildingsCardinallyAdjacent(r, footprint)) continue;
        touchesConnectedRoad = true;
        if (tc && areBuildingsCardinallyAdjacent(tc, r)) { touchesTCViaRoad = true; break; }
    }
    if (touchesTCViaRoad) return false;
    if (CITY_GROUND_TYPES.has(type)) {
        // Mirrors _resolveCityConnectivity: needs its OWN connected road, plus either chains off
        // an already-connected neighbor (real building, current _isolated snapshot) or lands
        // inside/completes a núcleo urbano cluster where every member also has its own road. Uses
        // the SAME cached adjacency graph updateBuildingConnectivity() already built this pass
        // (see _cachedCityAdjacency) instead of re-scanning cachedConnectedRoads per candidate —
        // this runs every frame while hovering to place a city building, and the old per-candidate
        // rescan was exactly the O(cityBuildings × connectedRoads) blowup that froze real cities.
        if (touchesConnectedRoad) {
            // footprint's own direct + shared-road-tile neighbors, found fresh (it isn't in the
            // cached graph — it doesn't exist yet) but cheaply: a straight scan for direct touch,
            // plus a lookup per road tile footprint touches (at most a handful) instead of every
            // connected road in the whole city.
            const footprintNeighbors = new Set();
            for (const b of buildings) {
                if (!CITY_GROUND_TYPES.has(b.type) || b.type === 'town_center') continue;
                if (areBuildingsCardinallyAdjacent(footprint, b)) footprintNeighbors.add(b);
            }
            if (_cachedCityBuildingsOnRoad) {
                for (const r of cachedConnectedRoads) {
                    if (!areBuildingsCardinallyAdjacent(r, footprint)) continue;
                    for (const b of (_cachedCityBuildingsOnRoad.get(r) || [])) footprintNeighbors.add(b);
                    // Puente alto: también los que tocan cualquier otra casilla del mismo puente (ver _buildCityAdjacency)
                    if (r.hb && _cachedCityBridgeBuildings) for (const b of (_cachedCityBridgeBuildings.get(r.hb) || [])) footprintNeighbors.add(b);
                }
            }
            for (const b of footprintNeighbors) { if (!b._isolated) return false; }
            if (_cachedCityAdjacency) {
                // Núcleo urbano subgraph only — same fix as _resolveCityConnectivity/
                // _getUrbanCoreInfo: a roadless neighbor can't be a member NOR a bridge, so it must
                // not appear in this walk at all ("por que no todo forma un nucleo urbano menos ese
                // edificio?"). footprint itself always qualifies as a seed here (touchesConnectedRoad
                // is true in this branch).
                const seeds = [...footprintNeighbors].filter(b => _cachedCityTouchesOwnRoad.get(b));
                const visited = new Set(seeds);
                const queue = [...seeds];
                let qi = 0;
                while (qi < queue.length) {
                    const cur = queue[qi++];
                    for (const b of (_cachedCityAdjacency.get(cur) || [])) {
                        if (visited.has(b) || !_cachedCityTouchesOwnRoad.get(b)) continue;
                        visited.add(b);
                        queue.push(b);
                    }
                }
                if (visited.size + 1 >= NUCLEO_URBANO_SIZE) { // +1 for footprint itself
                    return false;
                }
            }
        }
        return true;
    }
    // Non-city isolatable types (farm/sheep_farm/stone_quarry/...) only need a connected road —
    // no neighbor requirement at all, matching updateBuildingConnectivity's simpler rule for them.
    if (touchesConnectedRoad) return false;
    // Chained resource buildings (farm/sheep_farm/fruit_orchard/cotton_farm, with their matching
    // skill) act "as one" — touching an already-connected same-type neighbor saves it from
    // isolation exactly like _propagateChainConnectivity does after the fact.
    const chainSkillFor = { farm: hasSkillCadenaGranjas, sheep_farm: hasSkillCadenaOvejas, fruit_orchard: hasSkillCadenaFrutales, cotton_farm: hasSkillCadenaAlgodon };
    if (chainSkillFor[type]) {
        for (const b of buildings) {
            if (b.type === type && !b._isolated && areBuildingsCardinallyAdjacent(b, footprint)) return false;
        }
    }
    return true;
}

function _releaseBuildingWorkers(b) {
    villagers.forEach(v => {
        if (v.farmTarget !== b) return;
        _flushBackpack(v);
        v.farmTarget = null;
        v.state = 'idle';
        v._teatroSlot = undefined;
    });
}

function isValidHousePlacement(hx, hy) {
    // Keep 2x2 area inside boundaries
    if (hx < 0 || hx + 1 >= MAP_SIZE || hy < 0 || hy + 1 >= MAP_SIZE) return false;

    for (let dy = 0; dy <= 1; dy++) {
        for (let dx = 0; dx <= 1; dx++) {
            const key = `${hx + dx},${hy + dy}`;
            if (!ownedTiles.has(key)) return false;
            if (getBuildingAt(hx + dx, hy + dy) !== null) return false;
        }
    }

    // Deliberately NOT requiring city adjacency anymore (like the production buildings) — it can
    // be placed anywhere in owned territory, and just comes out isolated/paused (see
    // updateBuildingConnectivity) until a road AND a neighboring city building both reach it. See
    // the hover-preview's yellow warning for exactly this case (_wouldBePlacementIsolated).
    return true;
}

// "cuando construyo algo, lo bajo muchísimos y lo subo hasta su posición" — un edificio recién
// construido nace hundido BUILD_RISE_START px y sube a su sitio (ver _buildRise en el bucle de
// dibujo, mismo mecanismo que el pedestal de selección/_selLift pero en sentido contrario y con
// mucho más recorrido). Vive aquí porque _bOff() ya se esparce en CADA buildings.push() de
// construcción nueva de verdad — un solo sitio cubre todos los tipos sin tocar cada tryPlaceXxx.
// Nunca al relocalizar un edificio existente (_isMovingBuilding) — desplazarlo no es "nacer".
// "quiero que los caminos se creen igual que los edificios, subiendo desde el agujero" — a 128
// un camino (1 tile, 64px de huella) cruzaba el recorte y empezaba a asomar en ~3 frames: tan
// rápido que se veía "de golpe, sin pozo ni nada" aunque el mecanismo sí corría. 256 (4 tiles)
// asegura una fase oculta perceptible hasta edificios de 4x4 sin alargar el asentado total (que
// depende de la TASA de abajo, no de dónde arranca — el decaimiento exponencial tarda lo mismo
// en llegar cerca del objetivo sea cual sea el punto de partida).
const BUILD_RISE_START = 256;
// "una especie de rebote cuando se crea, subir más como si estuviera seleccionando y ya
// asentarse bien" — b._buildRise no decae solo hacia 0: primero hacia -BUILD_OVERSHOOT (por
// ENCIMA del suelo, mismo aspecto que el pedestal de selección — ver el bloque de dibujo, rama
// del rebote) y, al cruzarlo (b._buildOvershot), vuelve a decaer hacia 0 de verdad. Mismo valor
// que el tope de _selLift (12) a propósito, para que se vea igual de alto que "seleccionado".
const BUILD_OVERSHOOT = 12;
// "el edificio se le pone una variacion de cordenadas random para no ser cuadriculado, podemos
// desactivarlo" — desactivado: r() ya no aporta variación (antes ±5px), se deja la función y el
// spread _ox/_oy intactos (por si se reactiva) pero siempre en 0.
function _bOff() { const r = () => 0; return { _ox: r(), _oy: r(), ...(_isMovingBuilding ? {} : { _buildRise: BUILD_RISE_START }) }; }

// Comparte el ease + dibujo del "agujero de tierra" entre construir (b._buildRise arranca en
// BUILD_RISE_START y decae a 0, con rebote — ver _bOff), demoler (b._demolishing: arranca casi en
// 0 y SUBE hasta BUILD_RISE_START, momento en que dispara _finalizeDemolish y termina) y los
// fantasmas de terreno que quedan tras demoler (mismo decaimiento que construir, pero sin ningún
// edificio real detrás — ver _groundRiseGhosts, actualizados justo después de LAYER 3a). Solo
// dibuja el agujero en sí (pared de tierra, oscurecido progresivo, recorte + repintado del propio
// suelo/decoración/plaza/asfalto bajo el hueco): el sprite del edificio, si lo hay, lo sigue
// dibujando cada layer por su cuenta alrededor de esta llamada — por eso un objeto sin sprite real
// (un fantasma, o cualquier cosa sin `type` reconocido) pasa por aquí sin más y le sale
// exactamente el mismo efecto, sin ningún edificio encima.
// Devuelve true si `b` se acaba de demoler del todo en esta misma llamada (ya spliceado de
// `buildings`, ver _finalizeDemolish) — el layer que llama debe saltarse el despacho por tipo de
// ESE edificio a partir de ahí, ya no existe.
function _updateBuildRise(b, bPx, bPy, _dt) {
    // "quita el lapsus desde que baja hasta que vuelve el tile a su sitio" — el objetivo de la
    // demolición NO es BUILD_RISE_START (pensado para construir: quedarse oculto con margen de
    // sobra, para que "no aparezca de golpe"): basta con hundirse justo lo que mide su propia
    // huella. A partir de ahí ya está completamente tapado (el clip de más abajo no deja ver nada
    // por debajo de la huella real), así que seguir hundiéndose de más solo eran fotogramas de
    // "pantalla congelada" de sobra antes de poder terminar (_finalizeDemolish esperaba a
    // BUILD_RISE_START entero). El fantasma (ver _finalizeDemolish) arranca desde este mismo
    // valor exacto, nunca desde BUILD_RISE_START, así no hay una segunda tanda de hundimiento
    // fantasma al otro lado del corte.
    const _sinkTarget = b.h * TILE_SIZE;
    // "si está desactivado lo de animación seleccionar, que sea también a destruir y construir" —
    // mismo toggle que _selLift: sin animar, construir/demoler saltan directo a su estado final
    // (b._buildRise a 0 o a _sinkTarget) en vez de subir/hundirse poco a poco.
    if (b._demolishing) {
        // Sin rebote — hundirse es un solo trayecto hacia abajo, no hace falta cruzar el suelo ni
        // asentarse: al llegar a _sinkTarget (completamente hundido/tapado) ya está.
        if (settingShowSelectLift) {
            b._buildRise = (b._buildRise || 0) + (_sinkTarget - (b._buildRise || 0)) * Math.min(1, 0.2 * _dt);
            if (b._buildRise >= _sinkTarget - 0.5) b._buildRise = _sinkTarget;
        } else {
            b._buildRise = _sinkTarget;
        }
    } else if (b._buildRise) {
        if (settingShowSelectLift) {
            const _buildTarget = b._buildOvershot ? 0 : -BUILD_OVERSHOOT;
            b._buildRise += (_buildTarget - b._buildRise) * Math.min(1, 0.2 * _dt);
            if (!b._buildOvershot && b._buildRise <= _buildTarget + 0.5) b._buildOvershot = true;
            if (b._buildOvershot && Math.abs(b._buildRise) < 0.3) { b._buildRise = 0; delete b._buildOvershot; }
        } else {
            b._buildRise = 0;
            delete b._buildOvershot;
        }
    }
    if (!b._buildRise) { delete b._buildRise; return false; }

    const _fw = b.w * TILE_SIZE, _fh = b.h * TILE_SIZE;
    const _buildDarkPct = Math.round(100 - 40 * Math.pow(Math.max(0, Math.min(1, b._buildRise / BUILD_RISE_START)), 0.4));
    ctx.save();
    // Antes: ctx.filter = brightness(X%) para oscurecer el hueco. Un filtro de canvas se aplica por CADA dibujo del bloque y es lentísimo: con varios
    // caminos/edificios subiendo a la vez (un trazo en cadena) los FPS se hundían (medido: de 60 a 5 con 240 caminos). Ahora el oscurecido es una
    // capa negra translúcida sobre la huella al final del bloque (mismo resultado: oscurecer = multiplicar el color), sin filtro.
    if (b._buildRise > 0) {
        ctx.beginPath();
        ctx.rect(bPx - TILE_SIZE * 2, -100000, b.w * TILE_SIZE + TILE_SIZE * 4, 100000 + b.y * TILE_SIZE + b.h * TILE_SIZE);
        ctx.clip();
    }
    const _dirtSprite2 = spriteCache.terrain?.dirt_riser;
    if (_groundCanvas) {
        const _gsx = GROUND_MARGIN + canvas.width / 2 + (bPx - _groundBuiltCamX) * zoom;
        const _gsy = GROUND_MARGIN + _gameCenterY + (bPy - _groundBuiltCamY) * zoom;
        ctx.imageSmoothingEnabled = false;
        ctx.drawImage(_groundCanvas, _gsx, _gsy, _fw * zoom, _fh * zoom, bPx, bPy + b._buildRise, _fw, _fh);
    }
    if ((groundDecorations.size > 0 || groundOverlays.size > 0)) {
        for (let ty = b.y; ty < b.y + b.h; ty++) {
            for (let tx = b.x; tx < b.x + b.w; tx++) {
                const gd = groundDecorations.get(`${tx},${ty}`);
                if (gd) drawGroundDeco(tx * TILE_SIZE, ty * TILE_SIZE + b._buildRise, gd);
                const go = groundOverlays.get(`${tx},${ty}`);
                if (go) drawGroundDeco(tx * TILE_SIZE, ty * TILE_SIZE + b._buildRise, go);
            }
        }
    }
    if (plazaDiscordTile) {
        const _ox0 = Math.max(b.x, plazaDiscordTile.x), _ox1 = Math.min(b.x + b.w, plazaDiscordTile.x + PLAZA_DISCORD_SIZE);
        const _oy0 = Math.max(b.y, plazaDiscordTile.y), _oy1 = Math.min(b.y + b.h, plazaDiscordTile.y + PLAZA_DISCORD_SIZE);
        if (_ox1 > _ox0 && _oy1 > _oy0) {
            const _pdx = _ox0 * TILE_SIZE, _pdy = _oy0 * TILE_SIZE + b._buildRise;
            const _pdw = (_ox1 - _ox0) * TILE_SIZE, _pdh = (_oy1 - _oy0) * TILE_SIZE;
            const _pdSprite = spriteCache.buildings.plaza_discord;
            if (_pdSprite) {
                const _pdScaleX = _pdSprite.width / PLAZA_DISCORD_SIZE, _pdScaleY = _pdSprite.height / PLAZA_DISCORD_SIZE;
                ctx.drawImage(_pdSprite,
                    (_ox0 - plazaDiscordTile.x) * _pdScaleX, (_oy0 - plazaDiscordTile.y) * _pdScaleY,
                    (_ox1 - _ox0) * _pdScaleX, (_oy1 - _oy0) * _pdScaleY,
                    _pdx, _pdy, _pdw, _pdh);
            } else {
                ctx.fillStyle = 'rgba(88,101,242,0.5)';
                ctx.fillRect(_pdx, _pdy, _pdw, _pdh);
            }
        }
    }
    // Los caminos no tienen sprite propio (su asfalto ya vive en _roadCanvas, LAYER 1c) — mismo
    // truco que el pedestal de selección: tapar la posición real con suelo y repintar una copia
    // del asfalto en la posición actual (hundida o rebotando). Un fantasma de terreno hereda
    // b.type del edificio demolido (ver _finalizeDemolish), así que esto aplica igual al hueco
    // que deja un camino demolido, sin ningún caso especial adicional.
    if (b.type === 'road' && _roadCanvas) {
        if (_groundCanvas) {
            const _rgsx = GROUND_MARGIN + canvas.width / 2 + (bPx - _groundBuiltCamX) * zoom;
            const _rgsy = GROUND_MARGIN + _gameCenterY + (bPy - _groundBuiltCamY) * zoom;
            ctx.drawImage(_groundCanvas, _rgsx, _rgsy, _fw * zoom, _fh * zoom, bPx, bPy, _fw, _fh);
        }
        const _rgd = groundDecorations.get(`${b.x},${b.y}`);
        if (_rgd) drawGroundDeco(bPx, bPy, _rgd);
        if (plazaDiscordTile && b.x >= plazaDiscordTile.x && b.x < plazaDiscordTile.x + PLAZA_DISCORD_SIZE &&
            b.y >= plazaDiscordTile.y && b.y < plazaDiscordTile.y + PLAZA_DISCORD_SIZE) {
            const _rpdSprite = spriteCache.buildings.plaza_discord;
            if (_rpdSprite) {
                const _rpdScaleX = _rpdSprite.width / PLAZA_DISCORD_SIZE, _rpdScaleY = _rpdSprite.height / PLAZA_DISCORD_SIZE;
                ctx.drawImage(_rpdSprite,
                    (b.x - plazaDiscordTile.x) * _rpdScaleX, (b.y - plazaDiscordTile.y) * _rpdScaleY,
                    _rpdScaleX, _rpdScaleY,
                    bPx, bPy, _fw, _fh);
            } else {
                ctx.fillStyle = 'rgba(88,101,242,0.5)';
                ctx.fillRect(bPx, bPy, _fw, _fh);
            }
        }
        const _rrsx = canvas.width / 2 + (bPx - cameraX) * zoom;
        const _rrsy = _gameCenterY + (bPy - cameraY) * zoom;
        ctx.drawImage(_roadCanvas, _rrsx, _rrsy, _fw * zoom, _fh * zoom, bPx, bPy + b._buildRise, _fw, _fh);
    }
    if (b._buildRise > 0) {
        if (_dirtSprite2) {
            ctx.imageSmoothingEnabled = false;
            const _scale2 = TILE_SIZE / _dirtSprite2.width;
            const _tileH2 = _dirtSprite2.height * _scale2;
            for (let _yy = 0; _yy < b._buildRise; _yy += _tileH2) {
                const _rowH = Math.min(_tileH2, b._buildRise - _yy);
                const _srcH2 = _rowH / _scale2;
                for (let _i = 0; _i < b.w; _i++) {
                    ctx.drawImage(_dirtSprite2, 0, 0, _dirtSprite2.width, _srcH2,
                        bPx + _i * TILE_SIZE, bPy + _yy, TILE_SIZE, _rowH);
                }
            }
        } else {
            ctx.fillStyle = '#4a3018';
            ctx.fillRect(bPx, bPy, _fw, b._buildRise);
        }
    } else {
        const _riserH = -b._buildRise;
        const _riserY = bPy + _fh - _riserH;
        if (_dirtSprite2) {
            ctx.imageSmoothingEnabled = false;
            const _scale3 = TILE_SIZE / _dirtSprite2.width;
            const _srcH3 = Math.min(_dirtSprite2.height, _riserH / _scale3);
            for (let _i = 0; _i < b.w; _i++) {
                ctx.drawImage(_dirtSprite2, 0, 0, _dirtSprite2.width, _srcH3,
                    bPx + _i * TILE_SIZE, _riserY, TILE_SIZE, _riserH);
            }
        } else {
            ctx.fillStyle = '#4a3018';
            ctx.fillRect(bPx, _riserY, _fw, _riserH);
        }
    }
    if (b._buildRise > 0 && _buildDarkPct < 100) {   // oscurecido del hueco (dentro del recorte de la huella); a rise <= 0 no oscurece nada (100%)
        ctx.fillStyle = `rgba(0,0,0,${((100 - _buildDarkPct) / 100).toFixed(3)})`;
        ctx.fillRect(bPx, bPy, _fw, _fh);
    }
    ctx.restore();

    if (b._demolishing && b._buildRise >= _sinkTarget - 0.5) {
        _finalizeDemolish(b);
        return true;
    }
    return false;
}

function tryPlaceHouse(tx, ty) {
    const freeIdx = _freeBuildingQueue.indexOf('house');
    // Moving always skips this charge — the move cost was already paid up front (see
    // _tryMovePlace) — but the new building's own _free flag must reflect the ORIGINAL
    // building's status, not just "was this placement free".
    const skipCharge = freeIdx !== -1 || _isMovingBuilding;
    const isNewFree = _isMovingBuilding ? _movingBuildingWasFree : (freeIdx !== -1);
    const cost = getHouseCost();

    if ((skipCharge || (wood >= cost.wood && food >= (cost.food || 0) && wool >= (cost.wool || 0) && stone >= (cost.stone || 0) && gold >= (cost.gold || 0))) && isValidHousePlacement(tx, ty)) {
        if (!skipCharge) {
            wood  -= cost.wood;
            food  -= (cost.food  || 0);
            wool  -= (cost.wool  || 0);
            stone -= (cost.stone || 0);
            gold  -= (cost.gold  || 0);
            lifetimeStats.goldSpent += cost.gold || 0;
        } else if (!_isMovingBuilding && freeIdx !== -1) {
            _freeBuildingQueue.splice(freeIdx, 1);
        }
        buildings.push({ type: 'house', x: tx, y: ty, w: 2, h: 2, _free: isNewFree || undefined, ..._bOff() });
        if (!_isMovingBuilding) lifetimeStats.buildingsBuilt++;
        rebuildBuildingCaches();
        recalculatePopLimit();
        if (!_isMovingBuilding) {
            _totalHousesBuilt++;
            // Migración: un aldeano por cada casa por encima del máximo que había al coger la
            // habilidad (_maxHousesStanding ya incluye esta, ver rebuildBuildingCaches). NO mira la
            // población: antes exigía _popUsada() < popLimit, y una casa aislada (no suma al límite)
            // o construida por encima del tope se quedaba sin su aldeano hasta demolerla y
            // reconstruirla. Si se debía alguno de antes, llega ahora todo junto.
            if (hasSkillMigracion) {
                const cx = (tx + 1) * TILE_SIZE;
                const cy = (ty + 1) * TILE_SIZE;
                while (_maxHousesStanding - _migracionBaseline > _migracionGiven) {
                    _migracionGiven++;
                    villagers.push(new Villager(cx + (Math.random() - 0.5) * 40, cy + (Math.random() - 0.5) * 40));
                }
            }
        }
        buildMode = null;
        
        const pxWorld = tx * TILE_SIZE + TILE_SIZE;
        const pyWorld = ty * TILE_SIZE + TILE_SIZE;
        
        spawnBuildParticles(pxWorld, pyWorld);
        playBuildSound();
        updateUI();
        
        saveGame(); // Save progress immediately
    } else if (wood < cost.wood || stone < cost.stone) {
        buildMode = null;
        updateUI();
    }
}

// --- LUMBER CAMP CONSTRUCTION LOGIC ---
function getLumberCampCost() {
    const count = buildings.filter(b => b.type === 'lumber_camp').length;
    return { wood: applyBuildDiscount(100 * Math.pow(2, count)), food: 0, wool: 0, stone: 0 };
}

function startBuildLumberCamp() {
    const cost = getLumberCampCost();
    if (wood >= cost.wood) {
        buildMode = 'lumber_camp';
        updateUI();
    }
}
window.startBuildLumberCamp = startBuildLumberCamp;

function isValidLumberCampPlacement(hx, hy) {
    if (hx < 0 || hx + 1 >= MAP_SIZE || hy < 0 || hy + 1 >= MAP_SIZE) return false;
    for (let dy = 0; dy <= 1; dy++) {
        for (let dx = 0; dx <= 1; dx++) {
            const tx = hx + dx;
            const ty = hy + dy;
            const key = `${tx},${ty}`;
            if (!ownedTiles.has(key)) return false;
            if (getBuildingAt(tx, ty) !== null) return false;
        }
    }
    // Deliberately NOT requiring road adjacency here (unlike most other buildings) — pushing a
    // Lumber Camp out toward a fresh stand of trees ahead of the road reaching it is a normal
    // part of expanding, not a mistake to block. It just comes out isolated/paused like any
    // other disconnected building (see updateBuildingConnectivity — lumber_camp is NOT in
    // _ROAD_EXEMPT_TYPES, so that part is unchanged) until a road actually reaches it.
    return true;
}

function tryPlaceLumberCamp(tx, ty) {
    const cost = getLumberCampCost();
    // Moving: the cost was already charged up front by _tryMovePlace (via getMoveCost) —
    // skip charging again here, just place it.
    const canAfford = _isMovingBuilding || wood >= cost.wood;
    if (canAfford && isValidLumberCampPlacement(tx, ty)) {
        if (!_isMovingBuilding) wood -= cost.wood;
        buildings.push({ type: 'lumber_camp', x: tx, y: ty, w: 2, h: 2, ..._bOff() });
        if (!_isMovingBuilding) lifetimeStats.buildingsBuilt++;
        rebuildBuildingCaches();
        buildMode = null;

        const pxWorld = tx * TILE_SIZE + TILE_SIZE;
        const pyWorld = ty * TILE_SIZE + TILE_SIZE;

        spawnBuildParticles(pxWorld, pyWorld);
        playBuildSound();
        updateUI();

        saveGame();
    } else if (!canAfford) {
        buildMode = null;
        updateUI();
    }
}

// --- MADERERO MÓVIL CONSTRUCTION LOGIC ---
// Unlocked by the madereroMovil skill (child of aserradero). Functions exactly like a Lumber
// Camp — wood/stone dropoff, unlocks axe/pickaxe tool upgrades, gets the proximity-chop and
// sawmill-deposit bonuses (see every `|| b.type === 'maderero_movil'` alongside a lumber_camp
// check) — except it's exempt from the road-adjacency requirement (see _ROAD_EXEMPT_TYPES) and,
// being a unique building, only one can ever be built.
function getMaderoMovilCost() {
    return applyBuildDiscount({ wood: 4000, stone: 400 });
}
// Cuántos Madereros Móviles se pueden tener a la vez: uno por la habilidad y otro por el regalo de
// Legado 8 ("cuando en el Legado 8 desbloquee Maderero Móvil, entonces podré tener 2").
function _maderoMovilLimit() { return (hasSkillMadereroMovil ? 1 : 0) + (prestige.phase2Unlocked ? 1 : 0); }
function _maderoMovilCount() { return buildings.filter(b => b.type === 'maderero_movil').length; }
function startBuildMaderoMovil() {
    const hasFree = _freeBuildingQueue.includes('maderero_movil');
    if (!hasSkillMadereroMovil && !hasFree) return;
    if (_maderoMovilCount() >= _maderoMovilLimit()) return;
    const cost = getMaderoMovilCost();
    if (hasFree || (wood >= cost.wood && stone >= cost.stone)) {
        buildMode = 'maderero_movil';
        updateUI();
    }
}
window.startBuildMaderoMovil = startBuildMaderoMovil;

function isValidMaderoMovilPlacement(hx, hy) {
    if (hx < 0 || hx + 1 >= MAP_SIZE || hy < 0 || hy + 1 >= MAP_SIZE) return false;
    for (let dy = 0; dy <= 1; dy++) {
        for (let dx = 0; dx <= 1; dx++) {
            const key = `${hx + dx},${hy + dy}`;
            if (!ownedTiles.has(key)) return false;
            if (getBuildingAt(hx + dx, hy + dy) !== null) return false;
        }
    }
    return true; // exempt from the road-adjacency requirement — see _ROAD_EXEMPT_TYPES
}

function tryPlaceMaderoMovil(tx, ty) {
    const hasOne = !_isMovingBuilding && _maderoMovilCount() >= _maderoMovilLimit();
    const freeIdx = _freeBuildingQueue.indexOf('maderero_movil');
    const skipCharge = freeIdx !== -1 || _isMovingBuilding;
    const isNewFree = _isMovingBuilding ? _movingBuildingWasFree : (freeIdx !== -1);
    const cost = getMaderoMovilCost();
    const canAfford = skipCharge || (wood >= cost.wood && stone >= cost.stone);
    if (!hasOne && canAfford && isValidMaderoMovilPlacement(tx, ty)) {
        if (!skipCharge) { wood -= cost.wood; stone -= cost.stone; }
        else if (!_isMovingBuilding && freeIdx !== -1) _freeBuildingQueue.splice(freeIdx, 1);
        buildings.push({ type: 'maderero_movil', x: tx, y: ty, w: 2, h: 2, _free: isNewFree || undefined, ..._bOff() });
        if (!_isMovingBuilding) lifetimeStats.buildingsBuilt++;
        rebuildBuildingCaches();
        buildMode = null;

        const pxWorld = tx * TILE_SIZE + TILE_SIZE;
        const pyWorld = ty * TILE_SIZE + TILE_SIZE;

        spawnBuildParticles(pxWorld, pyWorld);
        playBuildSound();
        updateUI();
        saveGame();
    } else if (!canAfford || hasOne) {
        buildMode = null;
        updateUI();
    }
}
window.tryPlaceMaderoMovil = tryPlaceMaderoMovil;

// --- ESTATUA DE OFRENDAS CONSTRUCTION LOGIC --- one statue per resource type.
const _ESTATUA_COSTS = {
    madera: { wood: 30000000 },
    comida: { food: 10000000 },
    tela:   { wool: 5000000 },
    piedra: { stone: 2000000 },
};

// Footprint (tiles, always square) per variant — computed from each variant's PNG art:
// estatuamadera/estatuatela/estatuacomida.png are all 32x54 (2x2 footprint, sprite drawn
// at 2x3 tiles per the usual "+1 tile of height" convention); estatuapiedra.png is a clean
// 48x64 (3x3 footprint, sprite drawn at 3x4 tiles) — used for the grandest, final tier.
const ESTATUA_SIZE = { madera: 2, comida: 2, tela: 2, piedra: 3 };
// Sprite key in spriteCache.buildings per variant (one dedicated png each, see preloadAssets).
const ESTATUA_SPRITE = { madera: 'estatua_madera', comida: 'estatua_comida', tela: 'estatua_tela', piedra: 'estatua_piedra' };

// Whether this variant's one-time flag is already set — the real gate against building a
// second one of the same statue, checked fresh at both startBuildEstatua and tryPlaceEstatua
// (not just relied on via the shop button's `show:` condition, which only refreshes on the next
// full updateUI() and could otherwise be beaten by a fast double-click — ver tryPlaceEstatua).
function _estatuaAlreadyBuilt(variant) {
    if (variant === 'madera') return estatuaMaderaX2;
    if (variant === 'comida') return estatuaComida;
    if (variant === 'tela')   return estatuaTela;
    if (variant === 'piedra') return estatuaPiedra;
    return false;
}

function startBuildEstatua(variant) {
    if (!hasSkillEstatuaOfrenda) return;
    if (_estatuaAlreadyBuilt(variant)) return;
    buildMode = 'estatua_' + variant;
    updateUI();
}
window.startBuildEstatua = startBuildEstatua;

function isValidEstatuaPlacement(hx, hy, variant) {
    const n = ESTATUA_SIZE[variant] || 4;
    if (hx < 0 || hx + n - 1 >= MAP_SIZE || hy < 0 || hy + n - 1 >= MAP_SIZE) return false;
    for (let dy = 0; dy < n; dy++) {
        for (let dx = 0; dx < n; dx++) {
            const key = `${hx + dx},${hy + dy}`;
            if (!ownedTiles.has(key)) return false;
            if (getBuildingAt(hx + dx, hy + dy) !== null) return false;
        }
    }
    // Deliberately NOT requiring road adjacency, and fully exempt from the isolation system too
    // (see _ROAD_EXEMPT_TYPES) — same as the Well or the Ritual: a statue's bonus is passive and
    // needs no worker to walk anywhere, so there's nothing a road connection would actually do
    // for it. Always shows green in the hover preview (see _wouldBePlacementIsolated), never
    // yellow.
    return true;
}

function tryPlaceEstatua(tx, ty, variant) {
    // Skip the guard while relocating an existing statue (_isMovingBuilding): the flag stays
    // true the whole time a statue's bonus is active — including mid-move, since moveBuilding
    // splices the old copy out of `buildings` but never touches the flag — so without this
    // exception, moving a statue would always look like "already built" and silently no-op.
    if (!_isMovingBuilding && _estatuaAlreadyBuilt(variant)) return;
    if (!isValidEstatuaPlacement(tx, ty, variant)) return;
    const cost = _ESTATUA_COSTS[variant];
    if (!cost) return;
    if (!_isMovingBuilding) {
        if ((cost.wood  || 0) > wood)  return;
        if ((cost.food  || 0) > food)  return;
        if ((cost.wool  || 0) > wool)  return;
        if ((cost.stone || 0) > stone) return;
        wood  -= cost.wood  || 0;
        food  -= cost.food  || 0;
        wool  -= cost.wool  || 0;
        stone -= cost.stone || 0;
    }
    const n = ESTATUA_SIZE[variant] || 4;
    buildings.push({ type: 'estatua_' + variant, x: tx, y: ty, w: n, h: n, ..._bOff() });
    // Apply effect immediately on placement — but only for a fresh build. Moving an existing
    // one already has its one-time effect in place; re-running this would re-apply it (or just
    // harmlessly re-set an already-true flag), so skip it during a move.
    if (!_isMovingBuilding) {
        lifetimeStats.statuesBuilt++;
        if (variant === 'madera') {
            estatuaMaderaX2 = true;
        } else if (variant === 'comida') {
            const villagerGrant = 15;
            const tc = buildings.find(b => b.type === 'town_center');
            const cx = tc ? (tc.x + tc.w / 2) * TILE_SIZE : 50 * TILE_SIZE;
            const cy = tc ? (tc.y + tc.h / 2) * TILE_SIZE : 50 * TILE_SIZE;
            for (let i = 0; i < villagerGrant; i++) {
                villagers.push(new Villager(cx + (Math.random() - 0.5) * 100, cy + (Math.random() - 0.5) * 100));
            }
            estatuaComida = true;
        } else if (variant === 'tela') {
            roadStock += 50;
            estatuaTela = true;
        } else if (variant === 'piedra') {
            estatuaPiedra = true;
        }
    }
    rebuildBuildingCaches();
    buildMode = null;
    spawnBuildParticles(tx * TILE_SIZE + TILE_SIZE * n / 2, ty * TILE_SIZE + TILE_SIZE * n / 2);
    playBuildSound();
    // Full updateUI() (not _uiDirty — that lightweight path only refreshes counters, never
    // button show/hide, see its own comment at _updateCounters) so the shop button for this
    // variant hides THIS SAME FRAME, not on the next periodic refresh — with the flag-based
    // guard above this is now belt-and-braces, but the button lag was real and worth killing too.
    updateUI();
    saveGame();
}

function tryPlaceEstatuaMadera(tx, ty) { tryPlaceEstatua(tx, ty, 'madera'); }
function tryPlaceEstatuaComida(tx, ty) { tryPlaceEstatua(tx, ty, 'comida'); }
function tryPlaceEstatuaTela(tx, ty)   { tryPlaceEstatua(tx, ty, 'tela');   }
function tryPlaceEstatuaPiedra(tx, ty) { tryPlaceEstatua(tx, ty, 'piedra'); }

// --- PLAZA DISCORD: recompensa de un solo uso por unirse al Discord ---
// Es un SUELO, no un edificio — vive en su propio estado (plazaDiscordTile), ni en `buildings`
// ni en `groundDecorations`. Como las decoraciones de suelo normales, se puede colocar en
// cualquier casilla propia sin que haga falta que esté vacía de edificios (se pinta en la misma
// capa de fondo, ver la LAYER 1b2 del render — un edificio real encima simplemente se dibuja
// por delante, igual que ya pasa con tile_dirt/wood/stone). Solo bloquea si ya hay OTRO suelo
// pintado en alguna de las 9 casillas (ver isValidPlazaDiscordPlacement) — "si no hay otros
// suelos" fue el criterio pedido, literal. Gratis: lo que "paga" por ella es el código, no
// decoCoins. Solo puede haber una a la vez (ver _hasPlazaDiscordBuilt), pero borrarla no tiene
// coste — el código canjeado es permanente (ver hasPlazaDiscordCode), así que se puede volver a
// colocar gratis las veces que haga falta, incluso tras reiniciar por Legado o Reconstruir Ciudad.
const PLAZA_DISCORD_SIZE = 3;
// {x, y} = esquina superior-izquierda, o null si no hay ninguna colocada. Guardado (ver
// _buildSaveState/loadGame) — a diferencia de hasPlazaDiscordCode, esto SÍ es de esta ciudad.
let plazaDiscordTile = null;
// CAMBIA ESTO por el código real que publiques en vuestro Discord (ej. en el canal de bienvenida).
// Comparación en mayúsculas/sin espacios (ver _confirmDiscordCode) — el jugador puede escribirlo
// como quiera, no hace falta que acierte las mayúsculas exactas.
const DISCORD_PLAZA_CODE = 'TEAMAGORA';
// Global (no _slotKey) a propósito: canjear el código es una acción real del jugador en Discord,
// no algo de una ciudad concreta — se queda canjeado aunque reinicie por Legado o cree una ciudad
// nueva, igual que el resto de "esto ya lo vi/hice" de este navegador (ver _changelogSeenKey).
let hasPlazaDiscordCode = false;
function _discordCodeKey() { return 'fn_discordPlazaRedeemed'; }
function _loadDiscordCodeState() {
    try { hasPlazaDiscordCode = localStorage.getItem(_discordCodeKey()) === '1'; } catch (e) { hasPlazaDiscordCode = false; }
}
function _openDiscordCodeModal() {
    const modal = document.getElementById('discordCodeModal');
    if (modal) modal.style.display = 'flex';
}
window._openDiscordCodeModal = _openDiscordCodeModal;
function _closeDiscordCodeModal() {
    const modal = document.getElementById('discordCodeModal');
    if (modal) modal.style.display = 'none';
}
window._closeDiscordCodeModal = _closeDiscordCodeModal;
function _confirmDiscordCode() {
    const input = document.getElementById('discordCodeInput');
    if (!input) return;
    const val = (input.value || '').trim().toUpperCase().replace(/\s+/g, '');
    if (!val) return;
    if (val === DISCORD_PLAZA_CODE) {
        hasPlazaDiscordCode = true;
        try { localStorage.setItem(_discordCodeKey(), '1'); } catch (e) {}
        input.value = '';
        _closeDiscordCodeModal();
        showBuildToast(t('discord.code_success'));
        updateUI();
        // Entra directamente en modo construcción — acaba de recibirla, mejor dejarle colocarla
        // ya que hacerle volver a pulsar el mismo botón otra vez para lo mismo.
        startBuildPlazaDiscord();
    } else {
        showBuildToast(t('discord.code_invalid'));
    }
}
window._confirmDiscordCode = _confirmDiscordCode;

// Aviso único para quien lleva un rato jugando sin haberse enterado de la Plaza Discord —
// se dispara UNA sola vez EN TOTAL (no por partida ni por slot, ver _plazaInviteShownKey,
// igual de global que hasPlazaDiscordCode) la primera vez que _achPlaytimeMs() de la partida
// activa llega a 30 min sin tener aún el código canjeado. Una vez mostrado, nunca vuelve a
// salir, en ningún slot, aunque este en concreto no llegue a los 30 min o se reinicie.
let _plazaInviteShown = false;
function _plazaInviteShownKey() { return 'fn_plazaInviteShown'; }
function _loadPlazaInviteState() {
    try { _plazaInviteShown = localStorage.getItem(_plazaInviteShownKey()) === '1'; } catch (e) { _plazaInviteShown = false; }
}
// Margen tras cargar antes de poder disparar el aviso — sin esto, alguien que actualiza el
// juego con horas ya jugadas se encontraria el modal a los 3s de abrir, antes de ver siquiera
// su ciudad. Se fija en init() (ver _loadPlazaInviteState) a "ahora + 15s".
let _plazaInviteEligibleAt = Infinity;
function _maybeShowPlazaInvite() {
    if (_spectatorMode) return;
    if (_plazaInviteShown || hasPlazaDiscordCode) return;
    if (Date.now() < _plazaInviteEligibleAt) return;
    if (_achPlaytimeMs() < 30 * 60000) return;
    _plazaInviteShown = true;
    try { localStorage.setItem(_plazaInviteShownKey(), '1'); } catch (e) {}
    _openDiscordCodeModal();
}
setInterval(_maybeShowPlazaInvite, 3000);

function _hasPlazaDiscordBuilt() { return plazaDiscordTile !== null; }
function _isInsidePlazaDiscord(tx, ty) {
    if (!plazaDiscordTile) return false;
    const { x, y } = plazaDiscordTile;
    const n = PLAZA_DISCORD_SIZE;
    return tx >= x && tx < x + n && ty >= y && ty < y + n;
}

function isValidPlazaDiscordPlacement(hx, hy) {
    const n = PLAZA_DISCORD_SIZE;
    if (hx < 0 || hx + n - 1 >= MAP_SIZE || hy < 0 || hy + n - 1 >= MAP_SIZE) return false;
    for (let dy = 0; dy < n; dy++)
        for (let dx = 0; dx < n; dx++) {
            const key = `${hx + dx},${hy + dy}`;
            if (!ownedTiles.has(key)) return false;
            // Sin comprobar getBuildingAt a propósito — es un suelo, puede convivir con un
            // edificio real encima igual que tile_dirt/wood/stone (ver isValidGroundDecoPlacement,
            // que tampoco lo comprueba). Bloquea solo si ya hay OTRO suelo pintado aquí.
            if (groundDecorations.has(key)) return false;
        }
    return true; // sin adyacencia a carretera — es un suelo, igual que el resto de GROUND_DECO_TYPES
}

function startBuildPlazaDiscord() {
    if (_hasPlazaDiscordBuilt()) return;
    // Sin el código todavía, el botón es la propia promoción: abre el modal en vez de entrar en
    // modo construcción (ver _confirmDiscordCode, que llama a esta misma función al acertar).
    if (!hasPlazaDiscordCode) { _openDiscordCodeModal(); return; }
    buildMode = 'plaza_discord';
    updateUI();
}
window.startBuildPlazaDiscord = startBuildPlazaDiscord;

function tryPlacePlazaDiscord(tx, ty) {
    if (!hasPlazaDiscordCode || _hasPlazaDiscordBuilt()) return;
    if (!isValidPlazaDiscordPlacement(tx, ty)) return;
    const n = PLAZA_DISCORD_SIZE;
    plazaDiscordTile = { x: tx, y: ty };
    buildMode = null;
    spawnBuildParticles(tx * TILE_SIZE + TILE_SIZE * n / 2, ty * TILE_SIZE + TILE_SIZE * n / 2);
    playBuildSound();
    updateUI();
    saveGame();
}

// Borrado: no hay panel de selección (no está en `buildings`), así que se erasea con la misma
// herramienta que las decoraciones de suelo — ver tryEraseDecoration, que llama aquí cuando la
// casilla pulsada cae dentro de las 3×3 de plazaDiscordTile. Gratis quitarla igual que ponerla.
function _erasePlazaDiscordAt(tx, ty) {
    if (!_isInsidePlazaDiscord(tx, ty)) return false;
    plazaDiscordTile = null;
    saveGame();
    updateUI();
    return true;
}

// --- SHEEP FARM CONSTRUCTION LOGIC ---
// Sheep farm cost: 1000 wood + 500 food, both scale x1.25 per extra sheep farm
function getSheepFarmCost(nOverride) {
    const count = nOverride ?? _paidCountForType('sheep_farm');
    return applyBuildDiscount({
        wood: Math.round(1000 * Math.pow(1.5, count)),
        food: Math.round(500 * Math.pow(1.5, count))
    });
}

function startBuildSheepFarm() {
    const hasFreeSheepFarm = _freeBuildingQueue.includes('sheep_farm');
    // "si me dan un edificio gratis pero aún no lo tengo para comprar, con Ctrl me deja colocar
    // más de una" — mismo motivo que startBuildHouse: el botón se oculta con villagers.length<15,
    // pero eso no protege una llamada directa (ver _startBuildAgain).
    if (villagers.length < 15 && !hasFreeSheepFarm) return;
    const cost = getSheepFarmCost();
    if (hasFreeSheepFarm || (wood >= cost.wood && food >= cost.food)) {
        buildMode = 'sheep_farm';
        updateUI();
    }
}
window.startBuildSheepFarm = startBuildSheepFarm;

function isValidSheepFarmPlacement(hx, hy) {
    if (hx < 0 || hx + 3 >= MAP_SIZE || hy < 0 || hy + 3 >= MAP_SIZE) return false;
    for (let dy = 0; dy <= 3; dy++) {
        for (let dx = 0; dx <= 3; dx++) {
            const tx = hx + dx;
            const ty = hy + dy;
            const key = `${tx},${ty}`;
            if (!ownedTiles.has(key)) return false;
            if (getBuildingAt(tx, ty) !== null) return false;
        }
    }
    // Deliberately NOT requiring road adjacency (like lumber_camp/forest_farm) — a production
    // building can push out toward the land it needs before a road actually reaches it. It just
    // comes out isolated/paused like any other disconnected building (see
    // updateBuildingConnectivity) until one does — see the hover-preview's yellow warning for
    // exactly this case (_wouldBePlacementIsolated).
    return true;
}

function tryPlaceSheepFarm(tx, ty) {
    const freeIdx = _freeBuildingQueue.indexOf('sheep_farm');
    const skipCharge = freeIdx !== -1 || _isMovingBuilding;
    const isNewFree = _isMovingBuilding ? _movingBuildingWasFree : (freeIdx !== -1);
    const cost = getSheepFarmCost();
    if ((skipCharge || (wood >= cost.wood && food >= cost.food)) && isValidSheepFarmPlacement(tx, ty)) {
        if (!skipCharge) { wood -= cost.wood; food -= cost.food; }
        else if (!_isMovingBuilding && freeIdx !== -1) _freeBuildingQueue.splice(freeIdx, 1);
        buildings.push({ type: 'sheep_farm', x: tx, y: ty, w: 4, h: 4, _free: isNewFree || undefined, ..._bOff() });
        if (!_isMovingBuilding) lifetimeStats.buildingsBuilt++;
        rebuildBuildingCaches();
        buildMode = null;
        const pxWorld = tx * TILE_SIZE + TILE_SIZE * 2;
        const pyWorld = ty * TILE_SIZE + TILE_SIZE * 2;
        spawnBuildParticles(pxWorld, pyWorld);
        playBuildSound();
        updateUI();
        saveGame();
    } else if (wood < cost.wood || food < cost.food) {
        buildMode = null;
        updateUI();
    }
}

// --- WELL CONSTRUCTION LOGIC ---
function getWellCost(nOverride) {
    const count = nOverride ?? _paidCountForType('well');
    return applyBuildDiscount({ stone: Math.round(200 * Math.pow(2, count)) });
}

// --- MAR (fuera del 100×100) -----------------------------------------------------------------
// Todo lo que queda fuera del mapa se pinta como océano. Antes era negro liso (y antes de eso una
// textura de muralla), así que el mundo parecía flotar en el vacío en vez de ser una isla.
//
// La textura se genera EN CÓDIGO, no se carga: un PNG más solo para esto no vale la pena, y así
// no hay un asset que pueda faltar. Si algún día existe assets/sea.png (ver preloadAssets), se usa
// ese en su lugar sin tocar nada de aquí.
//
// Se construye una sola vez y se reutiliza como CanvasPattern, así que el coste por frame sigue
// siendo el mismo que el relleno plano de antes: un único fill() con todos los rectángulos.
// Niebla de guerra del mar. Mismo radio que el de tierra (_visRadius en recalculateVisibility),
// para que la costa no tenga dos reglas distintas según de qué lado la mires.
const SEA_FOG_RADIUS = 3;
const SEA_FOG = '#060d14';

// ¿Se ve esta casilla de mar? Una sola búsqueda en ownedTiles, no un barrido del vecindario.
//
// El truco: la casilla está FUERA del mapa por definición, así que su vecina de tierra más
// cercana es siempre la misma — la que sale de recortar sus coordenadas al 100×100. Si esa es
// tuya y no está más lejos que el radio, se ve. Comprobar un vecindario 7×7 habrían sido 49
// búsquedas por casilla y por frame, y con el mapa alejado eso son miles de casillas.
function _seaTileRevealed(x, y, dock) {
    // Sin Fase 2 no hay mar (ver PHASE2_ENABLED): fuera del 100x100 todo negro, como en la v014.
    if (!PHASE2_ENABLED) return false;
    if (_dbgRevealAll) return true;   // F9: ver todo el mapa
    const cx = x < 0 ? 0 : (x >= MAP_SIZE ? MAP_SIZE - 1 : x);
    const cy = y < 0 ? 0 : (y >= MAP_SIZE ? MAP_SIZE - 1 : y);
    const dist = Math.max(Math.abs(x - cx), Math.abs(y - cy));
    if (dist <= SEA_FOG_RADIUS && ownedTiles.has(`${cx},${cy}`)) return true;
    // La casilla del borde es agua (el río llega al borde): el agua no se reclama, así que vale una casilla tuya a su lado
    if (dist <= SEA_FOG_RADIUS && _isWaterTile(cx, cy)) {
        for (let j = -1; j <= 1; j++) for (let i = -1; i <= 1; i++) if ((i || j) && ownedTiles.has(`${cx + i},${cy + j}`)) return true;
    }
    // El dique seco alumbra su propio entorno: ocupa 8 casillas mar adentro, más de lo que llega
    // el radio desde la costa, así que sin esto se construiría dentro de la niebla y no se vería
    // ni él ni el barco.
    if (dock && x >= dock.x - SEA_FOG_RADIUS && x < dock.x + dock.w + SEA_FOG_RADIUS &&
                y >= dock.y - SEA_FOG_RADIUS && y < dock.y + dock.h + SEA_FOG_RADIUS) return true;
    // El Faro (conectado) alumbra el mar en su alcance — solo el agua, no la montaña.
    if (_lighthouseLitAt(x, y) && !(_world().mountains && _isMountainTile(x, y))) return true;
    return false;
}
// --- LAS PUERTAS (mundos con gates: true, hoy el 2) ---------------------------------------------------------
// ¿Qué estás buscando aquí? Esto es decoración y nada más: unas puertas en el centro del borde norte, en la montaña, y un panel que
// pide una contraseña "para desbloquear el mundo 3". No hay contraseña, ni hash, ni mundo 3 escondido detrás: lo que se escriba no se
// compara con nada ni se envía a ningún sitio. Deja de atropellar al dev. :-)
// (What are you looking for in here? It's just scenery: no password, no hash, no hidden world behind. Stop running over the dev. :-))
function _gatesOn() { return !!_world().gates; }
const GATE_TILES_W = 6, GATE_TILES_H = 1.5;   // 6 casillas de ancho por 1,5 de alto (dos torreones y las hojas en medio), apoyadas en el borde norte del mapa
function _gateRect() {
    const x0 = (MAP_SIZE / 2 - GATE_TILES_W / 2) * TILE_SIZE;
    return { x0, x1: x0 + GATE_TILES_W * TILE_SIZE, y0: -GATE_TILES_H * TILE_SIZE, y1: 0 };
}
// Solo se ven (y se pueden pulsar) cuando la montaña de detrás está descubierta, como todo lo que hay fuera del mapa
function _gateVisible() {
    if (!_gatesOn()) return false;
    const cx = MAP_SIZE / 2 - 1, dock = _dryDock();
    // las dos casillas del centro y las de los torreones de los extremos, en la fila de montaña pegada al mapa
    return _seaTileRevealed(cx, -1, dock) && _seaTileRevealed(cx + 1, -1, dock) && _seaTileRevealed(cx - 2, -1, dock) && _seaTileRevealed(cx + 3, -1, dock);
}
function _gateHit(wx, wy) {
    const r = _gateRect();
    return wx >= r.x0 && wx <= r.x1 && wy >= r.y0 && wy <= r.y1 && _gateVisible();
}
let _gateSprite = null;
// Dibujo en píxeles nativos (96×24 = 6×1,5 casillas a 16 px), pintado una vez y ampliado ×4 sin difuminar: dos torreones de piedra
// con almenas en los extremos, un muro con arco en medio y las hojas de madera con herrajes y una cerradura dorada.
function _buildGateSprite() {
    const W = 96, H = 24, c = document.createElement('canvas');
    c.width = W; c.height = H;
    const g = c.getContext('2d');
    const px = (col, x, y, w = 1, h = 1) => { g.fillStyle = col; g.fillRect(x, y, w, h); };
    const ST = '#55545a', STL = '#6f6e75', STD = '#3d3c42', WD = '#6b4423', WDL = '#7f5530', WDD = '#4a2f17', FE = '#2c2c32', RV = '#9a9aa3', GO = '#c9a55a', DARK = '#1a1410';
    // torreones (16 de ancho) con almenas arriba y sillares
    for (const x0 of [0, 80]) {
        px(ST, x0, 3, 16, 21); px(STL, x0, 3, 16, 1); px(STL, x0, 3, 1, 21); px(STD, x0 + 15, 3, 1, 21);
        for (let x = x0; x < x0 + 16; x += 6) { px(ST, x, 0, 4, 3); px(STL, x, 0, 4, 1); px(STD, x + 3, 0, 1, 3); }
        for (let y = 7; y < 24; y += 4) px(STD, x0, y, 16, 1);
        for (let y = 7; y < 24; y += 8) for (let x = x0 + 4; x < x0 + 16; x += 8) px(STD, x, y - 3, 1, 3);
        px(DARK, x0 + 6, 9, 4, 5); px(STD, x0 + 6, 9, 4, 1);   // aspillera
    }
    // muro entre torreones y arco sobre las puertas
    px(ST, 16, 4, 64, 20); px(STL, 16, 4, 64, 1);
    for (let y = 8; y < 24; y += 4) px(STD, 16, y, 64, 1);
    for (let x = 22; x < 76; x += 6) px(STD, x, 5, 1, 3);   // dovelas del arco
    // hueco en arco (esquinas de arriba cortadas) y hojas
    px(DARK, 24, 8, 48, 16);
    px(WD, 25, 9, 46, 15);
    px(DARK, 24, 8, 3, 2); px(DARK, 69, 8, 3, 2);   // esquinas
    px(ST, 24, 7, 48, 1); px(STL, 28, 6, 40, 1);    // el arco (clave más alta)
    for (let x = 26; x < 70; x += 3) px(WDD, x, 9, 1, 15);   // tablas
    px(WDL, 25, 9, 46, 1);
    px('#241408', 47, 9, 2, 15);                      // juntura central
    for (const y of [13, 20]) { px(FE, 25, y, 46, 2); for (let x = 28; x < 70; x += 5) px(RV, x, y, 1, 1); }   // herrajes
    px(GO, 44, 16, 1, 2); px(GO, 51, 16, 1, 2);       // aldabones
    px(GO, 46, 14, 4, 5); px('#1a1208', 47, 15, 2, 2); px('#1a1208', 47, 17, 1, 1);   // cerradura
    px(STD, 24, 23, 48, 1);                           // umbral
    return c;
}
function _drawWorldGates(c) {
    if (!_gateVisible()) return;
    if (!_gateSprite) _gateSprite = _buildGateSprite();
    const r = _gateRect();
    c.save();
    c.imageSmoothingEnabled = false;
    c.drawImage(_gateSprite, r.x0, r.y0, r.x1 - r.x0, r.y1 - r.y0);
    // brillo suave en la cerradura: la única señal de que "algo" hay (no lo hay)
    const k = TILE_SIZE / 16, gx = r.x0 + 48 * k, gy = r.y0 + 16.5 * k;
    const glow = c.createRadialGradient(gx, gy, 0, gx, gy, 5 * k);
    const a = 0.18 + 0.12 * Math.sin(performance.now() / 700);
    glow.addColorStop(0, 'rgba(255,220,120,' + a.toFixed(3) + ')'); glow.addColorStop(1, 'rgba(255,220,120,0)');
    c.fillStyle = glow; c.fillRect(gx - 5 * k, gy - 5 * k, 10 * k, 10 * k);
    c.restore();
}
let _gateTries = 0;
function _openGatePanel() {
    if (document.getElementById('gatePanel')) return;
    const ov = document.createElement('div');
    ov.id = 'gatePanel';
    ov.style.cssText = 'position:fixed;inset:0;z-index:99000;background:rgba(0,0,0,.72);display:flex;align-items:center;justify-content:center;padding:20px;';
    ov.innerHTML =
        '<div style="background:var(--panel-bg-gradient);border:2px ridge #8b6914;border-radius:10px;padding:22px 26px;max-width:360px;width:100%;text-align:center;">' +
            '<div style="font-family:\'Cinzel\',serif;font-size:19px;color:#c8a050;margin-bottom:12px;"><i class="fa-solid fa-door-closed"></i> ' + t('gate.title') + '</div>' +
            '<div style="color:#e8d5a0;font-size:14px;line-height:1.5;margin-bottom:14px;">' + t('gate.prompt') + '</div>' +
            '<input id="gateInput" type="text" autocomplete="off" spellcheck="false" maxlength="40" placeholder="' + t('gate.placeholder') + '" ' +
                'style="width:100%;box-sizing:border-box;padding:8px 10px;margin-bottom:10px;border:1px solid #8b6914;border-radius:5px;background:rgba(0,0,0,.45);color:#f2e6cf;font-size:14px;-webkit-text-security:disc;">' +
            '<div id="gateMsg" style="min-height:18px;color:#a89878;font-size:12px;font-style:italic;margin-bottom:10px;"></div>' +
            '<div style="display:flex;gap:8px;">' +
                '<button id="gateSay" class="menu-btn" style="flex:1;padding:8px;">' + t('gate.say') + '</button>' +
                '<button id="gateClose" class="menu-btn menu-btn-secondary" style="flex:1;padding:8px;">' + t('gate.close') + '</button>' +
            '</div>' +
        '</div>';
    document.body.appendChild(ov);
    const input = ov.querySelector('#gateInput'), msg = ov.querySelector('#gateMsg');
    const close = () => { document.removeEventListener('keydown', onKey, true); ov.remove(); };
    // ¿Qué estás buscando aquí? No se mira lo escrito: da igual qué pongas, las puertas no abren nada. Deja de atropellar al dev. :-)
    const say = () => { msg.textContent = t('gate.silence' + (1 + (_gateTries++ % 3))); input.value = ''; input.focus(); };
    const onKey = e => { if (e.key === 'Escape') { e.stopPropagation(); close(); } else if (e.key === 'Enter' && document.activeElement === input) { e.stopPropagation(); say(); } };
    document.addEventListener('keydown', onKey, true);
    ov.querySelector('#gateSay').onclick = say;
    ov.querySelector('#gateClose').onclick = close;
    ov.addEventListener('mousedown', e => { if (e.target === ov) close(); });
    setTimeout(() => input.focus(), 30);
}

// --- AGUA EN PIXEL ART: mar con olas largas que van hacia la orilla, río de color de orilla con corriente hacia abajo ---
// Texturas generadas en código (nada de assets/sea.png: ya no se pide, daba 'Missing resource' en CrazyGames).
//  · MAR: azul oscuro liso (SEA_DEEP) y, en las 2 casillas pegadas a la costa, un azul más claro (SEA_LIGHT). Las OLAS se pintan
//    en cada fotograma sobre el mar de fuera del mapa (_paintSeaWaves): rayas largas de 1 píxel nativo de alto, apenas más claras que
//    el fondo, que van acercándose a la orilla de píxel en píxel y aparecen y se apagan poco a poco (sin saltos ni teletransportes:
//    nacen y mueren con la opacidad a cero). Todo se sortea de nuevo en cada ciclo (hash de casilla y número de ciclo): nunca se repite el dibujo.
//  · RÍO: del mismo azul claro de la orilla, sin olas. La corriente son rayitas verticales casi transparentes que bajan despacio:
//    se pintan en cada fotograma sobre el agua visible (_paintRiverFlow); el suelo cacheado es el azul liso.
const SEA_DEEP    = '#123049';
const SEA_LIGHT   = '#235c85';
const WATER_NATIVE = 64;
const SEA_SHORE_TILES = 2;       // casillas de mar claro pegadas a la costa
const RIVER_FLOW_MS = 150;       // la corriente avanza 1 píxel nativo cada tanto
const WAVE_CELL = 2;             // una ola posible por cada WAVE_CELL×WAVE_CELL casillas de mar
const WAVE_TRAVEL = 128;         // lo que avanza cada ola hacia la orilla durante su vida (px de mundo)
const _waterTexCache = {};
function _waterTex(kind) {
    if (_waterTexCache[kind]) return _waterTexCache[kind];
    const N = WATER_NATIVE;
    const c = document.createElement('canvas');
    c.width = c.height = N;
    const g = c.getContext('2d');
    let seed = 777;
    const rnd = () => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; };
    if (kind === 'river') {
        g.fillStyle = SEA_LIGHT; g.fillRect(0, 0, N, N);   // azul liso de orilla, sin olas
    } else {
        // 'flow': solo la corriente, sobre transparente: rayitas verticales de 4-7 px, muy tenues
        for (let k = 0; k < 14; k++) {
            const x = Math.floor(rnd() * N), y = Math.floor(rnd() * N), len = 4 + Math.floor(rnd() * 4);
            g.fillStyle = k % 2 ? 'rgba(190,225,245,0.13)' : 'rgba(190,225,245,0.08)';
            for (let i = 0; i < len; i++) g.fillRect(x, (y + i) % N, 1, 1);
        }
    }
    // Ampliado ×4 con el vecino más cercano (píxeles nítidos); sin escalar luego el pattern
    const k = TILE_SIZE / 16, o = document.createElement('canvas');
    o.width = o.height = N * k;
    const og = o.getContext('2d');
    og.imageSmoothingEnabled = false;
    og.drawImage(c, 0, 0, o.width, o.height);
    return (_waterTexCache[kind] = o);
}
let _riverPat = null, _riverPatCtx = null, _flowPat = null, _flowPatCtx = null;
// Relleno del mar: liso. shore = el azul claro de las casillas pegadas a la costa
function _getSeaPattern(ctx2, shore = false) { return shore ? SEA_LIGHT : SEA_DEEP; }
// Pattern del río (azul liso y quieto), para el agua bajo los puentes
function _getRiverPattern(ctx2) {
    if (_riverPatCtx !== ctx2) { _riverPatCtx = ctx2; _riverPat = ctx2.createPattern(_waterTex('river'), 'repeat'); }
    return _riverPat;
}
// Corriente del río: rayitas que bajan, sobre el agua visible (sin los puentes ni la cara de la orilla, que va en el suelo cacheado)
function _paintRiverFlow(c, x0, x1, y0, y1) {
    const N = MAP_SIZE, T = TILE_SIZE;
    if (_flowPatCtx !== c) { _flowPatCtx = c; _flowPat = c.createPattern(_waterTex('flow'), 'repeat'); }
    if (!_flowPat || !_flowPat.setTransform) return;
    _flowPat.setTransform(new DOMMatrix().translate(0, (Math.floor(performance.now() / RIVER_FLOW_MS) % WATER_NATIVE) * (T / 16)));
    c.fillStyle = _flowPat;
    c.beginPath();
    let any = false;
    for (let y = Math.max(0, y0); y <= Math.min(N - 1, y1); y++) for (let x = Math.max(0, x0); x <= Math.min(N - 1, x1); x++) {
        const i = y * N + x;
        if (waterVisMask[i] !== 1 || bridgeMask[i]) continue;
        const cliff = y > 0 && waterVisMask[i - N] !== 1 ? CLIFF_FACE_H : 0;   // con tierra al norte asoma su cara: ahí no
        c.rect(x * T, y * T + cliff, T, T - cliff);
        any = true;
    }
    if (any) c.fill();
}
// Hash determinista (0..1) de una casilla de olas y un número de parámetro
function _waveHash(a, b, p) {
    let h = Math.imul(a, 374761393) ^ Math.imul(b, 668265263) ^ Math.imul(p, 1274126177);
    h = Math.imul(h ^ (h >>> 13), 1274126177);
    return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}
// Olas del mar de fuera del mapa. rev[(y-ry0)*(rx1-rx0+1)+(x-rx0)] = 1 en las casillas de mar visibles (ver LAYER 0).
function _paintSeaWaves(c, rx0, ry0, rx1, ry1, rev) {
    const T = TILE_SIZE, PX = T / 16, rw = rx1 - rx0 + 1, now = performance.now();
    // hacia dónde está la orilla desde el mar: costa sur -> las olas suben, etc.
    const coast = _world().coast || 'S';
    const dx = coast === 'W' ? 1 : coast === 'E' ? -1 : 0, dy = coast === 'S' ? -1 : coast === 'N' ? 1 : 0;
    const crestH = dy !== 0;   // la cresta es perpendicular al avance: horizontal si suben/bajan
    c.save();
    c.fillStyle = 'rgb(170,214,242)';
    const cx0 = Math.floor(rx0 / WAVE_CELL), cx1 = Math.floor(rx1 / WAVE_CELL), cy0 = Math.floor(ry0 / WAVE_CELL), cy1 = Math.floor(ry1 / WAVE_CELL);
    for (let cy = cy0; cy <= cy1; cy++) for (let cx = cx0; cx <= cx1; cx++) {
        // Cada casilla de olas va por ciclos (de 8 a 14 s); en CADA ciclo todo se vuelve a sortear: si hay ola o no (60%), dónde cae
        // dentro de la casilla, lo larga que es y en qué momento del ciclo nace. Así nunca se repite el mismo dibujo.
        const period = 8000 + _waveHash(cx, cy, 5) * 6000;
        const ph = now / period + _waveHash(cx, cy, 6), n = Math.floor(ph), local = ph - n;
        const hx = cx + n * 131, hy = cy - n * 57;   // semilla de este ciclo
        if (_waveHash(hx, hy, 1) > 0.6) continue;
        const start = _waveHash(hx, hy, 7) * 0.4, u = (local - start) / 0.6;   // dura el 60% del ciclo, empezando en un momento al azar
        if (u < 0 || u > 1) continue;
        const len = (10 + Math.floor(_waveHash(hx, hy, 2) * 13)) * PX;       // 10-22 px nativos: largas
        const bx = (cx + _waveHash(hx, hy, 3)) * WAVE_CELL * T, by = (cy + _waveHash(hx, hy, 4)) * WAVE_CELL * T;
        const a = Math.pow(Math.sin(Math.PI * u), 1.6) * 0.22;               // sube y baja la opacidad, suave
        if (a < 0.01) continue;
        const travel = (u - 0.5) * WAVE_TRAVEL;                              // avanza hacia la orilla, de píxel en píxel
        const x = Math.round((bx + dx * travel) / PX) * PX, y = Math.round((by + dy * travel) / PX) * PX;
        const tx = Math.floor(x / T), ty = Math.floor(y / T);
        if (tx < rx0 || tx > rx1 || ty < ry0 || ty > ry1 || !rev[(ty - ry0) * rw + (tx - rx0)]) continue;   // solo sobre mar visible
        c.globalAlpha = a;
        if (crestH) c.fillRect(x, y, len, PX); else c.fillRect(x, y, PX, len);
    }
    c.restore();
}

// Complejo Maderero: una Plantacion Forestal cuenta si toca un Aserradero. Mismo test de huella que
// getFarmWellMultiplier de aqui abajo (recorre las casillas del recinto y mira si el otro edificio
// queda a un tile), porque la plantacion es 12x12 y su "posicion" a secas no dice nada util.
// El aserradero aislado no cuenta: un edificio desconectado no produce, y esto es un bonus suyo.
function _isForestFarmBySawmill(ff) {
    if (!ff) return false;
    // Solape de RECTANGULOS con un tile de margen, no "la esquina del aserradero cerca de una casilla
    // de la plantacion". Esto se copio de getFarmWellMultiplier y ahi la cuenta corta vale porque el
    // POZO es 1x1: comparar su unica casilla ES comparar el edificio entero. El Aserradero es 4x4, asi
    // que mirar solo su x/y (su esquina superior izquierda) dejaba fuera todos los casos en que toca
    // con su borde derecho o inferior — el origen queda hasta 3 tiles lejos y no se detectaba.
    // Mismo idioma que ya usa la adyacencia entre huertos (ver cachedOrchardAdjMap).
    return buildings.some(b =>
        b.type === 'sawmill' && !b._isolated &&
        b.x < ff.x + ff.w + 1 && b.x + b.w > ff.x - 1 &&
        b.y < ff.y + ff.h + 1 && b.y + b.h > ff.y - 1);
}
// Tope de lenadores de UNA plantacion concreta. Existe como funcion y no como dos constantes
// sueltas porque lo consultan dos sitios muy separados —el reparto de trabajadores y la ficha del
// edificio— y si se desincronizan la ficha miente sobre cuanta gente cabe.
function _forestFarmWorkerCap(ff) {
    return (hasSkillComplejoMaderero && cachedForestSawmillAdj.has(ff)) ? FOREST_FARM_WORKERS * 2 : FOREST_FARM_WORKERS;
}
function getFarmWellMultiplier(farm) {
    if (!farm) return 1;
    return buildings.some(b => {
        if (b.type !== 'well') return false;
        for (let fy = farm.y; fy < farm.y + farm.h; fy++) {
            for (let fx = farm.x; fx < farm.x + farm.w; fx++) {
                if (Math.abs(b.x - fx) <= 1 && Math.abs(b.y - fy) <= 1) return true;
            }
        }
        return false;
    }) ? 3 : 1;
}

function startBuildWell() {
    if (!_worldHasBuilding('well')) return;
    const hasFreeWell = _freeBuildingQueue.includes('well');
    if (!hasSkillHidraulica && !hasFreeWell) return;
    const cost = getWellCost();
    if (hasFreeWell || stone >= cost.stone) {
        buildMode = 'well';
        updateUI();
    }
}
window.startBuildWell = startBuildWell;

function isFarmAdjacentToWell(farm) {
    for (const w of buildings) {
        if (w.type !== 'well') continue;
        for (let fy = farm.y; fy < farm.y + farm.h; fy++)
            for (let fx = farm.x; fx < farm.x + farm.w; fx++)
                if (Math.abs(w.x - fx) <= 1 && Math.abs(w.y - fy) <= 1) return true;
    }
    return false;
}

// --- COSMETIC DECORATIONS (see DECO_TYPES up top) --- one generic pair instead of one near-
// identical function per type: every type shares the exact same placement rule (owned + empty, no road/
// adjacency requirement — same exemption as well/watchtower, see _ROAD_EXEMPT_TYPES), just
// priced individually via DECO_COSTS (decoCoins, not resources — see that constant's own
// comment). Moving an already-placed one goes through the shared _tryMovePlace path (see
// _handleCanvasTap's own moveBuilding-first branch and _tryMovePlace's DECO_TYPES fallback for
// its placeFns lookup) same as every other building type — this still needs to know about
// _isMovingBuilding itself though, same as tryPlaceWell etc., so a move doesn't get charged twice.
function isValidDecorationPlacement(tx, ty, decoType) {
    const sz = _decoSize(decoType);
    for (let j = 0; j < sz.h; j++) for (let i = 0; i < sz.w; i++) {
        const x = tx + i, y = ty + j;
        if (x < 0 || x >= MAP_SIZE || y < 0 || y >= MAP_SIZE) return false;
        if (!ownedTiles.has(`${x},${y}`)) return false;
        if (getBuildingAt(x, y) !== null) return false;
    }
    return true;
}
function tryPlaceDecoration(tx, ty, decoType) {
    const cost = DECO_COSTS[decoType] || 0;
    // _isMovingBuilding: same convention every other tryPlaceX uses (see tryPlaceWell) — a move
    // already owns the thing being relocated, so it skips the charge/lifetime-stat entirely
    // instead of buying it a second time.
    const canAfford = _isMovingBuilding || decoCoins >= cost;
    if (!DECO_TYPES.includes(decoType) || !canAfford) {
        buildMode = null;
        updateUI();
        return;
    }
    // Invalid TILE (occupied/not owned) is its own, separate no-op — buildMode is deliberately
    // left untouched here, same convention as tryPlaceWell: a normal in-progress placement stays
    // in build mode so the player can just tap a different tile, and during a move this is what
    // lets _tryMovePlace's buildMode===null success check correctly see a failure and run its
    // restore-and-refund fallback instead of silently deleting the decoration (the actual bug
    // reported: moving one onto an already-built tile made it vanish with no decoCoins back).
    if (!isValidDecorationPlacement(tx, ty, decoType)) return;
    if (!_isMovingBuilding) { decoCoins -= cost; _decoCoinsUsed += cost; }
    const _dsz = _decoSize(decoType);
    buildings.push({ type: decoType, x: tx, y: ty, w: _dsz.w, h: _dsz.h, ..._bOff(), ...(decoType === 'deco_bandera' && _flagDesignNext !== 'h' ? { design: _flagDesignNext } : {}), ...(_isCandle(decoType) && _decoSeedNext ? { seed: _decoSeedNext } : {}), ...(_decoFlippable(decoType) && _decoFlipNext ? { flip: true } : {}), ...(DECO_EDGE_KIND[decoType] && _decoEdgeOf(decoType, _decoEdgeNext) !== DECO_EDGES[DECO_EDGE_KIND[decoType]][0] ? { edge: _decoEdgeOf(decoType, _decoEdgeNext) } : {}) });
    if (!_isMovingBuilding) lifetimeStats.buildingsBuilt++;
    rebuildBuildingCaches();
    buildMode = null;
    const px = tx * TILE_SIZE + TILE_SIZE * _dsz.w / 2;
    const py = ty * TILE_SIZE + TILE_SIZE * _dsz.h / 2;
    spawnBuildParticles(px, py);
    playBuildSound();
    updateUI();
    saveGame();
    savePrestige();
}
// Voltear decoraciones: b.flip, solo cambia el dibujo. No se voltean las velas (cada casilla ya sale distinta) ni las farolas, que
// no son edificios y tienen lo suyo (LAMP_FLIPPABLE). _decoFlipNext: cómo saldrá la próxima de _decoFlipType.
const DECO_NO_FLIP = new Set(['deco_vela', 'deco_vela_pocas']);
let _decoFlipNext = false, _decoFlipType = null, _decoFlipHinted = true;   // aviso apagado: lo explica el panel de controles
// Muros y pilares van en un borde de la casilla. El primer lado de cada lista es el de por defecto (b.edge sin poner).
