// --- FARM CONSTRUCTION LOGIC ---
function getFarmCost() {
    const count = buildings.filter(b => b.type === 'farm').length;
    return { wood: applyBuildDiscount(Math.round(250 * Math.pow(1.5, count))), food: 0, wool: 0, stone: 0 };
}

function startBuildFarm() {
    const cost = getFarmCost();
    if (wood >= cost.wood) {
        buildMode = 'farm';
        updateUI();
    } else {
        const cx = cameraX;
        const cy = cameraY;
    }
}
window.startBuildFarm = startBuildFarm;

function isValidFarmPlacement(hx, hy) {
    if (hx < 0 || hx + 2 >= MAP_SIZE || hy < 0 || hy + 2 >= MAP_SIZE) return false;
    for (let dy = 0; dy <= 2; dy++) {
        for (let dx = 0; dx <= 2; dx++) {
            const tx = hx + dx;
            const ty = hy + dy;
            const key = `${tx},${ty}`;
            if (!ownedTiles.has(key)) return false;
            if (getBuildingAt(tx, ty) !== null) return false;
        }
    }
    // Deliberately NOT requiring road adjacency (like lumber_camp/forest_farm) — a production
    // building can push out toward the land it needs before a road actually reaches it. It just
    // comes out isolated/paused like any other disconnected building (see
    // updateBuildingConnectivity) until one does — see the hover-preview's yellow warning for
    // exactly this case (_wouldBePlacementIsolated).
    return true;
}

function tryPlaceFarm(tx, ty) {
    const cost = getFarmCost();
    const canAfford = _isMovingBuilding || wood >= cost.wood;
    if (canAfford && isValidFarmPlacement(tx, ty)) {
        if (!_isMovingBuilding) wood -= cost.wood;
        buildings.push({ type: 'farm', x: tx, y: ty, w: 3, h: 3, ..._bOff() });
        if (!_isMovingBuilding) lifetimeStats.buildingsBuilt++;
        rebuildBuildingCaches();
        buildMode = null;

        const pxWorld = tx * TILE_SIZE + TILE_SIZE * 1.5;
        const pyWorld = ty * TILE_SIZE + TILE_SIZE * 1.5;

        spawnBuildParticles(pxWorld, pyWorld);
        playBuildSound();
        updateUI();

        saveGame();
    } else if (!canAfford) {
        buildMode = null;
        updateUI();
    }
}

// --- ZANJAS DE RIEGO (habilidad Zanja, mundos con río) ---------------------------------------
// Una zanja es una casilla de tu tierra, tocando el río u otra zanja. No cuesta recursos: cuesta
// TRABAJO — 2 aldeanos cavando 2 minutos, ×1.5 por cada zanja de distancia al río (dist). Mientras
// se cava es un agujero de tierra; cavada, es un canal azul y amplía el riego: la tierra a 1 casilla
