            const _vacios = villagers.filter(v => v.farmTarget === dock && _isShipWorker(v) && !v._shipCarry).length;
            const _mulasVacias = mules.filter(m => m._dockTarget === dock && _isShipMule(m) && !m._shipCarry).length;
            const comprometido = _vacios * _shipCarryAmount() + _mulasVacias * _shipCarryAmount() * DOCK_MULE_LITRES_MULT;
