                    const dCX = (dock.x + dock.w * 0.5) * TILE_SIZE, dCY = (dock.y + dock.h * 0.5) * TILE_SIZE;
                    const cands = mules.filter(m => _dockMuleCandidate(m)).sort((a, b) => Math.hypot(a.x - dCX, a.y - dCY) - Math.hypot(b.x - dCX, b.y - dCY));
