        // con el cubo lleno y la de andar normal de vuelta.
        if ((this.state === 'draining' || this.state === 'hauling_water') && spriteCache.villager?.bucket) {
            const _empty = this.state === 'draining' && !(this._farmAtNode && (this._waterCarried || 0) >= _dryDockLitresPerTrip() / 2);
            spriteName = (_empty && spriteCache.villager.bucket_empty) ? 'bucket_empty' : 'bucket';
        }
