    ctx.lineWidth = 3.5;
    ctx.beginPath();
    ctx.moveTo(cx - r * 0.62, cy + 4);
    ctx.lineTo(cx - r * 0.62, cy - r * 0.5);
    ctx.moveTo(cx + r * 0.62, cy + 4);
    ctx.lineTo(cx + r * 0.62, cy - r * 0.5);
    ctx.stroke();
