    if (type === 'dark') ctx.fillStyle = '#3e8000';
    ctx.fillRect(px, py, TILE_SIZE, TILE_SIZE);
    
    if (type === 'tuft') {
        ctx.fillStyle = '#59b300';
        ctx.beginPath();
        ctx.moveTo(px + 10, py + 20); ctx.lineTo(px + 15, py + 10); ctx.lineTo(px + 20, py + 20);
        ctx.fill();
        ctx.beginPath();
        ctx.moveTo(px + 30, py + 40); ctx.lineTo(px + 35, py + 25); ctx.lineTo(px + 40, py + 40);
        ctx.fill();
    } else if (type === 'flowers') {
        ctx.fillStyle = '#ffaa00';
        ctx.beginPath();
        ctx.arc(px + 15, py + 15, 3, 0, Math.PI * 2);
        ctx.arc(px + 45, py + 35, 3, 0, Math.PI * 2);
        ctx.arc(px + 25, py + 50, 3, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#ffffff';
        ctx.beginPath();
        ctx.arc(px + 50, py + 15, 2, 0, Math.PI * 2);
        ctx.arc(px + 10, py + 45, 2, 0, Math.PI * 2);
        ctx.fill();
    }
