    lighthouse:     (px, py) => drawLighthouse(px, py, false),
    zanja:          (px, py) => drawZanjaPending({ dist: 1, digDone: 0 }, px, py),
    lumber_camp:    (px, py) => drawLumberCamp(px, py),
    maderero_movil: (px, py) => drawMaderoMovil(px, py),
    farm:           (px, py) => drawFarm(px, py, false, false),
    mill:           (px, py) => drawMill(px, py),
    sheep_farm:     (px, py) => drawSheepFarm(px, py, false, false),
    tavern:         (px, py) => drawTavern(px, py),
    market:         (px, py) => drawMarket(px, py),
    stone_quarry:   (px, py) => drawQuarry(px, py, false),
    church:         (px, py) => drawChurch(px, py),
    constructor:    (px, py) => drawConstructor(px, py),
    well:           (px, py) => drawWell(px, py),
    watchtower:     (px, py) => drawWatchtower(px, py),
    ruta_comercial: (px, py) => drawRutaComercial(px, py),
