    forest_farm:    (px, py) => drawForestFarm(px, py, false),
    teatro:         (px, py) => drawTeatro(px, py, null),
    ritual:         (px, py) => drawRitual(px, py, null),
    establo:        (px, py) => drawEstablo(px, py),
    estatua_madera: (px, py) => drawEstatuaOfrenda(px, py, 'madera'),
    estatua_comida: (px, py) => drawEstatuaOfrenda(px, py, 'comida'),
    estatua_tela:   (px, py) => drawEstatuaOfrenda(px, py, 'tela'),
