            ctx.fill();
            ctx.fillStyle = '#8b2a2a';
            ctx.beginPath();
            for (let i = 0; i < _redRects.length; i += 2) ctx.rect(_redRects[i], _redRects[i + 1], _bw, _bh);
            ctx.fill();
            ctx.fillStyle = '#34a849';
            ctx.beginPath();
